export default App;

import { Agent } from "../game";
import { SpriteManager } from "../sprites";
import { AssetManager } from "../assets";
import { AnimState, Role, Team } from "../../types";
import { RenderableItem } from "./grid";
import { HEX_SIZE } from "../../constants";

// Visual Constants
const MAX_UNIT_SIZE_RATIO = 0.85; 
const UNIT_REFERENCE_HEIGHT = 100; 

export class UnitRenderSystem {

    public collectRenderables(
        agents: Agent[], 
        getTerrainHeight: (q: number, r: number) => number, 
        globalTime: number, 
        highlightAgent: Agent | null
    ): RenderableItem[] {
        const list: RenderableItem[] = [];

        agents.forEach(agent => {
            if (agent.hp <= 0 && agent.fullyDead) return;

            // --- HEIGHT INTERPOLATION ---
            let currentHeight = getTerrainHeight(agent.q, agent.r);
            if (agent.isMoving && agent.path.length > 0) {
                const dest = agent.path[0];
                const destHeight = getTerrainHeight(dest.q, dest.r);
                const t = agent.moveProgress;
                currentHeight = currentHeight + (destHeight - currentHeight) * t;
            }

            const visualY = agent.py - currentHeight;

            list.push({
                y: agent.py + 1, 
                z: 10,
                draw: (ctx) => this.drawAssembly(
                    ctx, 
                    agent, 
                    agent.px, 
                    visualY, 
                    globalTime, 
                    highlightAgent === agent,
                    false // Normal Mode
                )
            });
        });

        return list;
    }

    // Called by Renderer for Occlusion Pass
    public drawSilhouette(
        ctx: CanvasRenderingContext2D, 
        agent: Agent, 
        getTerrainHeight: (q: number, r: number) => number,
        globalTime: number
    ) {
        // Recalculate position (same as collectRenderables)
        let currentHeight = getTerrainHeight(agent.q, agent.r);
        if (agent.isMoving && agent.path.length > 0) {
            const dest = agent.path[0];
            const destHeight = getTerrainHeight(dest.q, dest.r);
            const t = agent.moveProgress;
            currentHeight = currentHeight + (destHeight - currentHeight) * t;
        }
        const visualY = agent.py - currentHeight;

        this.drawAssembly(ctx, agent, agent.px, visualY, globalTime, false, true);
    }

    // =================================================================================
    // 🎨 HIERARCHICAL VECTOR ASSEMBLY RENDERER
    // =================================================================================

    private drawAssembly(
        ctx: CanvasRenderingContext2D, 
        agent: Agent, 
        drawX: number, 
        drawY: number, 
        globalTime: number, 
        isSelected: boolean,
        isSilhouette: boolean
    ) {
        // 1. Setup Constraint Space
        const maxDimension = HEX_SIZE * 2 * MAX_UNIT_SIZE_RATIO;

        // Distinct Scale Factors for Roles
        let roleScaleMod = 1.0;
        switch(agent.role) {
            case Role.TANK: roleScaleMod = 1.25; break; // Bulky
            case Role.WARRIOR: roleScaleMod = 1.1; break; // Standard strong
            case Role.RANGER: roleScaleMod = 0.9; break; // Agile/Slim
            case Role.MAGE: roleScaleMod = 0.9; break; // Small/Floating
            case Role.SUPPORT: roleScaleMod = 0.95; break;
        }

        const scaleFactor = (maxDimension / UNIT_REFERENCE_HEIGHT) * roleScaleMod;

        ctx.save();
        ctx.translate(drawX, drawY);
        ctx.scale(scaleFactor, scaleFactor);

        // SILHOUETTE MODE SETUP
        if (isSilhouette) {
            ctx.globalCompositeOperation = 'source-over'; 
            // Increase alpha for stroke visibility, since we are not filling anymore
            ctx.globalAlpha = 0.8; 
            // We don't draw base/floor in silhouette, just the unit body
        } else {
            // NORMAL MODE: Base + Casting Floor
            // If Polymorph or Dead, hide base plate
            if (agent.hp > 0 && agent.visualStatus !== 'POLYMORPH') {
                const assets = SpriteManager.getUnitImages(agent.role, agent.team);
                ctx.save();
                ctx.drawImage(assets.base, -64, -75); 

                // Casting Floor Rune (Ground level)
                if (agent.castingSkillIdx !== -1) {
                    const skill = agent.skills[agent.castingSkillIdx];
                    if (skill) {
                        const circle = AssetManager.getMagicCircle(skill.color, skill.tag === 'ULT');
                        ctx.save(); 
                        ctx.scale(1, 0.5); 
                        ctx.rotate(globalTime * 2);
                        ctx.globalAlpha = 0.6;
                        ctx.drawImage(circle, -64, -64, 128, 128); 
                        ctx.restore();
                    }
                }
                ctx.restore();
            }
        }

        // --- 2. Spawn Animation (Materialize) ---
        // Applies scale stretch and alpha fade if spawning
        let spawnAlpha = 1.0;
        let spawnStretch = 1.0;
        let whiteOverlay = 0;

        if (agent.spawnTimer > 0) {
            const SPAWN_DURATION = 0.5; // From game.ts init
            const progress = 1 - (agent.spawnTimer / SPAWN_DURATION); // 0 -> 1
            const eased = 1 - Math.pow(1 - progress, 3); // Cubic Out

            spawnAlpha = eased;
            spawnStretch = 2.0 - eased; // 2.0 -> 1.0
            whiteOverlay = 1 - eased; // 1 -> 0

            ctx.scale(1, spawnStretch);
            ctx.globalAlpha *= spawnAlpha;
        }

        // 3. Apply Physics & Global Transforms
        // 3a. XY Offset from Physics Impulse
        const physX = agent.physics.x / scaleFactor;
        const physY = agent.physics.y / scaleFactor;

        // 3b. Z Height (The Blast Effect)
        // Physics Z is positive UP, so we subtract from Y
        const physZ = agent.physics.z / scaleFactor; 

        // Role-based float offset (ONLY IF ALIVE)
        let floatOffset = -20;
        if (agent.hp > 0) {
            if ((agent.role === Role.MAGE || agent.role === Role.SUPPORT) && !agent.isMoving && agent.visualStatus === 'NONE') {
                floatOffset -= 5 + Math.sin(globalTime * 2) * 3; // Mages float higher
            }
        } else {
            // Dead units sink slightly to ground (unless blasted)
            floatOffset = -5;
        }

        ctx.translate(physX, physY - physZ + floatOffset); // Apply full 3D pos
        ctx.rotate(agent.physics.angle); // Apply Ragdoll Rotation

        // Hit Flash Logic
        if (agent.hp <= 0 && !isSilhouette) {
            // Priority 1: DEATH (Gray)
            // Fix: Increased opacity to 80% so the fall is more visible against dark ground
            ctx.filter = 'grayscale(100%) opacity(80%)'; 
        } else if (!isSilhouette && agent.hitFlashTimer > 0) {
            // Priority 2: HIT (White Flash)
            ctx.filter = 'brightness(200%)'; 
        } else if (whiteOverlay > 0) {
            // Priority 3: Spawn Flash
            ctx.filter = `brightness(${100 + whiteOverlay * 200}%)`;
        }

        ctx.scale(agent.facing > 0 ? 1 : -1, 1);

        // 4. Render Body (or Special Form)
        if (agent.visualStatus === 'POLYMORPH') {
            // Draw Sheep
            const sheep = SpriteManager.getSpecialModel('SHEEP');
            const bounce = Math.abs(Math.sin(globalTime * 5) * 5);
            ctx.drawImage(sheep, -32, -32 - bounce, 64, 64);
        } else {
            // Standard Unit Render
            if (agent.team === Team.BLUE) {
                this.drawImperialLegion(ctx, agent, globalTime, isSilhouette);
            } else {
                this.drawArcaneCovenant(ctx, agent, globalTime, isSilhouette);
            }

            // Casting VFX (Only if alive)
            if (!isSilhouette && agent.hp > 0 && agent.castingSkillIdx !== -1) {
                this.drawCastingVFX(ctx, agent, globalTime);
            }

            // Frozen Overlay
            if (agent.visualStatus === 'FROZEN') {
                const ice = SpriteManager.getSpecialModel('ICE');
                ctx.save();
                ctx.globalCompositeOperation = 'hard-light';
                ctx.drawImage(ice, -48, -90, 96, 128);
                ctx.restore();
            }

            // Stasis Overlay
            if (agent.visualStatus === 'STASIS') {
                ctx.save();
                ctx.fillStyle = '#facc15';
                ctx.globalAlpha = 0.4;
                ctx.globalCompositeOperation = 'lighter';
                ctx.beginPath();
                ctx.ellipse(0, -30, 25, 50, 0, 0, Math.PI*2);
                ctx.fill();
                ctx.strokeStyle = '#fff';
                ctx.lineWidth = 2;
                ctx.stroke();
                ctx.restore();
            }
        }

        // 6. Selection Ring & Status (Only Normal Mode & Alive)
        if (!isSilhouette) {
            this.drawStatusIcons(ctx, agent, globalTime, drawX, drawY, scaleFactor);
            this.drawStatusEffects(ctx, agent, globalTime);

            if (isSelected && agent.hp > 0) {
                ctx.restore(); // Pop back
                ctx.save();
                ctx.translate(drawX, drawY);
                ctx.scale(scaleFactor, scaleFactor);
                ctx.strokeStyle = '#fff';
                ctx.lineWidth = 2 / scaleFactor; 
                ctx.beginPath();
                ctx.ellipse(0, -5, 30, 15, 0, 0, Math.PI * 2);
                ctx.stroke();
                ctx.restore();
                return; 
            }
        }

        ctx.restore();

        // 7. NEW: Spawn Role Indicator
        // Drawn AFTER restore so it is not affected by body stretch/fade
        if (agent.spawnTimer > 0 && !isSilhouette) {
            this.drawSpawnIndicator(ctx, agent, drawX, drawY, scaleFactor);
        }
    }

    private drawSpawnIndicator(ctx: CanvasRenderingContext2D, agent: Agent, x: number, y: number, scale: number) {
        const assets = SpriteManager.getUnitImages(agent.role, agent.team);

        // "Start instant fade out": Linear fade from 1.0 (start) to 0.0 (end)
        const totalDuration = 0.5;
        const alpha = Math.max(0, agent.spawnTimer / totalDuration);

        // Place it closer to the unit's actual body height (waist/chest area)
        const yOffset = -40 * scale; 

        ctx.save();
        ctx.translate(x, y + yOffset);

        // Pop in scale effect
        const popScale = 1.0 + alpha * 0.2;
        ctx.scale(popScale, popScale);

        ctx.globalAlpha = alpha;

        // Background Circle - Semi-transparent to not block Beam VFX
        ctx.fillStyle = 'rgba(15, 23, 42, 0.4)'; // High transparency
        ctx.strokeStyle = agent.team === Team.BLUE ? 'rgba(59, 130, 246, 0.8)' : 'rgba(239, 68, 68, 0.8)';
        ctx.lineWidth = 2;

        ctx.beginPath();
        ctx.arc(0, 0, 18, 0, Math.PI*2);
        ctx.fill();
        ctx.stroke();

        // Draw Icon
        ctx.drawImage(assets.icon, -12, -12, 24, 24);

        // Role Text
        ctx.font = 'bold 10px sans-serif';
        ctx.textAlign = 'center';
        ctx.fillStyle = '#fff';
        ctx.strokeStyle = 'rgba(0,0,0,0.8)';
        ctx.lineWidth = 2;
        ctx.strokeText(agent.role, 0, 28);
        ctx.fillText(agent.role, 0, 28);

        ctx.restore();
    }

    private drawStatusEffects(ctx: CanvasRenderingContext2D, agent: Agent, t: number) {
        if (agent.hp <= 0) return;

        ctx.save();
        // Undo facing flip so icons don't flip
        if (agent.facing < 0) ctx.scale(-1, 1);

        const HEAD_Y = -90; // Approximate head position in scaled local space

        // 1. STUN
        if (agent.stunTimer > 0 && !agent.banished && agent.visualStatus !== 'FROZEN') {
            const icon = AssetManager.getStatusIcon('STUN');
            const angle = t * 5;
            ctx.drawImage(icon, -20 + Math.cos(angle)*10, HEAD_Y + Math.sin(angle)*5, 24, 24);
            ctx.drawImage(icon, -10 + Math.cos(angle + 2)*10, HEAD_Y - 10 + Math.sin(angle + 2)*5, 16, 16);
        }

        // 2. SILENCE
        if (agent.silenceTimer > 0) {
            const icon = AssetManager.getStatusIcon('SILENCE');
            ctx.drawImage(icon, 15, HEAD_Y - 5 + Math.sin(t * 3) * 3, 24, 24);
        }

        // 3. BANISH (Only if not visual transform)
        if (agent.banished && agent.visualStatus === 'NONE') {
            const icon = AssetManager.getStatusIcon('BANISH');
            ctx.globalAlpha = 0.7;
            ctx.drawImage(icon, -12, HEAD_Y - 20 + Math.sin(t * 2) * 5, 24, 24);
        }

        // 4. DoT (Poison / Bleed / Burn) - Enhanced Visibility
        if (agent.dotTimer > 0) {
            // Icon
            const pulse = 1 + Math.sin(t * 10) * 0.2;
            const iconSize = 28 * pulse; // Larger
            const icon = AssetManager.getStatusIcon('POISON'); // Default to Poison skull for clarity

            // Optimization: Replaced shadowBlur with Glow Sprite
            const glow = AssetManager.getGlowSprite('#ef4444');
            ctx.globalCompositeOperation = 'lighter';
            ctx.drawImage(glow, -35 - iconSize/2, HEAD_Y - iconSize/2, iconSize*2, iconSize*2);
            ctx.globalCompositeOperation = 'source-over';

            ctx.drawImage(icon, -35, HEAD_Y, iconSize, iconSize);

            // Rising Toxic Particles
            ctx.globalAlpha = 0.8;
            for(let i=0; i<5; i++) {
                const cycle = (t * 2 + i * 0.7) % 1;
                const yOff = -cycle * 60; // Rise higher
                const xOff = Math.sin(t * 5 + i) * 15;
                const size = (1 - cycle) * 7;

                // Alternate colors (Green/Purple)
                ctx.fillStyle = i % 2 === 0 ? '#10b981' : '#a855f7';

                if (cycle < 1) {
                    ctx.beginPath();
                    ctx.arc(xOff, -20 + yOff, size, 0, Math.PI*2);
                    ctx.fill();
                }
            }
        }

        // 5. HoT (Regen)
        if (agent.hotTimer > 0) {
            const icon = AssetManager.getStatusIcon('REGEN');
            ctx.drawImage(icon, 25, HEAD_Y, 24, 24);

            ctx.globalAlpha = 0.8;
            ctx.fillStyle = '#4ade80';
            ctx.font = 'bold 14px sans-serif';
            for(let i=0; i<3; i++) {
                const cycle = (t * 1.5 + i * 0.4) % 1;
                const yOff = -cycle * 40;
                const xOff = Math.cos(t * 3 + i) * 15;
                if (cycle < 1) {
                    ctx.fillText('+', xOff, -20 + yOff);
                }
            }
        }

        ctx.restore();
    }

    // --- VFX METHODS ---

    private drawCastingVFX(ctx: CanvasRenderingContext2D, agent: Agent, t: number) {
        const skill = agent.skills[agent.castingSkillIdx];
        if (!skill) return;

        // 0.0 (Start) -> 1.0 (Finish)
        const progress = 1 - (agent.castTimer / skill.cast);
        const color = skill.color;

        ctx.save();
        // Undo facing flip for VFX so particles don't flip randomly
        if (agent.facing < 0) ctx.scale(-1, 1);

        // 1. Rising Energy Lines (Charging up) - INCREASED INTENSITY
        ctx.globalCompositeOperation = 'lighter';
        ctx.strokeStyle = color;
        ctx.lineWidth = 3; 

        const lineCount = 5 + Math.floor(progress * 8); // More lines as cast progresses
        for(let i=0; i<lineCount; i++) {
            const h = (t * 150 + i * 40) % 90; // Faster rising
            const alpha = 1 - (h / 90);
            const xOff = Math.sin(t * 15 + i) * 20 * (1-progress); // Converge as progress -> 1

            ctx.globalAlpha = alpha;
            ctx.beginPath();
            ctx.moveTo(xOff, 15 - h);
            ctx.lineTo(xOff, 15 - h - 20);
            ctx.stroke();
        }

        // 2. Converging Rings (at chest height) - DUAL RINGS
        if (progress > 0.2) {
            const ringScale = (1 - progress) * 2.5; 
            ctx.globalAlpha = progress;
            ctx.lineWidth = 2;
            ctx.beginPath();
            ctx.ellipse(0, -20, 30 * ringScale, 10 * ringScale, 0, 0, Math.PI*2);
            ctx.stroke();

            // Inner spinning ring
            ctx.save();
            ctx.translate(0, -20);
            ctx.rotate(t * 10);
            ctx.beginPath();
            ctx.ellipse(0, 0, 20 * ringScale, 5 * ringScale, 0, 0, Math.PI*2);
            ctx.stroke();
            ctx.restore();
        }

        // 3. Weapon Glow / Hand Gathering
        ctx.globalAlpha = 0.4 + (Math.sin(t * 20) * 0.2) + (progress * 0.6);
        ctx.fillStyle = color;
        ctx.beginPath();
        ctx.arc(0, -20, 10 + progress * 15, 0, Math.PI*2);
        ctx.fill();

        // 4. Final Flash pre-cast
        if (progress > 0.9) {
            ctx.globalAlpha = (progress - 0.9) * 10;
            ctx.fillStyle = '#fff';
            ctx.beginPath();
            ctx.arc(0, -20, 30, 0, Math.PI*2);
            ctx.fill();
        }

        ctx.restore();
    }

    private drawStatusIcons(ctx: CanvasRenderingContext2D, agent: Agent, t: number, drawX: number, drawY: number, scaleFactor: number) {
         if (agent.hp > 0 && agent.castingSkillIdx !== -1) {
            const skill = agent.skills[agent.castingSkillIdx];
            if (skill && skill.visual) {
                const icon = AssetManager.getSkillIcon(skill.visual, skill.color);
                ctx.save();
                // Move Higher to avoid overlap with HP bar (was -90)
                ctx.translate(0, -125);
                const pulse = 1 + Math.sin(t * 10) * 0.1;
                ctx.scale(pulse, pulse);

                // Optimization: Replaced ShadowBlur with Glow Sprite
                const glow = AssetManager.getGlowSprite(skill.color);
                ctx.globalCompositeOperation = 'lighter';
                ctx.globalAlpha = 0.6;
                ctx.drawImage(glow, -32, -32, 64, 64);
                ctx.globalCompositeOperation = 'source-over';
                ctx.globalAlpha = 1.0;

                ctx.drawImage(icon, -12, -12, 24, 24);

                // Cast Bar
                ctx.fillStyle = '#000';
                ctx.fillRect(-14, 20, 28, 5); // Slightly larger
                ctx.fillStyle = skill.color;
                const pct = Math.max(0, 1 - (agent.castTimer / skill.cast));
                ctx.fillRect(-14, 20, 28 * pct, 5);
                ctx.restore();
            }
        }
    }

    // =================================================================================
    // STYLE A: THE IMPERIAL LEGION
    // =================================================================================
    private drawImperialLegion(ctx: CanvasRenderingContext2D, agent: Agent, t: number, isSilhouette: boolean) {
        // Flat colors for Silhouette
        const silhouetteColor = '#3b82f6'; // Blue Team Color

        // -- Material Setup --
        let grad: any = silhouetteColor;
        let accent = silhouetteColor;
        let glow = silhouetteColor;

        if (!isSilhouette) {
            // REFACTORED COLOR SCHEME: Bright Silver/White/Blue to avoid looking gray/dead
            grad = ctx.createLinearGradient(-20, -40, 20, 40);
            grad.addColorStop(0, '#eff6ff');  // White-Blue
            grad.addColorStop(0.5, '#93c5fd'); // Bright Blue Steel
            grad.addColorStop(1, '#2563eb');   // Royal Blue Deep
            accent = '#3b82f6'; 
            glow = '#60a5fa';
        }

        // -- Animation --
        // STOP ANIMATION IF DEAD
        let breathe = (agent.hp > 0) ? Math.sin(t * 3) * 1 : 0;
        let thrustX = 0;
        let armRot = 0;

        if (agent.animState === AnimState.ATTACK && agent.hp > 0) {
            const progress = this.getCastProgress(agent);
            if (progress < 0.3) {
                thrustX = -5 * (progress / 0.3);
                armRot = -0.5 * (progress / 0.3);
            } else if (progress < 0.5) {
                thrustX = 15;
                armRot = 1.0;
            } else {
                thrustX = 15 * (1 - (progress - 0.5)/0.5);
                armRot = 1.0 * (1 - (progress - 0.5)/0.5);
            }
        }

        ctx.save();
        ctx.translate(thrustX, breathe);

        // 1. Back Arm
        ctx.save();
        ctx.translate(10, -10);
        ctx.rotate(armRot);
        this.drawImperialWeapon(ctx, agent.role, grad, accent, isSilhouette);
        ctx.restore();

        // 2. Body Shape Variation based on Role
        if (isSilhouette) {
            ctx.strokeStyle = silhouetteColor;
            ctx.lineWidth = 2;
            ctx.fillStyle = 'transparent'; // Outline only
        } else {
            ctx.fillStyle = grad;
            ctx.strokeStyle = '#1e3a8a'; // Dark Blue outline instead of black
            ctx.lineWidth = 1.5;
        }

        ctx.beginPath();
        if (agent.role === Role.TANK) {
             // WIDER Armor
            ctx.moveTo(-18, -30); 
            ctx.lineTo(18, -30);  
            ctx.lineTo(12, 15);    
            ctx.lineTo(-12, 15);   
        } else if (agent.role === Role.MAGE || agent.role === Role.SUPPORT) {
             // ROBE Shape (Trapezoid)
            ctx.moveTo(-10, -25); 
            ctx.lineTo(10, -25);  
            ctx.lineTo(16, 25);    
            ctx.lineTo(-16, 25);
        } else if (agent.role === Role.RANGER) {
             // SLIM body
            ctx.moveTo(-8, -25); 
            ctx.lineTo(8, -25);  
            ctx.lineTo(6, 15);    
            ctx.lineTo(-6, 15);
        } else {
            // STANDARD Warrior
            ctx.moveTo(-12, -25); 
            ctx.lineTo(12, -25);  
            ctx.lineTo(8, 15);    
            ctx.lineTo(-8, 15);   
        }
        ctx.closePath();

        if (isSilhouette) {
            ctx.stroke();
        } else {
            ctx.fill();
            // Rivets (Skip in silhouette)
            ctx.fillStyle = '#172554';
            ctx.stroke();
            if (agent.role === Role.TANK) {
                [[-12,-25], [12,-25], [-8, 10], [8, 10]].forEach(([rx, ry]) => {
                    ctx.beginPath(); ctx.arc(rx, ry, 1, 0, Math.PI*2); ctx.fill();
                });
            } else if (agent.role !== Role.MAGE && agent.role !== Role.SUPPORT) {
                [[-8,-20], [8,-20], [-5, 10], [5, 10]].forEach(([rx, ry]) => {
                    ctx.beginPath(); ctx.arc(rx, ry, 1, 0, Math.PI*2); ctx.fill();
                });
            }
        }

        // 3. Head
        ctx.save();
        ctx.translate(0, (agent.role === Role.TANK ? -35 : -32) + breathe * 0.5);
        if (isSilhouette) {
            ctx.fillStyle = 'transparent';
            ctx.strokeStyle = silhouetteColor;
        } else {
            ctx.fillStyle = grad;
        }

        ctx.beginPath();
        // Helmet Variations
        if (agent.role === Role.MAGE || agent.role === Role.SUPPORT) {
            // Hood shape
            ctx.moveTo(-10, 5); ctx.lineTo(-8, -15); ctx.lineTo(8, -15); ctx.lineTo(10, 5);
        } else if (agent.role === Role.TANK) {
            // Heavy Box Helm
            ctx.rect(-10, -14, 20, 16);
        } else {
            // Standard Helm
            ctx.rect(-8, -12, 16, 14);
        }

        if (isSilhouette) {
            ctx.stroke();
        } else {
            ctx.fill();
            ctx.stroke();
            // Eyes
            ctx.fillStyle = '#fef08a'; // Yellow glow eyes for contrast
            ctx.fillRect(-6, -8, 12, 2);
        }
        ctx.restore();

        // 4. Front Arm / Shield
        ctx.save();
        ctx.translate(-12, -8);
        if (agent.role === Role.TANK) {
            ctx.rotate(armRot * 0.2);
            ctx.translate(-5, 5);

            if (isSilhouette) {
                ctx.fillStyle = 'transparent';
                ctx.strokeStyle = silhouetteColor;
            } else {
                ctx.fillStyle = '#2563eb'; 
                ctx.strokeStyle = '#fcd34d'; 
            }
            ctx.lineWidth = 2;

            ctx.beginPath();
            ctx.moveTo(-10, -20); ctx.lineTo(10, -20);
            ctx.lineTo(10, 10); ctx.lineTo(0, 25); ctx.lineTo(-10, 10);
            ctx.closePath();

            if (isSilhouette) ctx.stroke();
            else { ctx.fill(); ctx.stroke(); }

        } else if (agent.role === Role.RANGER) {
            ctx.rotate(armRot);
            if (isSilhouette) {
                ctx.strokeStyle = silhouetteColor;
                ctx.strokeRect(-2, -2, 4, 15);
            } else {
                ctx.fillStyle = '#334155';
                ctx.fillRect(-2, -2, 4, 15);
            }
        } else {
            ctx.beginPath(); ctx.arc(0, 0, 6, 0, Math.PI*2); 
            if (isSilhouette) {
                ctx.strokeStyle = silhouetteColor;
                ctx.stroke();
            } else {
                ctx.fillStyle = grad;
                ctx.fill();
            }
        }
        ctx.restore();

        ctx.restore(); 
    }

    private drawImperialWeapon(ctx: CanvasRenderingContext2D, role: Role, grad: any, accent: string, isSilhouette: boolean) {
        // Outline Mode for Silhouette
        if (isSilhouette) {
            ctx.strokeStyle = '#3b82f6';
            ctx.lineWidth = 2;
        }

        if (role === Role.WARRIOR) {
            ctx.beginPath();
            ctx.moveTo(-2, 0); ctx.lineTo(2, 0);
            ctx.lineTo(2, -40); ctx.lineTo(0, -45); ctx.lineTo(-2, -40);

            if (isSilhouette) {
                ctx.stroke();
            } else {
                ctx.fillStyle = '#e2e8f0'; 
                ctx.fill(); ctx.stroke();
                ctx.fillStyle = '#f59e0b'; ctx.fillRect(-6, 0, 12, 3);
            }
        } else if (role === Role.RANGER) {
            ctx.rotate(-Math.PI/2);
            if (isSilhouette) {
                ctx.strokeRect(0, -3, 30, 4);
            } else {
                ctx.fillStyle = '#475569'; 
                ctx.fillRect(0, -3, 30, 4);
                ctx.fillStyle = '#78350f'; ctx.fillRect(-10, -2, 10, 6);
            }
        } else if (role === Role.MAGE || role === Role.SUPPORT) {
            if (isSilhouette) {
                ctx.strokeRect(-2, -40, 4, 50);
            } else {
                ctx.fillStyle = '#475569';
                ctx.fillRect(-2, -40, 4, 50);
                // Optimization: Replaced ShadowBlur with Glow Sprite or simple fill
                ctx.fillStyle = accent;
                const glow = AssetManager.getGlowSprite(accent);
                ctx.save();
                ctx.globalCompositeOperation = 'lighter';
                ctx.drawImage(glow, -16, -55, 32, 32);
                ctx.restore();
                ctx.fillRect(-6, -45, 12, 12);
            }
        }
    }

    // =================================================================================
    // STYLE B: THE ARCANE COVENANT
    // =================================================================================
    private drawArcaneCovenant(ctx: CanvasRenderingContext2D, agent: Agent, t: number, isSilhouette: boolean) {
        const silhouetteColor = '#ef4444'; // Red Team

        let bodyColor = isSilhouette ? 'transparent' : '#78350f'; 
        let glowColor = isSilhouette ? silhouetteColor : '#ef4444'; 
        let secondary = isSilhouette ? silhouetteColor : '#1c1917'; 

        // STOP ANIMATION IF DEAD
        const floatY = (agent.hp > 0) ? Math.sin(t * 2) * 3 : 0;
        let jitterX = 0; let jitterY = 0; let energyGather = 0;

        if (agent.animState === AnimState.ATTACK && agent.hp > 0) {
            const progress = this.getCastProgress(agent);
            if (progress < 0.6) {
                energyGather = progress;
                jitterX = (Math.random() - 0.5) * 3 * progress;
                jitterY = (Math.random() - 0.5) * 3 * progress;
            } else {
                const recoil = (progress - 0.6) / 0.4;
                jitterX = -5 * recoil; 
            }
        }

        ctx.save();
        ctx.translate(jitterX, floatY + jitterY);

        // Body Shape based on Role
        if (isSilhouette) {
            ctx.strokeStyle = silhouetteColor;
            ctx.lineWidth = 2;
            ctx.fillStyle = 'transparent';
        } else {
            ctx.fillStyle = bodyColor;
        }

        ctx.beginPath();
        if (agent.role === Role.TANK) {
             // Bulky
             ctx.ellipse(0, -10, 18, 28, 0, 0, Math.PI*2);
        } else if (agent.role === Role.MAGE || agent.role === Role.SUPPORT) {
             // Robe / Floating bits
             ctx.moveTo(-10, -30); ctx.lineTo(10, -30);
             ctx.lineTo(14, 15); ctx.lineTo(0, 20); ctx.lineTo(-14, 15);
        } else {
             // Standard Ellipse
             ctx.ellipse(0, -10, 12, 25, 0, 0, Math.PI*2);
        }

        if (isSilhouette) {
            ctx.stroke();
        } else {
            ctx.fill();
        }

        // Mage Orbs
        if ((agent.role === Role.MAGE || agent.role === Role.SUPPORT) && agent.hp > 0) {
            const orbGlow = AssetManager.getGlowSprite(glowColor);

            for(let i=0; i<3; i++) {
                const angle = t * 2 + (i * Math.PI * 2 / 3);
                const ox = Math.cos(angle) * (agent.role === Role.MAGE ? 20 : 15) * (1 - energyGather * 0.8);
                const oy = Math.sin(angle) * 5;

                ctx.save();
                ctx.translate(ox, oy - 20);

                if(!isSilhouette) { 
                    // Optimization: Use Glow Sprite
                    ctx.globalCompositeOperation = 'lighter';
                    ctx.globalAlpha = 0.6;
                    ctx.drawImage(orbGlow, -10, -15, 20, 20);
                    ctx.globalCompositeOperation = 'source-over';
                    ctx.globalAlpha = 1.0;
                    ctx.fillStyle = glowColor;
                    ctx.beginPath(); 
                    ctx.moveTo(0, -5); ctx.lineTo(3, 0); ctx.lineTo(0, 5); ctx.lineTo(-3, 0);
                    ctx.fill();
                } else {
                    ctx.strokeStyle = glowColor;
                    ctx.beginPath(); 
                    ctx.moveTo(0, -5); ctx.lineTo(3, 0); ctx.lineTo(0, 5); ctx.lineTo(-3, 0);
                    ctx.stroke();
                }

                ctx.restore();
            }
        }

        // Chest/Core Glow (Skip for Silhouette)
        if (!isSilhouette) {
            ctx.fillStyle = secondary;
            ctx.beginPath(); ctx.ellipse(0, -10, 6, 15, 0, 0, Math.PI*2); ctx.fill();

            // Optimization: Use Glow Sprite instead of shadowBlur
            const coreGlow = AssetManager.getGlowSprite(glowColor);
            ctx.save();
            ctx.globalCompositeOperation = 'lighter';
            ctx.globalAlpha = 0.5 + Math.sin(t*10)*0.2 + energyGather * 0.5;
            ctx.drawImage(coreGlow, -10, -25, 20, 20);
            ctx.restore();

            ctx.fillStyle = glowColor;
            ctx.beginPath(); ctx.arc(0, -15, 4, 0, Math.PI*2); ctx.fill();
        }

        // Head/Mask
        ctx.save();
        const headBob = (agent.hp > 0) ? Math.sin(t*3.5)*2 : 0;
        ctx.translate(0, (agent.role === Role.TANK ? -45 : -40) + headBob); 

        if (isSilhouette) {
            ctx.fillStyle = 'transparent';
            ctx.strokeStyle = silhouetteColor;
        } else {
            ctx.fillStyle = '#f5f5f4';
        }

        ctx.beginPath();
        if (agent.role === Role.TANK) {
            // Large Horned Mask
            ctx.moveTo(-12, -10); ctx.lineTo(12, -10); ctx.lineTo(0, 12);
        } else {
            // Standard Mask
            ctx.moveTo(-6, -8); ctx.lineTo(6, -8); ctx.lineTo(0, 8);
        }

        if (isSilhouette) {
            ctx.stroke();
        } else {
            ctx.fill();
            ctx.fillStyle = glowColor;
            ctx.fillRect(-3, -4, 2, 2); ctx.fillRect(1, -4, 2, 2);
        }
        ctx.restore();

        // Weapon
        ctx.save();
        ctx.translate(15, -15);
        if (agent.role === Role.WARRIOR || agent.role === Role.TANK) {
            const bladeAngle = (agent.hp > 0) ? Math.sin(t) * 0.2 + (agent.animState === AnimState.ATTACK ? -1 : 0) : 0;
            ctx.rotate(bladeAngle);

            if(!isSilhouette) {
                // Optimization: Glow sprite behind weapon
                const wepGlow = AssetManager.getGlowSprite(glowColor);
                ctx.save();
                ctx.globalCompositeOperation = 'lighter';
                ctx.globalAlpha = 0.4;
                ctx.drawImage(wepGlow, -10, -20, 30, 30);
                ctx.restore();
            } else {
                ctx.strokeStyle = silhouetteColor;
            }

            if (agent.role === Role.TANK) {
                ctx.lineWidth = 3;
                if (!isSilhouette) ctx.strokeStyle = glowColor;
                ctx.beginPath(); ctx.arc(0, 0, 20, Math.PI/2, 3*Math.PI/2); ctx.stroke();
            } else {
                ctx.beginPath();
                ctx.moveTo(0, 10); ctx.lineTo(5, -30); ctx.lineTo(-2, -25);
                if (isSilhouette) ctx.stroke();
                else { ctx.fillStyle = glowColor; ctx.fill(); }
            }
        } else if (agent.role === Role.RANGER) {
            ctx.translate(5, 0);
            ctx.rotate(agent.animState === AnimState.ATTACK ? -0.5 : 0);

            if (isSilhouette) {
                ctx.strokeStyle = silhouetteColor;
                ctx.beginPath(); ctx.moveTo(-5, -5); ctx.lineTo(15, 0); ctx.lineTo(-5, 5); ctx.stroke();
            } else {
                ctx.fillStyle = secondary;
                ctx.beginPath(); ctx.moveTo(-5, -5); ctx.lineTo(15, 0); ctx.lineTo(-5, 5); ctx.fill();
                // Optimization: Glow sprite
                const wepGlow = AssetManager.getGlowSprite(glowColor);
                ctx.save();
                ctx.globalCompositeOperation = 'lighter';
                ctx.globalAlpha = 0.4;
                ctx.drawImage(wepGlow, 0, -10, 20, 20);
                ctx.restore();

                ctx.fillStyle = glowColor; 
                ctx.beginPath(); ctx.arc(10, 0, 3, 0, Math.PI*2); ctx.fill();
            }
        }
        ctx.restore();

        ctx.restore(); 
    }

    private getCastProgress(agent: Agent): number {
        if (agent.castingSkillIdx === -1) return 0;
        const skill = agent.skills[agent.castingSkillIdx];
        if (!skill) return 0;
        const raw = agent.castTimer / skill.cast;
        return Math.max(0, Math.min(1, 1 - raw)); 
    }
}

import { Role, Team } from "../types";
import { PALETTE, OBSTACLE_STYLES } from "../constants";

const cache: Map<string, any> = new Map();

// Dimensions
const BASE_SIZE = 128;
const ICON_SIZE = 64;
const WEAPON_SIZE = 128;

function createCanvas(w: number, h: number) {
    const canvas = document.createElement('canvas');
    canvas.width = w;
    canvas.height = h;
    const ctx = canvas.getContext('2d')!;
    ctx.imageSmoothingEnabled = true; 
    return { canvas, ctx };
}

export interface UnitAssets {
    base: HTMLCanvasElement; // Pre-rendered base
    weapon: HTMLCanvasElement; // Pre-rendered weapon
    icon: HTMLCanvasElement;   // Pre-rendered class icon
    color: string;           // Glow color
}

// ==========================================
// 1. Base Generation (Ground Plate)
// ==========================================
const generateTokenBase = (team: Team): HTMLCanvasElement => {
    const { canvas, ctx } = createCanvas(BASE_SIZE, BASE_SIZE);
    const cx = BASE_SIZE / 2;
    const cy = BASE_SIZE / 2 + 15; // Offset slightly down
    const rx = 40;
    const ry = 20; 
    const height = 16; 

    // Drop Shadow
    ctx.fillStyle = 'rgba(0,0,0,0.6)';
    ctx.beginPath(); 
    ctx.ellipse(cx, cy + 5, rx + 6, ry + 6, 0, 0, Math.PI * 2); 
    ctx.fill();

    if (team === Team.RED) {
        // --- HORDE STYLE (Spiked, Iron, Crimson) ---
        ctx.fillStyle = '#1c1917'; 

        // Spikes
        for (let i = 0; i < 6; i++) {
            const angle = (i * Math.PI * 2) / 6;
            const sx = cx + Math.cos(angle) * (rx + 5);
            const sy = cy + Math.sin(angle) * (ry + 5);
            ctx.beginPath();
            ctx.moveTo(sx, sy);
            ctx.lineTo(sx + Math.cos(angle) * 15, sy + Math.sin(angle) * 15 - 10); 
            ctx.lineTo(sx + Math.cos(angle + 0.2) * 5, sy + Math.sin(angle + 0.2) * 5);
            ctx.fill();
        }

        // Side (Thickness)
        const gradSide = ctx.createLinearGradient(0, cy - height, 0, cy + ry);
        gradSide.addColorStop(0, '#450a0a'); 
        gradSide.addColorStop(0.5, '#1c1917'); 
        gradSide.addColorStop(1, '#450a0a');
        ctx.fillStyle = gradSide;

        ctx.beginPath(); 
        ctx.ellipse(cx, cy, rx, ry, 0, 0, Math.PI, false); 
        ctx.lineTo(cx + rx, cy - height); 
        ctx.ellipse(cx, cy - height, rx, ry, 0, 0, Math.PI, true); 
        ctx.lineTo(cx - rx, cy); 
        ctx.fill();

        // Top Surface
        ctx.fillStyle = '#7f1d1d'; 
        ctx.beginPath(); 
        ctx.ellipse(cx, cy - height, rx, ry, 0, 0, Math.PI * 2); 
        ctx.fill();

        // Iron Rim
        ctx.strokeStyle = '#a1a1aa'; 
        ctx.lineWidth = 4; 
        ctx.beginPath(); 
        ctx.ellipse(cx, cy - height, rx - 2, ry - 2, 0, 0, Math.PI * 2); 
        ctx.stroke();

    } else {
        // --- ALLIANCE STYLE (Smooth, Gold, Royal Blue) ---

        // Side (Thickness)
        const gradSide = ctx.createLinearGradient(0, cy - height, 0, cy + ry);
        gradSide.addColorStop(0, '#fbbf24'); 
        gradSide.addColorStop(0.5, '#b45309'); 
        gradSide.addColorStop(1, '#fbbf24');
        ctx.fillStyle = gradSide;

        ctx.beginPath(); 
        ctx.ellipse(cx, cy, rx, ry, 0, 0, Math.PI, false); 
        ctx.lineTo(cx + rx, cy - height); 
        ctx.ellipse(cx, cy - height, rx, ry, 0, 0, Math.PI, true); 
        ctx.lineTo(cx - rx, cy); 
        ctx.fill();

        // Top Surface (Marble/Light)
        const gradTop = ctx.createRadialGradient(cx, cy - height, 0, cx, cy - height, rx);
        gradTop.addColorStop(0, '#f8fafc'); 
        gradTop.addColorStop(1, '#e2e8f0');
        ctx.fillStyle = gradTop; 
        ctx.beginPath(); 
        ctx.ellipse(cx, cy - height, rx - 3, ry - 3, 0, 0, Math.PI * 2); 
        ctx.fill();

        // Blue Ring
        ctx.strokeStyle = '#2563eb'; 
        ctx.lineWidth = 2; 
        ctx.beginPath(); 
        ctx.ellipse(cx, cy - height, rx * 0.7, ry * 0.7, 0, 0, Math.PI * 2); 
        ctx.stroke();
    }
    return canvas;
};

// ==========================================
// 2. Class Icon Generation
// ==========================================
const generateRoleIcon = (role: Role, team: Team): HTMLCanvasElement => {
    const { canvas, ctx } = createCanvas(ICON_SIZE, ICON_SIZE);
    const cx = ICON_SIZE / 2;
    const cy = ICON_SIZE / 2;

    const isBlue = team === Team.BLUE;
    const color = isBlue ? '#2563eb' : '#dc2626'; 
    const secColor = isBlue ? '#fbbf24' : '#52525b';

    ctx.shadowColor = 'rgba(0,0,0,0.5)'; 
    ctx.shadowBlur = 4;
    ctx.lineJoin = 'round'; 
    ctx.lineCap = 'round';

    switch (role) {
        case Role.TANK:
            ctx.fillStyle = secColor; 
            ctx.strokeStyle = '#fff'; 
            ctx.lineWidth = 2;
            if (isBlue) {
                // Shield Shape
                ctx.beginPath(); 
                ctx.moveTo(cx - 15, cy - 15); 
                ctx.lineTo(cx + 15, cy - 15); 
                ctx.lineTo(cx + 15, cy); 
                ctx.quadraticCurveTo(cx, cy + 25, cx, cy + 25); 
                ctx.quadraticCurveTo(cx - 15, cy, cx - 15, cy); 
                ctx.closePath();
            } else {
                // Tower Shield (Square with spikes)
                ctx.beginPath();
                ctx.rect(cx - 14, cy - 18, 28, 36);
            }
            ctx.fill(); 
            ctx.stroke();

            // Center Dot/Spike
            ctx.fillStyle = color; 
            ctx.beginPath(); 
            ctx.arc(cx, cy, isBlue ? 6 : 8, 0, Math.PI * 2); 
            ctx.fill();
            break;

        case Role.WARRIOR:
            ctx.strokeStyle = '#fff'; 
            ctx.lineWidth = 3; 
            ctx.beginPath();
            if (isBlue) {
                // Sword
                ctx.moveTo(cx, cy - 20); ctx.lineTo(cx, cy + 15); 
                ctx.moveTo(cx - 8, cy + 15); ctx.lineTo(cx + 8, cy + 15); 
                ctx.moveTo(cx, cy + 15); ctx.lineTo(cx, cy + 25);
            } else {
                // Double Axe
                ctx.moveTo(cx, cy + 20); ctx.lineTo(cx, cy - 20); // Handle
                // Left Blade
                ctx.moveTo(cx, cy - 15); 
                ctx.quadraticCurveTo(cx - 15, cy - 25, cx - 20, cy - 5); 
                ctx.quadraticCurveTo(cx - 10, cy, cx, cy - 5);
                // Right Blade
                ctx.moveTo(cx, cy - 15); 
                ctx.quadraticCurveTo(cx + 15, cy - 25, cx + 20, cy - 5); 
                ctx.quadraticCurveTo(cx + 10, cy, cx, cy - 5);
            }
            ctx.stroke();
            break;

        case Role.RANGER:
            ctx.strokeStyle = '#fff'; 
            ctx.lineWidth = 2; 
            ctx.beginPath();
            if (isBlue) {
                // Bow
                ctx.arc(cx - 5, cy, 15, -Math.PI/2, Math.PI/2); 
                ctx.moveTo(cx - 5, cy - 15); ctx.lineTo(cx - 5, cy + 15); 
                ctx.moveTo(cx - 10, cy); ctx.lineTo(cx + 15, cy);
            } else {
                // Crossbow
                ctx.moveTo(cx - 5, cy + 15); ctx.lineTo(cx - 5, cy - 15); // Stock
                ctx.moveTo(cx - 15, cy - 10); ctx.lineTo(cx + 5, cy - 10); // Limb
            }
            ctx.stroke();
            break;

        case Role.MAGE:
            ctx.strokeStyle = '#fff'; 
            ctx.lineWidth = 2; 
            ctx.beginPath();
            // Staff diagonally
            ctx.moveTo(cx + 10, cy - 20); 
            ctx.lineTo(cx - 10, cy + 20); 
            ctx.stroke();

            // Orb / Gem
            ctx.fillStyle = color; 
            ctx.beginPath();
            if (isBlue) {
                ctx.arc(cx + 10, cy - 20, 6, 0, Math.PI * 2);
            } else { 
                // Crooked top
                ctx.moveTo(cx + 10, cy - 20); ctx.lineTo(cx + 15, cy - 25);
                ctx.moveTo(cx + 10, cy - 20); ctx.lineTo(cx + 5, cy - 28);
                ctx.stroke();
            }
            ctx.fill();
            break;

        case Role.SUPPORT:
        default:
            if (isBlue) {
                // Hammer / Mace
                ctx.fillStyle = '#fff'; 
                ctx.strokeStyle = '#fff';
                ctx.lineWidth = 2;
                ctx.beginPath();
                ctx.moveTo(cx, cy + 15); ctx.lineTo(cx, cy - 10); // Handle
                ctx.stroke();
                ctx.fillRect(cx - 8, cy - 20, 16, 12); // Head
            } else {
                // Claw
                ctx.strokeStyle = '#fff';
                ctx.lineWidth = 2;
                ctx.beginPath();
                ctx.moveTo(cx - 10, cy + 10); ctx.lineTo(cx + 15, cy - 10);
                ctx.moveTo(cx - 5, cy + 10); ctx.lineTo(cx + 20, cy - 5);
                ctx.stroke();
            }
            break;
    }
    return canvas;
};

// ==========================================
// 3. Weapon Generation
// ==========================================
const generateWeapon = (role: Role, team: Team): HTMLCanvasElement => {
    const { canvas, ctx } = createCanvas(WEAPON_SIZE, WEAPON_SIZE);

    const isBlue = team === Team.BLUE;
    const mainColor = isBlue ? '#fbbf24' : '#ef4444'; 
    const metalColor = isBlue ? '#e2e8f0' : '#27272a';
    const darkMetal = '#18181b';

    // PIVOT FIX: Move origin to center. 
    // We draw the weapon such that the handle/grip is at (0,0).
    ctx.translate(WEAPON_SIZE / 2, WEAPON_SIZE / 2);
    ctx.scale(1.5, 1.5);

    ctx.shadowColor = mainColor;
    ctx.shadowBlur = 5;
    ctx.lineJoin = 'round';

    switch (role) {
        case Role.WARRIOR:
            if (isBlue) {
                // --- BLUE: CLAYMORE (Long, Straight) ---
                ctx.rotate(Math.PI / 4);
                // Handle
                ctx.fillStyle = '#3f2c22'; ctx.fillRect(-3, -15, 6, 20); 
                // Guard (Cross)
                ctx.fillStyle = '#fbbf24'; 
                ctx.beginPath(); ctx.moveTo(-15, 5); ctx.lineTo(15, 5); ctx.lineTo(0, -2); ctx.fill();
                // Blade
                ctx.fillStyle = '#e2e8f0'; ctx.strokeStyle = '#94a3b8';
                ctx.beginPath(); 
                ctx.moveTo(-6, 5); ctx.lineTo(-4, 60); ctx.lineTo(0, 75); ctx.lineTo(4, 60); ctx.lineTo(6, 5);
                ctx.fill(); ctx.stroke();
                // Fuller (Blood groove)
                ctx.fillStyle = '#94a3b8'; ctx.fillRect(-1, 5, 2, 50);
            } else {
                // --- RED: GREATAXE (Wide, Double-headed) ---
                ctx.rotate(Math.PI / 4);
                // Handle (Long)
                ctx.fillStyle = '#3f2c22'; ctx.fillRect(-4, -10, 8, 70); 
                // Axe Head
                ctx.translate(0, 45); // Move to head position
                ctx.fillStyle = darkMetal; ctx.strokeStyle = '#ef4444'; ctx.lineWidth = 1;

                // Left Blade
                ctx.beginPath();
                ctx.moveTo(-4, 0); 
                ctx.quadraticCurveTo(-20, -25, -35, -20); // Top curve
                ctx.quadraticCurveTo(-30, 0, -35, 20);    // Edge
                ctx.quadraticCurveTo(-20, 25, -4, 10);    // Bottom curve
                ctx.fill(); ctx.stroke();

                // Right Blade
                ctx.beginPath();
                ctx.moveTo(4, 0); 
                ctx.quadraticCurveTo(20, -25, 35, -20);
                ctx.quadraticCurveTo(30, 0, 35, 20);
                ctx.quadraticCurveTo(20, 25, 4, 10);
                ctx.fill(); ctx.stroke();

                // Spike on top
                ctx.beginPath(); ctx.moveTo(-5, -10); ctx.lineTo(0, -25); ctx.lineTo(5, -10); ctx.fill();
            }
            break;

        case Role.TANK:
            if (isBlue) {
                // --- BLUE: KITE SHIELD (Elegant) ---
                ctx.fillStyle = '#1e3a8a'; ctx.strokeStyle = '#fbbf24'; ctx.lineWidth = 3;
                ctx.beginPath(); 
                ctx.moveTo(-15, -20); ctx.lineTo(15, -20); 
                ctx.lineTo(15, 5); ctx.lineTo(0, 25); ctx.lineTo(-15, 5); 
                ctx.closePath();
                ctx.fill(); ctx.stroke();
                // Symbol
                ctx.fillStyle = '#fbbf24'; ctx.beginPath(); ctx.arc(0, -5, 5, 0, Math.PI*2); ctx.fill();
            } else {
                // --- RED: TOWER SHIELD (Thick, Spiked, Rectangular) ---
                ctx.fillStyle = '#18181b'; // Dark Iron

                // Main Plate
                ctx.beginPath();
                ctx.moveTo(-18, -25); ctx.lineTo(18, -25);
                ctx.lineTo(16, 25); ctx.lineTo(0, 30); ctx.lineTo(-16, 25);
                ctx.closePath();
                ctx.fill();

                // Metal Banding
                ctx.strokeStyle = '#52525b'; ctx.lineWidth = 4;
                ctx.stroke();

                // Spikes
                ctx.fillStyle = '#d4d4d8';
                const spikes = [[0,0], [-10, -15], [10, -15], [0, 15]];
                spikes.forEach(([sx, sy]) => {
                    ctx.beginPath(); ctx.arc(sx, sy, 3, 0, Math.PI*2); ctx.fill();
                    ctx.beginPath(); ctx.moveTo(sx, sy); ctx.lineTo(sx, sy-8); ctx.stroke(); // Spike tip
                });

                // Glow cracks
                ctx.strokeStyle = '#ef4444'; ctx.lineWidth = 1;
                ctx.beginPath(); ctx.moveTo(-10, 0); ctx.lineTo(10, 0); ctx.stroke();
            }
            break;

        case Role.RANGER:
            if (isBlue) {
                // --- BLUE: LONGBOW (Vertical, Curved) ---
                ctx.rotate(-Math.PI / 4);
                // Wood
                ctx.strokeStyle = '#fcd34d'; ctx.lineWidth = 3;
                ctx.beginPath(); ctx.arc(10, 0, 30, -Math.PI/2, Math.PI/2); ctx.stroke();
                // String
                ctx.strokeStyle = '#fff'; ctx.lineWidth = 1; 
                ctx.beginPath(); ctx.moveTo(10, -30); ctx.lineTo(8, 30); ctx.stroke();
                // Handle
                ctx.fillStyle = '#b45309'; ctx.fillRect(8, -5, 4, 10);
            } else {
                // --- RED: HEAVY CROSSBOW (Horizontal structure) ---
                ctx.rotate(-Math.PI / 4);

                // Stock
                ctx.fillStyle = '#3f2c22'; ctx.fillRect(-10, -2, 40, 4);

                // Limb (Bow part) - Perpendicular
                ctx.strokeStyle = '#52525b'; ctx.lineWidth = 4;
                ctx.beginPath(); 
                ctx.moveTo(20, -15); 
                ctx.quadraticCurveTo(15, 0, 20, 15); 
                ctx.stroke();

                // String
                ctx.strokeStyle = '#94a3b8'; ctx.lineWidth = 1;
                ctx.beginPath(); ctx.moveTo(20, -15); ctx.lineTo(-5, 0); ctx.lineTo(20, 15); ctx.stroke();

                // Bolt loaded
                ctx.strokeStyle = '#ef4444'; ctx.lineWidth = 2;
                ctx.beginPath(); ctx.moveTo(-5, 0); ctx.lineTo(25, 0); ctx.stroke();
            }
            break;

        case Role.MAGE:
            ctx.rotate(Math.PI / 8);
            if (isBlue) {
                // --- BLUE: CRYSTAL STAFF ---
                // Shaft
                ctx.strokeStyle = '#fbbf24'; ctx.lineWidth = 3;
                ctx.beginPath(); ctx.moveTo(0, -10); ctx.lineTo(0, 60); ctx.stroke();

                // Head (Crescent)
                ctx.lineWidth = 2;
                ctx.beginPath(); ctx.arc(0, 60, 10, Math.PI, 0); ctx.stroke();

                // Crystal
                ctx.fillStyle = '#60a5fa'; ctx.shadowColor = '#60a5fa'; ctx.shadowBlur = 15;
                ctx.beginPath(); ctx.moveTo(0, 55); ctx.lineTo(5, 65); ctx.lineTo(0, 75); ctx.lineTo(-5, 65); ctx.fill();
            } else {
                // --- RED: VOODOO STAFF ---
                // Crooked Shaft
                ctx.strokeStyle = '#4a0404'; ctx.lineWidth = 4; 
                ctx.beginPath(); 
                ctx.moveTo(0, -10); ctx.lineTo(2, 20); ctx.lineTo(-2, 40); ctx.lineTo(0, 60); 
                ctx.stroke();

                // Head (Skull-ish shape)
                ctx.fillStyle = '#e5e5e5'; ctx.shadowColor = '#10b981'; 
                ctx.beginPath(); ctx.arc(0, 65, 8, 0, Math.PI*2); ctx.fill();
                // Green Eyes
                ctx.fillStyle = '#10b981'; 
                ctx.beginPath(); ctx.arc(-3, 67, 2, 0, Math.PI*2); ctx.arc(3, 67, 2, 0, Math.PI*2); ctx.fill();

                // Feathers/Charms
                ctx.strokeStyle = '#ef4444'; ctx.lineWidth = 2;
                ctx.beginPath(); ctx.moveTo(0, 55); ctx.lineTo(10, 50); ctx.stroke();
            }
            break;

        case Role.SUPPORT:
        default:
            if (isBlue) {
                // --- BLUE: WARHAMMER / MACE ---
                ctx.rotate(Math.PI / 4);
                // Handle
                ctx.fillStyle = '#3f2c22'; ctx.fillRect(-2, -10, 4, 50);
                // Head (Blocky)
                ctx.translate(0, 45);
                ctx.fillStyle = '#94a3b8'; ctx.strokeStyle = '#fbbf24'; ctx.lineWidth = 2;
                ctx.fillRect(-10, -8, 20, 16); ctx.strokeRect(-10, -8, 20, 16);
                // Runes on head
                ctx.fillStyle = '#fbbf24'; ctx.beginPath(); ctx.arc(0, 0, 4, 0, Math.PI*2); ctx.fill();
            } else {
                // --- RED: CLAWS / FIST WEAPON ---
                // Grip
                ctx.fillStyle = '#27272a'; ctx.fillRect(-8, -8, 16, 16);

                // Blades
                ctx.fillStyle = '#d4d4d8'; ctx.shadowColor = '#ef4444'; ctx.shadowBlur = 5;
                const blades = [-10, 0, 10];
                blades.forEach((offset, i) => {
                    ctx.beginPath();
                    ctx.moveTo(offset, 0);
                    // Curve out
                    ctx.quadraticCurveTo(offset * 1.5, 30, offset * 0.5, 45);
                    ctx.lineTo(offset * 0.5 - 2, 40); // Inner edge
                    ctx.closePath();
                    ctx.fill();
                });
            }
            break;
    }

    return canvas;
};

// ==========================================
// 4. Obstacle Generation (Scene Aware)
// ==========================================
const generateObstacle = (styleKey: string): HTMLCanvasElement => {
    const { canvas, ctx } = createCanvas(64, 96);
    const cx = 32;
    const cy = 80;

    // Default Fallback
    const style = OBSTACLE_STYLES[styleKey] || OBSTACLE_STYLES['WALL'];

    ctx.fillStyle = style.main;
    ctx.strokeStyle = style.light;
    ctx.lineWidth = 2;
    ctx.lineJoin = 'round';

    if (styleKey === 'TREE') {
        // --- ANCIENT TREE ---
        // Trunk
        ctx.fillStyle = style.dark;
        ctx.beginPath();
        ctx.moveTo(cx - 8, cy); 
        ctx.lineTo(cx + 8, cy); 
        ctx.lineTo(cx + 6, cy - 40); 
        ctx.lineTo(cx - 6, cy - 40); 
        ctx.fill();

        // Foliage Layers
        ctx.fillStyle = style.detail; 
        ctx.shadowColor = 'rgba(0,0,0,0.5)'; ctx.shadowBlur = 5;

        const leaves = (y: number, r: number) => {
            ctx.beginPath(); 
            ctx.arc(cx, y, r, 0, Math.PI * 2); 
            ctx.fill(); 
            ctx.stroke();
        };
        leaves(cy - 40, 20);
        leaves(cy - 60, 16);
        leaves(cy - 75, 12);

    } else if (styleKey === 'ICE_CRYSTAL') {
        // --- ICE SPIKES ---
        ctx.fillStyle = style.main;
        ctx.globalAlpha = 0.8;
        ctx.shadowColor = style.light; ctx.shadowBlur = 10;

        const shard = (x: number, h: number, w: number, ang: number) => {
            ctx.save();
            ctx.translate(x, cy);
            ctx.rotate(ang);
            ctx.beginPath();
            ctx.moveTo(-w, 0);
            ctx.lineTo(0, -h);
            ctx.lineTo(w, 0);
            ctx.fill(); ctx.stroke();

            // Highlight
            ctx.strokeStyle = '#fff';
            ctx.lineWidth = 1;
            ctx.beginPath(); ctx.moveTo(-w, 0); ctx.lineTo(0, -h); ctx.stroke();
            ctx.restore();
        };

        shard(cx, 60, 15, 0);
        shard(cx - 10, 40, 10, -0.2);
        shard(cx + 12, 45, 12, 0.3);

    } else if (styleKey === 'OBSIDIAN_PILLAR') {
        // --- MAGMA ROCK ---
        ctx.fillStyle = style.main;

        ctx.beginPath();
        ctx.moveTo(cx - 15, cy);
        ctx.lineTo(cx - 10, cy - 70);
        ctx.lineTo(cx + 15, cy - 80);
        ctx.lineTo(cx + 20, cy);
        ctx.closePath();
        ctx.fill(); ctx.stroke();

        // Cracks
        ctx.strokeStyle = style.detail; // Magma Red
        ctx.lineWidth = 2;
        ctx.beginPath();
        ctx.moveTo(cx, cy - 10); ctx.lineTo(cx + 5, cy - 30); ctx.lineTo(cx - 5, cy - 50);
        ctx.stroke();

    } else if (styleKey === 'SANDSTONE') {
        // --- ERODED ROCK ---
        ctx.fillStyle = style.main;

        ctx.beginPath();
        ctx.ellipse(cx, cy - 20, 20, 30, 0, 0, Math.PI * 2);
        ctx.fill(); ctx.stroke();

        // Layers
        ctx.strokeStyle = style.dark;
        ctx.lineWidth = 2;
        ctx.beginPath();
        ctx.moveTo(cx - 18, cy - 10); ctx.quadraticCurveTo(cx, cy - 5, cx + 18, cy - 10);
        ctx.moveTo(cx - 18, cy - 30); ctx.quadraticCurveTo(cx, cy - 25, cx + 18, cy - 30);
        ctx.stroke();

    } else {
        // --- WALL (Default) ---
        // Main Boulder
        ctx.fillStyle = style.dark;
        ctx.beginPath(); 
        ctx.moveTo(cx, cy - 80); 
        ctx.lineTo(cx + 24, cy - 70); 
        ctx.lineTo(cx, cy - 60); 
        ctx.lineTo(cx - 24, cy - 70); 
        ctx.closePath(); 
        ctx.fill(); ctx.stroke();

        // Side Facets
        ctx.fillStyle = style.main; 
        ctx.beginPath(); 
        ctx.moveTo(cx - 24, cy - 70); 
        ctx.lineTo(cx, cy - 60); 
        ctx.lineTo(cx, cy); 
        ctx.lineTo(cx - 24, cy - 10); 
        ctx.closePath(); 
        ctx.fill(); ctx.stroke();

        ctx.fillStyle = style.light; 
        ctx.beginPath(); 
        ctx.moveTo(cx, cy - 60); 
        ctx.lineTo(cx + 24, cy - 70); 
        ctx.lineTo(cx + 24, cy - 10); 
        ctx.lineTo(cx, cy); 
        ctx.closePath(); 
        ctx.fill(); ctx.stroke();

        // Moss Detail
        if (style.detail) {
            ctx.fillStyle = style.detail; 
            ctx.beginPath(); 
            ctx.arc(cx, cy - 5, 10, 0, Math.PI, true); 
            ctx.fill();
        }
    }

    return canvas;
};

// ==========================================
// 5. Special Effect Models (Sheep, Ice)
// ==========================================
const generateSheep = (): HTMLCanvasElement => {
    const { canvas, ctx } = createCanvas(64, 64);
    const cx = 32, cy = 45;

    // Fluff
    ctx.fillStyle = '#fff';
    ctx.shadowColor = '#d1d5db'; ctx.shadowBlur = 5;
    const fluffs = [
        {x: 0, y: -10, r: 15}, {x: -12, y: -5, r: 12}, {x: 12, y: -5, r: 12},
        {x: -8, y: 8, r: 12}, {x: 8, y: 8, r: 12}
    ];
    fluffs.forEach(f => {
        ctx.beginPath(); ctx.arc(cx + f.x, cy + f.y, f.r, 0, Math.PI*2); ctx.fill();
    });

    // Head
    ctx.shadowBlur = 0;
    ctx.fillStyle = '#1c1917';
    ctx.beginPath(); 
    ctx.ellipse(cx - 15, cy - 5, 8, 10, -0.2, 0, Math.PI*2); 
    ctx.fill();

    // Eye
    ctx.fillStyle = '#fff';
    ctx.beginPath(); ctx.arc(cx - 17, cy - 7, 2, 0, Math.PI*2); ctx.fill();

    // Legs
    ctx.fillStyle = '#1c1917';
    ctx.fillRect(cx - 10, cy + 10, 4, 10);
    ctx.fillRect(cx + 6, cy + 10, 4, 10);

    return canvas;
};

const generateIceBlock = (): HTMLCanvasElement => {
    const { canvas, ctx } = createCanvas(96, 128);
    const cx = 48, cy = 90;

    ctx.fillStyle = 'rgba(224, 242, 254, 0.4)'; // Sky-100 translucent
    ctx.strokeStyle = '#38bdf8'; // Sky-400
    ctx.lineWidth = 2;

    // Crystal Shape
    ctx.beginPath();
    ctx.moveTo(cx - 30, cy);
    ctx.lineTo(cx - 35, cy - 60);
    ctx.lineTo(cx, cy - 100);
    ctx.lineTo(cx + 35, cy - 70);
    ctx.lineTo(cx + 30, cy);
    ctx.closePath();

    ctx.fill();
    ctx.stroke();

    // Facets
    ctx.beginPath(); ctx.moveTo(cx, cy - 100); ctx.lineTo(cx - 10, cy - 50); ctx.lineTo(cx - 30, cy); ctx.stroke();
    ctx.beginPath(); ctx.moveTo(cx, cy - 100); ctx.lineTo(cx + 15, cy - 40); ctx.lineTo(cx + 30, cy); ctx.stroke();

    return canvas;
};

// ==========================================
// 6. Manager Access
// ==========================================
export const SpriteManager = {
    getUnitImages(role: Role, team: Team): UnitAssets {
        // Updated keys to force refresh with new designs
        const keyBase = `TOKEN_BASE_${team}_V3`; 
        let base = cache.get(keyBase);
        if (!base) {
            base = generateTokenBase(team);
            cache.set(keyBase, base);
        }

        const keyWep = `WEAPON_${role}_${team}_V3`;
        let weapon = cache.get(keyWep);
        if (!weapon) {
            weapon = generateWeapon(role, team);
            cache.set(keyWep, weapon);
        }

        const keyIcon = `ROLE_ICON_${role}_${team}_V3`;
        let icon = cache.get(keyIcon);
        if (!icon) {
            icon = generateRoleIcon(role, team);
            cache.set(keyIcon, icon);
        }

        return {
            base: base,
            weapon: weapon,
            icon: icon,
            color: PALETTE.TEAMS[team].glow
        };
    },

    getObstacleSprite(styleKey: string = 'WALL'): HTMLCanvasElement {
        const key = `OBSTACLE_${styleKey}`;
        if (cache.has(key)) return cache.get(key)!;

        const canvas = generateObstacle(styleKey);
        cache.set(key, canvas);
        return canvas;
    },

    getSpecialModel(type: 'SHEEP' | 'ICE'): HTMLCanvasElement {
        const key = `MODEL_${type}`;
        if (!cache.has(key)) {
            if (type === 'SHEEP') cache.set(key, generateSheep());
            else cache.set(key, generateIceBlock());
        }
        return cache.get(key)!;
    }
};

import { HEX_SIZE, BLOCK_HEIGHT, TERRAIN_THEMES } from "../../constants";
import { GameEngine, Agent } from "../game";
import { HexUtils } from "../utils";
import { AssetManager } from "../assets";
import { Hex, Skill, Projectile } from "../../types";

export interface RenderableItem {
    y: number;
    z: number;
    draw: (ctx: CanvasRenderingContext2D) => void;
}

interface CachedTile {
    q: number;
    r: number;
    px: number;
    py: number;
    h: number;
}

export class GridSystem {
    private heightCache: Map<string, number> = new Map();
    public terrainDepth: number = 1.0; // 1.0 = Standard, >1.0 = Deep

    // Optimization: Cache tiles to avoid re-parsing keys and re-calculating positions every frame
    private _tileCache: CachedTile[] = [];
    private _lastMapVersion: number = -1;

    setTerrainDepth(d: number) {
        if (Math.abs(this.terrainDepth - d) > 0.01) {
            this.terrainDepth = d;
            this.clearCache();
            this._lastMapVersion = -1; // Invalidate cache
        }
    }

    clearCache() {
        this.heightCache.clear();
    }

    private ensureCache(engine: GameEngine) {
        if (this._lastMapVersion !== engine.mapVersion || this._tileCache.length === 0) {
            this.rebuildTileCache(engine);
        }
    }

    private rebuildTileCache(engine: GameEngine) {
        this._tileCache = [];
        this._lastMapVersion = engine.mapVersion;

        engine.mapKeys.forEach(k => {
            const [q, r] = k.split(',').map(Number);
            const pos = HexUtils.toPx(q, r, engine.mapConfig);
            const h = this.getTerrainHeight(q, r);
            this._tileCache.push({ q, r, px: pos.x, py: pos.y, h });
        });
    }

    getTerrainHeight(q: number, r: number): number {
        const key = `${q},${r}`;
        if (this.heightCache.has(key)) return this.heightCache.get(key)!;

        // Deterministic Noise
        const n = Math.sin(q * 12.9898 + r * 78.233) * 43758.5453;
        const noise = Math.abs(n - Math.floor(n));

        // Logic:
        // Standard: Base(16) + Noise(0-16) = Max 32
        // Deep (2.5): Base(24) + Noise(0-60) = Max 84
        const base = BLOCK_HEIGHT * (0.8 + 0.2 * this.terrainDepth);
        const variance = 16 * Math.pow(this.terrainDepth, 1.8); 

        const h = Math.floor(base + noise * variance);
        this.heightCache.set(key, h);
        return h;
    }

    getHexAtScreenPoint(mx: number, my: number, camera: {x: number, y: number, zoom: number}, engine: GameEngine): Hex | null {
        this.ensureCache(engine);

        // Convert screen mouse to world coordinates (unzoomed)
        const wx = mx / camera.zoom + camera.x;
        const wy = my / camera.zoom + camera.y;

        // Collect all potential candidates
        // We only check tiles that actually exist in the map
        const candidates: CachedTile[] = [];
        // Approximate bounding check (HEX_SIZE * 2 covers height + width variance mostly)
        const limit = HEX_SIZE * 2; 

        for (const tile of this._tileCache) {
            // A visual tile is roughly at (px, py - h).
            // Hex radius is HEX_SIZE.
            // If mouse is too far, skip.
            const dist = Math.abs(wx - tile.px) + Math.abs(wy - (tile.py - tile.h));
            if (dist < limit) { 
                candidates.push(tile);
            }
        }

        // Sort by Visual Depth (Front to Back).
        // In this isometric projection, higher 'py' means closer to the bottom of the screen (Front).
        // We iterate front-to-back so we pick the first one that the mouse hits (handling occlusion).
        candidates.sort((a, b) => b.py - a.py);

        for (const cand of candidates) {
            // Project the world mouse coordinate "down" to the plane of this tile's top face.
            // The top face is visually at (px, py - h).
            // To check if the mouse (wx, wy) is on it, we treat the mouse as if it were at (wx, wy + h) on the 2D ground plane.
            const testHex = HexUtils.fromPx(wx, wy + cand.h, engine.mapConfig);
            const rounded = HexUtils.round(testHex.q, testHex.r);

            if (rounded.q === cand.q && rounded.r === cand.r) {
                return { q: cand.q, r: cand.r };
            }
        }

        return null;
    }

    /**
     * Identifies agents that are visually blocked by taller terrain in front of them.
     */
    getOccludedAgents(engine: GameEngine): Agent[] {
        const occluded: Agent[] = [];

        engine.agents.forEach(a => {
            if (a.hp <= 0 && a.fullyDead) return;

            const uPx = HexUtils.toPx(a.q, a.r, engine.mapConfig);
            const uHeight = this.getTerrainHeight(a.q, a.r);

            // In Diamond Isometric, "Front" means Higher Y on screen.
            // Blocks with higher Y and higher Z can occlude units with lower Y.
            const neighbors = HexUtils.neighbors({q: a.q, r: a.r});
            let isBlocked = false;

            for (const n of neighbors) {
                const k = HexUtils.key(n);
                if (engine.mapKeys.has(k)) {
                    const nPx = HexUtils.toPx(n.q, n.r, engine.mapConfig);

                    // Check if neighbor is physically "in front" (Screen Y is larger)
                    if (nPx.y > uPx.y) {
                         const nHeight = this.getTerrainHeight(n.q, n.r);
                         // If the blocking tile is taller than unit base
                         if (nHeight >= uHeight + 10) {
                             isBlocked = true;
                             break;
                         }
                    }
                }
            }

            if (isBlocked) {
                occluded.push(a);
            }
        });

        return occluded;
    }

    collectRenderables(
        engine: GameEngine, 
        hoveredHex: Hex | null, 
        hoveredSkill: Skill | null, 
        highlightAgent: Agent | null, 
        flashes: any[],
        projectiles: Projectile[],
        transitionT: number,      // 0.0 to 1.0
        transitionPhase: 'IN' | 'OUT' | 'IDLE',
        globalTime: number // Added time for particle animation
    ): RenderableItem[] {
        this.ensureCache(engine);

        const list: RenderableItem[] = [];
        const scene = engine.currentScene;
        const theme = TERRAIN_THEMES[scene.textureType] || TERRAIN_THEMES['VOID'];

        // Pre-calculate Danger Zones with Progress
        const dangerZones = new Map<string, {color: string, progress: number}>();
        engine.agents.forEach(a => {
            if (a.hp > 0 && a.castingSkillIdx !== -1) {
                const s = a.skills[a.castingSkillIdx];
                if (s && s.type === 'AOE') {
                    let centerHex: Hex | null = null;
                    if (a.targetHex) centerHex = a.targetHex;
                    else if (a.target) centerHex = {q: a.target.q, r: a.target.r};
                    else centerHex = {q: a.q, r: a.r};

                    if (centerHex) {
                        const progress = 1 - (a.castTimer / s.cast);
                        HexUtils.range(centerHex, s.aoeRadius || 1).forEach(h => {
                            dangerZones.set(`${h.q},${h.r}`, {
                                color: s.color, 
                                progress: progress
                            });
                        });
                    }
                }
            }
        });

        const unitPresence = new Map<string, boolean>();
        const unitVisualStatus = new Map<string, string>(); // 'FROZEN', 'POLYMORPH', etc.

        engine.agents.forEach(a => {
            if(a.hp > 0) {
                const key = `${a.q},${a.r}`;
                unitPresence.set(key, true);
                if (a.visualStatus !== 'NONE') {
                    unitVisualStatus.set(key, a.visualStatus);
                }
            }
        });

        // Center calculation for Wave Effect
        const centerQ = Math.floor(engine.mapConfig.w / 2);
        const centerR = Math.floor(engine.mapConfig.h / 2);
        const maxDist = Math.max(engine.mapConfig.w, engine.mapConfig.h) / 2;

        // Use cached tiles instead of parsing mapKeys
        for (const tile of this._tileCache) {
            const { q, r, px, py, h } = tile;

            // --- TRANSITION LOGIC ---
            let visualY = py;

            if (transitionPhase !== 'IDLE') {
                const dist = Math.sqrt((q - centerQ)**2 + (r - centerR)**2);
                const d = dist / maxDist; 

                if (transitionPhase === 'OUT') {
                    const trigger = d * 0.3;
                    if (transitionT > trigger) {
                        const fallT = Math.min(1, (transitionT - trigger) * 2.5);
                        const easedFall = fallT * fallT * fallT;
                        visualY += easedFall * 1000;
                    }
                } else if (transitionPhase === 'IN') {
                    const trigger = d * 0.3;
                    const riseT = Math.max(0, Math.min(1, (transitionT - trigger) * 2.5));
                    const easedRise = 1 - Math.pow(1 - riseT, 3);
                    visualY += (1 - easedRise) * 1000;
                }
            }

            // Cull if too far off screen
            if (visualY > py + 800) continue;

            const flash = flashes.find(f => f.q === q && f.r === r);
            let isRange = false;
            let rangeColor = '';

            if (hoveredSkill && highlightAgent) {
                if (HexUtils.dist({q, r}, highlightAgent) <= hoveredSkill.range) {
                    isRange = true; 
                    rangeColor = hoveredSkill.color;
                }
            }

            const isHover = hoveredHex ? (hoveredHex.q === q && hoveredHex.r === r) : false;

            const k = `${q},${r}`;
            const dangerInfo = dangerZones.get(k);
            const hasUnit = unitPresence.has(k);
            const specialStatus = unitVisualStatus.get(k);

            // Dynamic Lighting
            let lightColor = null;
            let lightIntensity = 0;
            const PROJ_LIGHT_RADIUS = 40; 
            const PROJ_LIGHT_RADIUS_SQ = PROJ_LIGHT_RADIUS * PROJ_LIGHT_RADIUS;

            for (const p of projectiles) {
                const distSq = (p.x - px)**2 + (p.y - py)**2;
                if (distSq < PROJ_LIGHT_RADIUS_SQ) {
                    lightColor = p.skill.color;
                    lightIntensity += (1 - Math.sqrt(distSq) / PROJ_LIGHT_RADIUS);
                }
            }

            list.push({
                y: visualY, 
                z: 0,        
                draw: (ctx) => this.drawIsoBlock(
                    ctx, 
                    px, visualY, 
                    HEX_SIZE, h, 
                    theme, 
                    flash, 
                    isRange, rangeColor, 
                    isHover, 
                    dangerInfo, 
                    hasUnit,
                    lightColor,
                    Math.min(1, lightIntensity),
                    q, r, scene.textureType,
                    specialStatus,
                    globalTime
                )
            });
        }

        return list;
    }

    private drawIsoBlock(
        ctx: CanvasRenderingContext2D, 
        x: number, y: number, 
        size: number, height: number, 
        theme: any, 
        flash: any, 
        isRange: boolean, rangeColor: string, 
        isHover: boolean, 
        dangerInfo: {color: string, progress: number} | undefined, 
        hasUnit: boolean,
        lightColor: string | null,
        lightIntensity: number,
        q: number = 0, r: number = 0, textureType: string = 'VOID',
        specialStatus: string | undefined,
        globalTime: number
    ) {
        // FFT Style: Squashed Hexagon to simulate 30 degree pitch
        const Y_SCALE = 0.6; 

        const corners: {x: number, y: number}[] = [];
        const startAngle = Math.PI / 6; 

        for (let i = 0; i < 6; i++) {
            const angle = startAngle + i * Math.PI / 3;
            corners.push({ 
                x: x + size * Math.cos(angle), 
                y: y + size * Math.sin(angle) * Y_SCALE 
            });
        }

        const topY = height; 

        // Define top face path creation used multiple times
        const traceTopFace = () => {
            ctx.beginPath();
            ctx.moveTo(corners[0].x, corners[0].y - topY);
            for (let i = 1; i < 6; i++) {
                ctx.lineTo(corners[i].x, corners[i].y - topY);
            }
            ctx.closePath();
        };

        // --- 1. Draw Side Faces ---
        for (let i = 0; i < 6; i++) {
            const j = (i + 1) % 6;
            const y1 = corners[i].y;
            const y2 = corners[j].y;

            if ((y1 - y) + (y2 - y) >= -0.1) { 
                 const grad = ctx.createLinearGradient(0, y - topY, 0, y);
                 const baseColor = (i % 2 === 0) ? theme.sideDark : theme.sideLight;
                 grad.addColorStop(0, baseColor);
                 grad.addColorStop(1, '#020617'); 

                 ctx.fillStyle = grad;
                 ctx.beginPath();
                 ctx.moveTo(corners[i].x, corners[i].y);
                 ctx.lineTo(corners[j].x, corners[j].y);
                 ctx.lineTo(corners[j].x, corners[j].y - topY);
                 ctx.lineTo(corners[i].x, corners[i].y - topY);
                 ctx.closePath();
                 ctx.fill();

                 ctx.strokeStyle = 'rgba(255,255,255,0.05)'; 
                 ctx.lineWidth = 1; 
                 ctx.stroke();
            }
        }

        // --- 2. Draw Top Face (Base) ---
        traceTopFace();

        const topGrad = ctx.createRadialGradient(x, y - topY, 0, x, y - topY, size);
        topGrad.addColorStop(0, theme.top);
        topGrad.addColorStop(1, theme.detail); 
        ctx.fillStyle = topGrad;
        ctx.fill();

        // --- 2.5 Draw Terrain Texture (Detailing) ---
        // Warning: This may destroy the current path!
        this.drawTerrainDetail(ctx, x, y - topY, size, q, r, textureType, theme.detail);

        // --- 2.6 SPECIAL STATUS FLOOR EFFECT ---
        if (specialStatus) {
            traceTopFace(); // Restore path
            ctx.save();
            ctx.globalCompositeOperation = 'overlay';
            if (specialStatus === 'FROZEN') {
                ctx.fillStyle = '#bae6fd'; 
                ctx.globalAlpha = 0.6;
            } else if (specialStatus === 'POLYMORPH') {
                ctx.fillStyle = '#d8b4fe'; 
                ctx.globalAlpha = 0.5;
            } else if (specialStatus === 'STASIS') {
                ctx.fillStyle = '#fde047';
                ctx.globalAlpha = 0.5;
            }
            ctx.fill(); 
            ctx.restore();
        }

        // --- 2.7 AOE TELEGRAPH (Colored Tile + Rising Particles) ---
        if (dangerInfo) {
            traceTopFace(); // Restore path
            ctx.save();
            // 1. Tile Coloring
            // Intensity ramps up: 0.1 -> 0.7 opacity
            const opacity = 0.1 + dangerInfo.progress * 0.6;

            ctx.fillStyle = dangerInfo.color;
            ctx.globalAlpha = opacity;
            ctx.globalCompositeOperation = 'source-over'; 
            ctx.fill(); // Fill the top face path

            // 2. Glowing Border
            ctx.strokeStyle = dangerInfo.color;
            ctx.lineWidth = 1 + dangerInfo.progress * 2;
            ctx.globalAlpha = 0.8;
            ctx.stroke();

            // 3. Rising Particles
            if (dangerInfo.progress > 0.2) {
                const particleCount = 3 + Math.floor(dangerInfo.progress * 5);
                ctx.fillStyle = dangerInfo.color;
                ctx.globalCompositeOperation = 'lighter'; 

                for(let i=0; i<particleCount; i++) {
                    const seed = (Math.abs(q * 100 + r * 10) + i * 123.45);
                    const speed = 20 + (seed % 20);
                    const t = (globalTime * speed * 0.05 + seed) % 1; 
                    const pAlpha = 1 - t;

                    const pX = x + Math.sin(t * 10 + seed) * (size * 0.5);
                    const pY = (y - topY) - (t * 40); 

                    ctx.globalAlpha = pAlpha * opacity; 
                    const pSize = 1 + (seed % 2);

                    ctx.beginPath();
                    ctx.arc(pX, pY, pSize, 0, Math.PI*2);
                    ctx.fill();
                }
            }
            ctx.restore();
        }

        // --- 3. Dynamic Lighting ---
        if (lightColor && lightIntensity > 0) {
            traceTopFace(); // Restore path
            ctx.save();
            ctx.globalCompositeOperation = 'lighter'; 
            ctx.globalAlpha = lightIntensity * 0.8; 
            ctx.fillStyle = lightColor;
            ctx.fill();
            ctx.restore();
        }

        // --- 4. Interactive Overlays ---
        if (flash || isRange || isHover || hasUnit) {
            ctx.save();
            traceTopFace(); // Restore path explicitly just in case

            if (isRange) { 
                ctx.fillStyle = rangeColor;
                ctx.globalAlpha = 0.2; 
                ctx.fill();
                ctx.strokeStyle = rangeColor; 
                ctx.lineWidth = 2; 
                ctx.globalAlpha = 0.8; 
                ctx.stroke();
            }

            if (isHover) { 
                ctx.fillStyle = 'rgba(255,255,255,0.15)'; 
                ctx.globalAlpha = 1.0;
                ctx.fill(); 
                ctx.strokeStyle = '#fff'; 
                ctx.lineWidth = 3; 
                ctx.stroke(); 
            }

            if (flash) {
                ctx.globalCompositeOperation = 'lighter';
                ctx.fillStyle = flash.color;
                ctx.globalAlpha = 0.6;
                ctx.fill();
                ctx.strokeStyle = '#fff';
                ctx.lineWidth = 2;
                ctx.stroke();
            }

            if (hasUnit && !isHover && !dangerInfo) {
                ctx.strokeStyle = 'rgba(255,255,255,0.3)';
                ctx.lineWidth = 1;
                ctx.stroke();
            }

            ctx.restore();
        }
    }

    private noise(q: number, r: number) {
        return Math.sin(q * 12.9898 + r * 78.233) * 43758.5453 - Math.floor(Math.sin(q * 12.9898 + r * 78.233) * 43758.5453);
    }

    private drawTerrainDetail(
        ctx: CanvasRenderingContext2D, 
        cx: number, cy: number, 
        size: number, 
        q: number, r: number, 
        type: string, 
        detailColor: string
    ) {
        ctx.save();
        ctx.fillStyle = detailColor;
        ctx.strokeStyle = detailColor;
        ctx.globalAlpha = 0.3; 

        const n = this.noise(q, r);
        const n2 = this.noise(r, q);

        if (type === 'VOID') {
            if (n > 0.6) {
                ctx.lineWidth = 1;
                ctx.beginPath();
                ctx.moveTo(cx - 10, cy - 5);
                ctx.lineTo(cx, cy + 5);
                ctx.lineTo(cx + 10, cy - 2);
                ctx.stroke();
            } else if (n < 0.3) {
                ctx.beginPath();
                ctx.arc(cx + n2 * 10, cy + n * 10, 2, 0, Math.PI * 2);
                ctx.fill();
            }
        } else if (type === 'FOREST') {
            const tufts = Math.floor(n * 3) + 1;
            for(let i=0; i<tufts; i++) {
                const ox = (this.noise(q+i, r) - 0.5) * 20;
                const oy = (this.noise(r, q+i) - 0.5) * 10;
                ctx.beginPath();
                ctx.moveTo(cx + ox, cy + oy);
                ctx.lineTo(cx + ox - 3, cy + oy - 5);
                ctx.moveTo(cx + ox, cy + oy);
                ctx.lineTo(cx + ox + 3, cy + oy - 5);
                ctx.stroke();
            }
        } else if (type === 'ICE') {
            ctx.globalAlpha = 0.5;
            ctx.fillStyle = '#fff';
            if (n > 0.5) {
                ctx.beginPath();
                ctx.moveTo(cx - 15, cy + 5);
                ctx.lineTo(cx + 15, cy - 5);
                ctx.lineTo(cx + 18, cy - 4);
                ctx.lineTo(cx - 12, cy + 6);
                ctx.fill();
            }
        } else if (type === 'MAGMA') {
            ctx.strokeStyle = '#000';
            ctx.lineWidth = 1;
            ctx.globalAlpha = 0.4;
            ctx.beginPath();
            ctx.moveTo(cx - 10, cy);
            ctx.lineTo(cx - 5, cy + 5 * n);
            ctx.lineTo(cx + 5, cy - 5 * n2);
            ctx.lineTo(cx + 10, cy);
            ctx.stroke();
            if (n > 0.8) {
                ctx.fillStyle = '#ef4444';
                ctx.globalAlpha = 0.6;
                ctx.beginPath(); ctx.arc(cx, cy, 3, 0, Math.PI*2); ctx.fill();
            }
        } else if (type === 'DESERT') {
            ctx.strokeStyle = '#92400e';
            ctx.lineWidth = 2;
            ctx.globalAlpha = 0.2;
            ctx.beginPath();
            ctx.arc(cx - 10, cy - 10, 30, 0.5, 2.0);
            ctx.stroke();
        }

        ctx.restore();
    }
}

import { Agent, GameEngine } from "../game";
import { HexUtils, Vector, NEIGHBOR_HASH_OFFSETS } from "../utils";
import { AnimState, Hex, NodeState } from "../../types";

// Constants extracted from game.ts
const PATHFINDING_MAX_ITERATIONS = 2500; 
const QUEUE_CAPACITY = 4096; 
const STACKING_RESOLUTION_FORCE = 5;

const PHYSICS_STIFFNESS_ALIVE = 150;
const PHYSICS_STIFFNESS_DEAD = 0;
// INCREASED DAMPING: Makes units stop snappier, reducing "floating" feel
const PHYSICS_DAMPING_ALIVE = 25; 
const PHYSICS_DAMPING_DEAD = 1.0; 

const GRAVITY = 2000; 

export class MovementSystem {
    // Pathfinding Memory Buffers (Reused to avoid GC)
    private _pfQueue: Int32Array; 
    private _pfCameFrom: Map<number, number> = new Map();
    private _pfBlockers: Set<number> = new Set();

    constructor() {
        this._pfQueue = new Int32Array(QUEUE_CAPACITY);
    }

    // =========================================================================================
    // 🏃 MOVEMENT & PHYSICS
    // =========================================================================================

    public updatePhysics(a: Agent, dt: number, engine: GameEngine) {
        const isDead = a.hp <= 0;
        const stiffness = isDead ? PHYSICS_STIFFNESS_DEAD : PHYSICS_STIFFNESS_ALIVE; 

        // If airborne (z > 0), reduce drag to allow projectile motion
        const isAirborne = a.physics.z > 0;
        const damping = (isDead && isAirborne) ? 0.5 : (isDead ? PHYSICS_DAMPING_DEAD : PHYSICS_DAMPING_ALIVE);

        // 1. Spring Forces (Return to 0,0 relative local space)
        const fx = -stiffness * a.physics.x;
        const fy = -stiffness * a.physics.y;
        const fRot = -stiffness * a.physics.angle * 0.1; 

        // 2. Acceleration (Force - Damping)
        const ax = fx - damping * a.physics.vx;
        const ay = fy - damping * a.physics.vy;
        const aRot = fRot - damping * a.physics.vAngle;

        // 3. Integrate Velocity
        a.physics.vx += ax * dt;
        a.physics.vy += ay * dt;
        a.physics.vAngle += aRot * dt;

        // 4. Gravity (Z-axis)
        if (isDead) {
            a.physics.vz -= GRAVITY * dt;
        }

        // 5. Integrate Position
        a.physics.x += a.physics.vx * dt;
        a.physics.y += a.physics.vy * dt;
        a.physics.z += a.physics.vz * dt;
        a.physics.angle += a.physics.vAngle * dt;

        // 6. Ground Collision (Bounce)
        if (a.physics.z < 0) {
            a.physics.z = 0;
            // Elastic collision with ground loss
            if (Math.abs(a.physics.vz) > 100) {
                a.physics.vz = -a.physics.vz * 0.5; // Bounce back
                a.physics.vx *= 0.6; // Ground friction
                a.physics.vy *= 0.6;
                a.physics.vAngle *= 0.5;
            } else {
                a.physics.vz = 0;
            }
        }

        // 7. World Position Drift (Slide effect for dead units)
        if (!isDead && !a.isMoving) {
            const targetPos = HexUtils.toPx(a.q, a.r, engine.mapConfig);
            const dx = targetPos.x - a.px;
            const dy = targetPos.y - a.py;
            const distSq = dx*dx + dy*dy;

            // Increased snap threshold to stop jitter
            if (distSq > 0.5) {
                const driftSpeed = 12.0 * dt;
                a.px += dx * driftSpeed;
                a.py += dy * driftSpeed;
                if (distSq < 2) {
                    a.px = targetPos.x;
                    a.py = targetPos.y;
                }
            } else {
                a.px = targetPos.x;
                a.py = targetPos.y;
            }
        } else if (isDead) {
            // Apply physics velocity to world position (Flying through air)
            a.px += a.physics.vx * dt * 0.1; 
            a.py += a.physics.vy * dt * 0.1;
        }
    }

    public updateMovement(a: Agent, dt: number, engine: GameEngine) {
        // Use per-agent move speed WITH dynamic multiplier (Charge effect)
        a.moveProgress += a.moveSpeed * a.moveSpeedMult * dt;

        const c = HexUtils.toPx(a.q, a.r, engine.mapConfig);
        const nextHex = a.path[0];
        const n = HexUtils.toPx(nextHex.q, nextHex.r, engine.mapConfig);

        if (n.x > c.x) a.facing = 1;
        else if (n.x < c.x) a.facing = -1;

        a.px = HexUtils.lerp(c.x, n.x, a.moveProgress);
        a.py = HexUtils.lerp(c.y, n.y, a.moveProgress);

        if (a.moveProgress >= 1) {
            // Commit move
            engine.updateAgentPosition(a, nextHex.q, nextHex.r);

            a.isMoving = false;
            a.moveSpeedMult = 1.0; // Reset speed after step completes

            // Small nudge to separate stacked units visually if they glitch
            a.physics.vx -= a.facing * STACKING_RESOLUTION_FORCE; 
        }
    }

    public moveAgentToHex(a: Agent, targetHex: Hex, r: number, engine: GameEngine, speedMult: number = 1.0): NodeState {
        if (a.isMoving) {
            a.moveSpeedMult = speedMult; // Update dynamic speed
            a.setAnim(AnimState.MOVE);
            return NodeState.RUNNING;
        }

        // Check range
        if (HexUtils.dist(a, targetHex) <= r) {
            a.setAnim(AnimState.COMBAT_IDLE);
            return NodeState.SUCCESS;
        }

        // 1. Try Standard Pathfinding (Respecting Allies)
        let path = this.findPath(a, targetHex.q, targetHex.r, r, false, engine);

        // 2. Fallback: Ghost Pathfinding (Ignoring Allies)
        // If normal path failed, try to find a path ignoring units to see if "direction" exists
        if (path.length === 0) {
            path = this.findPath(a, targetHex.q, targetHex.r, r, true, engine); // true = ignoreUnits
        }

        if (path.length > 0) {
            const next = path[0];

            // CRITICAL CHECK: Even if we found a ghost path, is the IMMEDIATE NEXT STEP blocked?
            if (engine.isBlocked(next.q, next.r, a.id)) {
                // We know where we WANT to go, but it's blocked right now.
                // Instead of failing (which causes AI jitter/wandering), we WAIT.
                // This simulates "queueing" behind the frontline.
                a.setAnim(AnimState.COMBAT_IDLE); 
                // Return RUNNING to keep the AI node active, preventing re-calculation jitter
                return NodeState.RUNNING; 
            }

            a.path = [next];
            a.trajectory = path; // Visual only
            a.isMoving = true;
            a.moveProgress = 0;
            a.moveSpeedMult = speedMult;
            a.setAnim(AnimState.MOVE);

            // Physics Lean
            const dir = a.facing;
            a.physics.vx += dir * 2; 

            return NodeState.RUNNING;
        }

        // Truly unreachable (walled off)
        return NodeState.FAILURE;
    }

    public moveAgent(a: Agent, t: Agent, r: number, engine: GameEngine, speedMult: number = 1.0): NodeState {
        // When chasing a unit, we want to get within range R of them.
        // We don't necessarily need to step ON their tile.
        return this.moveAgentToHex(a, {q: t.q, r: t.r}, r, engine, speedMult);
    }

    public resolveStacking(engine: GameEngine) {
        const map = new Map<number, Agent[]>();

        engine.agents.forEach(a => {
            if (a.hp <= 0 || a.banished) return;
            const h = HexUtils.hash(a.q, a.r);
            if (!map.has(h)) map.set(h, []);
            map.get(h)!.push(a);
        });

        map.forEach((list, hash) => {
            if (list.length > 1) {
                const coords = HexUtils.unhash(hash);

                const stationary = list.filter(a => !a.isMoving);
                const keep = stationary.length > 0 ? stationary[0] : list[0];
                const toDisplace = list.filter(a => a !== keep);

                toDisplace.forEach(agent => {
                    const neighbors = HexUtils.neighbors(coords);
                    for (let i = neighbors.length - 1; i > 0; i--) {
                        const j = Math.floor(Math.random() * (i + 1));
                        [neighbors[i], neighbors[j]] = [neighbors[j], neighbors[i]];
                    }

                    let target = neighbors.find(n => engine.map.isValid(n.q, n.r) && !engine.map.isBlocked(n.q, n.r, engine));

                    // Fallback: Try valid but not obstacle (ignoring units)
                    if (!target) target = neighbors.find(n => engine.map.isValid(n.q, n.r) && !engine.map.hasObstacle(n.q, n.r));

                    if (target) {
                        engine.updateAgentPosition(agent, target.q, target.r);
                        // Cancel current move to allow physics drift to slide unit visually
                        if (agent.isMoving) {
                            agent.isMoving = false;
                            agent.path = [];
                        }
                    }
                });
            }
        });
    }

    // =========================================================================================
    // 🗺️ PATHFINDING (A* / Multi-Layer BFS)
    // =========================================================================================

    public findPath(
        startAgent: Agent, 
        endQ: number, 
        endR: number, 
        range: number,
        ignoreUnits: boolean, 
        engine: GameEngine
    ): Hex[] {
        const startH = HexUtils.hash(startAgent.q, startAgent.r);

        // Optimization: Pre-check if start satisfies range
        const startDist = HexUtils.dist({q: startAgent.q, r: startAgent.r}, {q: endQ, r: endR});
        if (startDist <= range) return [];

        this._pfCameFrom.clear();
        this._pfBlockers.clear();

        // 1. Populate Blockers
        // If ignoreUnits is TRUE (Ghost Mode), we only block Walls/Obstacles
        if (!ignoreUnits) {
            for (const a of engine.agents) {
                if (a.hp > 0 && !a.banished && a !== startAgent) {
                    // Don't mark the target unit as a "Blocker" if we just need to get in range of it
                    // But actually, we usually want to move to an adjacent tile, not INSIDE the target.
                    // So marking units as blockers is correct, but the EXIT condition of BFS handles the range.
                    const h = HexUtils.hash(a.q, a.r);
                    this._pfBlockers.add(h);

                    if (a.isMoving && a.path.length > 0) {
                        const hp = HexUtils.hash(a.path[0].q, a.path[0].r);
                        this._pfBlockers.add(hp);
                    }
                }
            }
        }

        let head = 0; 
        let tail = 0; 
        this._pfQueue[head++] = startH; 
        this._pfCameFrom.set(startH, -1); 

        let iterations = 0;
        let foundHash = -1;
        const targetHex = { q: endQ, r: endR };

        while (tail < head) {
            iterations++;
            if (iterations > PATHFINDING_MAX_ITERATIONS) break;

            const currentH = this._pfQueue[tail++]; 
            const currentHex = HexUtils.unhash(currentH);

            // SUCCESS CONDITION: Inside Range?
            if (HexUtils.dist(currentHex, targetHex) <= range) {
                foundHash = currentH;
                break;
            }

            for(let j = 0; j < 6; j++) {
                const offset = NEIGHBOR_HASH_OFFSETS[j];
                const nextH = currentH + offset;

                if (this._pfCameFrom.has(nextH)) continue;

                // Map Bounds Check
                if (!engine.map.isValidHash(nextH)) continue;

                // Static Obstacle Check (Always active)
                if (engine.map.hasObstacleHash(nextH)) continue;

                // Dynamic Unit Check (Only if not ignoring units)
                if (!ignoreUnits && this._pfBlockers.has(nextH)) {
                    // However, if nextH IS the exact destination and range=0, we might want to allow it?
                    // No, for movement we move to neighbors.
                    continue;
                }

                this._pfCameFrom.set(nextH, currentH);

                if (head < QUEUE_CAPACITY) {
                    this._pfQueue[head++] = nextH;
                }
            }
        }

        if (foundHash !== -1) {
            const path: Hex[] = [];
            let curr = foundHash;

            let sanity = 0;
            while (curr !== startH && sanity++ < 100) {
                path.push(HexUtils.unhash(curr));
                const prev = this._pfCameFrom.get(curr);
                if (prev === undefined || prev === -1) break;
                curr = prev;
            }
            return path.reverse();
        }

        return [];
    }

    // =========================================================================================
    // 🎯 TARGETING & TACTICS
    // =========================================================================================

    public updateTarget(a: Agent, engine: GameEngine) {
        if (a.target && (a.target.hp <= 0 || a.target.banished)) a.target = null;
        let minD = 999;
        let t: Agent | null = null;

        for (const o of engine.agents) {
            if (o.team !== a.team && o.hp > 0 && !o.banished) {
                const d = HexUtils.dist(a, o);
                if (d < minD) { minD = d; t = o; }
            }
        }
        a.target = t;
    }

    public calculateOptimalTarget(source: Agent, skill: any, engine: GameEngine): { targetAgent: Agent | null, targetHex: Hex | null } {
        if (skill.ccType === 'SILENCE' || skill.ccType2 === 'SILENCE') {
            const enemies = engine.agents.filter(a => 
                a.team !== source.team && a.hp > 0 && !a.banished && 
                HexUtils.dist(source, a) <= skill.range
            );

            if (enemies.length > 0) {
                enemies.sort((a, b) => {
                    const score = (u: Agent) => {
                        if (u.castingSkillIdx === -1) return 0;
                        const s = u.skills[u.castingSkillIdx];
                        if (s?.tag === 'ULT') return 3;
                        if (s?.tag === 'ACTIVE') return 2;
                        return 1;
                    };
                    const sA = score(a);
                    const sB = score(b);
                    if (sA !== sB) return sB - sA;
                    return HexUtils.dist(source, a) - HexUtils.dist(source, b);
                });
                return { targetAgent: enemies[0], targetHex: null };
            }
        }

        if (skill.type === 'AOE') {
            const candidateHexes = new Set<number>();
            const radius = skill.aoeRadius || 1;
            const searchDist = skill.range + 3;

            engine.agents.forEach(enemy => {
                if (enemy.team !== source.team && enemy.hp > 0 && !enemy.banished) {
                    if (HexUtils.dist(source, enemy) <= searchDist) {
                        candidateHexes.add(HexUtils.hash(enemy.q, enemy.r));
                        HexUtils.neighbors(enemy).forEach(n => candidateHexes.add(HexUtils.hash(n.q, n.r)));
                    }
                }
            });

            let bestHex: Hex | null = null;
            let bestScore = -1;

            candidateHexes.forEach(hHash => {
                const h = HexUtils.unhash(hHash);
                if (!engine.map.isValid(h.q, h.r)) return;

                let score = 0;
                let hitCount = 0;

                for (const target of engine.agents) {
                    if (target.hp <= 0 || target.banished) continue;

                    if (HexUtils.dist(h, target) <= radius) {
                        if (skill.power >= 0) {
                            if (target.team !== source.team) {
                                hitCount++;
                                score += 10;
                                if (target.castingSkillIdx !== -1) score += 5;
                            }
                        } else {
                            if (target.team === source.team) {
                                hitCount++;
                                score += 10;
                                if (target.hp < target.maxHp * 0.5) score += 5;
                            }
                        }
                    }
                }

                if (hitCount > 0 && score > bestScore) {
                    bestScore = score;
                    bestHex = h;
                }
            });

            if (bestHex) {
                return { targetAgent: null, targetHex: bestHex };
            }
        }

        let minD = 999;
        let t: Agent | null = null;
        for (const o of engine.agents) {
            if (o.team !== source.team && o.hp > 0 && !o.banished) {
                const d = HexUtils.dist(source, o);
                if (d <= skill.range && d < minD) { minD = d; t = o; }
            }
        }
        return { targetAgent: t, targetHex: null };
    }
}

