import { HEX_SIZE, BLOCK_HEIGHT, TERRAIN_THEMES, MAX_TERRAIN_TIER } from "../../constants";
import { GameEngine, Agent } from "../game";
import { HexUtils } from "../utils";
import { AssetManager } from "../assets";
import { Hex, Skill, Projectile } from "../../types";

export interface RenderableItem {
    y: number;
    z: number;
    draw: (ctx: CanvasRenderingContext2D) => void;
}

interface CachedTile {
    q: number;
    r: number;
    px: number;
    py: number;
    h: number;
}

export class GridSystem {
    private heightCache: Map<string, number> = new Map();
    public terrainDepth: number = 1.0; // 1.0 = Standard, >1.0 = Deep

    // Optimization: Cache tiles to avoid re-parsing keys and re-calculating positions every frame
    private _tileCache: CachedTile[] = [];
    private _lastMapVersion: number = -1;

    setTerrainDepth(d: number) {
        if (Math.abs(this.terrainDepth - d) > 0.01) {
            this.terrainDepth = d;
            this.clearCache();
            this._lastMapVersion = -1; // Invalidate cache
        }
    }

    clearCache() {
        this.heightCache.clear();
    }

    private ensureCache(engine: GameEngine) {
        if (this._lastMapVersion !== engine.mapVersion || this._tileCache.length === 0) {
            this.rebuildTileCache(engine);
        }
    }

    private rebuildTileCache(engine: GameEngine) {
        this._tileCache = [];
        this._lastMapVersion = engine.mapVersion;

        engine.mapKeys.forEach(k => {
            const [q, r] = k.split(',').map(Number);
            const pos = HexUtils.toPx(q, r, engine.mapConfig);
            const h = this.getTerrainHeight(q, r);
            this._tileCache.push({ q, r, px: pos.x, py: pos.y, h });
        });
    }

    // QUANTIZED HEIGHT (Tier System)
    getTerrainHeight(q: number, r: number): number {
        const key = `${q},${r}`;
        if (this.heightCache.has(key)) return this.heightCache.get(key)!;

        // Deterministic Noise
        const n = Math.sin(q * 12.9898 + r * 78.233) * 43758.5453;
        const noise = Math.abs(n - Math.floor(n));

        // Logic:
        // Stepped Tiers: 0, 1, 2, 3...
        // Low frequency noise for smooth hills
        const n2 = Math.sin(q * 0.5 + r * 0.3) * 0.5 + 0.5; // Smooth large waves

        let tier = 0;
        if (this.terrainDepth > 1.5) {
            // Deep/Chaotic Terrain
            tier = Math.floor(noise * MAX_TERRAIN_TIER * 0.8 + n2 * 3);
        } else {
            // Standard Arena
            tier = Math.floor(n2 * 3); 
        }

        // Clamp
        tier = Math.max(0, Math.min(MAX_TERRAIN_TIER, tier));

        const h = tier * BLOCK_HEIGHT;
        this.heightCache.set(key, h);
        return h;
    }

    getHexAtScreenPoint(mx: number, my: number, camera: {x: number, y: number, zoom: number}, engine: GameEngine): Hex | null {
        this.ensureCache(engine);

        // Convert screen mouse to world coordinates (unzoomed)
        const wx = mx / camera.zoom + camera.x;
        const wy = my / camera.zoom + camera.y;

        const candidates: CachedTile[] = [];
        const limit = HEX_SIZE * 2; 

        for (const tile of this._tileCache) {
            const dist = Math.abs(wx - tile.px) + Math.abs(wy - (tile.py - tile.h));
            if (dist < limit) { 
                candidates.push(tile);
            }
        }

        // Sort by visual depth (Front to Back)
        candidates.sort((a, b) => b.py - a.py);

        for (const cand of candidates) {
            const testHex = HexUtils.fromPx(wx, wy + cand.h, engine.mapConfig);
            const rounded = HexUtils.round(testHex.q, testHex.r);
            if (rounded.q === cand.q && rounded.r === cand.r) {
                return { q: cand.q, r: cand.r };
            }
        }

        return null;
    }

    /**
     * Identifies agents that are visually blocked by taller terrain in front of them.
     */
    getOccludedAgents(engine: GameEngine): Agent[] {
        const occluded: Agent[] = [];

        engine.agents.forEach(a => {
            if (a.hp <= 0 && a.fullyDead) return;

            const uPx = HexUtils.toPx(a.q, a.r, engine.mapConfig);
            const uHeight = this.getTerrainHeight(a.q, a.r);

            // In Diamond Isometric, "Front" means Higher Y on screen.
            // Blocks with higher Y and higher Z can occlude units with lower Y.
            const neighbors = HexUtils.neighbors({q: a.q, r: a.r});
            let isBlocked = false;

            for (const n of neighbors) {
                const k = HexUtils.key(n);
                if (engine.mapKeys.has(k)) {
                    const nPx = HexUtils.toPx(n.q, n.r, engine.mapConfig);

                    // Check if neighbor is physically "in front" (Screen Y is larger)
                    if (nPx.y > uPx.y) {
                         const nHeight = this.getTerrainHeight(n.q, n.r);
                         // If the blocking tile is strictly taller
                         if (nHeight > uHeight) {
                             isBlocked = true;
                             break;
                         }
                    }
                }
            }

            if (isBlocked) {
                occluded.push(a);
            }
        });

        return occluded;
    }

    collectRenderables(
        engine: GameEngine, 
        hoveredHex: Hex | null, 
        hoveredSkill: Skill | null, 
        highlightAgent: Agent | null, 
        flashes: any[],
        projectiles: Projectile[],
        transitionT: number,      
        transitionPhase: 'IN' | 'OUT' | 'IDLE',
        globalTime: number
    ): RenderableItem[] {
        this.ensureCache(engine);

        const list: RenderableItem[] = [];
        const scene = engine.currentScene;
        const theme = TERRAIN_THEMES[scene.textureType] || TERRAIN_THEMES['VOID'];

        const dangerZones = new Map<string, {color: string, progress: number}>();
        engine.agents.forEach(a => {
            if (a.hp > 0 && a.castingSkillIdx !== -1) {
                const s = a.skills[a.castingSkillIdx];
                if (s && s.type === 'AOE') {
                    let centerHex: Hex | null = null;
                    if (a.targetHex) centerHex = a.targetHex;
                    else if (a.target) centerHex = {q: a.target.q, r: a.target.r};
                    else centerHex = {q: a.q, r: a.r};

                    if (centerHex) {
                        const progress = 1 - (a.castTimer / s.cast);
                        HexUtils.range(centerHex, s.aoeRadius || 1).forEach(h => {
                            dangerZones.set(`${h.q},${h.r}`, {
                                color: s.color, 
                                progress: progress
                            });
                        });
                    }
                }
            }
        });

        const unitPresence = new Map<string, boolean>();
        const unitVisualStatus = new Map<string, string>(); 

        engine.agents.forEach(a => {
            if(a.hp > 0) {
                const key = `${a.q},${a.r}`;
                unitPresence.set(key, true);
                if (a.visualStatus !== 'NONE') {
                    unitVisualStatus.set(key, a.visualStatus);
                }
            }
        });

        const centerQ = Math.floor(engine.mapConfig.w / 2);
        const centerR = Math.floor(engine.mapConfig.h / 2);
        const maxDist = Math.max(engine.mapConfig.w, engine.mapConfig.h) / 2;

        for (const tile of this._tileCache) {
            const { q, r, px, py, h } = tile;

            // --- TRANSITION LOGIC ---
            let visualY = py;

            if (transitionPhase !== 'IDLE') {
                const dist = Math.sqrt((q - centerQ)**2 + (r - centerR)**2);
                const d = dist / maxDist; 

                if (transitionPhase === 'OUT') {
                    const trigger = d * 0.3;
                    if (transitionT > trigger) {
                        const fallT = Math.min(1, (transitionT - trigger) * 2.5);
                        const easedFall = fallT * fallT * fallT;
                        visualY += easedFall * 1000;
                    }
                } else if (transitionPhase === 'IN') {
                    const trigger = d * 0.3;
                    const riseT = Math.max(0, Math.min(1, (transitionT - trigger) * 2.5));
                    const easedRise = 1 - Math.pow(1 - riseT, 3);
                    visualY += (1 - easedRise) * 1000;
                }
            }

            if (visualY > py + 800) continue;

            const flash = flashes.find(f => f.q === q && f.r === r);
            let isRange = false;
            let rangeColor = '';

            if (hoveredSkill && highlightAgent) {
                if (HexUtils.dist({q, r}, highlightAgent) <= hoveredSkill.range) {
                    isRange = true; 
                    rangeColor = hoveredSkill.color;
                }
            }

            const isHover = hoveredHex ? (hoveredHex.q === q && hoveredHex.r === r) : false;

            const k = `${q},${r}`;
            const dangerInfo = dangerZones.get(k);
            const hasUnit = unitPresence.has(k);
            const specialStatus = unitVisualStatus.get(k);

            let lightColor = null;
            let lightIntensity = 0;
            const PROJ_LIGHT_RADIUS = 40; 
            const PROJ_LIGHT_RADIUS_SQ = PROJ_LIGHT_RADIUS * PROJ_LIGHT_RADIUS;

            for (const p of projectiles) {
                const distSq = (p.x - px)**2 + (p.y - py)**2;
                if (distSq < PROJ_LIGHT_RADIUS_SQ) {
                    lightColor = p.skill.color;
                    lightIntensity += (1 - Math.sqrt(distSq) / PROJ_LIGHT_RADIUS);
                }
            }

            list.push({
                y: visualY, 
                z: 0,        
                draw: (ctx) => this.drawIsoBlock(
                    ctx, 
                    px, visualY, 
                    HEX_SIZE, h, 
                    theme, 
                    flash, 
                    isRange, rangeColor, 
                    isHover, 
                    dangerInfo, 
                    hasUnit,
                    lightColor,
                    Math.min(1, lightIntensity),
                    q, r, scene.textureType,
                    specialStatus,
                    globalTime
                )
            });
        }

        return list;
    }

    private drawIsoBlock(
        ctx: CanvasRenderingContext2D, 
        x: number, y: number, 
        size: number, height: number, 
        theme: any, 
        flash: any, 
        isRange: boolean, rangeColor: string, 
        isHover: boolean, 
        dangerInfo: {color: string, progress: number} | undefined, 
        hasUnit: boolean,
        lightColor: string | null,
        lightIntensity: number,
        q: number = 0, r: number = 0, textureType: string = 'VOID',
        specialStatus: string | undefined,
        globalTime: number
    ) {
        // FFT Style: Squashed Hexagon
        const Y_SCALE = 0.6; 

        const corners: {x: number, y: number}[] = [];
        const startAngle = Math.PI / 6; 

        for (let i = 0; i < 6; i++) {
            const angle = startAngle + i * Math.PI / 3;
            corners.push({ 
                x: x + size * Math.cos(angle), 
                y: y + size * Math.sin(angle) * Y_SCALE 
            });
        }

        // This is the TOP face Y level
        const topY = height; 

        const traceTopFace = () => {
            ctx.beginPath();
            ctx.moveTo(corners[0].x, corners[0].y - topY);
            for (let i = 1; i < 6; i++) {
                ctx.lineTo(corners[i].x, corners[i].y - topY);
            }
            ctx.closePath();
        };

        // --- 1. Draw Side Faces (The Stack) ---
        // We render sides that are facing the camera (bottom 3 faces for hex)
        // Indices 0, 1, 2 are usually the top-ish faces in this corner gen order.
        // Let's check: 
        // 0: ~30 deg (Bottom Right) -> VISIBLE
        // 1: ~90 deg (Bottom) -> VISIBLE
        // 2: ~150 deg (Bottom Left) -> VISIBLE
        // 3: ~210 deg (Top Left) -> HIDDEN
        // 4: ~270 deg (Top) -> HIDDEN
        // 5: ~330 deg (Top Right) -> HIDDEN

        const visibleIndices = [0, 1, 2];

        for (const i of visibleIndices) {
            const j = (i + 1) % 6;

            const grad = ctx.createLinearGradient(0, y - topY, 0, y);
            // Alternate brightness for 3D effect
            const baseColor = (i === 1) ? theme.sideDark : theme.sideLight;
            grad.addColorStop(0, baseColor);
            grad.addColorStop(1, '#020617'); 

            ctx.fillStyle = grad;
            ctx.beginPath();
            ctx.moveTo(corners[i].x, corners[i].y); // Ground corner
            ctx.lineTo(corners[j].x, corners[j].y); // Ground next corner
            ctx.lineTo(corners[j].x, corners[j].y - topY); // Top next corner
            ctx.lineTo(corners[i].x, corners[i].y - topY); // Top corner
            ctx.closePath();
            ctx.fill();

            // "Layer Lines" for Block Stack Effect (Tactics Ogre)
            if (height > BLOCK_HEIGHT) {
                ctx.strokeStyle = 'rgba(0,0,0,0.3)';
                ctx.lineWidth = 1;
                ctx.beginPath();
                for (let hStep = BLOCK_HEIGHT; hStep < height; hStep += BLOCK_HEIGHT) {
                    ctx.moveTo(corners[i].x, corners[i].y - hStep);
                    ctx.lineTo(corners[j].x, corners[j].y - hStep);
                }
                ctx.stroke();
            }

            // Outline Side
            ctx.strokeStyle = 'rgba(255,255,255,0.05)'; 
            ctx.lineWidth = 1; 
            ctx.stroke();
        }

        // --- 2. Draw Top Face (Base) ---
        traceTopFace();

        const topGrad = ctx.createRadialGradient(x, y - topY, 0, x, y - topY, size);
        topGrad.addColorStop(0, theme.top);
        topGrad.addColorStop(1, theme.detail); 
        ctx.fillStyle = topGrad;
        ctx.fill();

        // --- 2.5 Draw Terrain Texture (Detailing) ---
        // Re-calculate noise for texture detail
        this.drawTerrainDetail(ctx, x, y - topY, size, q, r, textureType, theme.detail);

        // --- 2.6 SPECIAL STATUS FLOOR EFFECT ---
        if (specialStatus) {
            traceTopFace(); 
            ctx.save();
            ctx.globalCompositeOperation = 'overlay';
            if (specialStatus === 'FROZEN') {
                ctx.fillStyle = '#bae6fd'; 
                ctx.globalAlpha = 0.6;
            } else if (specialStatus === 'POLYMORPH') {
                ctx.fillStyle = '#d8b4fe'; 
                ctx.globalAlpha = 0.5;
            } else if (specialStatus === 'STASIS') {
                ctx.fillStyle = '#fde047';
                ctx.globalAlpha = 0.5;
            }
            ctx.fill(); 
            ctx.restore();
        }

        // --- 2.7 AOE TELEGRAPH ---
        if (dangerInfo) {
            traceTopFace(); 
            ctx.save();
            // 1. Tile Coloring
            const opacity = 0.1 + dangerInfo.progress * 0.6;
            ctx.fillStyle = dangerInfo.color;
            ctx.globalAlpha = opacity;
            ctx.globalCompositeOperation = 'source-over'; 
            ctx.fill(); 

            // 2. Glowing Border
            ctx.strokeStyle = dangerInfo.color;
            ctx.lineWidth = 1 + dangerInfo.progress * 2;
            ctx.globalAlpha = 0.8;
            ctx.stroke();

            // 3. Particles
            if (dangerInfo.progress > 0.2) {
                const particleCount = 3 + Math.floor(dangerInfo.progress * 5);
                ctx.fillStyle = dangerInfo.color;
                ctx.globalCompositeOperation = 'lighter'; 

                for(let i=0; i<particleCount; i++) {
                    const seed = (Math.abs(q * 100 + r * 10) + i * 123.45);
                    const speed = 20 + (seed % 20);
                    const t = (globalTime * speed * 0.05 + seed) % 1; 
                    const pAlpha = 1 - t;

                    const pX = x + Math.sin(t * 10 + seed) * (size * 0.5);
                    const pY = (y - topY) - (t * 40); 

                    ctx.globalAlpha = pAlpha * opacity; 
                    const pSize = 1 + (seed % 2);

                    ctx.beginPath();
                    ctx.arc(pX, pY, pSize, 0, Math.PI*2);
                    ctx.fill();
                }
            }
            ctx.restore();
        }

        // --- 3. Dynamic Lighting ---
        if (lightColor && lightIntensity > 0) {
            traceTopFace(); 
            ctx.save();
            ctx.globalCompositeOperation = 'lighter'; 
            ctx.globalAlpha = lightIntensity * 0.8; 
            ctx.fillStyle = lightColor;
            ctx.fill();
            ctx.restore();
        }

        // --- 4. Interactive Overlays ---
        if (flash || isRange || isHover || hasUnit) {
            ctx.save();
            traceTopFace(); 

            if (isRange) { 
                ctx.fillStyle = rangeColor;
                ctx.globalAlpha = 0.2; 
                ctx.fill();
                ctx.strokeStyle = rangeColor; 
                ctx.lineWidth = 2; 
                ctx.globalAlpha = 0.8; 
                ctx.stroke();
            }

            if (isHover) { 
                ctx.fillStyle = 'rgba(255,255,255,0.15)'; 
                ctx.globalAlpha = 1.0;
                ctx.fill(); 
                ctx.strokeStyle = '#fff'; 
                ctx.lineWidth = 3; 
                ctx.stroke(); 
            }

            if (flash) {
                ctx.globalCompositeOperation = 'lighter';
                ctx.fillStyle = flash.color;
                ctx.globalAlpha = 0.6;
                ctx.fill();
                ctx.strokeStyle = '#fff';
                ctx.lineWidth = 2;
                ctx.stroke();
            }

            if (hasUnit && !isHover && !dangerInfo) {
                ctx.strokeStyle = 'rgba(255,255,255,0.3)';
                ctx.lineWidth = 1;
                ctx.stroke();
            }

            ctx.restore();
        }
    }

    private noise(q: number, r: number) {
        return Math.sin(q * 12.9898 + r * 78.233) * 43758.5453 - Math.floor(Math.sin(q * 12.9898 + r * 78.233) * 43758.5453);
    }

    private drawTerrainDetail(
        ctx: CanvasRenderingContext2D, 
        cx: number, cy: number, 
        size: number, 
        q: number, r: number, 
        type: string, 
        detailColor: string
    ) {
        ctx.save();
        ctx.fillStyle = detailColor;
        ctx.strokeStyle = detailColor;
        ctx.globalAlpha = 0.3; 

        const n = this.noise(q, r);
        const n2 = this.noise(r, q);

        if (type === 'VOID') {
            if (n > 0.6) {
                ctx.lineWidth = 1;
                ctx.beginPath();
                ctx.moveTo(cx - 10, cy - 5);
                ctx.lineTo(cx, cy + 5);
                ctx.lineTo(cx + 10, cy - 2);
                ctx.stroke();
            } else if (n < 0.3) {
                ctx.beginPath();
                ctx.arc(cx + n2 * 10, cy + n * 10, 2, 0, Math.PI * 2);
                ctx.fill();
            }
        } else if (type === 'FOREST') {
            const tufts = Math.floor(n * 3) + 1;
            for(let i=0; i<tufts; i++) {
                const ox = (this.noise(q+i, r) - 0.5) * 20;
                const oy = (this.noise(r, q+i) - 0.5) * 10;
                ctx.beginPath();
                ctx.moveTo(cx + ox, cy + oy);
                ctx.lineTo(cx + ox - 3, cy + oy - 5);
                ctx.moveTo(cx + ox, cy + oy);
                ctx.lineTo(cx + ox + 3, cy + oy - 5);
                ctx.stroke();
            }
        } else if (type === 'ICE') {
            ctx.globalAlpha = 0.5;
            ctx.fillStyle = '#fff';
            if (n > 0.5) {
                ctx.beginPath();
                ctx.moveTo(cx - 15, cy + 5);
                ctx.lineTo(cx + 15, cy - 5);
                ctx.lineTo(cx + 18, cy - 4);
                ctx.lineTo(cx - 12, cy + 6);
                ctx.fill();
            }
        } else if (type === 'MAGMA') {
            ctx.strokeStyle = '#000';
            ctx.lineWidth = 1;
            ctx.globalAlpha = 0.4;
            ctx.beginPath();
            ctx.moveTo(cx - 10, cy);
            ctx.lineTo(cx - 5, cy + 5 * n);
            ctx.lineTo(cx + 5, cy - 5 * n2);
            ctx.lineTo(cx + 10, cy);
            ctx.stroke();
            if (n > 0.8) {
                ctx.fillStyle = '#ef4444';
                ctx.globalAlpha = 0.6;
                ctx.beginPath(); ctx.arc(cx, cy, 3, 0, Math.PI*2); ctx.fill();
            }
        } else if (type === 'DESERT') {
            ctx.strokeStyle = '#92400e';
            ctx.lineWidth = 2;
            ctx.globalAlpha = 0.2;
            ctx.beginPath();
            ctx.arc(cx - 10, cy - 10, 30, 0.5, 2.0);
            ctx.stroke();
        }

        ctx.restore();
    }
}

import { GameEngine } from "../game";
import { SCENE_DB } from "../../data/scenes";
import { HexUtils } from "../utils";

export class MapSystem {
    public mapKeys: Set<string> = new Set();
    private validHashes: Set<number> = new Set();
    public obstacles: Set<string> = new Set();
    public obstaclesHash: Set<number> = new Set();

    constructor() {}

    public randomizeEnvironment(engine: GameEngine) {
        engine.mapConfig.w = Math.floor(8 + Math.random() * 7);
        engine.mapConfig.h = Math.floor(6 + Math.random() * 5);
        engine.currentScene = SCENE_DB[Math.floor(Math.random() * SCENE_DB.length)];
        this.rebuildMap(engine);
    }

    public rebuildMap(engine: GameEngine) {
        this.mapKeys.clear();
        this.validHashes.clear();
        this.obstacles.clear();
        this.obstaclesHash.clear();

        // 1. Generate Raw Grid
        for (let q = 0; q < engine.mapConfig.w; q++) {
            for (let r = 0; r < engine.mapConfig.h; r++) {
                const h = HexUtils.offsetToAxial(q, r, engine.mapConfig);
                this.mapKeys.add(HexUtils.key(h));
                this.validHashes.add(HexUtils.hash(h.q, h.r));
            }
        }

        // 2. Prune Disconnected Islands (Rule: No Disconnected Tiles)
        this.pruneDisconnected(engine);

        engine.mapVersion++;
    }

    private pruneDisconnected(engine: GameEngine) {
        if (this.validHashes.size === 0) return;

        // Find a center-ish tile as the seed
        const centerQ = Math.floor(engine.mapConfig.w / 2);
        const centerR = Math.floor(engine.mapConfig.h / 2);
        const centerHex = HexUtils.offsetToAxial(centerQ, centerR, engine.mapConfig);

        // Find closest valid tile to ideal center
        let seed = HexUtils.hash(centerHex.q, centerHex.r);
        if (!this.validHashes.has(seed)) {
            // Fallback: pick first valid
            seed = this.validHashes.values().next().value;
        }

        // BFS to find all reachable tiles
        const reachable = new Set<number>();
        const queue: number[] = [seed];
        reachable.add(seed);

        // Standard BFS
        let head = 0;
        while(head < queue.length) {
            const currentHash = queue[head++];
            const current = HexUtils.unhash(currentHash);
            const neighbors = HexUtils.neighbors(current);

            for (const n of neighbors) {
                const nHash = HexUtils.hash(n.q, n.r);
                if (this.validHashes.has(nHash) && !reachable.has(nHash)) {
                    reachable.add(nHash);
                    queue.push(nHash);
                }
            }
        }

        // Remove anything NOT in reachable set
        const toRemove: number[] = [];
        this.validHashes.forEach(h => {
            if (!reachable.has(h)) toRemove.push(h);
        });

        toRemove.forEach(h => {
            this.validHashes.delete(h);
            const hex = HexUtils.unhash(h);
            this.mapKeys.delete(HexUtils.key(hex));
        });
    }

    public toggleObstacle(q: number, r: number, engine: GameEngine) {
        if (!this.isValid(q, r)) return;

        const k = HexUtils.key({q, r});
        const h = HexUtils.hash(q, r);

        if (this.obstaclesHash.has(h)) {
            this.obstacles.delete(k);
            this.obstaclesHash.delete(h);
        } else {
            if (!engine.getAgentAt(q, r)) {
                this.obstacles.add(k);
                this.obstaclesHash.add(h);
            }
        }
    }

    public isValid(q: number, r: number) { 
        return this.validHashes.has(HexUtils.hash(q, r));
    }

    public isValidHash(h: number) {
        return this.validHashes.has(h);
    }

    public hasObstacle(q: number, r: number) {
        return this.obstaclesHash.has(HexUtils.hash(q, r));
    }

    public hasObstacleHash(h: number) {
        return this.obstaclesHash.has(h);
    }

    public isBlocked(q: number, r: number, engine: GameEngine, ignoreId: string | null = null) { 
        const h = HexUtils.hash(q, r);
        if (this.obstaclesHash.has(h)) return true;

        const occupant = engine.agentMap.get(h);
        if (occupant) {
            if (occupant.id === ignoreId) return false;
            if (occupant.hp <= 0 || occupant.banished) return false;
            return true;
        }

        // Check moving agents destination
        return engine.agents.some(a => {
            if (a.id === ignoreId) return false;
            if (!a.isMoving || a.path.length === 0) return false;
            const dest = a.path[0];
            return dest.q === q && dest.r === r;
        });
    }
}

import { DEFAULT_SKILL_DB } from "../skillDatabase";
import { UNIT_DB } from "../data/units";
import { SCENE_DB } from "../data/scenes";
import { LogEntry, NodeState, Role, Skill, Team, Projectile, GameEvent, AnimState, SceneTheme, Hex } from "../types";
import { BTNode } from "./behaviorTree";
import { HexUtils, MapConfig, Vector } from "./utils";
import { COLORS } from "../constants";

// Systems
import { MovementSystem } from "./systems/movement";
import { StatusSystem } from "./systems/status";
import { CombatSystem } from "./systems/combat";
import { MapSystem } from "./systems/map";
import { AISystem } from "./systems/ai";
import { AgentManager } from "./systems/agentManager";

export type SpecialVisualStatus = 'NONE' | 'FROZEN' | 'POLYMORPH' | 'STASIS';

export class Agent {
    public id: string;
    public team: Team;
    public role: Role;
    public q: number;
    public r: number;
    public px: number;
    public py: number;

    // Stats
    public hp: number = 100;
    public maxHp: number = 100;
    public mp: number = 0;
    public maxMp: number = 100;
    public moveSpeed: number = 1.0; 
    public moveSpeedMult: number = 1.0; 
    public jump: number = 1; // Vertical mobility tier
    public weight: number = 1; // Knockback resistance

    // Skills
    public skillIds: (string | null)[] = [null, null, null];
    public skills: (Skill | null)[] = [];
    public castingSkillIdx: number = -1;
    public castTimer: number = 0;
    public castingAnimationTimer: number = 0; 
    public curCDs: number[] = [0, 0, 0];

    // State / AI
    public isMoving: boolean = false;
    public path: Hex[] = []; 
    public trajectory: Hex[] = []; 
    public moveProgress: number = 0;
    public facing: number = 1; 
    public target: Agent | null = null;
    public targetHex: Hex | null = null; 
    public btStatus: string = "待機";
    public bt: BTNode | null = null;

    // Status Effects (Managed by StatusSystem)
    public stunTimer: number = 0;
    public banishTimer: number = 0;
    public silenceTimer: number = 0;
    public banished: boolean = false;
    public dotTimer: number = 0;
    public dotDmg: number = 0;
    public hotTimer: number = 0;
    public hotVal: number = 0;

    // Visual State
    public visualStatus: SpecialVisualStatus = 'NONE';
    public spawnTimer: number = 0;

    // Lifecycle
    public deadLogged: boolean = false;
    public fullyDead: boolean = false;
    public animState: AnimState = AnimState.IDLE;
    public animTimer: number = 0; 
    public hitFlashTimer: number = 0;

    // Physics (Enhanced for 3D bounce)
    public physics = { 
        x: 0, y: 0, z: 0,          
        vx: 0, vy: 0, vz: 0,       
        angle: 0, vAngle: 0   
    };

    public initialState: { q: number, r: number, maxHp: number, skillIds: (string|null)[], role: Role };

    constructor(team: Team, q: number, r: number, config: MapConfig) {
        this.id = Math.random().toString(36).substr(2, 5).toUpperCase();
        this.team = team;
        this.role = Role.WARRIOR; 
        this.q = q;
        this.r = r;

        const p = HexUtils.toPx(q, r, config);
        this.px = p.x;
        this.py = p.y;
        this.facing = team === Team.BLUE ? 1 : -1;

        this.initialState = { q, r, maxHp: 100, skillIds: [], role: Role.WARRIOR };
    }

    setAnim(state: AnimState) {
        if (this.animState !== state && this.animState !== AnimState.DEAD) {
            this.animState = state;
            this.animTimer = 0;
        }
    }

    saveState() {
        this.initialState = {
            q: this.q,
            r: this.r,
            maxHp: this.maxHp,
            skillIds: [...this.skillIds],
            role: this.role
        };
    }

    reset(config: MapConfig) {
        this.q = this.initialState.q;
        this.r = this.initialState.r;
        const p = HexUtils.toPx(this.q, this.r, config);
        this.px = p.x;
        this.py = p.y;

        this.maxHp = this.initialState.maxHp;
        this.hp = this.maxHp;
        this.mp = 0;

        this.skillIds = [...this.initialState.skillIds];
        this.role = this.initialState.role;

        const stats = UNIT_DB[this.role];
        if (stats) {
            this.moveSpeed = stats.moveSpeed;
            this.maxMp = stats.maxMp;
            this.jump = stats.jump;
            this.weight = stats.weight;
        }

        this.castingSkillIdx = -1;
        this.castTimer = 0;
        this.castingAnimationTimer = 0;
        this.curCDs = [0, 0, 0];

        this.isMoving = false;
        this.moveSpeedMult = 1.0; 
        this.path = [];
        this.moveProgress = 0;

        this.stunTimer = 0;
        this.banishTimer = 0;
        this.silenceTimer = 0;
        this.banished = false;
        this.dotTimer = 0;
        this.hotTimer = 0;
        this.visualStatus = 'NONE';

        this.hitFlashTimer = 0;
        this.deadLogged = false;
        this.fullyDead = false;
        this.animState = AnimState.IDLE;
        this.spawnTimer = 0.5; 

        this.target = null;
        this.targetHex = null;
        this.physics = { x: 0, y: 0, z: 0, vx: 0, vy: 0, vz: 0, angle: 0, vAngle: 0 };
    }
}

export class GameEngine {
    public agents: Agent[] = [];

    // Delegated to MapSystem but exposed via getters/proxies if needed by React
    get mapKeys() { return this.map.mapKeys; }
    get obstacles() { return this.map.obstacles; }

    public projectiles: Projectile[] = [];

    public events: GameEvent[] = [];

    public isRunning: boolean = false;
    public timeScale: number = 1.0;
    public battleTime: number = 0;
    public mapVersion: number = 0; 

    public mapConfig: MapConfig = { w: 12, h: 8, offsetX: 0, offsetY: 0 };
    public currentScene: SceneTheme = SCENE_DB[0];

    public logs: LogEntry[] = [];
    public skillDB: Skill[] = [...DEFAULT_SKILL_DB];

    public onWin?: (team: Team) => void;

    // AI Director State
    public directorTargetId: string | null = null;
    private directorTimer: number = 0;

    public agentMap: Map<number, Agent> = new Map();

    // Subsystems
    public movement: MovementSystem;
    public status: StatusSystem;
    public combat: CombatSystem;
    public map: MapSystem;
    public ai: AISystem;
    public agentManager: AgentManager;

    constructor() {
        this.movement = new MovementSystem();
        this.status = new StatusSystem();
        this.combat = new CombatSystem();
        this.map = new MapSystem();
        this.ai = new AISystem();
        this.agentManager = new AgentManager();

        this.map.randomizeEnvironment(this);
    }

    // --- Passthroughs ---

    addAgent(team: Team, q: number, r: number, hpOverride?: number) { return this.agentManager.addAgent(this, team, q, r, hpOverride); }
    toggleObstacle(q: number, r: number) { this.map.toggleObstacle(q, r, this); }
    isValid(q: number, r: number) { return this.map.isValid(q, r); }
    isBlocked(q: number, r: number, ignoreId?: string) { return this.map.isBlocked(q, r, this, ignoreId); }
    isValidHash(h: number) { return this.map.isValidHash(h); }
    hasObstacle(q: number, r: number) { return this.map.hasObstacle(q, r); }
    hasObstacleHash(h: number) { return this.map.hasObstacleHash(h); }
    randomizeEnvironment() { this.map.randomizeEnvironment(this); }
    rebuildMap() { this.map.rebuildMap(this); }

    removeAgent(q: number, r: number) {
        const hash = HexUtils.hash(q, r);
        const agent = this.agentMap.get(hash);
        if (agent) {
            this.agents = this.agents.filter(a => a !== agent);
            this.agentMap.delete(hash);
        }
    }

    getAgentAt(q: number, r: number): Agent | undefined {
        const agent = this.agentMap.get(HexUtils.hash(q, r));
        return (agent && agent.hp > 0) ? agent : undefined;
    }

    updateAgentPosition(agent: Agent, newQ: number, newR: number) {
        this.agentMap.delete(HexUtils.hash(agent.q, agent.r));
        agent.q = newQ;
        agent.r = newR;
        this.agentMap.set(HexUtils.hash(agent.q, agent.r), agent);
    }

    // --- Core Logic Control ---

    play() {
        if (!this.isRunning) {
            this.agents.forEach(a => a.saveState());
            this.battleTime = 0;
            this.logs = [];
            this.log(null, '開始', null, '戰鬥分析開始');
        }

        this.agentMap.clear();

        this.agents.forEach(a => {
            a.skills = a.skillIds.map(id => {
                if (!id) return null;
                return this.skillDB.find(s => s.id === id) || null;
            });
            a.bt = this.ai.buildAI(a, this); // Use AI System
            a.animState = AnimState.IDLE;
            if (a.hp > 0) {
                this.agentMap.set(HexUtils.hash(a.q, a.r), a);
            }
        });
        this.isRunning = true;
    }

    stop() { this.isRunning = false; }

    restart() {
        this.stop();
        this.agentMap.clear();
        this.agents.forEach(a => {
            a.reset(this.mapConfig);
            this.agentMap.set(HexUtils.hash(a.q, a.r), a);
        });
        this.projectiles = [];
        this.battleTime = 0;
        this.play();
    }

    clear(keepScene: boolean = false) {
        this.stop();
        this.agents = [];
        this.agentMap.clear();
        this.map.obstacles.clear();
        this.map.obstaclesHash.clear();
        this.projectiles = [];
        this.logs = [];
        this.directorTargetId = null;
        if (!keepScene) this.map.randomizeEnvironment(this); 
        else this.map.rebuildMap(this); 
    }

    // --- Main Game Loop ---

    tick(dt: number) {
        if (!this.isRunning) return;

        // Memory Optimization: Reuse array instead of reallocation
        this.events.length = 0;

        this.updateDirector(dt); // AI Director Logic

        // Win Condition Check
        let blue = 0, red = 0;
        for (const a of this.agents) {
            if (a.hp > 0) a.team === Team.BLUE ? blue++ : red++;
        }
        if (blue === 0 && red > 0) { this.stop(); this.onWin?.(Team.RED); }
        else if (red === 0 && blue > 0) { this.stop(); this.onWin?.(Team.BLUE); }

        for (const a of this.agents) {
            if (a.hitFlashTimer > 0) a.hitFlashTimer -= dt;

            // Physics delegated to MovementSystem
            this.movement.updatePhysics(a, dt, this);

            if (a.hp <= 0) {
                this.agentManager.handleDeadState(a, this);
                continue;
            }

            // --- DELEGATED SYSTEMS ---
            this.status.update(a, dt, this);

            // Movement Update
            if (a.isMoving && a.path.length > 0 && a.stunTimer <= 0) {
                this.movement.updateMovement(a, dt, this);
            }

            // AI Update
            if (a.bt) {
                const resetTree = (node: BTNode) => { 
                    node.status = null; 
                    if (node.c) node.c.forEach(resetTree); 
                };
                resetTree(a.bt);
                a.bt.tick(a);
            }
        }

        this.combat.update(dt, this);
        this.movement.resolveStacking(this);
    }

    // --- Loop Sub-Methods ---

    private updateDirector(dt: number) {
        this.directorTimer -= dt;

        // Ensure current target is still valid
        const current = this.agents.find(a => a.id === this.directorTargetId);
        if (!current || current.hp <= 0) {
            this.directorTimer = -1; // Force switch
        }

        if (this.directorTimer <= 0) {
            // Pick new target logic (simplified for brevity, logic remains same)
            const alive = this.agents.filter(a => a.hp > 0);
            if (alive.length > 0) {
                const ultCasters = alive.filter(a => a.castingSkillIdx !== -1 && a.skills[a.castingSkillIdx]?.tag === 'ULT');
                if (ultCasters.length > 0) {
                     this.directorTargetId = ultCasters[Math.floor(Math.random() * ultCasters.length)].id;
                     this.directorTimer = 4.0;
                     return;
                }

                this.directorTargetId = alive[Math.floor(Math.random() * alive.length)].id;
                this.directorTimer = 3.0;
            }
        }
    }

    performCast(a: Agent, i: number): NodeState {
        if (a.castingSkillIdx === -1) {
            a.castingSkillIdx = i;
            a.castTimer = a.skills[i]!.cast;
            a.castingAnimationTimer = a.skills[i]!.cast; 

            a.btStatus = `詠唱 ${a.skills[i]!.tag}`;

            let targetName = '地面';
            if (a.target) targetName = a.target.id;
            else if (a.targetHex) targetName = `(${a.targetHex.q},${a.targetHex.r})`;

            this.log(a, '詠唱', targetName, a.skills[i]!.name);
            this.events.push({ type: 'CAST_START', pos: {x: a.px, y: a.py}, sourceId: a.id, skill: a.skills[i]! });

            a.setAnim(AnimState.ATTACK);

            if (a.target) {
                a.facing = a.target.px > a.px ? 1 : -1;
            } else if (a.targetHex) {
                const tx = HexUtils.toPx(a.targetHex.q, a.targetHex.r, this.mapConfig).x;
                a.facing = tx > a.px ? 1 : -1;
            }
        }
        return NodeState.RUNNING;
    }

    log(agent: Agent | null, action: string, targetId: string | null, detail: string) {
        const time = this.battleTime.toFixed(1);
        const entry: LogEntry = {
            id: Math.random().toString(36),
            time,
            action,
            target: targetId || '自身',
            detail,
            agentId: agent?.id || (agent === null ? '系統' : undefined),
            team: agent?.team,
            loc: agent ? `@(${agent.q},${agent.r})` : undefined
        };
        this.logs.push(entry);
        if (this.logs.length > 2000) this.logs.shift();
    }
}

import { GameEngine } from "../game";
import { SCENE_DB } from "../../data/scenes";
import { HexUtils } from "../utils";
import { BLOCK_HEIGHT, MAX_TERRAIN_TIER } from "../../constants";

export class MapSystem {
    public mapKeys: Set<string> = new Set();
    private validHashes: Set<number> = new Set();
    public obstacles: Set<string> = new Set();
    public obstaclesHash: Set<number> = new Set();

    // Terrain Height Logic (Moved from GridSystem)
    private heightCache: Map<string, number> = new Map();
    public terrainDepth: number = 1.0; 

    constructor() {}

    public setTerrainDepth(d: number, engine: GameEngine) {
        if (Math.abs(this.terrainDepth - d) > 0.01) {
            this.terrainDepth = d;
            this.heightCache.clear();
            engine.mapVersion++;
        }
    }

    // QUANTIZED HEIGHT (Tier System)
    public getTerrainHeight(q: number, r: number): number {
        const key = `${q},${r}`;
        if (this.heightCache.has(key)) return this.heightCache.get(key)!;

        // Deterministic Noise
        const n = Math.sin(q * 12.9898 + r * 78.233) * 43758.5453;
        const noise = Math.abs(n - Math.floor(n));

        // Logic:
        // Stepped Tiers: 0, 1, 2, 3...
        // Low frequency noise for smooth hills
        const n2 = Math.sin(q * 0.5 + r * 0.3) * 0.5 + 0.5; // Smooth large waves

        let tier = 0;
        if (this.terrainDepth > 1.5) {
            // Deep/Chaotic Terrain
            tier = Math.floor(noise * MAX_TERRAIN_TIER * 0.8 + n2 * 3);
        } else {
            // Standard Arena
            tier = Math.floor(n2 * 3); 
        }

        // Clamp
        tier = Math.max(0, Math.min(MAX_TERRAIN_TIER, tier));

        const h = tier * BLOCK_HEIGHT;
        this.heightCache.set(key, h);
        return h;
    }

    public randomizeEnvironment(engine: GameEngine) {
        engine.mapConfig.w = Math.floor(8 + Math.random() * 7);
        engine.mapConfig.h = Math.floor(6 + Math.random() * 5);
        engine.currentScene = SCENE_DB[Math.floor(Math.random() * SCENE_DB.length)];
        this.rebuildMap(engine);
    }

    public rebuildMap(engine: GameEngine) {
        this.mapKeys.clear();
        this.validHashes.clear();
        this.obstacles.clear();
        this.obstaclesHash.clear();
        this.heightCache.clear();

        // 1. Generate Raw Grid
        for (let q = 0; q < engine.mapConfig.w; q++) {
            for (let r = 0; r < engine.mapConfig.h; r++) {
                const h = HexUtils.offsetToAxial(q, r, engine.mapConfig);
                this.mapKeys.add(HexUtils.key(h));
                this.validHashes.add(HexUtils.hash(h.q, h.r));
            }
        }

        // 2. Prune Disconnected Islands (Rule: No Disconnected Tiles)
        this.pruneDisconnected(engine);

        engine.mapVersion++;
    }

    private pruneDisconnected(engine: GameEngine) {
        if (this.validHashes.size === 0) return;

        // Find a center-ish tile as the seed
        const centerQ = Math.floor(engine.mapConfig.w / 2);
        const centerR = Math.floor(engine.mapConfig.h / 2);
        const centerHex = HexUtils.offsetToAxial(centerQ, centerR, engine.mapConfig);

        // Find closest valid tile to ideal center
        let seed = HexUtils.hash(centerHex.q, centerHex.r);
        if (!this.validHashes.has(seed)) {
            // Fallback: pick first valid
            seed = this.validHashes.values().next().value;
        }

        // BFS to find all reachable tiles
        const reachable = new Set<number>();
        const queue: number[] = [seed];
        reachable.add(seed);

        // Standard BFS
        let head = 0;
        while(head < queue.length) {
            const currentHash = queue[head++];
            const current = HexUtils.unhash(currentHash);
            // Height Aware? For checking island connectivity, we treat blocks as connected if they exist
            // Vertical movement is a pathfinding problem, not a map validity problem.
            const neighbors = HexUtils.neighbors(current);

            for (const n of neighbors) {
                const nHash = HexUtils.hash(n.q, n.r);
                if (this.validHashes.has(nHash) && !reachable.has(nHash)) {
                    reachable.add(nHash);
                    queue.push(nHash);
                }
            }
        }

        // Remove anything NOT in reachable set
        const toRemove: number[] = [];
        this.validHashes.forEach(h => {
            if (!reachable.has(h)) toRemove.push(h);
        });

        toRemove.forEach(h => {
            this.validHashes.delete(h);
            const hex = HexUtils.unhash(h);
            this.mapKeys.delete(HexUtils.key(hex));
        });
    }

    public toggleObstacle(q: number, r: number, engine: GameEngine) {
        if (!this.isValid(q, r)) return;

        const k = HexUtils.key({q, r});
        const h = HexUtils.hash(q, r);

        if (this.obstaclesHash.has(h)) {
            this.obstacles.delete(k);
            this.obstaclesHash.delete(h);
        } else {
            if (!engine.getAgentAt(q, r)) {
                this.obstacles.add(k);
                this.obstaclesHash.add(h);
            }
        }
    }

    public isValid(q: number, r: number) { 
        return this.validHashes.has(HexUtils.hash(q, r));
    }

    public isValidHash(h: number) {
        return this.validHashes.has(h);
    }

    public hasObstacle(q: number, r: number) {
        return this.obstaclesHash.has(HexUtils.hash(q, r));
    }

    public hasObstacleHash(h: number) {
        return this.obstaclesHash.has(h);
    }

    public isBlocked(q: number, r: number, engine: GameEngine, ignoreId: string | null = null) { 
        const h = HexUtils.hash(q, r);
        if (this.obstaclesHash.has(h)) return true;

        const occupant = engine.agentMap.get(h);
        if (occupant) {
            if (occupant.id === ignoreId) return false;
            if (occupant.hp <= 0 || occupant.banished) return false;
            return true;
        }

        // Check moving agents destination
        return engine.agents.some(a => {
            if (a.id === ignoreId) return false;
            if (!a.isMoving || a.path.length === 0) return false;
            const dest = a.path[0];
            return dest.q === q && dest.r === r;
        });
    }
}

import { HEX_SIZE, BLOCK_HEIGHT, TERRAIN_THEMES, MAX_TERRAIN_TIER } from "../../constants";
import { GameEngine, Agent } from "../game";
import { HexUtils } from "../utils";
import { AssetManager } from "../assets";
import { Hex, Skill, Projectile } from "../../types";

export interface RenderableItem {
    y: number;
    z: number;
    draw: (ctx: CanvasRenderingContext2D) => void;
}

interface CachedTile {
    q: number;
    r: number;
    px: number;
    py: number;
    h: number;
}

export class GridSystem {
    // Optimization: Cache tiles to avoid re-parsing keys and re-calculating positions every frame
    private _tileCache: CachedTile[] = [];
    private _lastMapVersion: number = -1;

    // Passthrough
    getTerrainHeight(q: number, r: number, engine?: GameEngine): number {
        if(engine) return engine.map.getTerrainHeight(q, r);
        return 0; 
    }

    private ensureCache(engine: GameEngine) {
        if (this._lastMapVersion !== engine.mapVersion || this._tileCache.length === 0) {
            this.rebuildTileCache(engine);
        }
    }

    private rebuildTileCache(engine: GameEngine) {
        this._tileCache = [];
        this._lastMapVersion = engine.mapVersion;

        engine.mapKeys.forEach(k => {
            const [q, r] = k.split(',').map(Number);
            const pos = HexUtils.toPx(q, r, engine.mapConfig);
            const h = engine.map.getTerrainHeight(q, r);
            this._tileCache.push({ q, r, px: pos.x, py: pos.y, h });
        });
    }

    getHexAtScreenPoint(mx: number, my: number, camera: {x: number, y: number, zoom: number}, engine: GameEngine): Hex | null {
        this.ensureCache(engine);

        // Convert screen mouse to world coordinates (unzoomed)
        const wx = mx / camera.zoom + camera.x;
        const wy = my / camera.zoom + camera.y;

        const candidates: CachedTile[] = [];
        const limit = HEX_SIZE * 2; 

        for (const tile of this._tileCache) {
            const dist = Math.abs(wx - tile.px) + Math.abs(wy - (tile.py - tile.h));
            if (dist < limit) { 
                candidates.push(tile);
            }
        }

        // Sort by visual depth (Front to Back)
        candidates.sort((a, b) => b.py - a.py);

        for (const cand of candidates) {
            const testHex = HexUtils.fromPx(wx, wy + cand.h, engine.mapConfig);
            const rounded = HexUtils.round(testHex.q, testHex.r);
            if (rounded.q === cand.q && rounded.r === cand.r) {
                return { q: cand.q, r: cand.r };
            }
        }

        return null;
    }

    /**
     * Identifies agents that are visually blocked by taller terrain in front of them.
     */
    getOccludedAgents(engine: GameEngine): Agent[] {
        const occluded: Agent[] = [];

        engine.agents.forEach(a => {
            if (a.hp <= 0 && a.fullyDead) return;

            const uPx = HexUtils.toPx(a.q, a.r, engine.mapConfig);
            const uHeight = engine.map.getTerrainHeight(a.q, a.r);

            // In Diamond Isometric, "Front" means Higher Y on screen.
            // Blocks with higher Y and higher Z can occlude units with lower Y.
            const neighbors = HexUtils.neighbors({q: a.q, r: a.r});
            let isBlocked = false;

            for (const n of neighbors) {
                const k = HexUtils.key(n);
                if (engine.mapKeys.has(k)) {
                    const nPx = HexUtils.toPx(n.q, n.r, engine.mapConfig);

                    // Check if neighbor is physically "in front" (Screen Y is larger)
                    if (nPx.y > uPx.y) {
                         const nHeight = engine.map.getTerrainHeight(n.q, n.r);
                         // If the blocking tile is strictly taller
                         if (nHeight > uHeight) {
                             isBlocked = true;
                             break;
                         }
                    }
                }
            }

            if (isBlocked) {
                occluded.push(a);
            }
        });

        return occluded;
    }

    collectRenderables(
        engine: GameEngine, 
        hoveredHex: Hex | null, 
        hoveredSkill: Skill | null, 
        highlightAgent: Agent | null, 
        flashes: any[],
        projectiles: Projectile[],
        transitionT: number,      
        transitionPhase: 'IN' | 'OUT' | 'IDLE',
        globalTime: number
    ): RenderableItem[] {
        this.ensureCache(engine);

        const list: RenderableItem[] = [];
        const scene = engine.currentScene;
        const theme = TERRAIN_THEMES[scene.textureType] || TERRAIN_THEMES['VOID'];

        const dangerZones = new Map<string, {color: string, progress: number}>();
        engine.agents.forEach(a => {
            if (a.hp > 0 && a.castingSkillIdx !== -1) {
                const s = a.skills[a.castingSkillIdx];
                if (s && s.type === 'AOE') {
                    let centerHex: Hex | null = null;
                    if (a.targetHex) centerHex = a.targetHex;
                    else if (a.target) centerHex = {q: a.target.q, r: a.target.r};
                    else centerHex = {q: a.q, r: a.r};

                    if (centerHex) {
                        const progress = 1 - (a.castTimer / s.cast);
                        HexUtils.range(centerHex, s.aoeRadius || 1).forEach(h => {
                            dangerZones.set(`${h.q},${h.r}`, {
                                color: s.color, 
                                progress: progress
                            });
                        });
                    }
                }
            }
        });

        const unitPresence = new Map<string, boolean>();
        const unitVisualStatus = new Map<string, string>(); 

        engine.agents.forEach(a => {
            if(a.hp > 0) {
                const key = `${a.q},${a.r}`;
                unitPresence.set(key, true);
                if (a.visualStatus !== 'NONE') {
                    unitVisualStatus.set(key, a.visualStatus);
                }
            }
        });

        const centerQ = Math.floor(engine.mapConfig.w / 2);
        const centerR = Math.floor(engine.mapConfig.h / 2);
        const maxDist = Math.max(engine.mapConfig.w, engine.mapConfig.h) / 2;

        for (const tile of this._tileCache) {
            const { q, r, px, py, h } = tile;

            // --- TRANSITION LOGIC ---
            let visualY = py;

            if (transitionPhase !== 'IDLE') {
                const dist = Math.sqrt((q - centerQ)**2 + (r - centerR)**2);
                const d = dist / maxDist; 

                if (transitionPhase === 'OUT') {
                    const trigger = d * 0.3;
                    if (transitionT > trigger) {
                        const fallT = Math.min(1, (transitionT - trigger) * 2.5);
                        const easedFall = fallT * fallT * fallT;
                        visualY += easedFall * 1000;
                    }
                } else if (transitionPhase === 'IN') {
                    const trigger = d * 0.3;
                    const riseT = Math.max(0, Math.min(1, (transitionT - trigger) * 2.5));
                    const easedRise = 1 - Math.pow(1 - riseT, 3);
                    visualY += (1 - easedRise) * 1000;
                }
            }

            if (visualY > py + 800) continue;

            const flash = flashes.find(f => f.q === q && f.r === r);
            let isRange = false;
            let rangeColor = '';

            if (hoveredSkill && highlightAgent) {
                if (HexUtils.dist({q, r}, highlightAgent) <= hoveredSkill.range) {
                    isRange = true; 
                    rangeColor = hoveredSkill.color;
                }
            }

            const isHover = hoveredHex ? (hoveredHex.q === q && hoveredHex.r === r) : false;

            const k = `${q},${r}`;
            const dangerInfo = dangerZones.get(k);
            const hasUnit = unitPresence.has(k);
            const specialStatus = unitVisualStatus.get(k);

            let lightColor = null;
            let lightIntensity = 0;
            const PROJ_LIGHT_RADIUS = 40; 
            const PROJ_LIGHT_RADIUS_SQ = PROJ_LIGHT_RADIUS * PROJ_LIGHT_RADIUS;

            for (const p of projectiles) {
                const distSq = (p.x - px)**2 + (p.y - py)**2;
                if (distSq < PROJ_LIGHT_RADIUS_SQ) {
                    lightColor = p.skill.color;
                    lightIntensity += (1 - Math.sqrt(distSq) / PROJ_LIGHT_RADIUS);
                }
            }

            list.push({
                y: visualY, 
                z: 0,        
                draw: (ctx) => this.drawIsoBlock(
                    ctx, 
                    px, visualY, 
                    HEX_SIZE, h, 
                    theme, 
                    flash, 
                    isRange, rangeColor, 
                    isHover, 
                    dangerInfo, 
                    hasUnit,
                    lightColor,
                    Math.min(1, lightIntensity),
                    q, r, scene.textureType,
                    specialStatus,
                    globalTime
                )
            });
        }

        return list;
    }

    private drawIsoBlock(
        ctx: CanvasRenderingContext2D, 
        x: number, y: number, 
        size: number, height: number, 
        theme: any, 
        flash: any, 
        isRange: boolean, rangeColor: string, 
        isHover: boolean, 
        dangerInfo: {color: string, progress: number} | undefined, 
        hasUnit: boolean,
        lightColor: string | null,
        lightIntensity: number,
        q: number = 0, r: number = 0, textureType: string = 'VOID',
        specialStatus: string | undefined,
        globalTime: number
    ) {
        // FFT Style: Squashed Hexagon
        const Y_SCALE = 0.6; 

        const corners: {x: number, y: number}[] = [];
        const startAngle = Math.PI / 6; 

        for (let i = 0; i < 6; i++) {
            const angle = startAngle + i * Math.PI / 3;
            corners.push({ 
                x: x + size * Math.cos(angle), 
                y: y + size * Math.sin(angle) * Y_SCALE 
            });
        }

        // This is the TOP face Y level
        const topY = height; 

        const traceTopFace = () => {
            ctx.beginPath();
            ctx.moveTo(corners[0].x, corners[0].y - topY);
            for (let i = 1; i < 6; i++) {
                ctx.lineTo(corners[i].x, corners[i].y - topY);
            }
            ctx.closePath();
        };

        // --- 1. Draw Side Faces (The Stack) ---
        // We render sides that are facing the camera (bottom 3 faces for hex)
        // Indices 0, 1, 2 are usually the top-ish faces in this corner gen order.

        const visibleIndices = [0, 1, 2];

        for (const i of visibleIndices) {
            const j = (i + 1) % 6;

            const grad = ctx.createLinearGradient(0, y - topY, 0, y);
            // Alternate brightness for 3D effect
            const baseColor = (i === 1) ? theme.sideDark : theme.sideLight;
            grad.addColorStop(0, baseColor);
            grad.addColorStop(1, '#020617'); 

            ctx.fillStyle = grad;
            ctx.beginPath();
            ctx.moveTo(corners[i].x, corners[i].y); // Ground corner
            ctx.lineTo(corners[j].x, corners[j].y); // Ground next corner
            ctx.lineTo(corners[j].x, corners[j].y - topY); // Top next corner
            ctx.lineTo(corners[i].x, corners[i].y - topY); // Top corner
            ctx.closePath();
            ctx.fill();

            // "Layer Lines" for Block Stack Effect (Tactics Ogre)
            if (height > BLOCK_HEIGHT) {
                ctx.strokeStyle = 'rgba(0,0,0,0.3)';
                ctx.lineWidth = 1;
                ctx.beginPath();
                for (let hStep = BLOCK_HEIGHT; hStep < height; hStep += BLOCK_HEIGHT) {
                    ctx.moveTo(corners[i].x, corners[i].y - hStep);
                    ctx.lineTo(corners[j].x, corners[j].y - hStep);
                }
                ctx.stroke();
            }

            // Outline Side
            ctx.strokeStyle = 'rgba(255,255,255,0.05)'; 
            ctx.lineWidth = 1; 
            ctx.stroke();
        }

        // --- 2. Draw Top Face (Base) ---
        traceTopFace();

        const topGrad = ctx.createRadialGradient(x, y - topY, 0, x, y - topY, size);
        topGrad.addColorStop(0, theme.top);
        topGrad.addColorStop(1, theme.detail); 
        ctx.fillStyle = topGrad;
        ctx.fill();

        // --- 2.5 Draw Terrain Texture (Detailing) ---
        this.drawTerrainDetail(ctx, x, y - topY, size, q, r, textureType, theme.detail);

        // --- 2.6 SPECIAL STATUS FLOOR EFFECT ---
        if (specialStatus) {
            traceTopFace(); 
            ctx.save();
            ctx.globalCompositeOperation = 'overlay';
            if (specialStatus === 'FROZEN') {
                ctx.fillStyle = '#bae6fd'; 
                ctx.globalAlpha = 0.6;
            } else if (specialStatus === 'POLYMORPH') {
                ctx.fillStyle = '#d8b4fe'; 
                ctx.globalAlpha = 0.5;
            } else if (specialStatus === 'STASIS') {
                ctx.fillStyle = '#fde047';
                ctx.globalAlpha = 0.5;
            }
            ctx.fill(); 
            ctx.restore();
        }

        // --- 2.7 AOE TELEGRAPH ---
        if (dangerInfo) {
            traceTopFace(); 
            ctx.save();
            // 1. Tile Coloring
            const opacity = 0.1 + dangerInfo.progress * 0.6;
            ctx.fillStyle = dangerInfo.color;
            ctx.globalAlpha = opacity;
            ctx.globalCompositeOperation = 'source-over'; 
            ctx.fill(); 

            // 2. Glowing Border
            ctx.strokeStyle = dangerInfo.color;
            ctx.lineWidth = 1 + dangerInfo.progress * 2;
            ctx.globalAlpha = 0.8;
            ctx.stroke();

            // 3. Particles
            if (dangerInfo.progress > 0.2) {
                const particleCount = 3 + Math.floor(dangerInfo.progress * 5);
                ctx.fillStyle = dangerInfo.color;
                ctx.globalCompositeOperation = 'lighter'; 

                for(let i=0; i<particleCount; i++) {
                    const seed = (Math.abs(q * 100 + r * 10) + i * 123.45);
                    const speed = 20 + (seed % 20);
                    const t = (globalTime * speed * 0.05 + seed) % 1; 
                    const pAlpha = 1 - t;

                    const pX = x + Math.sin(t * 10 + seed) * (size * 0.5);
                    const pY = (y - topY) - (t * 40); 

                    ctx.globalAlpha = pAlpha * opacity; 
                    const pSize = 1 + (seed % 2);

                    ctx.beginPath();
                    ctx.arc(pX, pY, pSize, 0, Math.PI*2);
                    ctx.fill();
                }
            }
            ctx.restore();
        }

        // --- 3. Dynamic Lighting ---
        if (lightColor && lightIntensity > 0) {
            traceTopFace(); 
            ctx.save();
            ctx.globalCompositeOperation = 'lighter'; 
            ctx.globalAlpha = lightIntensity * 0.8; 
            ctx.fillStyle = lightColor;
            ctx.fill();
            ctx.restore();
        }

        // --- 4. Interactive Overlays ---
        if (flash || isRange || isHover || hasUnit) {
            ctx.save();
            traceTopFace(); 

            if (isRange) { 
                ctx.fillStyle = rangeColor;
                ctx.globalAlpha = 0.2; 
                ctx.fill();
                ctx.strokeStyle = rangeColor; 
                ctx.lineWidth = 2; 
                ctx.globalAlpha = 0.8; 
                ctx.stroke();
            }

            if (isHover) { 
                ctx.fillStyle = 'rgba(255,255,255,0.15)'; 
                ctx.globalAlpha = 1.0;
                ctx.fill(); 
                ctx.strokeStyle = '#fff'; 
                ctx.lineWidth = 3; 
                ctx.stroke(); 
            }

            if (flash) {
                ctx.globalCompositeOperation = 'lighter';
                ctx.fillStyle = flash.color;
                ctx.globalAlpha = 0.6;
                ctx.fill();
                ctx.strokeStyle = '#fff';
                ctx.lineWidth = 2;
                ctx.stroke();
            }

            if (hasUnit && !isHover && !dangerInfo) {
                ctx.strokeStyle = 'rgba(255,255,255,0.3)';
                ctx.lineWidth = 1;
                ctx.stroke();
            }

            ctx.restore();
        }
    }

    private noise(q: number, r: number) {
        return Math.sin(q * 12.9898 + r * 78.233) * 43758.5453 - Math.floor(Math.sin(q * 12.9898 + r * 78.233) * 43758.5453);
    }

    private drawTerrainDetail(
        ctx: CanvasRenderingContext2D, 
        cx: number, cy: number, 
        size: number, 
        q: number, r: number, 
        type: string, 
        detailColor: string
    ) {
        ctx.save();
        ctx.fillStyle = detailColor;
        ctx.strokeStyle = detailColor;
        ctx.globalAlpha = 0.3; 

        const n = this.noise(q, r);
        const n2 = this.noise(r, q);

        if (type === 'VOID') {
            if (n > 0.6) {
                ctx.lineWidth = 1;
                ctx.beginPath();
                ctx.moveTo(cx - 10, cy - 5);
                ctx.lineTo(cx, cy + 5);
                ctx.lineTo(cx + 10, cy - 2);
                ctx.stroke();
            } else if (n < 0.3) {
                ctx.beginPath();
                ctx.arc(cx + n2 * 10, cy + n * 10, 2, 0, Math.PI * 2);
                ctx.fill();
            }
        } else if (type === 'FOREST') {
            const tufts = Math.floor(n * 3) + 1;
            for(let i=0; i<tufts; i++) {
                const ox = (this.noise(q+i, r) - 0.5) * 20;
                const oy = (this.noise(r, q+i) - 0.5) * 10;
                ctx.beginPath();
                ctx.moveTo(cx + ox, cy + oy);
                ctx.lineTo(cx + ox - 3, cy + oy - 5);
                ctx.moveTo(cx + ox, cy + oy);
                ctx.lineTo(cx + ox + 3, cy + oy - 5);
                ctx.stroke();
            }
        } else if (type === 'ICE') {
            ctx.globalAlpha = 0.5;
            ctx.fillStyle = '#fff';
            if (n > 0.5) {
                ctx.beginPath();
                ctx.moveTo(cx - 15, cy + 5);
                ctx.lineTo(cx + 15, cy - 5);
                ctx.lineTo(cx + 18, cy - 4);
                ctx.lineTo(cx - 12, cy + 6);
                ctx.fill();
            }
        } else if (type === 'MAGMA') {
            ctx.strokeStyle = '#000';
            ctx.lineWidth = 1;
            ctx.globalAlpha = 0.4;
            ctx.beginPath();
            ctx.moveTo(cx - 10, cy);
            ctx.lineTo(cx - 5, cy + 5 * n);
            ctx.lineTo(cx + 5, cy - 5 * n2);
            ctx.lineTo(cx + 10, cy);
            ctx.stroke();
            if (n > 0.8) {
                ctx.fillStyle = '#ef4444';
                ctx.globalAlpha = 0.6;
                ctx.beginPath(); ctx.arc(cx, cy, 3, 0, Math.PI*2); ctx.fill();
            }
        } else if (type === 'DESERT') {
            ctx.strokeStyle = '#92400e';
            ctx.lineWidth = 2;
            ctx.globalAlpha = 0.2;
            ctx.beginPath();
            ctx.arc(cx - 10, cy - 10, 30, 0.5, 2.0);
            ctx.stroke();
        }

        ctx.restore();
    }
}

import { Agent, GameEngine } from "../game";
import { HexUtils, Vector, NEIGHBOR_HASH_OFFSETS } from "../utils";
import { AnimState, Hex, NodeState } from "../../types";
import { BLOCK_HEIGHT } from "../../constants";

// Constants extracted from game.ts
const PATHFINDING_MAX_ITERATIONS = 2500; 
const QUEUE_CAPACITY = 4096; 
const STACKING_RESOLUTION_FORCE = 5;

const PHYSICS_STIFFNESS_ALIVE = 150;
const PHYSICS_STIFFNESS_DEAD = 0;
// INCREASED DAMPING: Makes units stop snappier, reducing "floating" feel
const PHYSICS_DAMPING_ALIVE = 25; 
const PHYSICS_DAMPING_DEAD = 1.0; 

const GRAVITY = 2000; 

export class MovementSystem {
    // Pathfinding Memory Buffers (Reused to avoid GC)
    private _pfQueue: Int32Array; 
    private _pfCameFrom: Map<number, number> = new Map();
    private _pfBlockers: Set<number> = new Set();

    constructor() {
        this._pfQueue = new Int32Array(QUEUE_CAPACITY);
    }

    // =========================================================================================
    // 🏃 MOVEMENT & PHYSICS
    // =========================================================================================

    public updatePhysics(a: Agent, dt: number, engine: GameEngine) {
        const isDead = a.hp <= 0;
        const stiffness = isDead ? PHYSICS_STIFFNESS_DEAD : PHYSICS_STIFFNESS_ALIVE; 

        // If airborne (z > 0), reduce drag to allow projectile motion
        const isAirborne = a.physics.z > 0;
        const damping = (isDead && isAirborne) ? 0.5 : (isDead ? PHYSICS_DAMPING_DEAD : PHYSICS_DAMPING_ALIVE);

        // 1. Spring Forces (Return to 0,0 relative local space)
        const fx = -stiffness * a.physics.x;
        const fy = -stiffness * a.physics.y;
        const fRot = -stiffness * a.physics.angle * 0.1; 

        // 2. Acceleration (Force - Damping)
        const ax = fx - damping * a.physics.vx;
        const ay = fy - damping * a.physics.vy;
        const aRot = fRot - damping * a.physics.vAngle;

        // 3. Integrate Velocity
        a.physics.vx += ax * dt;
        a.physics.vy += ay * dt;
        a.physics.vAngle += aRot * dt;

        // 4. Gravity (Z-axis)
        if (isDead || isAirborne) {
            a.physics.vz -= GRAVITY * dt;
        }

        // 5. Integrate Position
        a.physics.x += a.physics.vx * dt;
        a.physics.y += a.physics.vy * dt;
        a.physics.z += a.physics.vz * dt;
        a.physics.angle += a.physics.vAngle * dt;

        // 6. Ground Collision (Bounce)
        if (a.physics.z < 0) {
            a.physics.z = 0;
            // Elastic collision with ground loss
            if (Math.abs(a.physics.vz) > 100) {
                a.physics.vz = -a.physics.vz * 0.5; // Bounce back
                a.physics.vx *= 0.6; // Ground friction
                a.physics.vy *= 0.6;
                a.physics.vAngle *= 0.5;
            } else {
                a.physics.vz = 0;
            }
        }

        // 7. World Position Drift (Slide effect for dead units)
        if (!isDead && !a.isMoving) {
            const targetPos = HexUtils.toPx(a.q, a.r, engine.mapConfig);
            const dx = targetPos.x - a.px;
            const dy = targetPos.y - a.py;
            const distSq = dx*dx + dy*dy;

            // Increased snap threshold to stop jitter
            if (distSq > 0.5) {
                const driftSpeed = 12.0 * dt;
                a.px += dx * driftSpeed;
                a.py += dy * driftSpeed;
                if (distSq < 2) {
                    a.px = targetPos.x;
                    a.py = targetPos.y;
                }
            } else {
                a.px = targetPos.x;
                a.py = targetPos.y;
            }
        } else if (isDead) {
            // Apply physics velocity to world position (Flying through air)
            a.px += a.physics.vx * dt * 0.1; 
            a.py += a.physics.vy * dt * 0.1;
        }
    }

    public updateMovement(a: Agent, dt: number, engine: GameEngine) {
        // Use per-agent move speed WITH dynamic multiplier (Charge effect)
        a.moveProgress += a.moveSpeed * a.moveSpeedMult * dt;

        const c = HexUtils.toPx(a.q, a.r, engine.mapConfig);
        const nextHex = a.path[0];
        const n = HexUtils.toPx(nextHex.q, nextHex.r, engine.mapConfig);

        // Vertical interpolation logic can be handled in UnitRenderSystem, 
        // here we mostly care about X/Y transition for logic updates

        if (n.x > c.x) a.facing = 1;
        else if (n.x < c.x) a.facing = -1;

        a.px = HexUtils.lerp(c.x, n.x, a.moveProgress);
        a.py = HexUtils.lerp(c.y, n.y, a.moveProgress);

        if (a.moveProgress >= 1) {
            // Commit move
            engine.updateAgentPosition(a, nextHex.q, nextHex.r);

            a.isMoving = false;
            a.moveSpeedMult = 1.0; // Reset speed after step completes

            // Small nudge to separate stacked units visually if they glitch
            a.physics.vx -= a.facing * STACKING_RESOLUTION_FORCE; 
        }
    }

    public moveAgentToHex(a: Agent, targetHex: Hex, r: number, engine: GameEngine, speedMult: number = 1.0): NodeState {
        if (a.isMoving) {
            a.moveSpeedMult = speedMult; // Update dynamic speed
            a.setAnim(AnimState.MOVE);
            return NodeState.RUNNING;
        }

        // Check range
        if (HexUtils.dist(a, targetHex) <= r) {
            a.setAnim(AnimState.COMBAT_IDLE);
            return NodeState.SUCCESS;
        }

        // 1. Try Standard Pathfinding (Respecting Allies)
        let path = this.findPath(a, targetHex.q, targetHex.r, r, false, engine);

        // 2. Fallback: Ghost Pathfinding (Ignoring Allies)
        // If normal path failed, try to find a path ignoring units to see if "direction" exists
        if (path.length === 0) {
            path = this.findPath(a, targetHex.q, targetHex.r, r, true, engine); // true = ignoreUnits
        }

        if (path.length > 0) {
            const next = path[0];

            // CRITICAL CHECK: Even if we found a ghost path, is the IMMEDIATE NEXT STEP blocked?
            if (engine.isBlocked(next.q, next.r, a.id)) {
                // We know where we WANT to go, but it's blocked right now.
                // Instead of failing (which causes AI jitter/wandering), we WAIT.
                // This simulates "queueing" behind the frontline.
                a.setAnim(AnimState.COMBAT_IDLE); 
                // Return RUNNING to keep the AI node active, preventing re-calculation jitter
                return NodeState.RUNNING; 
            }

            a.path = [next];
            a.trajectory = path; // Visual only
            a.isMoving = true;
            a.moveProgress = 0;
            a.moveSpeedMult = speedMult;
            a.setAnim(AnimState.MOVE);

            // Physics Lean
            const dir = a.facing;
            a.physics.vx += dir * 2; 

            return NodeState.RUNNING;
        }

        // Truly unreachable (walled off)
        return NodeState.FAILURE;
    }

    public moveAgent(a: Agent, t: Agent, r: number, engine: GameEngine, speedMult: number = 1.0): NodeState {
        // When chasing a unit, we want to get within range R of them.
        // We don't necessarily need to step ON their tile.
        return this.moveAgentToHex(a, {q: t.q, r: t.r}, r, engine, speedMult);
    }

    public resolveStacking(engine: GameEngine) {
        const map = new Map<number, Agent[]>();

        engine.agents.forEach(a => {
            if (a.hp <= 0 || a.banished) return;
            const h = HexUtils.hash(a.q, a.r);
            if (!map.has(h)) map.set(h, []);
            map.get(h)!.push(a);
        });

        map.forEach((list, hash) => {
            if (list.length > 1) {
                const coords = HexUtils.unhash(hash);

                const stationary = list.filter(a => !a.isMoving);
                const keep = stationary.length > 0 ? stationary[0] : list[0];
                const toDisplace = list.filter(a => a !== keep);

                toDisplace.forEach(agent => {
                    const neighbors = HexUtils.neighbors(coords);
                    for (let i = neighbors.length - 1; i > 0; i--) {
                        const j = Math.floor(Math.random() * (i + 1));
                        [neighbors[i], neighbors[j]] = [neighbors[j], neighbors[i]];
                    }

                    let target = neighbors.find(n => engine.map.isValid(n.q, n.r) && !engine.map.isBlocked(n.q, n.r, engine));

                    // Fallback: Try valid but not obstacle (ignoring units)
                    if (!target) target = neighbors.find(n => engine.map.isValid(n.q, n.r) && !engine.map.hasObstacle(n.q, n.r));

                    if (target) {
                        engine.updateAgentPosition(agent, target.q, target.r);
                        // Cancel current move to allow physics drift to slide unit visually
                        if (agent.isMoving) {
                            agent.isMoving = false;
                            agent.path = [];
                        }
                    }
                });
            }
        });
    }

    // =========================================================================================
    // 🗺️ PATHFINDING (A* / Multi-Layer BFS)
    // =========================================================================================

    public findPath(
        startAgent: Agent, 
        endQ: number, 
        endR: number, 
        range: number,
        ignoreUnits: boolean, 
        engine: GameEngine
    ): Hex[] {
        const startH = HexUtils.hash(startAgent.q, startAgent.r);

        // Optimization: Pre-check if start satisfies range
        const startDist = HexUtils.dist({q: startAgent.q, r: startAgent.r}, {q: endQ, r: endR});
        if (startDist <= range) return [];

        this._pfCameFrom.clear();
        this._pfBlockers.clear();

        // 1. Populate Blockers
        // If ignoreUnits is TRUE (Ghost Mode), we only block Walls/Obstacles
        if (!ignoreUnits) {
            for (const a of engine.agents) {
                if (a.hp > 0 && !a.banished && a !== startAgent) {
                    const h = HexUtils.hash(a.q, a.r);
                    this._pfBlockers.add(h);

                    if (a.isMoving && a.path.length > 0) {
                        const hp = HexUtils.hash(a.path[0].q, a.path[0].r);
                        this._pfBlockers.add(hp);
                    }
                }
            }
        }

        let head = 0; 
        let tail = 0; 
        this._pfQueue[head++] = startH; 
        this._pfCameFrom.set(startH, -1); 

        let iterations = 0;
        let foundHash = -1;
        const targetHex = { q: endQ, r: endR };

        while (tail < head) {
            iterations++;
            if (iterations > PATHFINDING_MAX_ITERATIONS) break;

            const currentH = this._pfQueue[tail++]; 
            const currentHex = HexUtils.unhash(currentH);
            const currentTerrainH = engine.map.getTerrainHeight(currentHex.q, currentHex.r);

            // SUCCESS CONDITION: Inside Range?
            if (HexUtils.dist(currentHex, targetHex) <= range) {
                foundHash = currentH;
                break;
            }

            for(let j = 0; j < 6; j++) {
                const offset = NEIGHBOR_HASH_OFFSETS[j];
                const nextH = currentH + offset;

                if (this._pfCameFrom.has(nextH)) continue;

                // Map Bounds Check
                if (!engine.map.isValidHash(nextH)) continue;

                // Static Obstacle Check (Always active)
                if (engine.map.hasObstacleHash(nextH)) continue;

                // Dynamic Unit Check (Only if not ignoring units)
                if (!ignoreUnits && this._pfBlockers.has(nextH)) {
                    continue;
                }

                // --- TACTICS OGRE HEIGHT CHECK ---
                const nextHexCoord = HexUtils.unhash(nextH);
                const nextTerrainH = engine.map.getTerrainHeight(nextHexCoord.q, nextHexCoord.r);
                const deltaH = Math.abs(nextTerrainH - currentTerrainH);

                // Allow climb/drop if deltaH <= Jump Height (in pixels)
                // Using max(1, jump) to ensure at least 1 block can be traversed by default
                const maxClimb = Math.max(1, startAgent.jump) * BLOCK_HEIGHT;

                if (deltaH > maxClimb) {
                    continue; // Too steep!
                }

                this._pfCameFrom.set(nextH, currentH);

                if (head < QUEUE_CAPACITY) {
                    this._pfQueue[head++] = nextH;
                }
            }
        }

        if (foundHash !== -1) {
            const path: Hex[] = [];
            let curr = foundHash;

            let sanity = 0;
            while (curr !== startH && sanity++ < 100) {
                path.push(HexUtils.unhash(curr));
                const prev = this._pfCameFrom.get(curr);
                if (prev === undefined || prev === -1) break;
                curr = prev;
            }
            return path.reverse();
        }

        return [];
    }

    // =========================================================================================
    // 🎯 TARGETING & TACTICS
    // =========================================================================================

    public updateTarget(a: Agent, engine: GameEngine) {
        if (a.target && (a.target.hp <= 0 || a.target.banished)) a.target = null;
        let minD = 999;
        let t: Agent | null = null;

        for (const o of engine.agents) {
            if (o.team !== a.team && o.hp > 0 && !o.banished) {
                const d = HexUtils.dist(a, o);
                if (d < minD) { minD = d; t = o; }
            }
        }
        a.target = t;
    }

    public calculateOptimalTarget(source: Agent, skill: any, engine: GameEngine): { targetAgent: Agent | null, targetHex: Hex | null } {
        if (skill.ccType === 'SILENCE' || skill.ccType2 === 'SILENCE') {
            const enemies = engine.agents.filter(a => 
                a.team !== source.team && a.hp > 0 && !a.banished && 
                HexUtils.dist(source, a) <= skill.range
            );

            if (enemies.length > 0) {
                enemies.sort((a, b) => {
                    const score = (u: Agent) => {
                        if (u.castingSkillIdx === -1) return 0;
                        const s = u.skills[u.castingSkillIdx];
                        if (s?.tag === 'ULT') return 3;
                        if (s?.tag === 'ACTIVE') return 2;
                        return 1;
                    };
                    const sA = score(a);
                    const sB = score(b);
                    if (sA !== sB) return sB - sA;
                    return HexUtils.dist(source, a) - HexUtils.dist(source, b);
                });
                return { targetAgent: enemies[0], targetHex: null };
            }
        }

        if (skill.type === 'AOE') {
            const candidateHexes = new Set<number>();
            const radius = skill.aoeRadius || 1;
            const searchDist = skill.range + 3;

            engine.agents.forEach(enemy => {
                if (enemy.team !== source.team && enemy.hp > 0 && !enemy.banished) {
                    if (HexUtils.dist(source, enemy) <= searchDist) {
                        candidateHexes.add(HexUtils.hash(enemy.q, enemy.r));
                        HexUtils.neighbors(enemy).forEach(n => candidateHexes.add(HexUtils.hash(n.q, n.r)));
                    }
                }
            });

            let bestHex: Hex | null = null;
            let bestScore = -1;

            candidateHexes.forEach(hHash => {
                const h = HexUtils.unhash(hHash);
                if (!engine.map.isValid(h.q, h.r)) return;

                let score = 0;
                let hitCount = 0;

                for (const target of engine.agents) {
                    if (target.hp <= 0 || target.banished) continue;

                    if (HexUtils.dist(h, target) <= radius) {
                        if (skill.power >= 0) {
                            if (target.team !== source.team) {
                                hitCount++;
                                score += 10;
                                if (target.castingSkillIdx !== -1) score += 5;
                            }
                        } else {
                            if (target.team === source.team) {
                                hitCount++;
                                score += 10;
                                if (target.hp < target.maxHp * 0.5) score += 5;
                            }
                        }
                    }
                }

                if (hitCount > 0 && score > bestScore) {
                    bestScore = score;
                    bestHex = h;
                }
            });

            if (bestHex) {
                return { targetAgent: null, targetHex: bestHex };
            }
        }

        let minD = 999;
        let t: Agent | null = null;
        for (const o of engine.agents) {
            if (o.team !== source.team && o.hp > 0 && !o.banished) {
                const d = HexUtils.dist(source, o);
                if (d <= skill.range && d < minD) { minD = d; t = o; }
            }
        }
        return { targetAgent: t, targetHex: null };
    }
}

import { Agent, GameEngine } from "../game";
import { Projectile, Skill, GameEventType, AnimState, Hex } from "../../types";
import { HexUtils, Vector } from "../utils";
import { BLOCK_HEIGHT } from "../../constants";

const UNIT_CHEST_HEIGHT = 40;
const HIT_IMPULSE_MAX = 20;
const HIT_IMPULSE_MIN = 5;

export class CombatSystem {
    public projectiles: Projectile[] = [];

    // =========================================================================================
    // ⚔️ MAIN UPDATE LOOP
    // =========================================================================================

    public update(dt: number, engine: GameEngine) {
        this.updateProjectiles(dt, engine);

        // Handle Casting Logic for Agents
        engine.agents.forEach(a => {
            if (a.hp <= 0) return;
            if (a.castingSkillIdx !== -1) {
                this.updateAgentCasting(a, dt, engine);
            }
        });
    }

    private updateAgentCasting(a: Agent, dt: number, engine: GameEngine) {
        // Interrupt Checks
        if (a.stunTimer > 0 || a.banished || a.silenceTimer > 0) {
            const skillName = a.skills[a.castingSkillIdx]?.name || '技能';
            engine.log(a, '中斷', null, `${skillName} 被打斷`);

            a.castingSkillIdx = -1;
            a.castTimer = 0;
            a.castingAnimationTimer = 0;
            a.setAnim(AnimState.IDLE); 
            return;
        }

        a.castTimer -= dt;
        if (a.castingAnimationTimer > 0) a.castingAnimationTimer -= dt; 

        // Cast Completion
        if (a.castTimer <= 0) {
            const s = a.skills[a.castingSkillIdx]!;

            // Mana Cost & Gain
            a.mp = Math.min(a.maxMp, Math.max(0, a.mp - s.cost + s.gain));
            a.curCDs[a.castingSkillIdx] = s.cd;

            // Execution
            if (s.projectileSpeed && s.projectileSpeed > 0) {
                 this.spawnProjectile(a, s, engine);
            } else {
                this.executeInstantSkill(a, s, engine);
            }

            // Reset State
            a.castingSkillIdx = -1;
            a.castingAnimationTimer = 0;
            a.setAnim(AnimState.COMBAT_IDLE);
        }
    }

    // =========================================================================================
    // 🏹 PROJECTILE LOGIC
    // =========================================================================================

    public spawnProjectile(source: Agent, skill: Skill, engine: GameEngine) {
        let tx = 0, ty = 0;
        let tid = "";
        let targetPos = {x: 0, y: 0};

        if (skill.type === 'AOE') {
             if (source.targetHex) {
                 const p = HexUtils.toPx(source.targetHex.q, source.targetHex.r, engine.mapConfig);
                 tx = p.x; ty = p.y;
                 tid = `ground-${source.targetHex.q},${source.targetHex.r}`;
             } else if (source.target) {
                 tx = source.target.px; ty = source.target.py;
                 tid = source.target.id;
             } else {
                 return; // No target
             }
             targetPos = {x: tx, y: ty};
             this.createProjectile(source, skill, targetPos, tid, engine);
             engine.events.push({ type: 'PROJECTILE_SPAWN', pos: {x: source.px, y: source.py}, skill: skill, targetId: tid });

        } else {
            // Single Target Projectile (Multi-target logic if needed in future)
            const targets = (source.target && !source.target.banished && source.target.hp > 0 ? [source.target] : []);
            targets.forEach(t => {
                 targetPos = {x: t.px, y: t.py};
                 this.createProjectile(source, skill, targetPos, t.id, engine);
                 engine.events.push({ type: 'PROJECTILE_SPAWN', pos: {x: source.px, y: source.py}, skill: skill, targetId: t.id });
            });
        }
    }

    private createProjectile(source: Agent, skill: Skill, targetPos: {x: number, y: number}, targetId: string, engine: GameEngine) {
        this.projectiles.push({
            id: Math.random().toString(),
            x: source.px, 
            y: source.py,
            startX: source.px, 
            startY: source.py,
            targetId: targetId,
            targetPos: targetPos,
            speed: skill.projectileSpeed!,
            skill: skill,
            sourceId: source.id,
            team: source.team,
            trail: []
        });
    }

    private updateProjectiles(dt: number, engine: GameEngine) {
        for (let i = this.projectiles.length - 1; i >= 0; i--) {
            const p = this.projectiles[i];

            const isGroundTarget = p.targetId.startsWith('ground-');
            let target = isGroundTarget ? null : engine.agents.find(a => a.id === p.targetId);

            // Homing logic: update target position if unit moves
            if (target && !isGroundTarget) {
                p.targetPos = {x: target.px, y: target.py};
            }

            const dir = Vector.normalize(Vector.sub(p.targetPos, {x: p.x, y: p.y}));
            const dist = Vector.dist({x: p.x, y: p.y}, p.targetPos);
            const moveDist = p.speed * dt;

            p.trail.push({x: p.x, y: p.y});
            if (p.trail.length > 20) p.trail.shift();

            // Hit Detection
            if (dist <= moveDist || dist < 10) {
                const source = engine.agents.find(a => a.id === p.sourceId) || engine.agents[0]; // Fallback to first if source dead (rare)

                if (p.skill.type === 'AOE') {
                    const hitPos = p.targetPos; 
                    const hitHex = HexUtils.fromPx(hitPos.x, hitPos.y, engine.mapConfig);
                    const radius = p.skill.aoeRadius || 1;
                    const targets = engine.agents.filter(e => e.team !== p.team && e.hp > 0 && !e.banished && HexUtils.dist(hitHex, e) <= radius);
                    targets.forEach(t => { if (source) this.applyDamage(source, t, p.skill, hitPos, engine); });
                    engine.events.push({ type: 'PROJECTILE_HIT', pos: {x: hitPos.x, y: hitPos.y}, skill: p.skill });
                } else {
                    if (target && target.hp > 0 && !target.banished) {
                        if (source) this.applyDamage(source, target, p.skill, undefined, engine);
                    }
                    engine.events.push({ type: 'PROJECTILE_HIT', pos: {x: p.x, y: p.y}, skill: p.skill });
                }

                // Remove projectile (swap and pop for performance)
                const lastIdx = this.projectiles.length - 1;
                if (i !== lastIdx) {
                    this.projectiles[i] = this.projectiles[lastIdx];
                }
                this.projectiles.pop();

            } else {
                p.x += dir.x * moveDist;
                p.y += dir.y * moveDist;
            }
        }
    }

    // =========================================================================================
    // 💥 SKILL EXECUTION
    // =========================================================================================

    public executeInstantSkill(source: Agent, skill: Skill, engine: GameEngine) {
        const radius = skill.aoeRadius || 1;
        let targets: Agent[] = [];
        let centerHex: Hex | null = null;

        if (skill.type === 'AOE') {
            if (source.targetHex) {
                centerHex = source.targetHex;
            } else if (source.target) {
                centerHex = { q: source.target.q, r: source.target.r };
            } else {
                centerHex = { q: source.q, r: source.r };
            }

            if (centerHex) {
                targets = engine.agents.filter(e => 
                    e.team !== source.team && 
                    e.hp > 0 && !e.banished &&
                    HexUtils.dist(centerHex!, e) <= radius
                );
            }
        } else {
            targets = (source.target && !source.target.banished && source.target.hp > 0 ? [source.target] : []);
        }

        const origin = {x: source.px, y: source.py};

        targets.forEach(t => this.applyDamage(source, t, skill, origin, engine));
        engine.events.push({ type: 'CAST_FINISH', pos: {x: source.px, y: source.py}, skill: skill });
    }

    public applyDamage(source: Agent, target: Agent, skill: Skill, origin: {x: number, y: number} | undefined, engine: GameEngine) {
        let rawDmg = skill.power;

        // Execute Logic
        const isExecute1 = skill.effectType === 'EXECUTE';
        const isExecute2 = skill.effectType2 === 'EXECUTE';
        if ((isExecute1 || isExecute2) && target.hp < target.maxHp * 0.3) {
            const multiplier = (isExecute1 ? skill.effectVal : skill.effectVal2) || 1.5;
            rawDmg = Math.floor(rawDmg * multiplier);
            engine.events.push({ type: 'CC_APPLIED', pos: {x: target.px, y: target.py}, text: "斬殺!", color: "#dc2626" });
        }

        let evtType: GameEventType = 'DAMAGE';
        let val = 0;

        if (rawDmg > 0) {
            target.hp -= rawDmg;
            val = -rawDmg;
            evtType = 'DAMAGE';
            target.setAnim(AnimState.HIT);
            target.hitFlashTimer = 0.2;

            // Physics Impulse
            const originX = origin ? origin.x : source.px;
            const originY = origin ? origin.y : source.py;
            let dx = target.px - originX;
            let dy = target.py - originY;
            const len = Math.sqrt(dx * dx + dy * dy);
            if (len > 0) {
                dx /= len; dy /= len;
                const impactForce = Math.min(HIT_IMPULSE_MAX, Math.max(HIT_IMPULSE_MIN, rawDmg * 0.3));
                target.physics.vx += dx * impactForce;
                target.physics.vy += dy * impactForce;
                target.physics.vAngle += (Math.random() - 0.5) * impactForce * 0.05;
            }

            // Vamp Logic
            const isVamp1 = skill.effectType === 'VAMP';
            const isVamp2 = skill.effectType2 === 'VAMP';
            if ((isVamp1 || isVamp2) && source.hp > 0) {
                const vampPct = (isVamp1 ? skill.effectVal : skill.effectVal2) || 0.5;
                const healAmt = Math.floor(rawDmg * vampPct);
                if (healAmt > 0) {
                    source.hp = Math.min(source.maxHp, source.hp + healAmt);
                    engine.events.push({ type: 'HEAL', pos: {x: source.px, y: source.py}, value: healAmt, color: '#86efac' });
                }
            }

        } else if (rawDmg < 0) {
            const heal = -rawDmg;
            target.hp = Math.min(target.maxHp, target.hp + heal);
            val = heal;
            evtType = 'HEAL';
        }

        // Mana Burn
        const isBurn1 = skill.effectType === 'MANA_BURN';
        const isBurn2 = skill.effectType2 === 'MANA_BURN';
        if (isBurn1 || isBurn2) {
            const burnAmt = (isBurn1 ? skill.effectVal : skill.effectVal2) || 30;
            target.mp = Math.max(0, target.mp - burnAmt);
            source.mp = Math.min(source.maxMp, source.mp + burnAmt);
            engine.events.push({ type: 'CC_APPLIED', pos: {x: target.px, y: target.py}, text: `-${burnAmt} MP`, color: "#3b82f6" });
        }

        // Mana Restore
        const isRestore1 = skill.effectType === 'MANA_RESTORE';
        const isRestore2 = skill.effectType2 === 'MANA_RESTORE';
        if (isRestore1 || isRestore2) {
             const amt = (isRestore1 ? skill.effectVal : skill.effectVal2) || 30;
             target.mp = Math.min(target.maxMp, target.mp + amt);
             engine.events.push({ type: 'CC_APPLIED', pos: {x: target.px, y: target.py}, text: `+${amt} MP`, color: "#60a5fa" });
        }

        engine.events.push({
            type: evtType,
            pos: { x: target.px, y: target.py },
            value: val,
            sourceId: source.id,
            targetId: target.id,
            skill: skill,
            color: skill.color
        });

        this.applyCC(source, target, skill, skill.ccType, skill.ccDur, skill.ccForce, origin, engine);
        this.applyCC(source, target, skill, skill.ccType2, skill.ccDur2, skill.ccForce2, origin, engine);

        engine.log(source, '命中', target.id, `${skill.name} ${rawDmg > 0 ? `-${rawDmg}` : (rawDmg < 0 ? `+${-rawDmg}` : '')}`);
    }

    public applyCC(source: Agent, target: Agent, skill: Skill, type: string | undefined, dur: number | undefined, force: number | undefined, origin: {x: number, y: number} | undefined, engine: GameEngine) {
        if (!type) return;
        const duration = dur || 0;
        const power = force || 0;

        if (type === 'STUN') {
            target.stunTimer = Math.max(target.stunTimer, duration);
            target.isMoving = false;
            target.setAnim(AnimState.STUN);
            engine.events.push({ type: 'CC_APPLIED', pos: {x: target.px, y: target.py}, text: "暈眩", color: "#facc15" });

            const isIce = skill.color.toLowerCase().includes('blue') || 
                          skill.color.includes('#60a5fa') || 
                          skill.color.includes('#e0f2fe') || 
                          skill.name.includes("冰") || 
                          skill.name.includes("凍") || 
                          skill.name.includes("雪");

            if (isIce) {
                target.visualStatus = 'FROZEN';
            }
        } else if (type === 'SILENCE') {
            target.silenceTimer = Math.max(target.silenceTimer, duration);
            engine.events.push({ type: 'CC_APPLIED', pos: {x: target.px, y: target.py}, text: "沉默", color: "#94a3b8" });
        } else if (type === 'BANISH') {
            target.banishTimer = Math.max(target.banishTimer, duration);
            target.banished = true;
            target.isMoving = false;
            target.setAnim(AnimState.STUN);
            engine.events.push({ type: 'CC_APPLIED', pos: {x: target.px, y: target.py}, text: "放逐", color: "#c084fc" });

            if (skill.name.includes("變形") || skill.name.includes("羊") || skill.name.includes("動物")) {
                target.visualStatus = 'POLYMORPH'; 
            } else {
                target.visualStatus = 'STASIS'; 
            }
        } else if (type === 'KNOCKBACK' || type === 'PULL') {
            // --- WEIGHTED KNOCKBACK LOGIC ---

            // 1. Calculate push tiles: (Skill Force - Unit Weight)
            const rawForce = Math.max(1, power);
            const resistance = target.weight || 1; 
            const tilesToPush = Math.max(0, rawForce - resistance);

            if (tilesToPush === 0) {
                engine.events.push({ type: 'CC_APPLIED', pos: {x: target.px, y: target.py}, text: "抵抗", color: "#94a3b8" });
                return;
            }

            const originPx = origin ? origin : {x: source.px, y: source.py};
            const dir = Vector.normalize(Vector.sub({x: target.px, y: target.py}, originPx));
            const vector = type === 'KNOCKBACK' ? dir : Vector.mult(dir, -1);

            let currentH = {q: target.q, r: target.r};
            let currentHeight = engine.map.getTerrainHeight(currentH.q, currentH.r);
            let finalH = currentH;

            // Iterative push
            for(let k=0; k<tilesToPush; k++) {
                const neighbors = HexUtils.neighbors(currentH);
                let bestN = null;
                let bestDot = -99;

                // Find best neighbor matching direction
                for(const n of neighbors) {
                    const nPx = HexUtils.toPx(n.q, n.r, engine.mapConfig);
                    const cPx = HexUtils.toPx(currentH.q, currentH.r, engine.mapConfig);
                    const nDir = Vector.normalize(Vector.sub(nPx, cPx));
                    const dot = nDir.x * vector.x + nDir.y * vector.y;

                    if (dot > bestDot) {
                        bestDot = dot;
                        bestN = n;
                    }
                }

                if (bestN) {
                    // Check Validity
                    if (!engine.isValid(bestN.q, bestN.r)) break; // Map Edge
                    if (engine.hasObstacle(bestN.q, bestN.r)) break; // Wall collision

                    const nextHeight = engine.map.getTerrainHeight(bestN.q, bestN.r);

                    // Height Check (Tactics Ogre Physics)
                    // If hitting a wall > 1 block high -> STOP
                    if (nextHeight > currentHeight + BLOCK_HEIGHT) {
                        break; 
                    }

                    // If falling off a cliff > 2 blocks -> STOP (or future: fall damage)
                    // Currently stopping to prevent weirdness, but allow small drops
                    if (nextHeight < currentHeight - BLOCK_HEIGHT * 2) {
                        break; 
                    }

                    // Move one step
                    currentH = bestN;
                    currentHeight = nextHeight;
                    finalH = bestN;
                } else {
                    break;
                }
            }

            if (finalH.q !== target.q || finalH.r !== target.r) {
                engine.updateAgentPosition(target, finalH.q, finalH.r);
                target.isMoving = false; 
                engine.events.push({ type: 'CC_APPLIED', pos: {x: target.px, y: target.py}, text: type === 'PULL' ? "牽引" : "擊退", color: "#fff" });
                target.setAnim(AnimState.HIT);

                // Add upward impulse for "hop" effect visually
                target.physics.vz += 200;
            }
        } else if (type === 'DOT') {
            target.dotDmg = power || 5;
            target.dotTimer = duration || 3;
            engine.events.push({ type: 'CC_APPLIED', pos: {x: target.px, y: target.py}, text: "中毒", color: "#10b981" });
        } else if (type === 'HOT') {
            target.hotVal = power || 5;
            target.hotTimer = duration || 3;
            engine.events.push({ type: 'CC_APPLIED', pos: {x: target.px, y: target.py}, text: "再生", color: "#86efac" });
        }
    }
}

import React, { useEffect, useRef, useState } from 'react';
import { GameEngine, Agent } from '../engine/game';
import { GameRenderer } from '../engine/renderer';
import { HexUtils } from '../engine/utils';
import { Team, ToolType, Hex, Skill, GameEvent } from '../types';
import { BLOCK_HEIGHT, HEX_SIZE } from '../constants'; 

interface GameCanvasProps {
    engine: GameEngine;
    tool: ToolType;
    hpInput: number;
    selectedAgent: Agent | null; 
    hoveredSkill: Skill | null;
    isDeepTerrain: boolean;
    isShowcaseMode: boolean; 
    onSelect: (a: Agent | null) => void;
    onWin: (team: Team) => void;
    winner: Team | null;
    rematch: () => void;
    transitionPhase: 'IDLE' | 'IN' | 'OUT';
}

const GameCanvas: React.FC<GameCanvasProps> = ({ engine, tool, hpInput, selectedAgent, hoveredSkill, isDeepTerrain, isShowcaseMode, onSelect, onWin, winner, rematch, transitionPhase }) => {
    const canvasRef = useRef<HTMLCanvasElement>(null);
    const wrapperRef = useRef<HTMLDivElement>(null);
    const camera = useRef({ x: 0, y: 0, zoom: 1.0 }); // Adjusted default zoom
    const fpsRef = useRef(60);

    // Instantiate Renderer
    const rendererRef = useRef(new GameRenderer());
    const transitionStartTime = useRef(0);

    // Bridge for Synchronous Redraw (Fixes black flash on resize)
    const drawCurrentFrameRef = useRef<() => void>(() => {});

    // Sync Terrain Mode
    useEffect(() => {
        // Updated: Set depth on MapSystem, which Logic uses
        engine.map.setTerrainDepth(isDeepTerrain ? 2.5 : 1.0, engine);
        // GridSystem in Renderer will read from engine.map automatically
    }, [isDeepTerrain, engine]);

    // Handle Transition Phase Timing
    useEffect(() => {
        transitionStartTime.current = performance.now();
    }, [transitionPhase]);

    // Interaction State
    const draggedAgentRef = useRef<Agent | null>(null);
    const dragStartHex = useRef<{q: number, r: number} | null>(null);
    const isDraggingUnit = useRef(false);

    const isPanning = useRef(false);
    const pointerDownStart = useRef<{x: number, y: number} | null>(null);
    const pendingAction = useRef<boolean>(false); 

    // Track hovered hex for visual feedback
    const hoveredHexRef = useRef<Hex | null>(null);

    // Track selected agent for the render loop
    const selectedAgentRef = useRef<Agent | null>(selectedAgent);
    useEffect(() => {
        selectedAgentRef.current = selectedAgent;
    }, [selectedAgent]);

    // --- Camera Control Logic ---
    const centerCamera = () => {
        if (!canvasRef.current || !wrapperRef.current) return;

        // Ensure dims are fresh
        canvasRef.current.width = wrapperRef.current.clientWidth;
        canvasRef.current.height = wrapperRef.current.clientHeight;

        const cw = engine.mapConfig.w;
        const ch = engine.mapConfig.h;

        // Calculate grid visual center
        // Grid Top-Left is roughly (0,0) in Axial
        // Center is (w/2, h/2)
        const centerHex = { q: Math.floor(cw / 2), r: Math.floor(ch / 2) };
        const p = HexUtils.toPx(centerHex.q, centerHex.r, engine.mapConfig);

        // Visual adjustments
        // 1. Terrain Height offset: Blocks go "up" (negative Y), so the visual center of the top face is higher than p.y
        // We estimate average height to be around 2 blocks
        const verticalOffset = -BLOCK_HEIGHT * 2; 

        // Center Point Formula: WorldPos - (ScreenSize / Zoom) / 2
        camera.current.x = p.x - (canvasRef.current.width / camera.current.zoom) / 2;
        camera.current.y = p.y + verticalOffset - (canvasRef.current.height / camera.current.zoom) / 2;
    };

    // Auto-Center Triggers
    useEffect(() => {
        // Trigger centering when:
        // 1. Transition IN starts (New map generated in Showcase)
        // 2. Showcase Mode is entered toggled on
        // 3. Map dimensions change (manual settings)
        if (isShowcaseMode || transitionPhase === 'IN') {
            // Wait for CSS transition (300ms) to finish before centering
            const t = setTimeout(centerCamera, 350);
            return () => clearTimeout(t);
        } else if (!isShowcaseMode && transitionPhase === 'IDLE') {
             // Also recenter when exiting showcase mode
             const t = setTimeout(centerCamera, 350);
             return () => clearTimeout(t);
        }
    }, [isShowcaseMode, transitionPhase, engine.mapConfig.w, engine.mapConfig.h]);

    // Resize Observer for Fluid Layout
    useEffect(() => {
        if (!wrapperRef.current || !canvasRef.current) return;

        const resizeObserver = new ResizeObserver(() => {
            if (wrapperRef.current && canvasRef.current) {
                // Immediately update canvas resolution to match container
                canvasRef.current.width = wrapperRef.current.clientWidth;
                canvasRef.current.height = wrapperRef.current.clientHeight;

                // If map is empty (initial load), center it
                if (engine.agents.length === 0) {
                    centerCamera();
                }

                // CRITICAL FIX: Synchronous Redraw
                // Immediately draw the frame to prevent the canvas from appearing blank/black 
                // between the resize (clear) and the next animation frame.
                drawCurrentFrameRef.current();
            }
        });

        resizeObserver.observe(wrapperRef.current);

        // Force initial center
        centerCamera();

        return () => resizeObserver.disconnect();
    }, [engine]);

    // Render Loop
    useEffect(() => {
        let frameId: number;
        let lastTime = 0;
        let acc = 0;
        const targetFPS = 60;
        const step = 1000 / targetFPS;
        let frameCount = 0;
        let lastFpsTime = 0;

        // Define draw function that can be called externally via ref
        const drawFrame = () => {
            const ctx = canvasRef.current?.getContext('2d');
            if (ctx) {
                const highlight = draggedAgentRef.current || selectedAgentRef.current || null;
                rendererRef.current.draw(ctx, engine, camera.current, highlight, fpsRef.current, hoveredHexRef.current, hoveredSkill); 
            }
        };

        // Assign to ref for ResizeObserver
        drawCurrentFrameRef.current = drawFrame;

        const loop = (t: number) => {
            if (!lastTime) lastTime = t;
            const dt = t - lastTime;
            lastTime = t;

            // Measure FPS
            frameCount++;
            if (t - lastFpsTime >= 1000) {
                fpsRef.current = frameCount;
                frameCount = 0;
                lastFpsTime = t;
            }

            // Logic Step
            if (engine.isRunning) {
                acc += dt;
                if (acc > 200) acc = 200;

                const frameEvents: GameEvent[] = [];

                while (acc >= step) {
                    const sdt = (step / 1000) * engine.timeScale;
                    engine.tick(sdt);
                    engine.battleTime += sdt;
                    acc -= step;

                    // Collect events from this tick to avoid dropping them
                    // or processing them multiple times in the render loop
                    frameEvents.push(...engine.events);
                }

                // Only process events if we actually ticked logic this frame
                if (frameEvents.length > 0) {
                    rendererRef.current.processEventsWithEngine(frameEvents, engine);
                }
            }

            // Visual Update
            rendererRef.current.update(dt / 1000, engine);

            // Handle Transition Animation Progress
            if (transitionPhase !== 'IDLE') {
                const elapsed = (performance.now() - transitionStartTime.current) / 1000;
                // Transition usually lasts 1.5s total logic in App, let's map 0-1 over 1.2s for visual
                const progress = Math.min(1.0, elapsed / 1.2);
                rendererRef.current.setTransition(progress, transitionPhase);
            } else {
                rendererRef.current.setTransition(0, 'IDLE');
            }

            drawFrame();
            frameId = requestAnimationFrame(loop);
        };

        engine.onWin = (team) => {
            onWin(team);
        };

        frameId = requestAnimationFrame(loop);
        return () => cancelAnimationFrame(frameId);
    }, [engine, onWin, hoveredSkill, transitionPhase]);

    // Input Handling
    useEffect(() => {
        const cvs = canvasRef.current;
        if (!cvs) return;

        const getHexFromEvent = (e: MouseEvent) => {
            const rect = cvs.getBoundingClientRect();
            const mouseX = e.clientX - rect.left;
            const mouseY = e.clientY - rect.top;

            // Use renderer's accurate 3D picking logic
            const hex = rendererRef.current.getHexAtScreenPoint(mouseX, mouseY, camera.current, engine);
            if (hex) return hex;

            // Picking fallback in 3D is tricky, we rely on the grid system's robustness
            return HexUtils.fromPx(
                mouseX / camera.current.zoom + camera.current.x,
                mouseY / camera.current.zoom + camera.current.y,
                engine.mapConfig
            );
        };

        const getWorldPosFromEvent = (e: MouseEvent) => {
            const rect = cvs.getBoundingClientRect();
            const mouseX = e.clientX - rect.left;
            const mouseY = e.clientY - rect.top;
            const wx = mouseX / camera.current.zoom + camera.current.x;

            // Get height at this position (approximate)
            const hex = rendererRef.current.getHexAtScreenPoint(mouseX, mouseY, camera.current, engine);
            let h = BLOCK_HEIGHT + 6;
            if (hex) h = rendererRef.current.getTerrainHeight(hex.q, hex.r);

            const wy = mouseY / camera.current.zoom + camera.current.y + h;
            return { x: wx, y: wy };
        };

        const handleMouseDown = (e: MouseEvent) => {
            pointerDownStart.current = { x: e.clientX, y: e.clientY };

            if (e.button === 2) {
                isPanning.current = true;
                pendingAction.current = false;
                return;
            }

            const h = getHexFromEvent(e);
            const agent = engine.getAgentAt(h.q, h.r);

            if (agent) {
                pendingAction.current = false;

                if (!engine.isRunning && tool === ToolType.DELETE) {
                    engine.removeAgent(h.q, h.r);
                    onSelect(null);
                    return;
                }

                onSelect(agent);

                if (!engine.isRunning) {
                    draggedAgentRef.current = agent;
                    dragStartHex.current = { q: agent.q, r: agent.r };
                    isDraggingUnit.current = true;
                }
                return;
            }

            pendingAction.current = true;
            isPanning.current = false;
        };

        const handleMouseMove = (e: MouseEvent) => {
            const h = getHexFromEvent(e);
            if (engine.isValid(h.q, h.r)) {
                hoveredHexRef.current = h;
            } else {
                hoveredHexRef.current = null;
            }

            if (isPanning.current) {
                camera.current.x -= e.movementX / camera.current.zoom;
                camera.current.y -= e.movementY / camera.current.zoom;
                return;
            }

            if (isDraggingUnit.current && draggedAgentRef.current) {
                const wPos = getWorldPosFromEvent(e);
                draggedAgentRef.current.px = wPos.x;
                draggedAgentRef.current.py = wPos.y;
                return;
            }

            if (pendingAction.current && pointerDownStart.current) {
                const dx = e.clientX - pointerDownStart.current.x;
                const dy = e.clientY - pointerDownStart.current.y;
                const dist = Math.sqrt(dx*dx + dy*dy);

                if (dist > 5) {
                    pendingAction.current = false;
                    isPanning.current = true;
                    camera.current.x -= e.movementX / camera.current.zoom;
                    camera.current.y -= e.movementY / camera.current.zoom;
                }
            }
        };

        const handleMouseUp = (e: MouseEvent) => {
            if (isPanning.current) {
                isPanning.current = false;
                pointerDownStart.current = null;
                return;
            }

            if (isDraggingUnit.current && draggedAgentRef.current) {
                const h = getHexFromEvent(e);
                const agent = draggedAgentRef.current;
                const isValidHex = engine.isValid(h.q, h.r);
                const isObstacle = engine.obstacles.has(HexUtils.key(h));
                const occupant = engine.getAgentAt(h.q, h.r);
                const isOccupiedByOther = occupant && occupant !== agent;

                if (isValidHex && !isObstacle && !isOccupiedByOther) {
                    agent.q = h.q;
                    agent.r = h.r;
                    const p = HexUtils.toPx(h.q, h.r, engine.mapConfig);
                    agent.px = p.x;
                    agent.py = p.y;
                } else {
                    if (dragStartHex.current) {
                        agent.q = dragStartHex.current.q;
                        agent.r = dragStartHex.current.r;
                        const p = HexUtils.toPx(agent.q, agent.r, engine.mapConfig);
                        agent.px = p.x;
                        agent.py = p.y;
                    }
                }

                draggedAgentRef.current = null;
                dragStartHex.current = null;
                isDraggingUnit.current = false;
                onSelect(agent);
                return;
            }

            if (pendingAction.current) {
                pendingAction.current = false;
                const h = getHexFromEvent(e);

                if (tool === ToolType.SELECT) {
                    onSelect(null);
                } else if (!engine.isRunning && winner === null) {
                    if (tool === ToolType.ADD_BLUE) engine.addAgent(Team.BLUE, h.q, h.r, hpInput);
                    else if (tool === ToolType.ADD_RED) engine.addAgent(Team.RED, h.q, h.r, hpInput);
                    else if (tool === ToolType.OBSTACLE) engine.toggleObstacle(h.q, h.r);
                    else if (tool === ToolType.DELETE) {
                        if (engine.obstacles.has(HexUtils.key(h))) {
                            engine.toggleObstacle(h.q, h.r);
                        }
                        onSelect(null);
                    }
                }
            }

            pointerDownStart.current = null;
        };

        const handleWheel = (e: WheelEvent) => {
            e.preventDefault();
            const delta = e.deltaY > 0 ? -0.1 : 0.1;
            camera.current.zoom = Math.max(0.5, Math.min(3.0, camera.current.zoom + delta));
        };

        const handleContextMenu = (e: MouseEvent) => e.preventDefault();

        cvs.addEventListener('mousedown', handleMouseDown);
        window.addEventListener('mousemove', handleMouseMove);
        window.addEventListener('mouseup', handleMouseUp);
        cvs.addEventListener('wheel', handleWheel, { passive: false });
        cvs.addEventListener('contextmenu', handleContextMenu);

        return () => {
            cvs.removeEventListener('mousedown', handleMouseDown);
            window.removeEventListener('mousemove', handleMouseMove);
            window.removeEventListener('mouseup', handleMouseUp);
            cvs.removeEventListener('wheel', handleWheel);
            cvs.removeEventListener('contextmenu', handleContextMenu);
        };
    }, [engine, tool, hpInput, onSelect, winner, isDeepTerrain]);

    return (
        <div ref={wrapperRef} className="flex-1 overflow-hidden relative bg-slate-950 border-r border-slate-700">
            <canvas 
                ref={canvasRef} 
                className={`block shadow-inner ${tool === ToolType.SELECT ? 'cursor-default' : 'cursor-crosshair'}`}
                style={{ backgroundColor: engine.currentScene.background }} 
            />

            {/* STANDARD MODE VICTORY SCREEN */}
            {winner !== null && !isShowcaseMode && (
                <div className="absolute inset-0 flex items-center justify-center bg-black/70 z-50">
                    <div className="text-center p-8 bg-slate-900 rounded-lg border border-slate-700 shadow-2xl animate-bounce-in">
                        <h2 className={`text-4xl font-bold mb-4 font-serif tracking-widest ${winner === Team.BLUE ? 'text-blue-400' : 'text-red-400'}`}>
                            {winner === Team.BLUE ? 'VICTORY' : 'DEFEAT'}
                        </h2>
                        <button onClick={rematch} className="bg-slate-700 hover:bg-slate-600 text-white font-bold py-2 px-6 rounded border border-slate-500">REMATCH</button>
                    </div>
                </div>
            )}
        </div>
    );
};

export default GameCanvas;

import { Agent } from "../game";
import { SpriteManager } from "../sprites";
import { AssetManager } from "../assets";
import { AnimState, Role, Team } from "../../types";
import { RenderableItem } from "./grid";
import { HEX_SIZE } from "../../constants";

// Visual Constants
const MAX_UNIT_SIZE_RATIO = 0.85; 
const UNIT_REFERENCE_HEIGHT = 100; 

export class UnitRenderSystem {

    public collectRenderables(
        agents: Agent[], 
        getTerrainHeight: (q: number, r: number) => number, 
        globalTime: number, 
        highlightAgent: Agent | null
    ): RenderableItem[] {
        const list: RenderableItem[] = [];

        agents.forEach(agent => {
            if (agent.hp <= 0 && agent.fullyDead) return;

            // --- HEIGHT INTERPOLATION ---
            let currentHeight = getTerrainHeight(agent.q, agent.r);
            if (agent.isMoving && agent.path.length > 0) {
                const dest = agent.path[0];
                const destHeight = getTerrainHeight(dest.q, dest.r);
                const t = agent.moveProgress;
                currentHeight = currentHeight + (destHeight - currentHeight) * t;
            }

            const visualY = agent.py - currentHeight;

            list.push({
                y: agent.py + 1, 
                z: 10,
                draw: (ctx) => this.drawAssembly(
                    ctx, 
                    agent, 
                    agent.px, 
                    visualY, 
                    globalTime, 
                    highlightAgent === agent,
                    false // Normal Mode
                )
            });
        });

        return list;
    }

    // Called by Renderer for Occlusion Pass
    public drawSilhouette(
        ctx: CanvasRenderingContext2D, 
        agent: Agent, 
        getTerrainHeight: (q: number, r: number) => number,
        globalTime: number
    ) {
        // Recalculate position (same as collectRenderables)
        let currentHeight = getTerrainHeight(agent.q, agent.r);
        if (agent.isMoving && agent.path.length > 0) {
            const dest = agent.path[0];
            const destHeight = getTerrainHeight(dest.q, dest.r);
            const t = agent.moveProgress;
            currentHeight = currentHeight + (destHeight - currentHeight) * t;
        }
        const visualY = agent.py - currentHeight;

        this.drawAssembly(ctx, agent, agent.px, visualY, globalTime, false, true);
    }

    // =================================================================================
    // 🎨 HIERARCHICAL VECTOR ASSEMBLY RENDERER
    // =================================================================================

    private drawAssembly(
        ctx: CanvasRenderingContext2D, 
        agent: Agent, 
        drawX: number, 
        drawY: number, 
        globalTime: number, 
        isSelected: boolean,
        isSilhouette: boolean
    ) {
        // 1. Setup Constraint Space
        const maxDimension = HEX_SIZE * 2 * MAX_UNIT_SIZE_RATIO;

        // Distinct Scale Factors for Roles
        let roleScaleMod = 1.0;
        switch(agent.role) {
            case Role.TANK: roleScaleMod = 1.25; break; // Bulky
            case Role.WARRIOR: roleScaleMod = 1.1; break; // Standard strong
            case Role.RANGER: roleScaleMod = 0.9; break; // Agile/Slim
            case Role.MAGE: roleScaleMod = 0.9; break; // Small/Floating
            case Role.SUPPORT: roleScaleMod = 0.95; break;
        }

        const scaleFactor = (maxDimension / UNIT_REFERENCE_HEIGHT) * roleScaleMod;

        ctx.save();
        ctx.translate(drawX, drawY);
        ctx.scale(scaleFactor, scaleFactor);

        // 3. Apply Physics (Z-Jump / Blast)
        // We apply Physics Z translation to the whole container (Base + Body)
        const physX = agent.physics.x / scaleFactor;
        const physY = agent.physics.y / scaleFactor;
        const physZ = agent.physics.z / scaleFactor; 

        ctx.translate(physX, physY - physZ); 
        ctx.rotate(agent.physics.angle); // Apply Ragdoll Rotation

        // --- DRAW BASE (Ground Level) ---
        // The base should strictly align with the grid face (0,0 local)
        if (!isSilhouette && agent.hp > 0 && agent.visualStatus !== 'POLYMORPH') {
            const assets = SpriteManager.getUnitImages(agent.role, agent.team);
            ctx.save();
            // Center of base sprite ellipse is at (64, 79). 
            // We draw at (-64, -79) to align it with (0,0).
            ctx.drawImage(assets.base, -64, -79); 

            // Casting Floor Rune (Ground level)
            if (agent.castingSkillIdx !== -1) {
                const skill = agent.skills[agent.castingSkillIdx];
                if (skill) {
                    const circle = AssetManager.getMagicCircle(skill.color, skill.tag === 'ULT');
                    ctx.save(); 
                    ctx.scale(1, 0.5); 
                    ctx.rotate(globalTime * 2);
                    ctx.globalAlpha = 0.6;
                    ctx.drawImage(circle, -64, -64, 128, 128); 
                    ctx.restore();
                }
            }
            ctx.restore();
        }

        // --- PREPARE BODY TRANSFORM ---
        // Shift up to align body feet with ground (y=0)
        // Standard body drawing has feet around y=15. So we shift up by -15.
        const BODY_GROUNDING_OFFSET = -15; 

        let bodyFloat = BODY_GROUNDING_OFFSET; 

        // Add Breathing / Hovering
        if (agent.hp > 0) {
             if ((agent.role === Role.MAGE || agent.role === Role.SUPPORT) && !agent.isMoving && agent.visualStatus === 'NONE') {
                bodyFloat -= 5 + Math.sin(globalTime * 2) * 3; // Mages float higher
            }
        } else {
            bodyFloat = -5; // Dead units sink slightly into ground
        }

        ctx.translate(0, bodyFloat);

        // --- 2. Spawn Animation (Materialize) ---
        // Applies scale stretch and alpha fade if spawning
        let spawnAlpha = 1.0;
        let whiteOverlay = 0;

        if (agent.spawnTimer > 0) {
            const SPAWN_DURATION = 0.5; // From game.ts init
            const progress = 1 - (agent.spawnTimer / SPAWN_DURATION); // 0 -> 1
            const eased = 1 - Math.pow(1 - progress, 3); // Cubic Out

            spawnAlpha = eased;
            const spawnStretch = 2.0 - eased; // 2.0 -> 1.0
            whiteOverlay = 1 - eased; // 1 -> 0

            // Scale body vertically around its feet (now at 0,0 due to translate)
            ctx.scale(1, spawnStretch);
            ctx.globalAlpha *= spawnAlpha;
        }

        // Hit Flash / Death Filter
        if (agent.hp <= 0 && !isSilhouette) {
            ctx.filter = 'grayscale(100%) opacity(80%)'; 
        } else if (!isSilhouette && agent.hitFlashTimer > 0) {
            ctx.filter = 'brightness(200%)'; 
        } else if (whiteOverlay > 0) {
            ctx.filter = `brightness(${100 + whiteOverlay * 200}%)`;
        }

        ctx.scale(agent.facing > 0 ? 1 : -1, 1);

        // SILHOUETTE MODE SETUP
        if (isSilhouette) {
            ctx.globalCompositeOperation = 'source-over'; 
            ctx.globalAlpha = 0.8; 
        }

        // 4. Render Body (or Special Form)
        if (agent.visualStatus === 'POLYMORPH') {
            // Draw Sheep
            const sheep = SpriteManager.getSpecialModel('SHEEP');
            const bounce = Math.abs(Math.sin(globalTime * 5) * 5);
            ctx.drawImage(sheep, -32, -32 - bounce, 64, 64);
        } else {
            // Standard Unit Render
            if (agent.team === Team.BLUE) {
                this.drawImperialLegion(ctx, agent, globalTime, isSilhouette);
            } else {
                this.drawArcaneCovenant(ctx, agent, globalTime, isSilhouette);
            }

            // Casting VFX (Only if alive)
            if (!isSilhouette && agent.hp > 0 && agent.castingSkillIdx !== -1) {
                this.drawCastingVFX(ctx, agent, globalTime);
            }

            // Frozen Overlay
            if (agent.visualStatus === 'FROZEN') {
                const ice = SpriteManager.getSpecialModel('ICE');
                ctx.save();
                ctx.globalCompositeOperation = 'hard-light';
                // Ice block needs to cover body, roughly centered
                ctx.drawImage(ice, -48, -75, 96, 128);
                ctx.restore();
            }

            // Stasis Overlay
            if (agent.visualStatus === 'STASIS') {
                ctx.save();
                ctx.fillStyle = '#facc15';
                ctx.globalAlpha = 0.4;
                ctx.globalCompositeOperation = 'lighter';
                ctx.beginPath();
                ctx.ellipse(0, -15, 25, 50, 0, 0, Math.PI*2);
                ctx.fill();
                ctx.strokeStyle = '#fff';
                ctx.lineWidth = 2;
                ctx.stroke();
                ctx.restore();
            }
        }

        // 6. Selection Ring & Status (Only Normal Mode & Alive)
        if (!isSilhouette) {
            this.drawStatusIcons(ctx, agent, globalTime, drawX, drawY, scaleFactor);
            this.drawStatusEffects(ctx, agent, globalTime);

            if (isSelected && agent.hp > 0) {
                // Draw Selection Ring around Body center (approx -20)
                ctx.strokeStyle = '#fff';
                ctx.lineWidth = 2 / scaleFactor; 
                ctx.beginPath();
                ctx.ellipse(0, -20, 30, 15, 0, 0, Math.PI * 2);
                ctx.stroke();
            }
        }

        ctx.restore(); // End Assembly

        // 7. NEW: Spawn Role Indicator
        // Drawn AFTER restore so it is not affected by body stretch/fade/rotation
        if (agent.spawnTimer > 0 && !isSilhouette) {
            this.drawSpawnIndicator(ctx, agent, drawX, drawY, scaleFactor);
        }
    }

    private drawSpawnIndicator(ctx: CanvasRenderingContext2D, agent: Agent, x: number, y: number, scale: number) {
        const assets = SpriteManager.getUnitImages(agent.role, agent.team);
        const totalDuration = 0.5;
        const alpha = Math.max(0, agent.spawnTimer / totalDuration);
        const yOffset = -40 * scale; 

        ctx.save();
        ctx.translate(x, y + yOffset);
        const popScale = 1.0 + alpha * 0.2;
        ctx.scale(popScale, popScale);
        ctx.globalAlpha = alpha;

        ctx.fillStyle = 'rgba(15, 23, 42, 0.4)'; 
        ctx.strokeStyle = agent.team === Team.BLUE ? 'rgba(59, 130, 246, 0.8)' : 'rgba(239, 68, 68, 0.8)';
        ctx.lineWidth = 2;
        ctx.beginPath(); ctx.arc(0, 0, 18, 0, Math.PI*2); ctx.fill(); ctx.stroke();

        ctx.drawImage(assets.icon, -12, -12, 24, 24);

        ctx.font = 'bold 10px sans-serif';
        ctx.textAlign = 'center';
        ctx.fillStyle = '#fff';
        ctx.strokeStyle = 'rgba(0,0,0,0.8)';
        ctx.lineWidth = 2;
        ctx.strokeText(agent.role, 0, 28);
        ctx.fillText(agent.role, 0, 28);

        ctx.restore();
    }

    private drawStatusEffects(ctx: CanvasRenderingContext2D, agent: Agent, t: number) {
        if (agent.hp <= 0) return;

        ctx.save();
        // Undo facing flip so icons don't flip
        if (agent.facing < 0) ctx.scale(-1, 1);

        const HEAD_Y = -75; // Adjusted head position for icons

        // 1. STUN
        if (agent.stunTimer > 0 && !agent.banished && agent.visualStatus !== 'FROZEN') {
            const icon = AssetManager.getStatusIcon('STUN');
            const angle = t * 5;
            ctx.drawImage(icon, -20 + Math.cos(angle)*10, HEAD_Y + Math.sin(angle)*5, 24, 24);
            ctx.drawImage(icon, -10 + Math.cos(angle + 2)*10, HEAD_Y - 10 + Math.sin(angle + 2)*5, 16, 16);
        }

        // 2. SILENCE
        if (agent.silenceTimer > 0) {
            const icon = AssetManager.getStatusIcon('SILENCE');
            ctx.drawImage(icon, 15, HEAD_Y - 5 + Math.sin(t * 3) * 3, 24, 24);
        }

        // 3. BANISH
        if (agent.banished && agent.visualStatus === 'NONE') {
            const icon = AssetManager.getStatusIcon('BANISH');
            ctx.globalAlpha = 0.7;
            ctx.drawImage(icon, -12, HEAD_Y - 20 + Math.sin(t * 2) * 5, 24, 24);
        }

        // 4. DoT
        if (agent.dotTimer > 0) {
            const pulse = 1 + Math.sin(t * 10) * 0.2;
            const iconSize = 28 * pulse; 
            const icon = AssetManager.getStatusIcon('POISON'); 
            const glow = AssetManager.getGlowSprite('#ef4444');
            ctx.globalCompositeOperation = 'lighter';
            ctx.drawImage(glow, -35 - iconSize/2, HEAD_Y - iconSize/2, iconSize*2, iconSize*2);
            ctx.globalCompositeOperation = 'source-over';
            ctx.drawImage(icon, -35, HEAD_Y, iconSize, iconSize);

            ctx.globalAlpha = 0.8;
            for(let i=0; i<5; i++) {
                const cycle = (t * 2 + i * 0.7) % 1;
                const yOff = -cycle * 60; 
                const xOff = Math.sin(t * 5 + i) * 15;
                const size = (1 - cycle) * 7;
                ctx.fillStyle = i % 2 === 0 ? '#10b981' : '#a855f7';
                if (cycle < 1) {
                    ctx.beginPath(); ctx.arc(xOff, -20 + yOff, size, 0, Math.PI*2); ctx.fill();
                }
            }
        }

        // 5. HoT
        if (agent.hotTimer > 0) {
            const icon = AssetManager.getStatusIcon('REGEN');
            ctx.drawImage(icon, 25, HEAD_Y, 24, 24);
            ctx.globalAlpha = 0.8;
            ctx.fillStyle = '#4ade80';
            ctx.font = 'bold 14px sans-serif';
            for(let i=0; i<3; i++) {
                const cycle = (t * 1.5 + i * 0.4) % 1;
                const yOff = -cycle * 40;
                const xOff = Math.cos(t * 3 + i) * 15;
                if (cycle < 1) ctx.fillText('+', xOff, -20 + yOff);
            }
        }

        ctx.restore();
    }

    // --- VFX METHODS ---

    private drawCastingVFX(ctx: CanvasRenderingContext2D, agent: Agent, t: number) {
        const skill = agent.skills[agent.castingSkillIdx];
        if (!skill) return;

        const progress = 1 - (agent.castTimer / skill.cast);
        const color = skill.color;

        ctx.save();
        if (agent.facing < 0) ctx.scale(-1, 1);

        // 1. Rising Energy Lines
        ctx.globalCompositeOperation = 'lighter';
        ctx.strokeStyle = color;
        ctx.lineWidth = 3; 
        const lineCount = 5 + Math.floor(progress * 8); 
        for(let i=0; i<lineCount; i++) {
            const h = (t * 150 + i * 40) % 90; 
            const alpha = 1 - (h / 90);
            const xOff = Math.sin(t * 15 + i) * 20 * (1-progress); 
            ctx.globalAlpha = alpha;
            ctx.beginPath(); ctx.moveTo(xOff, 15 - h); ctx.lineTo(xOff, 15 - h - 20); ctx.stroke();
        }

        // 2. Converging Rings
        if (progress > 0.2) {
            const ringScale = (1 - progress) * 2.5; 
            ctx.globalAlpha = progress;
            ctx.lineWidth = 2;
            ctx.beginPath(); ctx.ellipse(0, -20, 30 * ringScale, 10 * ringScale, 0, 0, Math.PI*2); ctx.stroke();

            ctx.save(); ctx.translate(0, -20); ctx.rotate(t * 10);
            ctx.beginPath(); ctx.ellipse(0, 0, 20 * ringScale, 5 * ringScale, 0, 0, Math.PI*2); ctx.stroke();
            ctx.restore();
        }

        // 3. Hand Glow
        ctx.globalAlpha = 0.4 + (Math.sin(t * 20) * 0.2) + (progress * 0.6);
        ctx.fillStyle = color;
        ctx.beginPath(); ctx.arc(0, -20, 10 + progress * 15, 0, Math.PI*2); ctx.fill();

        // 4. Final Flash
        if (progress > 0.9) {
            ctx.globalAlpha = (progress - 0.9) * 10;
            ctx.fillStyle = '#fff';
            ctx.beginPath(); ctx.arc(0, -20, 30, 0, Math.PI*2); ctx.fill();
        }

        ctx.restore();
    }

    private drawStatusIcons(ctx: CanvasRenderingContext2D, agent: Agent, t: number, drawX: number, drawY: number, scaleFactor: number) {
         if (agent.hp > 0 && agent.castingSkillIdx !== -1) {
            const skill = agent.skills[agent.castingSkillIdx];
            if (skill && skill.visual) {
                const icon = AssetManager.getSkillIcon(skill.visual, skill.color);
                ctx.save();
                // Move Higher relative to Body top (approx -120 local)
                ctx.translate(0, -110);
                const pulse = 1 + Math.sin(t * 10) * 0.1;
                ctx.scale(pulse, pulse);

                const glow = AssetManager.getGlowSprite(skill.color);
                ctx.globalCompositeOperation = 'lighter';
                ctx.globalAlpha = 0.6;
                ctx.drawImage(glow, -32, -32, 64, 64);
                ctx.globalCompositeOperation = 'source-over';
                ctx.globalAlpha = 1.0;

                ctx.drawImage(icon, -12, -12, 24, 24);

                // Cast Bar
                ctx.fillStyle = '#000';
                ctx.fillRect(-14, 20, 28, 5); 
                ctx.fillStyle = skill.color;
                const pct = Math.max(0, 1 - (agent.castTimer / skill.cast));
                ctx.fillRect(-14, 20, 28 * pct, 5);
                ctx.restore();
            }
        }
    }

    // =================================================================================
    // STYLE A: THE IMPERIAL LEGION
    // =================================================================================
    private drawImperialLegion(ctx: CanvasRenderingContext2D, agent: Agent, t: number, isSilhouette: boolean) {
        const silhouetteColor = '#3b82f6'; 
        let grad: any = silhouetteColor;
        let accent = silhouetteColor;

        if (!isSilhouette) {
            grad = ctx.createLinearGradient(-20, -40, 20, 40);
            grad.addColorStop(0, '#eff6ff'); 
            grad.addColorStop(0.5, '#93c5fd'); 
            grad.addColorStop(1, '#2563eb');   
            accent = '#3b82f6'; 
        }

        let breathe = (agent.hp > 0) ? Math.sin(t * 3) * 1 : 0;
        let thrustX = 0;
        let armRot = 0;

        if (agent.animState === AnimState.ATTACK && agent.hp > 0) {
            const progress = this.getCastProgress(agent);
            if (progress < 0.3) {
                thrustX = -5 * (progress / 0.3);
                armRot = -0.5 * (progress / 0.3);
            } else if (progress < 0.5) {
                thrustX = 15;
                armRot = 1.0;
            } else {
                thrustX = 15 * (1 - (progress - 0.5)/0.5);
                armRot = 1.0 * (1 - (progress - 0.5)/0.5);
            }
        }

        ctx.save();
        ctx.translate(thrustX, breathe);

        // 1. Back Arm
        ctx.save();
        ctx.translate(10, -10);
        ctx.rotate(armRot);
        this.drawImperialWeapon(ctx, agent.role, grad, accent, isSilhouette);
        ctx.restore();

        // 2. Body Shape
        if (isSilhouette) {
            ctx.strokeStyle = silhouetteColor;
            ctx.lineWidth = 2;
            ctx.fillStyle = 'transparent'; 
        } else {
            ctx.fillStyle = grad;
            ctx.strokeStyle = '#1e3a8a'; 
            ctx.lineWidth = 1.5;
        }

        ctx.beginPath();
        if (agent.role === Role.TANK) {
            ctx.moveTo(-18, -30); ctx.lineTo(18, -30);  
            ctx.lineTo(12, 15); ctx.lineTo(-12, 15);   
        } else if (agent.role === Role.MAGE || agent.role === Role.SUPPORT) {
            ctx.moveTo(-10, -25); ctx.lineTo(10, -25);  
            ctx.lineTo(16, 25); ctx.lineTo(-16, 25);
        } else if (agent.role === Role.RANGER) {
            ctx.moveTo(-8, -25); ctx.lineTo(8, -25);  
            ctx.lineTo(6, 15); ctx.lineTo(-6, 15);
        } else {
            ctx.moveTo(-12, -25); ctx.lineTo(12, -25);  
            ctx.lineTo(8, 15); ctx.lineTo(-8, 15);   
        }
        ctx.closePath();

        if (isSilhouette) {
            ctx.stroke();
        } else {
            ctx.fill();
            ctx.fillStyle = '#172554';
            ctx.stroke();
            // Rivets
            if (agent.role === Role.TANK) {
                [[-12,-25], [12,-25], [-8, 10], [8, 10]].forEach(([rx, ry]) => {
                    ctx.beginPath(); ctx.arc(rx, ry, 1, 0, Math.PI*2); ctx.fill();
                });
            }
        }

        // 3. Head
        ctx.save();
        ctx.translate(0, (agent.role === Role.TANK ? -35 : -32) + breathe * 0.5);
        if (isSilhouette) {
            ctx.fillStyle = 'transparent';
            ctx.strokeStyle = silhouetteColor;
        } else {
            ctx.fillStyle = grad;
        }

        ctx.beginPath();
        if (agent.role === Role.MAGE || agent.role === Role.SUPPORT) {
            ctx.moveTo(-10, 5); ctx.lineTo(-8, -15); ctx.lineTo(8, -15); ctx.lineTo(10, 5);
        } else if (agent.role === Role.TANK) {
            ctx.rect(-10, -14, 20, 16);
        } else {
            ctx.rect(-8, -12, 16, 14);
        }

        if (isSilhouette) ctx.stroke();
        else {
            ctx.fill(); ctx.stroke();
            ctx.fillStyle = '#fef08a'; ctx.fillRect(-6, -8, 12, 2);
        }
        ctx.restore();

        // 4. Front Arm / Shield
        ctx.save();
        ctx.translate(-12, -8);
        if (agent.role === Role.TANK) {
            ctx.rotate(armRot * 0.2);
            ctx.translate(-5, 5);

            if (isSilhouette) {
                ctx.fillStyle = 'transparent';
                ctx.strokeStyle = silhouetteColor;
            } else {
                ctx.fillStyle = '#2563eb'; ctx.strokeStyle = '#fcd34d'; 
            }
            ctx.lineWidth = 2;

            ctx.beginPath();
            ctx.moveTo(-10, -20); ctx.lineTo(10, -20);
            ctx.lineTo(10, 10); ctx.lineTo(0, 25); ctx.lineTo(-10, 10);
            ctx.closePath();

            if (isSilhouette) ctx.stroke();
            else { ctx.fill(); ctx.stroke(); }

        } else if (agent.role === Role.RANGER) {
            ctx.rotate(armRot);
            if (isSilhouette) {
                ctx.strokeStyle = silhouetteColor;
                ctx.strokeRect(-2, -2, 4, 15);
            } else {
                ctx.fillStyle = '#334155'; ctx.fillRect(-2, -2, 4, 15);
            }
        } else {
            ctx.beginPath(); ctx.arc(0, 0, 6, 0, Math.PI*2); 
            if (isSilhouette) {
                ctx.strokeStyle = silhouetteColor; ctx.stroke();
            } else {
                ctx.fillStyle = grad; ctx.fill();
            }
        }
        ctx.restore();

        ctx.restore(); 
    }

    private drawImperialWeapon(ctx: CanvasRenderingContext2D, role: Role, grad: any, accent: string, isSilhouette: boolean) {
        if (isSilhouette) {
            ctx.strokeStyle = '#3b82f6';
            ctx.lineWidth = 2;
        }

        if (role === Role.WARRIOR) {
            ctx.beginPath();
            ctx.moveTo(-2, 0); ctx.lineTo(2, 0);
            ctx.lineTo(2, -40); ctx.lineTo(0, -45); ctx.lineTo(-2, -40);
            if (isSilhouette) ctx.stroke();
            else {
                ctx.fillStyle = '#e2e8f0'; ctx.fill(); ctx.stroke();
                ctx.fillStyle = '#f59e0b'; ctx.fillRect(-6, 0, 12, 3);
            }
        } else if (role === Role.RANGER) {
            ctx.rotate(-Math.PI/2);
            if (isSilhouette) ctx.strokeRect(0, -3, 30, 4);
            else {
                ctx.fillStyle = '#475569'; ctx.fillRect(0, -3, 30, 4);
                ctx.fillStyle = '#78350f'; ctx.fillRect(-10, -2, 10, 6);
            }
        } else if (role === Role.MAGE || role === Role.SUPPORT) {
            if (isSilhouette) ctx.strokeRect(-2, -40, 4, 50);
            else {
                ctx.fillStyle = '#475569'; ctx.fillRect(-2, -40, 4, 50);
                const glow = AssetManager.getGlowSprite(accent);
                ctx.save(); ctx.globalCompositeOperation = 'lighter';
                ctx.drawImage(glow, -16, -55, 32, 32); ctx.restore();
                ctx.fillStyle = accent; ctx.fillRect(-6, -45, 12, 12);
            }
        }
    }

    // =================================================================================
    // STYLE B: THE ARCANE COVENANT
    // =================================================================================
    private drawArcaneCovenant(ctx: CanvasRenderingContext2D, agent: Agent, t: number, isSilhouette: boolean) {
        const silhouetteColor = '#ef4444'; 
        let bodyColor = isSilhouette ? 'transparent' : '#78350f'; 
        let glowColor = isSilhouette ? silhouetteColor : '#ef4444'; 
        let secondary = isSilhouette ? silhouetteColor : '#1c1917'; 

        const floatY = (agent.hp > 0) ? Math.sin(t * 2) * 3 : 0;
        let jitterX = 0; let jitterY = 0; let energyGather = 0;

        if (agent.animState === AnimState.ATTACK && agent.hp > 0) {
            const progress = this.getCastProgress(agent);
            if (progress < 0.6) {
                energyGather = progress;
                jitterX = (Math.random() - 0.5) * 3 * progress;
                jitterY = (Math.random() - 0.5) * 3 * progress;
            } else {
                const recoil = (progress - 0.6) / 0.4;
                jitterX = -5 * recoil; 
            }
        }

        ctx.save();
        ctx.translate(jitterX, floatY + jitterY);

        if (isSilhouette) {
            ctx.strokeStyle = silhouetteColor;
            ctx.lineWidth = 2;
            ctx.fillStyle = 'transparent';
        } else {
            ctx.fillStyle = bodyColor;
        }

        ctx.beginPath();
        if (agent.role === Role.TANK) {
             ctx.ellipse(0, -10, 18, 28, 0, 0, Math.PI*2);
        } else if (agent.role === Role.MAGE || agent.role === Role.SUPPORT) {
             ctx.moveTo(-10, -30); ctx.lineTo(10, -30);
             ctx.lineTo(14, 15); ctx.lineTo(0, 20); ctx.lineTo(-14, 15);
        } else {
             ctx.ellipse(0, -10, 12, 25, 0, 0, Math.PI*2);
        }

        if (isSilhouette) ctx.stroke();
        else ctx.fill();

        if ((agent.role === Role.MAGE || agent.role === Role.SUPPORT) && agent.hp > 0) {
            const orbGlow = AssetManager.getGlowSprite(glowColor);
            for(let i=0; i<3; i++) {
                const angle = t * 2 + (i * Math.PI * 2 / 3);
                const ox = Math.cos(angle) * (agent.role === Role.MAGE ? 20 : 15) * (1 - energyGather * 0.8);
                const oy = Math.sin(angle) * 5;
                ctx.save(); ctx.translate(ox, oy - 20);
                if(!isSilhouette) { 
                    ctx.globalCompositeOperation = 'lighter'; ctx.globalAlpha = 0.6;
                    ctx.drawImage(orbGlow, -10, -15, 20, 20);
                    ctx.globalCompositeOperation = 'source-over'; ctx.globalAlpha = 1.0;
                    ctx.fillStyle = glowColor;
                    ctx.beginPath(); ctx.moveTo(0, -5); ctx.lineTo(3, 0); ctx.lineTo(0, 5); ctx.lineTo(-3, 0); ctx.fill();
                } else {
                    ctx.strokeStyle = glowColor;
                    ctx.beginPath(); ctx.moveTo(0, -5); ctx.lineTo(3, 0); ctx.lineTo(0, 5); ctx.lineTo(-3, 0); ctx.stroke();
                }
                ctx.restore();
            }
        }

        if (!isSilhouette) {
            ctx.fillStyle = secondary;
            ctx.beginPath(); ctx.ellipse(0, -10, 6, 15, 0, 0, Math.PI*2); ctx.fill();
            const coreGlow = AssetManager.getGlowSprite(glowColor);
            ctx.save(); ctx.globalCompositeOperation = 'lighter';
            ctx.globalAlpha = 0.5 + Math.sin(t*10)*0.2 + energyGather * 0.5;
            ctx.drawImage(coreGlow, -10, -25, 20, 20); ctx.restore();
            ctx.fillStyle = glowColor;
            ctx.beginPath(); ctx.arc(0, -15, 4, 0, Math.PI*2); ctx.fill();
        }

        ctx.save();
        const headBob = (agent.hp > 0) ? Math.sin(t*3.5)*2 : 0;
        ctx.translate(0, (agent.role === Role.TANK ? -45 : -40) + headBob); 

        if (isSilhouette) {
            ctx.fillStyle = 'transparent'; ctx.strokeStyle = silhouetteColor;
        } else {
            ctx.fillStyle = '#f5f5f4';
        }

        ctx.beginPath();
        if (agent.role === Role.TANK) {
            ctx.moveTo(-12, -10); ctx.lineTo(12, -10); ctx.lineTo(0, 12);
        } else {
            ctx.moveTo(-6, -8); ctx.lineTo(6, -8); ctx.lineTo(0, 8);
        }

        if (isSilhouette) ctx.stroke();
        else {
            ctx.fill();
            ctx.fillStyle = glowColor;
            ctx.fillRect(-3, -4, 2, 2); ctx.fillRect(1, -4, 2, 2);
        }
        ctx.restore();

        ctx.save();
        ctx.translate(15, -15);
        if (agent.role === Role.WARRIOR || agent.role === Role.TANK) {
            const bladeAngle = (agent.hp > 0) ? Math.sin(t) * 0.2 + (agent.animState === AnimState.ATTACK ? -1 : 0) : 0;
            ctx.rotate(bladeAngle);
            if(!isSilhouette) {
                const wepGlow = AssetManager.getGlowSprite(glowColor);
                ctx.save(); ctx.globalCompositeOperation = 'lighter'; ctx.globalAlpha = 0.4;
                ctx.drawImage(wepGlow, -10, -20, 30, 30); ctx.restore();
            } else {
                ctx.strokeStyle = silhouetteColor;
            }

            if (agent.role === Role.TANK) {
                ctx.lineWidth = 3;
                if (!isSilhouette) ctx.strokeStyle = glowColor;
                ctx.beginPath(); ctx.arc(0, 0, 20, Math.PI/2, 3*Math.PI/2); ctx.stroke();
            } else {
                ctx.beginPath();
                ctx.moveTo(0, 10); ctx.lineTo(5, -30); ctx.lineTo(-2, -25);
                if (isSilhouette) ctx.stroke(); else { ctx.fillStyle = glowColor; ctx.fill(); }
            }
        } else if (agent.role === Role.RANGER) {
            ctx.translate(5, 0);
            ctx.rotate(agent.animState === AnimState.ATTACK ? -0.5 : 0);
            if (isSilhouette) {
                ctx.strokeStyle = silhouetteColor;
                ctx.beginPath(); ctx.moveTo(-5, -5); ctx.lineTo(15, 0); ctx.lineTo(-5, 5); ctx.stroke();
            } else {
                ctx.fillStyle = secondary;
                ctx.beginPath(); ctx.moveTo(-5, -5); ctx.lineTo(15, 0); ctx.lineTo(-5, 5); ctx.fill();
                const wepGlow = AssetManager.getGlowSprite(glowColor);
                ctx.save(); ctx.globalCompositeOperation = 'lighter'; ctx.globalAlpha = 0.4;
                ctx.drawImage(wepGlow, 0, -10, 20, 20); ctx.restore();
                ctx.fillStyle = glowColor; ctx.beginPath(); ctx.arc(10, 0, 3, 0, Math.PI*2); ctx.fill();
            }
        }
        ctx.restore();

        ctx.restore(); 
    }

    private getCastProgress(agent: Agent): number {
        if (agent.castingSkillIdx === -1) return 0;
        const skill = agent.skills[agent.castingSkillIdx];
        if (!skill) return 0;
        const raw = agent.castTimer / skill.cast;
        return Math.max(0, Math.min(1, 1 - raw)); 
    }
}

import { Agent } from "../game";
import { SpriteManager } from "../sprites";
import { AssetManager } from "../assets";
import { AnimState, Role, Team } from "../../types";
import { RenderableItem } from "./grid";
import { HEX_SIZE } from "../../constants";
import { HexUtils, MapConfig } from "../utils";

// Visual Constants
const MAX_UNIT_SIZE_RATIO = 0.85; 
const UNIT_REFERENCE_HEIGHT = 100; 

export class UnitRenderSystem {

    public collectRenderables(
        agents: Agent[], 
        getTerrainHeight: (q: number, r: number) => number, 
        globalTime: number, 
        highlightAgent: Agent | null,
        mapConfig: MapConfig
    ): RenderableItem[] {
        const list: RenderableItem[] = [];

        agents.forEach(agent => {
            if (agent.hp <= 0 && agent.fullyDead) return;

            // --- HEIGHT CORRECTION ---
            // Fix: Calculate height based on where the unit IS (px, py), not where it's GOING (q, r).
            // This prevents units from sinking/floating when knocked back between height tiers.
            const visualHex = HexUtils.fromPx(agent.px, agent.py, mapConfig);
            const currentHeight = getTerrainHeight(visualHex.q, visualHex.r);

            const visualY = agent.py - currentHeight;

            list.push({
                y: agent.py + 1, 
                z: 10,
                draw: (ctx) => this.drawAssembly(
                    ctx, 
                    agent, 
                    agent.px, 
                    visualY, 
                    globalTime, 
                    highlightAgent === agent,
                    false // Normal Mode
                )
            });
        });

        return list;
    }

    // Called by Renderer for Occlusion Pass
    public drawSilhouette(
        ctx: CanvasRenderingContext2D, 
        agent: Agent, 
        getTerrainHeight: (q: number, r: number) => number,
        globalTime: number,
        mapConfig: MapConfig
    ) {
        // Same height logic as collectRenderables
        const visualHex = HexUtils.fromPx(agent.px, agent.py, mapConfig);
        const currentHeight = getTerrainHeight(visualHex.q, visualHex.r);
        const visualY = agent.py - currentHeight;

        this.drawAssembly(ctx, agent, agent.px, visualY, globalTime, false, true);
    }

    // =================================================================================
    // 🎨 HIERARCHICAL VECTOR ASSEMBLY RENDERER
    // =================================================================================

    private drawAssembly(
        ctx: CanvasRenderingContext2D, 
        agent: Agent, 
        drawX: number, 
        drawY: number, 
        globalTime: number, 
        isSelected: boolean,
        isSilhouette: boolean
    ) {
        // 1. Setup Constraint Space
        const maxDimension = HEX_SIZE * 2 * MAX_UNIT_SIZE_RATIO;

        // Distinct Scale Factors for Roles
        let roleScaleMod = 1.0;
        switch(agent.role) {
            case Role.TANK: roleScaleMod = 1.25; break; // Bulky
            case Role.WARRIOR: roleScaleMod = 1.1; break; // Standard strong
            case Role.RANGER: roleScaleMod = 0.9; break; // Agile/Slim
            case Role.MAGE: roleScaleMod = 0.9; break; // Small/Floating
            case Role.SUPPORT: roleScaleMod = 0.95; break;
        }

        const scaleFactor = (maxDimension / UNIT_REFERENCE_HEIGHT) * roleScaleMod;

        ctx.save();
        ctx.translate(drawX, drawY);
        ctx.scale(scaleFactor, scaleFactor);

        // 3. Apply Physics (Z-Jump / Blast)
        // We apply Physics Z translation to the whole container (Base + Body)
        const physX = agent.physics.x / scaleFactor;
        const physY = agent.physics.y / scaleFactor;
        const physZ = agent.physics.z / scaleFactor; 

        ctx.translate(physX, physY - physZ); 
        ctx.rotate(agent.physics.angle); // Apply Ragdoll Rotation

        // --- DRAW BASE (Ground Level) ---
        // The base should strictly align with the grid face (0,0 local)
        if (!isSilhouette && agent.hp > 0 && agent.visualStatus !== 'POLYMORPH') {
            const assets = SpriteManager.getUnitImages(agent.role, agent.team);
            ctx.save();
            // Center of base sprite ellipse is at (64, 79). 
            // We draw at (-64, -79) to align it with (0,0).
            ctx.drawImage(assets.base, -64, -79); 

            // Casting Floor Rune (Ground level)
            if (agent.castingSkillIdx !== -1) {
                const skill = agent.skills[agent.castingSkillIdx];
                if (skill) {
                    const circle = AssetManager.getMagicCircle(skill.color, skill.tag === 'ULT');
                    ctx.save(); 
                    ctx.scale(1, 0.5); 
                    ctx.rotate(globalTime * 2);
                    ctx.globalAlpha = 0.6;
                    ctx.drawImage(circle, -64, -64, 128, 128); 
                    ctx.restore();
                }
            }
            ctx.restore();
        }

        // --- PREPARE BODY TRANSFORM ---
        // Shift up to align body feet with ground (y=0)
        // Standard body drawing has feet around y=15. So we shift up by -15.
        const BODY_GROUNDING_OFFSET = -15; 

        let bodyFloat = BODY_GROUNDING_OFFSET; 

        // Add Breathing / Hovering
        if (agent.hp > 0) {
             if ((agent.role === Role.MAGE || agent.role === Role.SUPPORT) && !agent.isMoving && agent.visualStatus === 'NONE') {
                bodyFloat -= 5 + Math.sin(globalTime * 2) * 3; // Mages float higher
            }
        } else {
            bodyFloat = -5; // Dead units sink slightly into ground
        }

        ctx.translate(0, bodyFloat);

        // --- 2. Spawn Animation (Materialize) ---
        // Applies scale stretch and alpha fade if spawning
        let spawnAlpha = 1.0;
        let whiteOverlay = 0;

        if (agent.spawnTimer > 0) {
            const SPAWN_DURATION = 0.5; // From game.ts init
            const progress = 1 - (agent.spawnTimer / SPAWN_DURATION); // 0 -> 1
            const eased = 1 - Math.pow(1 - progress, 3); // Cubic Out

            spawnAlpha = eased;
            const spawnStretch = 2.0 - eased; // 2.0 -> 1.0
            whiteOverlay = 1 - eased; // 1 -> 0

            // Scale body vertically around its feet (now at 0,0 due to translate)
            ctx.scale(1, spawnStretch);
            ctx.globalAlpha *= spawnAlpha;
        }

        // Hit Flash / Death Filter
        if (agent.hp <= 0 && !isSilhouette) {
            ctx.filter = 'grayscale(100%) opacity(80%)'; 
        } else if (!isSilhouette && agent.hitFlashTimer > 0) {
            ctx.filter = 'brightness(200%)'; 
        } else if (whiteOverlay > 0) {
            ctx.filter = `brightness(${100 + whiteOverlay * 200}%)`;
        }

        ctx.scale(agent.facing > 0 ? 1 : -1, 1);

        // SILHOUETTE MODE SETUP
        if (isSilhouette) {
            ctx.globalCompositeOperation = 'source-over'; 
            ctx.globalAlpha = 0.8; 
        }

        // 4. Render Body (or Special Form)
        if (agent.visualStatus === 'POLYMORPH') {
            // Draw Sheep
            const sheep = SpriteManager.getSpecialModel('SHEEP');
            const bounce = Math.abs(Math.sin(globalTime * 5) * 5);
            ctx.drawImage(sheep, -32, -32 - bounce, 64, 64);
        } else {
            // Standard Unit Render
            if (agent.team === Team.BLUE) {
                this.drawImperialLegion(ctx, agent, globalTime, isSilhouette);
            } else {
                this.drawArcaneCovenant(ctx, agent, globalTime, isSilhouette);
            }

            // Casting VFX (Only if alive)
            if (!isSilhouette && agent.hp > 0 && agent.castingSkillIdx !== -1) {
                this.drawCastingVFX(ctx, agent, globalTime);
            }

            // Frozen Overlay
            if (agent.visualStatus === 'FROZEN') {
                const ice = SpriteManager.getSpecialModel('ICE');
                ctx.save();
                ctx.globalCompositeOperation = 'hard-light';
                // Ice block needs to cover body, roughly centered
                ctx.drawImage(ice, -48, -75, 96, 128);
                ctx.restore();
            }

            // Stasis Overlay
            if (agent.visualStatus === 'STASIS') {
                ctx.save();
                ctx.fillStyle = '#facc15';
                ctx.globalAlpha = 0.4;
                ctx.globalCompositeOperation = 'lighter';
                ctx.beginPath();
                ctx.ellipse(0, -15, 25, 50, 0, 0, Math.PI*2);
                ctx.fill();
                ctx.strokeStyle = '#fff';
                ctx.lineWidth = 2;
                ctx.stroke();
                ctx.restore();
            }
        }

        // 6. Selection Ring & Status (Only Normal Mode & Alive)
        if (!isSilhouette) {
            this.drawStatusIcons(ctx, agent, globalTime, drawX, drawY, scaleFactor);
            this.drawStatusEffects(ctx, agent, globalTime);

            if (isSelected && agent.hp > 0) {
                // Draw Selection Ring around Body center (approx -20)
                ctx.strokeStyle = '#fff';
                ctx.lineWidth = 2 / scaleFactor; 
                ctx.beginPath();
                ctx.ellipse(0, -20, 30, 15, 0, 0, Math.PI * 2);
                ctx.stroke();
            }
        }

        ctx.restore(); // End Assembly

        // 7. NEW: Spawn Role Indicator
        // Drawn AFTER restore so it is not affected by body stretch/fade/rotation
        if (agent.spawnTimer > 0 && !isSilhouette) {
            this.drawSpawnIndicator(ctx, agent, drawX, drawY, scaleFactor);
        }
    }

    private drawSpawnIndicator(ctx: CanvasRenderingContext2D, agent: Agent, x: number, y: number, scale: number) {
        const assets = SpriteManager.getUnitImages(agent.role, agent.team);
        const totalDuration = 0.5;
        const alpha = Math.max(0, agent.spawnTimer / totalDuration);
        const yOffset = -40 * scale; 

        ctx.save();
        ctx.translate(x, y + yOffset);
        const popScale = 1.0 + alpha * 0.2;
        ctx.scale(popScale, popScale);
        ctx.globalAlpha = alpha;

        ctx.fillStyle = 'rgba(15, 23, 42, 0.4)'; 
        ctx.strokeStyle = agent.team === Team.BLUE ? 'rgba(59, 130, 246, 0.8)' : 'rgba(239, 68, 68, 0.8)';
        ctx.lineWidth = 2;
        ctx.beginPath(); ctx.arc(0, 0, 18, 0, Math.PI*2); ctx.fill(); ctx.stroke();

        ctx.drawImage(assets.icon, -12, -12, 24, 24);

        ctx.font = 'bold 10px sans-serif';
        ctx.textAlign = 'center';
        ctx.fillStyle = '#fff';
        ctx.strokeStyle = 'rgba(0,0,0,0.8)';
        ctx.lineWidth = 2;
        ctx.strokeText(agent.role, 0, 28);
        ctx.fillText(agent.role, 0, 28);

        ctx.restore();
    }

    private drawStatusEffects(ctx: CanvasRenderingContext2D, agent: Agent, t: number) {
        if (agent.hp <= 0) return;

        ctx.save();
        // Undo facing flip so icons don't flip
        if (agent.facing < 0) ctx.scale(-1, 1);

        const HEAD_Y = -75; // Adjusted head position for icons

        // 1. STUN
        if (agent.stunTimer > 0 && !agent.banished && agent.visualStatus !== 'FROZEN') {
            const icon = AssetManager.getStatusIcon('STUN');
            const angle = t * 5;
            ctx.drawImage(icon, -20 + Math.cos(angle)*10, HEAD_Y + Math.sin(angle)*5, 24, 24);
            ctx.drawImage(icon, -10 + Math.cos(angle + 2)*10, HEAD_Y - 10 + Math.sin(angle + 2)*5, 16, 16);
        }

        // 2. SILENCE
        if (agent.silenceTimer > 0) {
            const icon = AssetManager.getStatusIcon('SILENCE');
            ctx.drawImage(icon, 15, HEAD_Y - 5 + Math.sin(t * 3) * 3, 24, 24);
        }

        // 3. BANISH
        if (agent.banished && agent.visualStatus === 'NONE') {
            const icon = AssetManager.getStatusIcon('BANISH');
            ctx.globalAlpha = 0.7;
            ctx.drawImage(icon, -12, HEAD_Y - 20 + Math.sin(t * 2) * 5, 24, 24);
        }

        // 4. DoT
        if (agent.dotTimer > 0) {
            const pulse = 1 + Math.sin(t * 10) * 0.2;
            const iconSize = 28 * pulse; 
            const icon = AssetManager.getStatusIcon('POISON'); 
            const glow = AssetManager.getGlowSprite('#ef4444');
            ctx.globalCompositeOperation = 'lighter';
            ctx.drawImage(glow, -35 - iconSize/2, HEAD_Y - iconSize/2, iconSize*2, iconSize*2);
            ctx.globalCompositeOperation = 'source-over';
            ctx.drawImage(icon, -35, HEAD_Y, iconSize, iconSize);

            ctx.globalAlpha = 0.8;
            for(let i=0; i<5; i++) {
                const cycle = (t * 2 + i * 0.7) % 1;
                const yOff = -cycle * 60; 
                const xOff = Math.sin(t * 5 + i) * 15;
                const size = (1 - cycle) * 7;
                ctx.fillStyle = i % 2 === 0 ? '#10b981' : '#a855f7';
                if (cycle < 1) {
                    ctx.beginPath(); ctx.arc(xOff, -20 + yOff, size, 0, Math.PI*2); ctx.fill();
                }
            }
        }

        // 5. HoT
        if (agent.hotTimer > 0) {
            const icon = AssetManager.getStatusIcon('REGEN');
            ctx.drawImage(icon, 25, HEAD_Y, 24, 24);
            ctx.globalAlpha = 0.8;
            ctx.fillStyle = '#4ade80';
            ctx.font = 'bold 14px sans-serif';
            for(let i=0; i<3; i++) {
                const cycle = (t * 1.5 + i * 0.4) % 1;
                const yOff = -cycle * 40;
                const xOff = Math.cos(t * 3 + i) * 15;
                if (cycle < 1) ctx.fillText('+', xOff, -20 + yOff);
            }
        }

        ctx.restore();
    }

    // --- VFX METHODS ---

    private drawCastingVFX(ctx: CanvasRenderingContext2D, agent: Agent, t: number) {
        const skill = agent.skills[agent.castingSkillIdx];
        if (!skill) return;

        const progress = 1 - (agent.castTimer / skill.cast);
        const color = skill.color;

        ctx.save();
        if (agent.facing < 0) ctx.scale(-1, 1);

        // 1. Rising Energy Lines
        ctx.globalCompositeOperation = 'lighter';
        ctx.strokeStyle = color;
        ctx.lineWidth = 3; 
        const lineCount = 5 + Math.floor(progress * 8); 
        for(let i=0; i<lineCount; i++) {
            const h = (t * 150 + i * 40) % 90; 
            const alpha = 1 - (h / 90);
            const xOff = Math.sin(t * 15 + i) * 20 * (1-progress); 
            ctx.globalAlpha = alpha;
            ctx.beginPath(); ctx.moveTo(xOff, 15 - h); ctx.lineTo(xOff, 15 - h - 20); ctx.stroke();
        }

        // 2. Converging Rings
        if (progress > 0.2) {
            const ringScale = (1 - progress) * 2.5; 
            ctx.globalAlpha = progress;
            ctx.lineWidth = 2;
            ctx.beginPath(); ctx.ellipse(0, -20, 30 * ringScale, 10 * ringScale, 0, 0, Math.PI*2); ctx.stroke();

            ctx.save(); ctx.translate(0, -20); ctx.rotate(t * 10);
            ctx.beginPath(); ctx.ellipse(0, 0, 20 * ringScale, 5 * ringScale, 0, 0, Math.PI*2); ctx.stroke();
            ctx.restore();
        }

        // 3. Hand Glow
        ctx.globalAlpha = 0.4 + (Math.sin(t * 20) * 0.2) + (progress * 0.6);
        ctx.fillStyle = color;
        ctx.beginPath(); ctx.arc(0, -20, 10 + progress * 15, 0, Math.PI*2); ctx.fill();

        // 4. Final Flash
        if (progress > 0.9) {
            ctx.globalAlpha = (progress - 0.9) * 10;
            ctx.fillStyle = '#fff';
            ctx.beginPath(); ctx.arc(0, -20, 30, 0, Math.PI*2); ctx.fill();
        }

        ctx.restore();
    }

    private drawStatusIcons(ctx: CanvasRenderingContext2D, agent: Agent, t: number, drawX: number, drawY: number, scaleFactor: number) {
         if (agent.hp > 0 && agent.castingSkillIdx !== -1) {
            const skill = agent.skills[agent.castingSkillIdx];
            if (skill && skill.visual) {
                const icon = AssetManager.getSkillIcon(skill.visual, skill.color);
                ctx.save();
                // Move Higher relative to Body top (approx -120 local)
                ctx.translate(0, -110);
                const pulse = 1 + Math.sin(t * 10) * 0.1;
                ctx.scale(pulse, pulse);

                const glow = AssetManager.getGlowSprite(skill.color);
                ctx.globalCompositeOperation = 'lighter';
                ctx.globalAlpha = 0.6;
                ctx.drawImage(glow, -32, -32, 64, 64);
                ctx.globalCompositeOperation = 'source-over';
                ctx.globalAlpha = 1.0;

                ctx.drawImage(icon, -12, -12, 24, 24);

                // Cast Bar
                ctx.fillStyle = '#000';
                ctx.fillRect(-14, 20, 28, 5); 
                ctx.fillStyle = skill.color;
                const pct = Math.max(0, 1 - (agent.castTimer / skill.cast));
                ctx.fillRect(-14, 20, 28 * pct, 5);
                ctx.restore();
            }
        }
    }

    // =================================================================================
    // STYLE A: THE IMPERIAL LEGION
    // =================================================================================
    private drawImperialLegion(ctx: CanvasRenderingContext2D, agent: Agent, t: number, isSilhouette: boolean) {
        const silhouetteColor = '#3b82f6'; 
        let grad: any = silhouetteColor;
        let accent = silhouetteColor;

        if (!isSilhouette) {
            grad = ctx.createLinearGradient(-20, -40, 20, 40);
            grad.addColorStop(0, '#eff6ff'); 
            grad.addColorStop(0.5, '#93c5fd'); 
            grad.addColorStop(1, '#2563eb');   
            accent = '#3b82f6'; 
        }

        let breathe = (agent.hp > 0) ? Math.sin(t * 3) * 1 : 0;
        let thrustX = 0;
        let armRot = 0;

        if (agent.animState === AnimState.ATTACK && agent.hp > 0) {
            const progress = this.getCastProgress(agent);
            if (progress < 0.3) {
                thrustX = -5 * (progress / 0.3);
                armRot = -0.5 * (progress / 0.3);
            } else if (progress < 0.5) {
                thrustX = 15;
                armRot = 1.0;
            } else {
                thrustX = 15 * (1 - (progress - 0.5)/0.5);
                armRot = 1.0 * (1 - (progress - 0.5)/0.5);
            }
        }

        ctx.save();
        ctx.translate(thrustX, breathe);

        // 1. Back Arm
        ctx.save();
        ctx.translate(10, -10);
        ctx.rotate(armRot);
        this.drawImperialWeapon(ctx, agent.role, grad, accent, isSilhouette);
        ctx.restore();

        // 2. Body Shape
        if (isSilhouette) {
            ctx.strokeStyle = silhouetteColor;
            ctx.lineWidth = 2;
            ctx.fillStyle = 'transparent'; 
        } else {
            ctx.fillStyle = grad;
            ctx.strokeStyle = '#1e3a8a'; 
            ctx.lineWidth = 1.5;
        }

        ctx.beginPath();
        if (agent.role === Role.TANK) {
            ctx.moveTo(-18, -30); ctx.lineTo(18, -30);  
            ctx.lineTo(12, 15); ctx.lineTo(-12, 15);   
        } else if (agent.role === Role.MAGE || agent.role === Role.SUPPORT) {
            ctx.moveTo(-10, -25); ctx.lineTo(10, -25);  
            ctx.lineTo(16, 25); ctx.lineTo(-16, 25);
        } else if (agent.role === Role.RANGER) {
            ctx.moveTo(-8, -25); ctx.lineTo(8, -25);  
            ctx.lineTo(6, 15); ctx.lineTo(-6, 15);
        } else {
            ctx.moveTo(-12, -25); ctx.lineTo(12, -25);  
            ctx.lineTo(8, 15); ctx.lineTo(-8, 15);   
        }
        ctx.closePath();

        if (isSilhouette) {
            ctx.stroke();
        } else {
            ctx.fill();
            ctx.fillStyle = '#172554';
            ctx.stroke();
            // Rivets
            if (agent.role === Role.TANK) {
                [[-12,-25], [12,-25], [-8, 10], [8, 10]].forEach(([rx, ry]) => {
                    ctx.beginPath(); ctx.arc(rx, ry, 1, 0, Math.PI*2); ctx.fill();
                });
            }
        }

        // 3. Head
        ctx.save();
        ctx.translate(0, (agent.role === Role.TANK ? -35 : -32) + breathe * 0.5);
        if (isSilhouette) {
            ctx.fillStyle = 'transparent';
            ctx.strokeStyle = silhouetteColor;
        } else {
            ctx.fillStyle = grad;
        }

        ctx.beginPath();
        if (agent.role === Role.MAGE || agent.role === Role.SUPPORT) {
            ctx.moveTo(-10, 5); ctx.lineTo(-8, -15); ctx.lineTo(8, -15); ctx.lineTo(10, 5);
        } else if (agent.role === Role.TANK) {
            ctx.rect(-10, -14, 20, 16);
        } else {
            ctx.rect(-8, -12, 16, 14);
        }

        if (isSilhouette) ctx.stroke();
        else {
            ctx.fill(); ctx.stroke();
            ctx.fillStyle = '#fef08a'; ctx.fillRect(-6, -8, 12, 2);
        }
        ctx.restore();

        // 4. Front Arm / Shield
        ctx.save();
        ctx.translate(-12, -8);
        if (agent.role === Role.TANK) {
            ctx.rotate(armRot * 0.2);
            ctx.translate(-5, 5);

            if (isSilhouette) {
                ctx.fillStyle = 'transparent';
                ctx.strokeStyle = silhouetteColor;
            } else {
                ctx.fillStyle = '#2563eb'; ctx.strokeStyle = '#fcd34d'; 
            }
            ctx.lineWidth = 2;

            ctx.beginPath();
            ctx.moveTo(-10, -20); ctx.lineTo(10, -20);
            ctx.lineTo(10, 10); ctx.lineTo(0, 25); ctx.lineTo(-10, 10);
            ctx.closePath();

            if (isSilhouette) ctx.stroke();
            else { ctx.fill(); ctx.stroke(); }

        } else if (agent.role === Role.RANGER) {
            ctx.rotate(armRot);
            if (isSilhouette) {
                ctx.strokeStyle = silhouetteColor;
                ctx.strokeRect(-2, -2, 4, 15);
            } else {
                ctx.fillStyle = '#334155'; ctx.fillRect(-2, -2, 4, 15);
            }
        } else {
            ctx.beginPath(); ctx.arc(0, 0, 6, 0, Math.PI*2); 
            if (isSilhouette) {
                ctx.strokeStyle = silhouetteColor; ctx.stroke();
            } else {
                ctx.fillStyle = grad; ctx.fill();
            }
        }
        ctx.restore();

        ctx.restore(); 
    }

    private drawImperialWeapon(ctx: CanvasRenderingContext2D, role: Role, grad: any, accent: string, isSilhouette: boolean) {
        if (isSilhouette) {
            ctx.strokeStyle = '#3b82f6';
            ctx.lineWidth = 2;
        }

        if (role === Role.WARRIOR) {
            ctx.beginPath();
            ctx.moveTo(-2, 0); ctx.lineTo(2, 0);
            ctx.lineTo(2, -40); ctx.lineTo(0, -45); ctx.lineTo(-2, -40);
            if (isSilhouette) ctx.stroke();
            else {
                ctx.fillStyle = '#e2e8f0'; ctx.fill(); ctx.stroke();
                ctx.fillStyle = '#f59e0b'; ctx.fillRect(-6, 0, 12, 3);
            }
        } else if (role === Role.RANGER) {
            ctx.rotate(-Math.PI/2);
            if (isSilhouette) ctx.strokeRect(0, -3, 30, 4);
            else {
                ctx.fillStyle = '#475569'; ctx.fillRect(0, -3, 30, 4);
                ctx.fillStyle = '#78350f'; ctx.fillRect(-10, -2, 10, 6);
            }
        } else if (role === Role.MAGE || role === Role.SUPPORT) {
            if (isSilhouette) ctx.strokeRect(-2, -40, 4, 50);
            else {
                ctx.fillStyle = '#475569'; ctx.fillRect(-2, -40, 4, 50);
                const glow = AssetManager.getGlowSprite(accent);
                ctx.save(); ctx.globalCompositeOperation = 'lighter';
                ctx.drawImage(glow, -16, -55, 32, 32); ctx.restore();
                ctx.fillStyle = accent; ctx.fillRect(-6, -45, 12, 12);
            }
        }
    }

    // =================================================================================
    // STYLE B: THE ARCANE COVENANT
    // =================================================================================
    private drawArcaneCovenant(ctx: CanvasRenderingContext2D, agent: Agent, t: number, isSilhouette: boolean) {
        const silhouetteColor = '#ef4444'; 
        let bodyColor = isSilhouette ? 'transparent' : '#78350f'; 
        let glowColor = isSilhouette ? silhouetteColor : '#ef4444'; 
        let secondary = isSilhouette ? silhouetteColor : '#1c1917'; 

        const floatY = (agent.hp > 0) ? Math.sin(t * 2) * 3 : 0;
        let jitterX = 0; let jitterY = 0; let energyGather = 0;

        if (agent.animState === AnimState.ATTACK && agent.hp > 0) {
            const progress = this.getCastProgress(agent);
            if (progress < 0.6) {
                energyGather = progress;
                jitterX = (Math.random() - 0.5) * 3 * progress;
                jitterY = (Math.random() - 0.5) * 3 * progress;
            } else {
                const recoil = (progress - 0.6) / 0.4;
                jitterX = -5 * recoil; 
            }
        }

        ctx.save();
        ctx.translate(jitterX, floatY + jitterY);

        if (isSilhouette) {
            ctx.strokeStyle = silhouetteColor;
            ctx.lineWidth = 2;
            ctx.fillStyle = 'transparent';
        } else {
            ctx.fillStyle = bodyColor;
        }

        ctx.beginPath();
        if (agent.role === Role.TANK) {
             ctx.ellipse(0, -10, 18, 28, 0, 0, Math.PI*2);
        } else if (agent.role === Role.MAGE || agent.role === Role.SUPPORT) {
             ctx.moveTo(-10, -30); ctx.lineTo(10, -30);
             ctx.lineTo(14, 15); ctx.lineTo(0, 20); ctx.lineTo(-14, 15);
        } else {
             ctx.ellipse(0, -10, 12, 25, 0, 0, Math.PI*2);
        }

        if (isSilhouette) ctx.stroke();
        else ctx.fill();

        if ((agent.role === Role.MAGE || agent.role === Role.SUPPORT) && agent.hp > 0) {
            const orbGlow = AssetManager.getGlowSprite(glowColor);
            for(let i=0; i<3; i++) {
                const angle = t * 2 + (i * Math.PI * 2 / 3);
                const ox = Math.cos(angle) * (agent.role === Role.MAGE ? 20 : 15) * (1 - energyGather * 0.8);
                const oy = Math.sin(angle) * 5;
                ctx.save(); ctx.translate(ox, oy - 20);
                if(!isSilhouette) { 
                    ctx.globalCompositeOperation = 'lighter'; ctx.globalAlpha = 0.6;
                    ctx.drawImage(orbGlow, -10, -15, 20, 20);
                    ctx.globalCompositeOperation = 'source-over'; ctx.globalAlpha = 1.0;
                    ctx.fillStyle = glowColor;
                    ctx.beginPath(); ctx.moveTo(0, -5); ctx.lineTo(3, 0); ctx.lineTo(0, 5); ctx.lineTo(-3, 0); ctx.fill();
                } else {
                    ctx.strokeStyle = glowColor;
                    ctx.beginPath(); ctx.moveTo(0, -5); ctx.lineTo(3, 0); ctx.lineTo(0, 5); ctx.lineTo(-3, 0); ctx.stroke();
                }
                ctx.restore();
            }
        }

        if (!isSilhouette) {
            ctx.fillStyle = secondary;
            ctx.beginPath(); ctx.ellipse(0, -10, 6, 15, 0, 0, Math.PI*2); ctx.fill();
            const coreGlow = AssetManager.getGlowSprite(glowColor);
            ctx.save(); ctx.globalCompositeOperation = 'lighter';
            ctx.globalAlpha = 0.5 + Math.sin(t*10)*0.2 + energyGather * 0.5;
            ctx.drawImage(coreGlow, -10, -25, 20, 20); ctx.restore();
            ctx.fillStyle = glowColor;
            ctx.beginPath(); ctx.arc(0, -15, 4, 0, Math.PI*2); ctx.fill();
        }

        ctx.save();
        const headBob = (agent.hp > 0) ? Math.sin(t*3.5)*2 : 0;
        ctx.translate(0, (agent.role === Role.TANK ? -45 : -40) + headBob); 

        if (isSilhouette) {
            ctx.fillStyle = 'transparent'; ctx.strokeStyle = silhouetteColor;
        } else {
            ctx.fillStyle = '#f5f5f4';
        }

        ctx.beginPath();
        if (agent.role === Role.TANK) {
            ctx.moveTo(-12, -10); ctx.lineTo(12, -10); ctx.lineTo(0, 12);
        } else {
            ctx.moveTo(-6, -8); ctx.lineTo(6, -8); ctx.lineTo(0, 8);
        }

        if (isSilhouette) ctx.stroke();
        else {
            ctx.fill();
            ctx.fillStyle = glowColor;
            ctx.fillRect(-3, -4, 2, 2); ctx.fillRect(1, -4, 2, 2);
        }
        ctx.restore();

        ctx.save();
        ctx.translate(15, -15);
        if (agent.role === Role.WARRIOR || agent.role === Role.TANK) {
            const bladeAngle = (agent.hp > 0) ? Math.sin(t) * 0.2 + (agent.animState === AnimState.ATTACK ? -1 : 0) : 0;
            ctx.rotate(bladeAngle);
            if(!isSilhouette) {
                const wepGlow = AssetManager.getGlowSprite(glowColor);
                ctx.save(); ctx.globalCompositeOperation = 'lighter'; ctx.globalAlpha = 0.4;
                ctx.drawImage(wepGlow, -10, -20, 30, 30); ctx.restore();
            } else {
                ctx.strokeStyle = silhouetteColor;
            }

            if (agent.role === Role.TANK) {
                ctx.lineWidth = 3;
                if (!isSilhouette) ctx.strokeStyle = glowColor;
                ctx.beginPath(); ctx.arc(0, 0, 20, Math.PI/2, 3*Math.PI/2); ctx.stroke();
            } else {
                ctx.beginPath();
                ctx.moveTo(0, 10); ctx.lineTo(5, -30); ctx.lineTo(-2, -25);
                if (isSilhouette) ctx.stroke(); else { ctx.fillStyle = glowColor; ctx.fill(); }
            }
        } else if (agent.role === Role.RANGER) {
            ctx.translate(5, 0);
            ctx.rotate(agent.animState === AnimState.ATTACK ? -0.5 : 0);
            if (isSilhouette) {
                ctx.strokeStyle = silhouetteColor;
                ctx.beginPath(); ctx.moveTo(-5, -5); ctx.lineTo(15, 0); ctx.lineTo(-5, 5); ctx.stroke();
            } else {
                ctx.fillStyle = secondary;
                ctx.beginPath(); ctx.moveTo(-5, -5); ctx.lineTo(15, 0); ctx.lineTo(-5, 5); ctx.fill();
                const wepGlow = AssetManager.getGlowSprite(glowColor);
                ctx.save(); ctx.globalCompositeOperation = 'lighter'; ctx.globalAlpha = 0.4;
                ctx.drawImage(wepGlow, 0, -10, 20, 20); ctx.restore();
                ctx.fillStyle = glowColor; ctx.beginPath(); ctx.arc(10, 0, 3, 0, Math.PI*2); ctx.fill();
            }
        }
        ctx.restore();

        ctx.restore(); 
    }

    private getCastProgress(agent: Agent): number {
        if (agent.castingSkillIdx === -1) return 0;
        const skill = agent.skills[agent.castingSkillIdx];
        if (!skill) return 0;
        const raw = agent.castTimer / skill.cast;
        return Math.max(0, Math.min(1, 1 - raw)); 
    }
}

import { Agent, GameEngine } from "./game";
import { HexUtils } from "./utils";
import { SpriteManager } from "./sprites";
import { AssetManager } from "./assets";
import { Hex, GameEvent, Skill, SceneTheme, Team } from "../types";
import { HEX_SIZE } from "../constants";

// Sub-systems
import { GridSystem, RenderableItem } from "./systems/grid";
import { VFXSystem } from "./systems/vfx";
import { UnitRenderSystem } from "./systems/unit";
import { HUDSystem } from "./systems/hud";

// Constants
const HUD_TEXT_OFFSET = 40; 
const OBSTACLE_Z_INDEX = 10;
const OBSTACLE_OFFSET_Y = 86; 

export interface Camera {
    x: number;
    y: number;
    zoom: number;
}

export class GameRenderer {
    public globalTime: number = 0;

    // Sub-systems
    public grid: GridSystem;
    public vfx: VFXSystem;
    public unit: UnitRenderSystem;
    public hud: HUDSystem;

    // Camera Shake Effects
    private shakeTimer = 0; 
    private shakeIntensity = 0;

    // Transition State
    private transitionT: number = 0;
    private transitionPhase: 'IN' | 'OUT' | 'IDLE' = 'IDLE';

    // Hologram Glitch State
    private holoGlitchTimer = 0;
    private lastDirectorTarget = "";

    constructor() {
        this.grid = new GridSystem();
        this.vfx = new VFXSystem();
        this.unit = new UnitRenderSystem();
        this.hud = new HUDSystem();
    }

    public setTransition(t: number, phase: 'IN' | 'OUT' | 'IDLE') {
        this.transitionT = t;
        this.transitionPhase = phase;
    }

    // --- Core Accessors ---

    public getTerrainHeight(q: number, r: number): number {
        return this.grid.getTerrainHeight(q, r);
    }

    public getHexAtScreenPoint(mouseX: number, mouseY: number, camera: Camera, engine: GameEngine): Hex | null {
        return this.grid.getHexAtScreenPoint(mouseX, mouseY, camera, engine);
    }

    // --- Update Loop ---

    public update(dt: number, engine: GameEngine): void {
        this.globalTime += dt;
        if (this.shakeTimer > 0) {
            this.shakeTimer -= dt;
        }

        // Hologram Glitch Logic
        if (engine.directorTargetId !== this.lastDirectorTarget) {
            this.lastDirectorTarget = engine.directorTargetId || "";
            this.holoGlitchTimer = 0.3; // Trigger glitch for 0.3s
        }
        if (this.holoGlitchTimer > 0) this.holoGlitchTimer -= dt;

        // Propagate updates to sub-systems
        this.vfx.update(dt, this.globalTime, engine.currentScene.ambientType);
        this.hud.update(dt);
    }

    public processEventsWithEngine(events: GameEvent[], engine: GameEngine): void {
        events.forEach(event => {
            // 1. HUD Events (Floating Text)
            if (['DAMAGE', 'HEAL', 'CC_APPLIED'].includes(event.type)) {
                 const hex = HexUtils.fromPx(event.pos.x, event.pos.y, engine.mapConfig);
                 const terrainHeight = this.grid.getTerrainHeight(hex.q, hex.r);
                 const baseY = event.pos.y - terrainHeight - HUD_TEXT_OFFSET; 

                 let text = "";
                 let color = "#fff";
                 let size = 16;
                 let type: 'DAMAGE' | 'HEAL' | 'SHOUT' | 'CC' = 'DAMAGE';
                 let xOffset = 0;

                 if (event.type === 'DAMAGE') {
                     const val = Math.abs(event.value || 0);
                     text = val.toString();
                     color = val > 100 ? '#ef4444' : '#fff'; // Crit Red vs White
                     size = val > 100 ? 24 : 16;
                     type = 'DAMAGE';
                     xOffset = (Math.random() - 0.5) * 10;
                 } else if (event.type === 'HEAL') {
                     text = "+" + Math.abs(event.value || 0);
                     color = '#4ade80';
                     type = 'HEAL';
                     xOffset = (Math.random() - 0.5) * 10;
                 } else {
                     text = event.text || "";
                     color = event.color || "#fff";
                     type = 'CC';
                     size = 14;
                     xOffset = -45;
                 }

                 if (text) {
                     this.hud.addFloatingText(event.pos.x + xOffset, baseY, text, color, size, type);
                 }

                 // --- BEAM VISUAL CHECK ---
                 if (event.skill && event.skill.visual === 'BEAM' && event.sourceId) {
                     const source = engine.agents.find(a => a.id === event.sourceId);
                     if (source) {
                         // Use visual position for beam start/end
                         const sHex = HexUtils.fromPx(source.px, source.py, engine.mapConfig);
                         const sH = this.grid.getTerrainHeight(sHex.q, sHex.r);
                         const sx = source.px;
                         const sy = source.py - sH - 40; 
                         const tH = terrainHeight; 
                         const tx = event.pos.x;
                         const ty = event.pos.y - tH - 20; 
                         this.vfx.spawnBeam(sx, sy, tx, ty, event.skill.color);
                     }
                 }

            } else if (event.type === 'CAST_START') {
                 if (event.skill && event.skill.tag !== 'BASIC') {
                     const hex = HexUtils.fromPx(event.pos.x, event.pos.y, engine.mapConfig);
                     const terrainHeight = this.grid.getTerrainHeight(hex.q, hex.r);
                     const isUlt = event.skill.tag === 'ULT';
                     const baseY = event.pos.y - terrainHeight - HUD_TEXT_OFFSET - (isUlt ? 30 : 10); 
                     const xOffset = 55; 
                     this.hud.addFloatingText(event.pos.x + xOffset, baseY, event.skill.name, event.skill.color, 14, 'SHOUT', isUlt);
                 }
            } else if (event.type === 'CAST_FINISH') {
                 if (event.skill && event.skill.tag === 'ULT') {
                     if (event.skill.projectileSpeed === 0 || event.skill.power <= 0) {
                         this.vfx.spawnDomainExpansion(event.pos.x, event.pos.y, event.skill.color, 4.0);
                         this.triggerCameraShake(0.5, 8); 
                     }
                 }
            }

            const hex = HexUtils.fromPx(event.pos.x, event.pos.y, engine.mapConfig);
            const terrainHeight = this.grid.getTerrainHeight(hex.q, hex.r);
            const visualY = event.pos.y - terrainHeight;

            switch (event.type) {
                case 'DAMAGE': 
                    this.vfx.spawnExplosion(event.pos.x, visualY, 0, 5, event.color || '#fff', 1.0, 0.8, 'SPARK'); 
                    break;
                case 'PROJECTILE_HIT': 
                    this.handleHitVisuals(event, engine, visualY); 
                    break;
                case 'DEATH':
                    // Trigger massive shatter effect
                    // event.team is passed from AgentManager
                    const team = event.team !== undefined ? event.team : Team.BLUE; 
                    this.vfx.spawnUnitShatter(event.pos.x, visualY, team);
                    break;
                case 'SPAWN':
                    // Trigger spawn visual (Beam in)
                    this.vfx.spawnTeleport(event.pos.x, visualY, event.color || '#fff');
                    break;
            }
        });
    }

    private handleHitVisuals(event: GameEvent, engine: GameEngine, visualY: number): void {
        const color = event.skill?.color || '#fff';
        const isUlt = event.skill?.tag === 'ULT';

        if (isUlt) {
            this.triggerCameraShake(0.6, 15); 
            this.vfx.spawnDivinePillar(event.pos.x, visualY, color, 1.5);
            this.vfx.spawnShockwave(event.pos.x, visualY, color, 2.0);

            if (event.skill?.type === 'AOE') {
                const centerHex = HexUtils.fromPx(event.pos.x, event.pos.y, engine.mapConfig);
                const radius = event.skill.aoeRadius || 1;
                const affectedHexes = HexUtils.range(centerHex, radius);

                affectedHexes.forEach(h => {
                    if (engine.isValid(h.q, h.r)) {
                        const tileH = this.grid.getTerrainHeight(h.q, h.r);
                        const tilePos = HexUtils.toPx(h.q, h.r, engine.mapConfig);
                        const tileVisualY = tilePos.y - tileH;

                        const distToCenter = Math.abs(h.q - centerHex.q) + Math.abs(h.r - centerHex.r);
                        if (distToCenter > 0) {
                            const delay = distToCenter * 0.05;
                            this.vfx.spawnDivinePillar(tilePos.x, tileVisualY, color, 0.7, delay);
                            this.vfx.addGridFlash(h.q, h.r, color);
                        } else {
                            this.vfx.addGridFlash(h.q, h.r, color);
                        }
                    }
                });
            } else {
                this.vfx.addImpact(event.pos.x, visualY, color, 'RING', 3.0);
                this.vfx.spawnExplosion(event.pos.x, visualY, 0, 50, color, 2.0, 1.0, 'SPARK');
            }
        } else {
            if (event.skill?.type === 'AOE') {
                const center = HexUtils.fromPx(event.pos.x, event.pos.y, engine.mapConfig);
                const radius = event.skill.aoeRadius || 1;
                HexUtils.range(center, radius).forEach(h => {
                    if (engine.isValid(h.q, h.r)) {
                        this.vfx.addGridFlash(h.q, h.r, color);
                        if (h.q === center.q && h.r === center.r) {
                            this.vfx.addDecal(event.pos.x, visualY, color);
                        }
                    }
                });
                this.vfx.addImpact(event.pos.x, visualY, color, 'RING', 1.2);
            } else {
                this.vfx.addImpact(event.pos.x, visualY, color, 'RING', 0.8);
                this.vfx.spawnExplosion(event.pos.x, visualY, 0, 8, color, 1.2, 0.6, 'SPARK');
            }
        }
    }

    private triggerCameraShake(duration: number, intensity: number) {
        this.shakeTimer = duration;
        this.shakeIntensity = intensity;
    }

    // --- Main Rendering Loop ---

    public draw(
        ctx: CanvasRenderingContext2D, 
        engine: GameEngine, 
        camera: Camera, 
        highlight: Agent | null, 
        fps: number, 
        hoveredHex: Hex | null, 
        hoveredSkill: Skill | null
    ): void {
        const { width: canvasWidth, height: canvasHeight } = ctx.canvas;
        const scene = engine.currentScene;
        const obstacleStyle = scene.obstacleStyle || 'WALL'; 

        // 1. Complex Background
        ctx.clearRect(0, 0, canvasWidth, canvasHeight);
        this.drawComplexBackground(ctx, canvasWidth, canvasHeight, scene);

        // 2. Camera Transform application
        ctx.save();

        let shakeOffsetX = 0;
        let shakeOffsetY = 0;
        if (this.shakeTimer > 0) {
            shakeOffsetX = (Math.random() - 0.5) * this.shakeIntensity;
            shakeOffsetY = (Math.random() - 0.5) * this.shakeIntensity;
        }

        ctx.translate(canvasWidth / 2 + shakeOffsetX, canvasHeight / 2 + shakeOffsetY);
        ctx.scale(camera.zoom, camera.zoom);
        ctx.translate(-camera.x - canvasWidth / 2 / camera.zoom, -camera.y - canvasHeight / 2 / camera.zoom);

        // 3. MAIN PASS: Collect and Sort Renderables
        let renderList: RenderableItem[] = [];

        renderList.push(...this.grid.collectRenderables(
            engine, hoveredHex, hoveredSkill, highlight, 
            this.vfx.gridFlashes, engine.projectiles,
            this.transitionT, this.transitionPhase,
            this.globalTime
        ));

        renderList.push(...this.vfx.collectRenderables(
            engine,
            (q, r) => this.grid.getTerrainHeight(q, r),
            engine.mapConfig,
            this.transitionT,
            this.transitionPhase
        ));

        renderList.push(...this.unit.collectRenderables(
            engine.agents, (q, r) => this.grid.getTerrainHeight(q, r), this.globalTime, highlight, engine.mapConfig
        ));

        engine.obstacles.forEach(key => {
             const [q, r] = key.split(',').map(Number);
             const pos = HexUtils.toPx(q, r, engine.mapConfig);

             let visualY = pos.y;
             if (this.transitionPhase !== 'IDLE') {
                 const centerQ = Math.floor(engine.mapConfig.w / 2);
                 const centerR = Math.floor(engine.mapConfig.h / 2);
                 const dist = Math.sqrt((q - centerQ)**2 + (r - centerR)**2);
                 const maxDist = Math.max(engine.mapConfig.w, engine.mapConfig.h) / 2;
                 const d = dist / maxDist;

                 if (this.transitionPhase === 'OUT') {
                    const trigger = d * 0.3;
                    if (this.transitionT > trigger) {
                        const fallT = Math.min(1, (this.transitionT - trigger) * 2.5);
                        visualY += fallT * fallT * fallT * 1000;
                    }
                 } else if (this.transitionPhase === 'IN') {
                    const trigger = d * 0.3;
                    const riseT = Math.max(0, Math.min(1, (this.transitionT - trigger) * 2.5));
                    const easedRise = 1 - Math.pow(1 - riseT, 3);
                    visualY += (1 - easedRise) * 1000;
                 }
             }

             if (visualY < pos.y + 800) {
                 const terrainH = this.grid.getTerrainHeight(q, r);
                 renderList.push({
                     y: visualY, z: OBSTACLE_Z_INDEX,
                     draw: (c) => {
                         const sprite = SpriteManager.getObstacleSprite(obstacleStyle);
                         c.drawImage(sprite, pos.x - 32, visualY - terrainH - OBSTACLE_OFFSET_Y + 20);
                     }
                 });
             }
        });

        renderList.sort((a, b) => {
            if (Math.abs(a.y - b.y) < 2) return a.z - b.z;
            if (a.z > 50 && b.z <= 50) return 1; 
            if (b.z > 50 && a.z <= 50) return -1;
            return a.y - b.y;
        });

        renderList.forEach(item => item.draw(ctx));

        // 4. Occlusion Pass
        const occludedAgents = this.grid.getOccludedAgents(engine);
        if (occludedAgents.length > 0) {
            ctx.save();
            occludedAgents.forEach(agent => {
                this.unit.drawSilhouette(
                    ctx, agent, 
                    (q, r) => this.grid.getTerrainHeight(q, r), 
                    this.globalTime,
                    engine.mapConfig
                );
            });
            ctx.restore();
        }

        // 5. Atmospheric Fog
        this.drawAtmosphericFog(ctx, engine.mapConfig.w * HEX_SIZE * 2, engine.mapConfig.h * HEX_SIZE * 2, scene);

        // 6. Tactical Overlay Lines (World Space)
        this.drawTacticalOverlay(ctx, engine, highlight);

        // 7. Top VFX
        this.vfx.drawTopLayerParticles(ctx, scene, engine.mapConfig, this.transitionT, this.transitionPhase);

        // 8. HUD
        this.hud.draw(ctx, engine.agents, (q, r) => this.grid.getTerrainHeight(q, r));

        // 9. Holographic Director HUD (Screen Space, but Diegetic)
        if (engine.directorTargetId) {
            const focus = engine.agents.find(a => a.id === engine.directorTargetId);
            if (focus) {
                // We draw this *inside* the camera transform if we want it tied to world, 
                // BUT the requirement is screen corner.
                // To make it look "in-world" but stuck to corner, we draw it after restore() but apply manual perspective.
                ctx.restore(); // Exit Camera
                this.drawHolographicHUD(ctx, focus, canvasWidth, canvasHeight, camera);
                ctx.save(); // Restore dummy save to match final restore() call
            } else {
                ctx.restore();
                ctx.save();
            }
        } else {
            ctx.restore();
            ctx.save();
        }

        ctx.restore(); // Final restore

        // 10. Debug Overlay
        this.drawDebugOverlay(ctx, fps);
    }

    // =========================================================================================
    // 📺 HOLOGRAPHIC TACTICAL HUD (Diegetic UI)
    // =========================================================================================

    private drawHolographicHUD(ctx: CanvasRenderingContext2D, agent: Agent, w: number, h: number, cam: Camera) {
        // Position: Top Right, floating
        const hudX = w - 280;
        const hudY = 80;
        const width = 240;
        const height = 160;

        ctx.save();

        // --- 1. Glitch Effect ---
        let gx = 0, gy = 0;
        if (this.holoGlitchTimer > 0) {
            gx = (Math.random() - 0.5) * 20;
            gy = (Math.random() - 0.5) * 10;
            if (Math.random() > 0.7) return; // Flicker off
        }

        // --- 2. Perspective Transform ---
        // Skew to match isometric feel (Parallel to ground planes)
        // matrix(1, -0.1, 0, 1, x, y) gives a slight "leaning back" feel
        ctx.transform(1, -0.12, 0, 1, hudX + gx, hudY + gy);

        // --- 3. Glass Background ---
        const bgGrad = ctx.createLinearGradient(0, 0, width, height);
        const baseColor = agent.team === Team.BLUE ? '#06b6d4' : '#f97316'; // Cyan vs Orange

        bgGrad.addColorStop(0, `${baseColor}40`); // 25% opacity
        bgGrad.addColorStop(1, `${baseColor}05`); // 2% opacity

        ctx.fillStyle = bgGrad;
        ctx.fillRect(0, 0, width, height);

        // Grid Lines
        ctx.strokeStyle = `${baseColor}30`;
        ctx.lineWidth = 1;
        ctx.beginPath();
        for(let i=0; i<=width; i+=20) { ctx.moveTo(i, 0); ctx.lineTo(i, height); }
        for(let i=0; i<=height; i+=20) { ctx.moveTo(0, i); ctx.lineTo(width, i); }
        ctx.stroke();

        // Border corners
        ctx.strokeStyle = baseColor;
        ctx.lineWidth = 2;
        const len = 15;
        ctx.beginPath();
        ctx.moveTo(0, len); ctx.lineTo(0, 0); ctx.lineTo(len, 0); // TL
        ctx.moveTo(width-len, 0); ctx.lineTo(width, 0); ctx.lineTo(width, len); // TR
        ctx.moveTo(width, height-len); ctx.lineTo(width, height); ctx.lineTo(width-len, height); // BR
        ctx.moveTo(len, height); ctx.lineTo(0, height); ctx.lineTo(0, height-len); // BL
        ctx.stroke();

        // --- 4. Content: Logic Visualization ---

        // Header
        ctx.fillStyle = baseColor;
        ctx.font = 'bold 12px monospace';
        ctx.fillText(`TARGET: ${agent.id}`, 10, 20);
        ctx.font = '10px monospace';
        ctx.fillStyle = '#fff';
        ctx.fillText(`STATUS: ${agent.btStatus.toUpperCase()}`, 10, 35);

        // Logic Graph
        // [SCAN] -> [DECISION] -> [ACTION]
        const nodes = [
            { x: 30, y: 80, label: 'SCAN', active: true }, // Always active
            { x: 100, y: 80, label: 'THINK', active: agent.btStatus !== '待機' },
            { x: 170, y: 80, label: 'ACT', active: agent.castingSkillIdx !== -1 || agent.isMoving }
        ];

        // Draw Connections
        ctx.strokeStyle = `${baseColor}60`;
        ctx.lineWidth = 2;
        ctx.beginPath();
        ctx.moveTo(nodes[0].x, nodes[0].y);
        ctx.lineTo(nodes[2].x, nodes[2].y);
        ctx.stroke();

        // Draw Active Flow (Pulse)
        const flowTime = (this.globalTime * 3) % 1; 
        const flowX = 30 + flowTime * 140;
        ctx.strokeStyle = '#fff';
        ctx.lineWidth = 2;
        ctx.beginPath();
        ctx.moveTo(flowX, 80);
        ctx.lineTo(flowX + 15, 80);
        ctx.stroke();

        // Draw Nodes
        nodes.forEach(n => {
            const isActive = n.active;

            // Outer Ring
            ctx.strokeStyle = isActive ? baseColor : `${baseColor}40`;
            ctx.fillStyle = `${baseColor}10`;
            ctx.beginPath(); ctx.arc(n.x, n.y, 10, 0, Math.PI*2); 
            ctx.fill(); ctx.stroke();

            // Inner Dot
            if (isActive) {
                ctx.fillStyle = '#fff';
                ctx.shadowColor = baseColor; ctx.shadowBlur = 10;
                ctx.beginPath(); ctx.arc(n.x, n.y, 4, 0, Math.PI*2); ctx.fill();
                ctx.shadowBlur = 0;
            }

            // Label
            ctx.fillStyle = isActive ? '#fff' : `${baseColor}60`;
            ctx.textAlign = 'center';
            ctx.fillText(n.label, n.x, n.y + 22);
        });

        // Special Alert: ULTIMATE
        if (agent.castingSkillIdx !== -1 && agent.skills[agent.castingSkillIdx]?.tag === 'ULT') {
            ctx.fillStyle = '#ef4444';
            ctx.globalAlpha = 0.5 + Math.sin(this.globalTime * 20) * 0.5;
            ctx.fillRect(0, 130, width, 20);
            ctx.fillStyle = '#fff';
            ctx.globalAlpha = 1.0;
            ctx.font = 'bold 12px monospace';
            ctx.textAlign = 'center';
            ctx.fillText('WARNING: ULTIMATE DETECTED', width/2, 144);
        } else if (agent.hp < agent.maxHp * 0.3) {
            ctx.fillStyle = '#ef4444';
            ctx.font = 'bold 10px monospace';
            ctx.fillText('CRITICAL CONDITION', width - 70, 20);
        }

        // --- 5. Tether Line to Unit ---
        ctx.beginPath();
        ctx.moveTo(10, height);
        ctx.lineTo(10, height + 20);
        ctx.strokeStyle = `${baseColor}40`;
        ctx.setLineDash([2, 4]);
        ctx.stroke();
        ctx.setLineDash([]);

        ctx.restore();
    }

    // =========================================================================================
    // ⚔️ TACTICAL OVERLAY SYSTEM (Visualizing AI Intent)
    // =========================================================================================

    private drawTacticalOverlay(ctx: CanvasRenderingContext2D, engine: GameEngine, highlight: Agent | null) {
        ctx.save();

        // B. Selected Agent Details (Path & Targets)
        if (highlight && highlight.hp > 0) {
            const hH = this.grid.getTerrainHeight(highlight.q, highlight.r);
            const startPx = highlight.px;
            const startPy = highlight.py - hH - 30; // Waist height

            // 1. Movement Trajectory
            if (highlight.trajectory.length > 0) {
                ctx.beginPath();
                ctx.moveTo(startPx, startPy);

                highlight.trajectory.forEach(hex => {
                    const p = HexUtils.toPx(hex.q, hex.r, engine.mapConfig);
                    const h = this.grid.getTerrainHeight(hex.q, hex.r);
                    ctx.lineTo(p.x, p.y - h - 30);
                });

                ctx.strokeStyle = '#fff';
                ctx.lineWidth = 2;
                ctx.setLineDash([5, 5]); // Dashed Line
                ctx.globalAlpha = 0.6;
                ctx.stroke();
                ctx.setLineDash([]); // Reset
                ctx.globalAlpha = 1.0;

                // Destination Marker
                const dest = highlight.trajectory[highlight.trajectory.length - 1];
                const dP = HexUtils.toPx(dest.q, dest.r, engine.mapConfig);
                const dH = this.grid.getTerrainHeight(dest.q, dest.r);

                ctx.save();
                ctx.translate(dP.x, dP.y - dH);
                ctx.scale(1, 0.6);
                ctx.beginPath(); ctx.arc(0, 0, 10, 0, Math.PI*2); 
                ctx.fillStyle = '#fff'; ctx.globalAlpha = 0.3; ctx.fill();
                ctx.strokeStyle = '#fff'; ctx.globalAlpha = 0.8; ctx.lineWidth=2; ctx.stroke();
                ctx.restore();
            }

            // 2. Target Line
            if (highlight.target && highlight.target.hp > 0) {
                const t = highlight.target;
                const tH = this.grid.getTerrainHeight(t.q, t.r);
                const endPx = t.px;
                const endPy = t.py - tH - 30;

                const grad = ctx.createLinearGradient(startPx, startPy, endPx, endPy);
                const isEnemy = highlight.team !== t.team;
                const color = isEnemy ? '#ef4444' : '#4ade80';

                grad.addColorStop(0, 'rgba(0,0,0,0)'); // Fade out near source
                grad.addColorStop(0.2, color);
                grad.addColorStop(1, color);

                ctx.beginPath();
                ctx.moveTo(startPx, startPy);
                ctx.lineTo(endPx, endPy);

                ctx.strokeStyle = grad;
                ctx.lineWidth = 2;
                ctx.globalAlpha = 0.8 + Math.sin(this.globalTime * 10) * 0.2; // Pulse
                ctx.stroke();
                ctx.globalAlpha = 1.0;
            }
        }

        ctx.restore();
    }

    // =========================================================================================
    // 🌌 COMPLEX BACKGROUND SYSTEM
    // =========================================================================================

    private drawComplexBackground(ctx: CanvasRenderingContext2D, w: number, h: number, scene: SceneTheme): void {
        const t = this.globalTime;

        // 1. Base Gradient (Sky + Horizon)
        const bgGrad = ctx.createLinearGradient(0, 0, 0, h);
        bgGrad.addColorStop(0, scene.background); // Sky Top
        bgGrad.addColorStop(0.6, scene.horizon);  // Horizon Line
        bgGrad.addColorStop(1, '#000');           // Below Horizon (Ground blend)
        ctx.fillStyle = bgGrad;
        ctx.fillRect(0, 0, w, h);

        ctx.save();

        // 2. Stars / Nebula (For Space/Ice/Night themes)
        if (scene.id === 'VOID' || scene.id === 'ICE' || scene.id === 'FOREST') {
             // Nebula clouds
             ctx.globalCompositeOperation = 'screen';
             const cloudCount = 3;
             for(let i=0; i<cloudCount; i++) {
                 const x = (Math.sin(i * 1.5 + t * 0.05) * 0.5 + 0.5) * w;
                 const y = (Math.cos(i * 1.2 + t * 0.03) * 0.3 + 0.3) * h;
                 const radius = w * 0.4;
                 const grad = ctx.createRadialGradient(x, y, 0, x, y, radius);
                 grad.addColorStop(0, scene.ambientColor);
                 grad.addColorStop(1, 'transparent');
                 ctx.fillStyle = grad;
                 ctx.globalAlpha = 0.15;
                 ctx.beginPath(); ctx.arc(x, y, radius, 0, Math.PI*2); ctx.fill();
             }

             // Stars
             ctx.fillStyle = '#fff';
             const seed = 123; 
             for(let i=0; i<80; i++) {
                 const sx = (Math.sin(i * seed) * 0.5 + 0.5) * w;
                 const sy = (Math.cos(i * seed * 1.5) * 0.5 + 0.5) * h * 0.8; // Keep stars in upper sky
                 const size = Math.random() * 2;
                 const alpha = Math.sin(t + i) * 0.5 + 0.5;
                 ctx.globalAlpha = alpha * (scene.id === 'VOID' ? 0.8 : 0.4);
                 ctx.beginPath(); ctx.arc(sx, sy, size, 0, Math.PI*2); ctx.fill();
             }
        }

        // 3. Distant Silhouette / Terrain (Mountains)
        if (scene.id === 'FOREST' || scene.id === 'ICE' || scene.id === 'DESERT' || scene.id === 'MAGMA') {
            ctx.globalCompositeOperation = 'source-over';
            ctx.fillStyle = scene.background; // Blend with sky color but darker
            ctx.globalAlpha = 0.5;

            const drawMountainLayer = (speed: number, yOffset: number, roughness: number) => {
                ctx.beginPath();
                ctx.moveTo(0, h);
                for(let x=0; x<=w; x+=20) {
                    // Simple procedural terrain noise
                    const n = Math.sin(x * 0.01 + t * speed) * Math.cos(x * 0.03) * roughness;
                    ctx.lineTo(x, h * 0.6 + yOffset + n);
                }
                ctx.lineTo(w, h);
                ctx.fill();
            };

            // Far Layer
            drawMountainLayer(0.01, 0, 50);
            // Near Layer (Darker)
            ctx.fillStyle = '#000';
            ctx.globalAlpha = 0.3;
            drawMountainLayer(0.02, 50, 30);
        }

        // 4. Special Sky Features
        this.drawSkyFeatures(ctx, w, h, scene, t);

        ctx.restore();
    }

    private drawSkyFeatures(ctx: CanvasRenderingContext2D, w: number, h: number, scene: SceneTheme, t: number) {
        if (scene.bgFeature === 'NONE') return;

        ctx.globalCompositeOperation = 'screen';

        if (scene.bgFeature === 'SKY_RIVER') {
            // --- COSMIC RIVER ---
            const color = scene.ambientColor; // Purple

            // Draw multiple sine waves to simulate a flowing river
            for(let i=0; i<5; i++) {
                const lineWidth = 30 + i * 10;
                const amplitude = 30 + i * 10;
                const phase = t * (0.2 + i * 0.05);
                const yBase = h * 0.3 + i * 20;

                ctx.strokeStyle = color;
                ctx.lineWidth = lineWidth;
                ctx.globalAlpha = 0.1 - (i * 0.01);
                ctx.beginPath();
                for(let x=0; x<=w; x+=10) {
                    const y = yBase + Math.sin(x * 0.005 + phase) * amplitude + Math.cos(x * 0.01 - t*0.5) * 20;
                    if (x===0) ctx.moveTo(x, y);
                    else ctx.lineTo(x, y);
                }
                ctx.stroke();
            }

            // Add particles in the river
            ctx.fillStyle = '#fff';
            ctx.globalAlpha = 0.6;
            for(let i=0; i<20; i++) {
                const prog = (t * 0.1 + i / 20) % 1;
                const x = prog * w;
                const y = h * 0.3 + 50 + Math.sin(x * 0.005 + t * 0.2) * 40;
                ctx.beginPath(); ctx.arc(x, y, Math.random()*2 + 1, 0, Math.PI*2); ctx.fill();
            }

        } else if (scene.bgFeature === 'AURORA') {
            // --- VERTICAL CURTAINS ---
            const colors = ['#34d399', '#22d3ee', '#818cf8']; // Green, Cyan, Indigo

            for(let i=0; i<3; i++) {
                const grad = ctx.createLinearGradient(0, 0, 0, h);
                grad.addColorStop(0, 'transparent');
                grad.addColorStop(0.2, colors[i]);
                grad.addColorStop(0.8, 'transparent');

                ctx.fillStyle = grad;
                ctx.globalAlpha = 0.15;

                const phase = t * 0.5 + i * 2;
                ctx.beginPath();
                ctx.moveTo(0, h);
                for(let x=0; x<=w; x+=20) {
                    const y = h * 0.4 + Math.sin(x * 0.01 + phase) * 100 * Math.sin(x*0.002);
                    ctx.lineTo(x, y);
                }
                ctx.lineTo(w, 0); // Top Right
                ctx.lineTo(0, 0); // Top Left
                ctx.fill();
            }

        } else if (scene.bgFeature === 'CANOPY') {
            // --- GOD RAYS ---
            ctx.globalCompositeOperation = 'overlay';
            const centerX = w * 0.8;
            const centerY = -100;

            const grad = ctx.createRadialGradient(centerX, centerY, 50, centerX, centerY, w);
            grad.addColorStop(0, '#fef08a'); // Yellow light
            grad.addColorStop(1, 'transparent');

            ctx.fillStyle = grad;
            ctx.globalAlpha = 0.2;

            // Draw Angular Rays
            for(let i=0; i<6; i++) {
                const angle = Math.PI / 2 + Math.sin(t * 0.2 + i) * 0.2 + (i * 0.3);
                const width = Math.PI / 16;

                ctx.beginPath();
                ctx.moveTo(centerX, centerY);
                ctx.lineTo(centerX + Math.cos(angle - width) * w * 1.5, centerY + Math.sin(angle - width) * w * 1.5);
                ctx.lineTo(centerX + Math.cos(angle + width) * w * 1.5, centerY + Math.sin(angle + width) * w * 1.5);
                ctx.fill();
            }
        } else if (scene.bgFeature === 'HEAT_WAVE') {
            // Rising heat distortion visual
            ctx.fillStyle = '#fca5a5';
            ctx.globalAlpha = 0.05;
            for(let i=0; i<10; i++) {
                const x = (i / 10) * w;
                const height = h * 0.5 + Math.sin(t * 2 + i) * 50;
                const width = w / 10;
                ctx.fillRect(x, h - height, width, height);
            }
        }
    }

    private drawAtmosphericFog(ctx: CanvasRenderingContext2D, mapW: number, mapH: number, scene: SceneTheme) {
        const t = this.globalTime;

        ctx.save();
        ctx.globalCompositeOperation = 'screen';

        const fogColor = scene.fogColor || '#fff';
        const fogSprite = AssetManager.getFogCloud(fogColor); // Use pre-rendered sprite
        const numClouds = 8;

        for (let i = 0; i < numClouds; i++) {
            // Moving clouds across the map
            const speed = 20;
            const x = ((t * speed + i * (mapW / numClouds)) % (mapW * 1.5)) - mapW * 0.25;
            const y = (Math.sin(i * 123 + t * 0.1) * 0.5 + 0.5) * mapH;
            const size = 300 + Math.sin(i) * 100;

            ctx.globalAlpha = 0.1 + Math.sin(t * 0.5 + i) * 0.05; // Pulse opacity
            ctx.drawImage(fogSprite, x - size/2, y - size/2, size, size * 0.6);
        }

        ctx.restore();
    }

    private drawDebugOverlay(ctx: CanvasRenderingContext2D, fps: number): void {
        ctx.fillStyle = 'rgba(255,255,255,0.5)'; 
        ctx.font = '10px monospace';
        ctx.fillText(`FPS: ${fps}`, 10, 20);
    }
}

import { Agent } from "../game";
import { COLORS } from "../../constants";
import { Role } from "../../types";
import { HexUtils, MapConfig } from "../utils";

// --- Constants ---
const GRAVITY = 200;
const TEXT_LIFESPAN = 1.0;
const BAR_WIDTH = 40;
const BAR_HEIGHT = 5;
const BAR_BORDER = 1;

interface FloatingText {
    x: number; 
    y: number;
    vx: number; 
    vy: number;
    text: string; 
    color: string;
    life: number; 
    maxLife: number;
    size: number;
    type: 'DAMAGE' | 'HEAL' | 'SHOUT' | 'CC';
    isUlt?: boolean; // New flag for Ultimate visuals
}

export class HUDSystem {
    damageNumbers: FloatingText[] = [];

    addFloatingText(x: number, y: number, text: string, color: string, size: number, type: 'DAMAGE' | 'HEAL' | 'SHOUT' | 'CC' = 'DAMAGE', isUlt: boolean = false) {
        let vx = 0;
        let vy = 0;
        let life = TEXT_LIFESPAN;

        if (type === 'SHOUT') {
            if (isUlt) {
                vy = -5; // Ults float very slowly
                life = 2.5; // Stay longer
                size = 24; // Bigger font
            } else {
                vy = -20; // Normal skills float gently
                life = 1.2;
                size = 14; // Smaller to be less intrusive
            }
        } else if (type === 'CC') {
            vy = -40; 
            life = 1.2;
        } else {
            // DAMAGE / HEAL
            vx = (Math.random() - 0.5) * 60; 
            vy = -100; // Initial jump
        }

        this.damageNumbers.push({
            x, y,
            vx, vy, 
            text, 
            color, 
            life, 
            maxLife: life, 
            size,
            type,
            isUlt
        });
    }

    update(dt: number) {
        for (let i = this.damageNumbers.length - 1; i >= 0; i--) { 
            const d = this.damageNumbers[i]; 
            d.life -= dt; 

            // Physics integration
            d.x += d.vx * dt;
            d.y += d.vy * dt; 

            // Gravity logic
            if (d.type === 'DAMAGE' || d.type === 'HEAL') {
                d.vy += GRAVITY * dt;
            } else if (d.type === 'SHOUT' || d.type === 'CC') {
                d.vy *= 0.98; // Friction
            }

            if (d.life <= 0) {
                this.damageNumbers.splice(i, 1); 
            }
        }
    }

    private getUnitScale(role: Role): number {
        switch (role) {
            case Role.TANK: return 1.8;
            case Role.WARRIOR: return 1.6;
            default: return 1.4;
        }
    }

    draw(ctx: CanvasRenderingContext2D, agents: Agent[], getTerrainHeight: (q: number, r: number) => number, mapConfig: MapConfig) {
        // 1. Draw HP/MP Bars
        agents.forEach(a => {
            if (a.hp <= 0) return;
            if (a.spawnTimer > 0) return; 

            // Fix: Use visual position (px, py) to determine height to avoid bars detaching during knockback
            // Or interpolate if moving to keep bar attached to unit head
            let h = 0;

            if (a.isMoving && a.path.length > 0) {
                // Interpolate height for smoother visual
                // Note: a.q, a.r is the START of movement logic in this codebase structure (updated at end)
                const startH = getTerrainHeight(a.q, a.r);
                const endHex = a.path[0];
                const endH = getTerrainHeight(endHex.q, endHex.r);
                h = HexUtils.lerp(startH, endH, a.moveProgress);
            } else {
                // Static or knocked back (physics drift)
                const visualHex = HexUtils.fromPx(a.px, a.py, mapConfig);
                h = getTerrainHeight(visualHex.q, visualHex.r);
            }

            const scale = this.getUnitScale(a.role);

            const groundY = a.py - h;
            const baseOffset = 5; 
            const bodyHeightApprox = 35 * scale; 
            const floatOffset = a.physics.y; 

            const headX = a.px + a.physics.x;
            const headY = groundY - baseOffset - bodyHeightApprox + floatOffset;

            this.drawUnitBars(ctx, a, headX, headY);
        });

        // 2. Draw Floating Text
        this.drawFloatingText(ctx);
    }

    private drawUnitBars(ctx: CanvasRenderingContext2D, agent: Agent, x: number, y: number) {
        const w = BAR_WIDTH;
        const h = BAR_HEIGHT;
        const b = BAR_BORDER;

        // Background (Black Border)
        ctx.fillStyle = '#000'; 
        ctx.fillRect(x - w/2 - b, y - b, w + b*2, h + b*2);

        // HP Fill
        const hpPct = Math.max(0, agent.hp / agent.maxHp);
        ctx.fillStyle = COLORS.HP; 
        ctx.fillRect(x - w/2, y, w * hpPct, h);

        // MP Bar (Only if unit uses MP)
        if (agent.maxMp > 0) {
            const mpH = h / 2 + 1;
            const mpY = y + h + b;

            ctx.fillStyle = '#000'; 
            ctx.fillRect(x - w/2 - b, mpY, w + b*2, mpH + b*2);

            const mpPct = Math.max(0, agent.mp / agent.maxMp);
            ctx.fillStyle = COLORS.MP; 
            ctx.fillRect(x - w/2, mpY + b, w * mpPct, mpH);
        }
    }

    private drawFloatingText(ctx: CanvasRenderingContext2D) {
        this.damageNumbers.forEach(d => {
            const lifePct = d.life / d.maxLife;
            // Fade logic
            const alpha = lifePct < 0.3 ? lifePct / 0.3 : 1.0;

            ctx.globalAlpha = alpha;
            ctx.textAlign = 'center';
            ctx.textBaseline = 'middle';

            if (d.type === 'SHOUT') {
                if (d.isUlt) {
                    // --- ULTIMATE STYLE: Cinematic Strip ---
                    // Scale: Pop in slightly, then slow constant grow
                    const scale = 1 + (1 - lifePct) * 0.1; 

                    ctx.save();
                    ctx.translate(d.x, d.y);
                    ctx.scale(scale, scale);

                    ctx.font = `900 italic ${d.size}px "Arial Black", sans-serif`;
                    const textMetrics = ctx.measureText(d.text);
                    const w = textMetrics.width / 2 + 40;
                    const h = d.size + 20;

                    // 1. Transparent Cinematic Bar (Gradient)
                    // Fades to transparent at left/right edges
                    const bgGrad = ctx.createLinearGradient(-w, 0, w, 0);
                    bgGrad.addColorStop(0, 'rgba(0,0,0,0)');
                    bgGrad.addColorStop(0.2, 'rgba(0,0,0,0.5)'); // Semi-transparent black center
                    bgGrad.addColorStop(0.8, 'rgba(0,0,0,0.5)');
                    bgGrad.addColorStop(1, 'rgba(0,0,0,0)');

                    ctx.globalCompositeOperation = 'source-over';
                    ctx.fillStyle = bgGrad;
                    ctx.fillRect(-w, -h/2, w*2, h);

                    // 2. Text Glow (Outer Glow matching skill color)
                    ctx.shadowColor = d.color;
                    ctx.shadowBlur = 15;
                    ctx.fillStyle = '#fff';
                    ctx.strokeStyle = '#000'; // Black outline for contrast
                    ctx.lineWidth = 3;

                    ctx.strokeText(d.text, 0, 0);
                    ctx.fillText(d.text, 0, 0);

                    // 3. Additive Shine (Brighten text center)
                    ctx.globalCompositeOperation = 'lighter';
                    ctx.shadowBlur = 5;
                    ctx.fillStyle = d.color; 
                    ctx.globalAlpha = alpha * 0.5; // Subtle color overlay
                    ctx.fillText(d.text, 0, 0);

                    ctx.restore();

                } else {
                    // --- NORMAL SKILL: Minimalist Text ---
                    // No Background Box -> Reduces clutter significantly

                    ctx.font = `bold italic ${d.size}px "Segoe UI", sans-serif`;

                    // Heavy Stroke for readability against any background
                    ctx.lineWidth = 3;
                    ctx.lineJoin = 'round';
                    ctx.strokeStyle = 'rgba(0, 0, 0, 0.8)'; 
                    ctx.strokeText(d.text, d.x, d.y);

                    // Colored Text
                    ctx.fillStyle = d.color;
                    ctx.fillText(d.text, d.x, d.y);
                }

            } else if (d.type === 'CC') {
                // LEFT SIDE STATUS TEXT
                ctx.font = `900 ${d.size}px "Arial Black", sans-serif`; 
                ctx.strokeStyle = 'rgba(0,0,0,1.0)';
                ctx.lineWidth = 4;
                ctx.strokeText(d.text, d.x, d.y);

                ctx.fillStyle = d.color;
                ctx.fillText(d.text, d.x, d.y);

            } else {
                // DAMAGE / HEAL (CENTER)
                ctx.font = `bold ${d.size}px "Segoe UI", sans-serif`;
                ctx.fillStyle = d.color; 
                ctx.strokeStyle = 'rgba(0,0,0,0.8)'; 
                ctx.lineWidth = 3; 

                ctx.strokeText(d.text, d.x, d.y); 
                ctx.fillText(d.text, d.x, d.y);
            }

            // Reset context
            ctx.globalAlpha = 1.0;
            ctx.shadowBlur = 0;
            ctx.shadowColor = 'transparent';
        });
    }
}

import { Agent, GameEngine } from "./game";
import { HexUtils } from "./utils";
import { SpriteManager } from "./sprites";
import { AssetManager } from "./assets";
import { Hex, GameEvent, Skill, SceneTheme, Team } from "../types";
import { HEX_SIZE } from "../constants";

// Sub-systems
import { GridSystem, RenderableItem } from "./systems/grid";
import { VFXSystem } from "./systems/vfx";
import { UnitRenderSystem } from "./systems/unit";
import { HUDSystem } from "./systems/hud";

// Constants
const HUD_TEXT_OFFSET = 40; 
const OBSTACLE_Z_INDEX = 10;
const OBSTACLE_OFFSET_Y = 86; 

export interface Camera {
    x: number;
    y: number;
    zoom: number;
}

export class GameRenderer {
    public globalTime: number = 0;

    // Sub-systems
    public grid: GridSystem;
    public vfx: VFXSystem;
    public unit: UnitRenderSystem;
    public hud: HUDSystem;

    // Camera Shake Effects
    private shakeTimer = 0; 
    private shakeIntensity = 0;

    // Transition State
    private transitionT: number = 0;
    private transitionPhase: 'IN' | 'OUT' | 'IDLE' = 'IDLE';

    // Hologram Glitch State
    private holoGlitchTimer = 0;
    private lastDirectorTarget = "";

    constructor() {
        this.grid = new GridSystem();
        this.vfx = new VFXSystem();
        this.unit = new UnitRenderSystem();
        this.hud = new HUDSystem();
    }

    public setTransition(t: number, phase: 'IN' | 'OUT' | 'IDLE') {
        this.transitionT = t;
        this.transitionPhase = phase;
    }

    // --- Core Accessors ---

    public getTerrainHeight(q: number, r: number): number {
        return this.grid.getTerrainHeight(q, r);
    }

    public getHexAtScreenPoint(mouseX: number, mouseY: number, camera: Camera, engine: GameEngine): Hex | null {
        return this.grid.getHexAtScreenPoint(mouseX, mouseY, camera, engine);
    }

    // --- Update Loop ---

    public update(dt: number, engine: GameEngine): void {
        this.globalTime += dt;
        if (this.shakeTimer > 0) {
            this.shakeTimer -= dt;
        }

        // Hologram Glitch Logic
        if (engine.directorTargetId !== this.lastDirectorTarget) {
            this.lastDirectorTarget = engine.directorTargetId || "";
            this.holoGlitchTimer = 0.3; // Trigger glitch for 0.3s
        }
        if (this.holoGlitchTimer > 0) this.holoGlitchTimer -= dt;

        // Propagate updates to sub-systems
        this.vfx.update(dt, this.globalTime, engine.currentScene.ambientType);
        this.hud.update(dt);
    }

    public processEventsWithEngine(events: GameEvent[], engine: GameEngine): void {
        events.forEach(event => {
            // 1. HUD Events (Floating Text)
            if (['DAMAGE', 'HEAL', 'CC_APPLIED'].includes(event.type)) {
                 const hex = HexUtils.fromPx(event.pos.x, event.pos.y, engine.mapConfig);
                 const terrainHeight = this.grid.getTerrainHeight(hex.q, hex.r);
                 const baseY = event.pos.y - terrainHeight - HUD_TEXT_OFFSET; 

                 let text = "";
                 let color = "#fff";
                 let size = 16;
                 let type: 'DAMAGE' | 'HEAL' | 'SHOUT' | 'CC' = 'DAMAGE';
                 let xOffset = 0;

                 if (event.type === 'DAMAGE') {
                     const val = Math.abs(event.value || 0);
                     text = val.toString();
                     color = val > 100 ? '#ef4444' : '#fff'; // Crit Red vs White
                     size = val > 100 ? 24 : 16;
                     type = 'DAMAGE';
                     xOffset = (Math.random() - 0.5) * 10;
                 } else if (event.type === 'HEAL') {
                     text = "+" + Math.abs(event.value || 0);
                     color = '#4ade80';
                     type = 'HEAL';
                     xOffset = (Math.random() - 0.5) * 10;
                 } else {
                     text = event.text || "";
                     color = event.color || "#fff";
                     type = 'CC';
                     size = 14;
                     xOffset = -45;
                 }

                 if (text) {
                     this.hud.addFloatingText(event.pos.x + xOffset, baseY, text, color, size, type);
                 }

                 // --- BEAM VISUAL CHECK ---
                 if (event.skill && event.skill.visual === 'BEAM' && event.sourceId) {
                     const source = engine.agents.find(a => a.id === event.sourceId);
                     if (source) {
                         // Use visual position for beam start/end
                         const sHex = HexUtils.fromPx(source.px, source.py, engine.mapConfig);
                         const sH = this.grid.getTerrainHeight(sHex.q, sHex.r);
                         const sx = source.px;
                         const sy = source.py - sH - 40; 
                         const tH = terrainHeight; 
                         const tx = event.pos.x;
                         const ty = event.pos.y - tH - 20; 
                         this.vfx.spawnBeam(sx, sy, tx, ty, event.skill.color);
                     }
                 }

            } else if (event.type === 'CAST_START') {
                 if (event.skill && event.skill.tag !== 'BASIC') {
                     const hex = HexUtils.fromPx(event.pos.x, event.pos.y, engine.mapConfig);
                     const terrainHeight = this.grid.getTerrainHeight(hex.q, hex.r);
                     const isUlt = event.skill.tag === 'ULT';
                     const baseY = event.pos.y - terrainHeight - HUD_TEXT_OFFSET - (isUlt ? 30 : 10); 
                     const xOffset = 55; 
                     this.hud.addFloatingText(event.pos.x + xOffset, baseY, event.skill.name, event.skill.color, 14, 'SHOUT', isUlt);
                 }
            } else if (event.type === 'CAST_FINISH') {
                 if (event.skill && event.skill.tag === 'ULT') {
                     if (event.skill.projectileSpeed === 0 || event.skill.power <= 0) {
                         this.vfx.spawnDomainExpansion(event.pos.x, event.pos.y, event.skill.color, 4.0);
                         this.triggerCameraShake(0.5, 8); 
                     }
                 }
            }

            const hex = HexUtils.fromPx(event.pos.x, event.pos.y, engine.mapConfig);
            const terrainHeight = this.grid.getTerrainHeight(hex.q, hex.r);
            const visualY = event.pos.y - terrainHeight;

            switch (event.type) {
                case 'DAMAGE': 
                    this.vfx.spawnExplosion(event.pos.x, visualY, 0, 5, event.color || '#fff', 1.0, 0.8, 'SPARK'); 
                    break;
                case 'PROJECTILE_HIT': 
                    this.handleHitVisuals(event, engine, visualY); 
                    break;
                case 'DEATH':
                    // Trigger massive shatter effect
                    // event.team is passed from AgentManager
                    const team = event.team !== undefined ? event.team : Team.BLUE; 
                    this.vfx.spawnUnitShatter(event.pos.x, visualY, team);
                    break;
                case 'SPAWN':
                    // Trigger spawn visual (Beam in)
                    this.vfx.spawnTeleport(event.pos.x, visualY, event.color || '#fff');
                    break;
            }
        });
    }

    private handleHitVisuals(event: GameEvent, engine: GameEngine, visualY: number): void {
        const color = event.skill?.color || '#fff';
        const isUlt = event.skill?.tag === 'ULT';

        if (isUlt) {
            this.triggerCameraShake(0.6, 15); 
            this.vfx.spawnDivinePillar(event.pos.x, visualY, color, 1.5);
            this.vfx.spawnShockwave(event.pos.x, visualY, color, 2.0);

            if (event.skill?.type === 'AOE') {
                const centerHex = HexUtils.fromPx(event.pos.x, event.pos.y, engine.mapConfig);
                const radius = event.skill.aoeRadius || 1;
                const affectedHexes = HexUtils.range(centerHex, radius);

                affectedHexes.forEach(h => {
                    if (engine.isValid(h.q, h.r)) {
                        const tileH = this.grid.getTerrainHeight(h.q, h.r);
                        const tilePos = HexUtils.toPx(h.q, h.r, engine.mapConfig);
                        const tileVisualY = tilePos.y - tileH;

                        const distToCenter = Math.abs(h.q - centerHex.q) + Math.abs(h.r - centerHex.r);
                        if (distToCenter > 0) {
                            const delay = distToCenter * 0.05;
                            this.vfx.spawnDivinePillar(tilePos.x, tileVisualY, color, 0.7, delay);
                            this.vfx.addGridFlash(h.q, h.r, color);
                        } else {
                            this.vfx.addGridFlash(h.q, h.r, color);
                        }
                    }
                });
            } else {
                this.vfx.addImpact(event.pos.x, visualY, color, 'RING', 3.0);
                this.vfx.spawnExplosion(event.pos.x, visualY, 0, 50, color, 2.0, 1.0, 'SPARK');
            }
        } else {
            if (event.skill?.type === 'AOE') {
                const center = HexUtils.fromPx(event.pos.x, event.pos.y, engine.mapConfig);
                const radius = event.skill.aoeRadius || 1;
                HexUtils.range(center, radius).forEach(h => {
                    if (engine.isValid(h.q, h.r)) {
                        this.vfx.addGridFlash(h.q, h.r, color);
                        if (h.q === center.q && h.r === center.r) {
                            this.vfx.addDecal(event.pos.x, visualY, color);
                        }
                    }
                });
                this.vfx.addImpact(event.pos.x, visualY, color, 'RING', 1.2);
            } else {
                this.vfx.addImpact(event.pos.x, visualY, color, 'RING', 0.8);
                this.vfx.spawnExplosion(event.pos.x, visualY, 0, 8, color, 1.2, 0.6, 'SPARK');
            }
        }
    }

    private triggerCameraShake(duration: number, intensity: number) {
        this.shakeTimer = duration;
        this.shakeIntensity = intensity;
    }

    // --- Main Rendering Loop ---

    public draw(
        ctx: CanvasRenderingContext2D, 
        engine: GameEngine, 
        camera: Camera, 
        highlight: Agent | null, 
        fps: number, 
        hoveredHex: Hex | null, 
        hoveredSkill: Skill | null
    ): void {
        const { width: canvasWidth, height: canvasHeight } = ctx.canvas;
        const scene = engine.currentScene;
        const obstacleStyle = scene.obstacleStyle || 'WALL'; 

        // 1. Complex Background
        ctx.clearRect(0, 0, canvasWidth, canvasHeight);
        this.drawComplexBackground(ctx, canvasWidth, canvasHeight, scene);

        // 2. Camera Transform application
        ctx.save();

        let shakeOffsetX = 0;
        let shakeOffsetY = 0;
        if (this.shakeTimer > 0) {
            shakeOffsetX = (Math.random() - 0.5) * this.shakeIntensity;
            shakeOffsetY = (Math.random() - 0.5) * this.shakeIntensity;
        }

        ctx.translate(canvasWidth / 2 + shakeOffsetX, canvasHeight / 2 + shakeOffsetY);
        ctx.scale(camera.zoom, camera.zoom);
        ctx.translate(-camera.x - canvasWidth / 2 / camera.zoom, -camera.y - canvasHeight / 2 / camera.zoom);

        // 3. MAIN PASS: Collect and Sort Renderables
        let renderList: RenderableItem[] = [];

        renderList.push(...this.grid.collectRenderables(
            engine, hoveredHex, hoveredSkill, highlight, 
            this.vfx.gridFlashes, engine.projectiles,
            this.transitionT, this.transitionPhase,
            this.globalTime
        ));

        renderList.push(...this.vfx.collectRenderables(
            engine,
            (q, r) => this.grid.getTerrainHeight(q, r),
            engine.mapConfig,
            this.transitionT,
            this.transitionPhase
        ));

        renderList.push(...this.unit.collectRenderables(
            engine.agents, (q, r) => this.grid.getTerrainHeight(q, r), this.globalTime, highlight, engine.mapConfig
        ));

        engine.obstacles.forEach(key => {
             const [q, r] = key.split(',').map(Number);
             const pos = HexUtils.toPx(q, r, engine.mapConfig);

             let visualY = pos.y;
             if (this.transitionPhase !== 'IDLE') {
                 const centerQ = Math.floor(engine.mapConfig.w / 2);
                 const centerR = Math.floor(engine.mapConfig.h / 2);
                 const dist = Math.sqrt((q - centerQ)**2 + (r - centerR)**2);
                 const maxDist = Math.max(engine.mapConfig.w, engine.mapConfig.h) / 2;
                 const d = dist / maxDist;

                 if (this.transitionPhase === 'OUT') {
                    const trigger = d * 0.3;
                    if (this.transitionT > trigger) {
                        const fallT = Math.min(1, (this.transitionT - trigger) * 2.5);
                        visualY += fallT * fallT * fallT * 1000;
                    }
                 } else if (this.transitionPhase === 'IN') {
                    const trigger = d * 0.3;
                    const riseT = Math.max(0, Math.min(1, (this.transitionT - trigger) * 2.5));
                    const easedRise = 1 - Math.pow(1 - riseT, 3);
                    visualY += (1 - easedRise) * 1000;
                 }
             }

             if (visualY < pos.y + 800) {
                 const terrainH = this.grid.getTerrainHeight(q, r);
                 renderList.push({
                     y: visualY, z: OBSTACLE_Z_INDEX,
                     draw: (c) => {
                         const sprite = SpriteManager.getObstacleSprite(obstacleStyle);
                         c.drawImage(sprite, pos.x - 32, visualY - terrainH - OBSTACLE_OFFSET_Y + 20);
                     }
                 });
             }
        });

        renderList.sort((a, b) => {
            if (Math.abs(a.y - b.y) < 2) return a.z - b.z;
            if (a.z > 50 && b.z <= 50) return 1; 
            if (b.z > 50 && a.z <= 50) return -1;
            return a.y - b.y;
        });

        renderList.forEach(item => item.draw(ctx));

        // 4. Occlusion Pass
        const occludedAgents = this.grid.getOccludedAgents(engine);
        if (occludedAgents.length > 0) {
            ctx.save();
            occludedAgents.forEach(agent => {
                this.unit.drawSilhouette(
                    ctx, agent, 
                    (q, r) => this.grid.getTerrainHeight(q, r), 
                    this.globalTime,
                    engine.mapConfig
                );
            });
            ctx.restore();
        }

        // 5. Atmospheric Fog
        this.drawAtmosphericFog(ctx, engine.mapConfig.w * HEX_SIZE * 2, engine.mapConfig.h * HEX_SIZE * 2, scene);

        // 6. Tactical Overlay Lines (World Space)
        this.drawTacticalOverlay(ctx, engine, highlight);

        // 7. Top VFX
        this.vfx.drawTopLayerParticles(ctx, scene, engine.mapConfig, this.transitionT, this.transitionPhase);

        // 8. HUD
        this.hud.draw(ctx, engine.agents, (q, r) => this.grid.getTerrainHeight(q, r), engine.mapConfig);

        // 9. Holographic Director HUD (Screen Space, but Diegetic)
        if (engine.directorTargetId) {
            const focus = engine.agents.find(a => a.id === engine.directorTargetId);
            if (focus) {
                // We draw this *inside* the camera transform if we want it tied to world, 
                // BUT the requirement is screen corner.
                // To make it look "in-world" but stuck to corner, we draw it after restore() but apply manual perspective.
                ctx.restore(); // Exit Camera
                this.drawHolographicHUD(ctx, focus, canvasWidth, canvasHeight, camera);
                ctx.save(); // Restore dummy save to match final restore() call
            } else {
                ctx.restore();
                ctx.save();
            }
        } else {
            ctx.restore();
            ctx.save();
        }

        ctx.restore(); // Final restore

        // 10. Debug Overlay
        this.drawDebugOverlay(ctx, fps);
    }

    // =========================================================================================
    // 📺 HOLOGRAPHIC TACTICAL HUD (Diegetic UI)
    // =========================================================================================

    private drawHolographicHUD(ctx: CanvasRenderingContext2D, agent: Agent, w: number, h: number, cam: Camera) {
        // Position: Top Right, floating
        const hudX = w - 280;
        const hudY = 80;
        const width = 240;
        const height = 160;

        ctx.save();

        // --- 1. Glitch Effect ---
        let gx = 0, gy = 0;
        if (this.holoGlitchTimer > 0) {
            gx = (Math.random() - 0.5) * 20;
            gy = (Math.random() - 0.5) * 10;
            if (Math.random() > 0.7) return; // Flicker off
        }

        // --- 2. Perspective Transform ---
        // Skew to match isometric feel (Parallel to ground planes)
        // matrix(1, -0.1, 0, 1, x, y) gives a slight "leaning back" feel
        ctx.transform(1, -0.12, 0, 1, hudX + gx, hudY + gy);

        // --- 3. Glass Background ---
        const bgGrad = ctx.createLinearGradient(0, 0, width, height);
        const baseColor = agent.team === Team.BLUE ? '#06b6d4' : '#f97316'; // Cyan vs Orange

        bgGrad.addColorStop(0, `${baseColor}40`); // 25% opacity
        bgGrad.addColorStop(1, `${baseColor}05`); // 2% opacity

        ctx.fillStyle = bgGrad;
        ctx.fillRect(0, 0, width, height);

        // Grid Lines
        ctx.strokeStyle = `${baseColor}30`;
        ctx.lineWidth = 1;
        ctx.beginPath();
        for(let i=0; i<=width; i+=20) { ctx.moveTo(i, 0); ctx.lineTo(i, height); }
        for(let i=0; i<=height; i+=20) { ctx.moveTo(0, i); ctx.lineTo(width, i); }
        ctx.stroke();

        // Border corners
        ctx.strokeStyle = baseColor;
        ctx.lineWidth = 2;
        const len = 15;
        ctx.beginPath();
        ctx.moveTo(0, len); ctx.lineTo(0, 0); ctx.lineTo(len, 0); // TL
        ctx.moveTo(width-len, 0); ctx.lineTo(width, 0); ctx.lineTo(width, len); // TR
        ctx.moveTo(width, height-len); ctx.lineTo(width, height); ctx.lineTo(width-len, height); // BR
        ctx.moveTo(len, height); ctx.lineTo(0, height); ctx.lineTo(0, height-len); // BL
        ctx.stroke();

        // --- 4. Content: Logic Visualization ---

        // Header
        ctx.fillStyle = baseColor;
        ctx.font = 'bold 12px monospace';
        ctx.fillText(`TARGET: ${agent.id}`, 10, 20);
        ctx.font = '10px monospace';
        ctx.fillStyle = '#fff';
        ctx.fillText(`STATUS: ${agent.btStatus.toUpperCase()}`, 10, 35);

        // Logic Graph
        // [SCAN] -> [DECISION] -> [ACTION]
        const nodes = [
            { x: 30, y: 80, label: 'SCAN', active: true }, // Always active
            { x: 100, y: 80, label: 'THINK', active: agent.btStatus !== '待機' },
            { x: 170, y: 80, label: 'ACT', active: agent.castingSkillIdx !== -1 || agent.isMoving }
        ];

        // Draw Connections
        ctx.strokeStyle = `${baseColor}60`;
        ctx.lineWidth = 2;
        ctx.beginPath();
        ctx.moveTo(nodes[0].x, nodes[0].y);
        ctx.lineTo(nodes[2].x, nodes[2].y);
        ctx.stroke();

        // Draw Active Flow (Pulse)
        const flowTime = (this.globalTime * 3) % 1; 
        const flowX = 30 + flowTime * 140;
        ctx.strokeStyle = '#fff';
        ctx.lineWidth = 2;
        ctx.beginPath();
        ctx.moveTo(flowX, 80);
        ctx.lineTo(flowX + 15, 80);
        ctx.stroke();

        // Draw Nodes
        nodes.forEach(n => {
            const isActive = n.active;

            // Outer Ring
            ctx.strokeStyle = isActive ? baseColor : `${baseColor}40`;
            ctx.fillStyle = `${baseColor}10`;
            ctx.beginPath(); ctx.arc(n.x, n.y, 10, 0, Math.PI*2); 
            ctx.fill(); ctx.stroke();

            // Inner Dot
            if (isActive) {
                ctx.fillStyle = '#fff';
                ctx.shadowColor = baseColor; ctx.shadowBlur = 10;
                ctx.beginPath(); ctx.arc(n.x, n.y, 4, 0, Math.PI*2); ctx.fill();
                ctx.shadowBlur = 0;
            }

            // Label
            ctx.fillStyle = isActive ? '#fff' : `${baseColor}60`;
            ctx.textAlign = 'center';
            ctx.fillText(n.label, n.x, n.y + 22);
        });

        // Special Alert: ULTIMATE
        if (agent.castingSkillIdx !== -1 && agent.skills[agent.castingSkillIdx]?.tag === 'ULT') {
            ctx.fillStyle = '#ef4444';
            ctx.globalAlpha = 0.5 + Math.sin(this.globalTime * 20) * 0.5;
            ctx.fillRect(0, 130, width, 20);
            ctx.fillStyle = '#fff';
            ctx.globalAlpha = 1.0;
            ctx.font = 'bold 12px monospace';
            ctx.textAlign = 'center';
            ctx.fillText('WARNING: ULTIMATE DETECTED', width/2, 144);
        } else if (agent.hp < agent.maxHp * 0.3) {
            ctx.fillStyle = '#ef4444';
            ctx.font = 'bold 10px monospace';
            ctx.fillText('CRITICAL CONDITION', width - 70, 20);
        }

        // --- 5. Tether Line to Unit ---
        ctx.beginPath();
        ctx.moveTo(10, height);
        ctx.lineTo(10, height + 20);
        ctx.strokeStyle = `${baseColor}40`;
        ctx.setLineDash([2, 4]);
        ctx.stroke();
        ctx.setLineDash([]);

        ctx.restore();
    }

    // =========================================================================================
    // ⚔️ TACTICAL OVERLAY SYSTEM (Visualizing AI Intent)
    // =========================================================================================

    private drawTacticalOverlay(ctx: CanvasRenderingContext2D, engine: GameEngine, highlight: Agent | null) {
        ctx.save();

        // B. Selected Agent Details (Path & Targets)
        if (highlight && highlight.hp > 0) {
            const hH = this.grid.getTerrainHeight(highlight.q, highlight.r);
            const startPx = highlight.px;
            const startPy = highlight.py - hH - 30; // Waist height

            // 1. Movement Trajectory
            if (highlight.trajectory.length > 0) {
                ctx.beginPath();
                ctx.moveTo(startPx, startPy);

                highlight.trajectory.forEach(hex => {
                    const p = HexUtils.toPx(hex.q, hex.r, engine.mapConfig);
                    const h = this.grid.getTerrainHeight(hex.q, hex.r);
                    ctx.lineTo(p.x, p.y - h - 30);
                });

                ctx.strokeStyle = '#fff';
                ctx.lineWidth = 2;
                ctx.setLineDash([5, 5]); // Dashed Line
                ctx.globalAlpha = 0.6;
                ctx.stroke();
                ctx.setLineDash([]); // Reset
                ctx.globalAlpha = 1.0;

                // Destination Marker
                const dest = highlight.trajectory[highlight.trajectory.length - 1];
                const dP = HexUtils.toPx(dest.q, dest.r, engine.mapConfig);
                const dH = this.grid.getTerrainHeight(dest.q, dest.r);

                ctx.save();
                ctx.translate(dP.x, dP.y - dH);
                ctx.scale(1, 0.6);
                ctx.beginPath(); ctx.arc(0, 0, 10, 0, Math.PI*2); 
                ctx.fillStyle = '#fff'; ctx.globalAlpha = 0.3; ctx.fill();
                ctx.strokeStyle = '#fff'; ctx.globalAlpha = 0.8; ctx.lineWidth=2; ctx.stroke();
                ctx.restore();
            }

            // 2. Target Line
            if (highlight.target && highlight.target.hp > 0) {
                const t = highlight.target;
                const tH = this.grid.getTerrainHeight(t.q, t.r);
                const endPx = t.px;
                const endPy = t.py - tH - 30;

                const grad = ctx.createLinearGradient(startPx, startPy, endPx, endPy);
                const isEnemy = highlight.team !== t.team;
                const color = isEnemy ? '#ef4444' : '#4ade80';

                grad.addColorStop(0, 'rgba(0,0,0,0)'); // Fade out near source
                grad.addColorStop(0.2, color);
                grad.addColorStop(1, color);

                ctx.beginPath();
                ctx.moveTo(startPx, startPy);
                ctx.lineTo(endPx, endPy);

                ctx.strokeStyle = grad;
                ctx.lineWidth = 2;
                ctx.globalAlpha = 0.8 + Math.sin(this.globalTime * 10) * 0.2; // Pulse
                ctx.stroke();
                ctx.globalAlpha = 1.0;
            }
        }

        ctx.restore();
    }

    // =========================================================================================
    // 🌌 COMPLEX BACKGROUND SYSTEM
    // =========================================================================================

    private drawComplexBackground(ctx: CanvasRenderingContext2D, w: number, h: number, scene: SceneTheme): void {
        const t = this.globalTime;

        // 1. Base Gradient (Sky + Horizon)
        const bgGrad = ctx.createLinearGradient(0, 0, 0, h);
        bgGrad.addColorStop(0, scene.background); // Sky Top
        bgGrad.addColorStop(0.6, scene.horizon);  // Horizon Line
        bgGrad.addColorStop(1, '#000');           // Below Horizon (Ground blend)
        ctx.fillStyle = bgGrad;
        ctx.fillRect(0, 0, w, h);

        ctx.save();

        // 2. Stars / Nebula (For Space/Ice/Night themes)
        if (scene.id === 'VOID' || scene.id === 'ICE' || scene.id === 'FOREST') {
             // Nebula clouds
             ctx.globalCompositeOperation = 'screen';
             const cloudCount = 3;
             for(let i=0; i<cloudCount; i++) {
                 const x = (Math.sin(i * 1.5 + t * 0.05) * 0.5 + 0.5) * w;
                 const y = (Math.cos(i * 1.2 + t * 0.03) * 0.3 + 0.3) * h;
                 const radius = w * 0.4;
                 const grad = ctx.createRadialGradient(x, y, 0, x, y, radius);
                 grad.addColorStop(0, scene.ambientColor);
                 grad.addColorStop(1, 'transparent');
                 ctx.fillStyle = grad;
                 ctx.globalAlpha = 0.15;
                 ctx.beginPath(); ctx.arc(x, y, radius, 0, Math.PI*2); ctx.fill();
             }

             // Stars
             ctx.fillStyle = '#fff';
             const seed = 123; 
             for(let i=0; i<80; i++) {
                 const sx = (Math.sin(i * seed) * 0.5 + 0.5) * w;
                 const sy = (Math.cos(i * seed * 1.5) * 0.5 + 0.5) * h * 0.8; // Keep stars in upper sky
                 const size = Math.random() * 2;
                 const alpha = Math.sin(t + i) * 0.5 + 0.5;
                 ctx.globalAlpha = alpha * (scene.id === 'VOID' ? 0.8 : 0.4);
                 ctx.beginPath(); ctx.arc(sx, sy, size, 0, Math.PI*2); ctx.fill();
             }
        }

        // 3. Distant Silhouette / Terrain (Mountains)
        if (scene.id === 'FOREST' || scene.id === 'ICE' || scene.id === 'DESERT' || scene.id === 'MAGMA') {
            ctx.globalCompositeOperation = 'source-over';
            ctx.fillStyle = scene.background; // Blend with sky color but darker
            ctx.globalAlpha = 0.5;

            const drawMountainLayer = (speed: number, yOffset: number, roughness: number) => {
                ctx.beginPath();
                ctx.moveTo(0, h);
                for(let x=0; x<=w; x+=20) {
                    // Simple procedural terrain noise
                    const n = Math.sin(x * 0.01 + t * speed) * Math.cos(x * 0.03) * roughness;
                    ctx.lineTo(x, h * 0.6 + yOffset + n);
                }
                ctx.lineTo(w, h);
                ctx.fill();
            };

            // Far Layer
            drawMountainLayer(0.01, 0, 50);
            // Near Layer (Darker)
            ctx.fillStyle = '#000';
            ctx.globalAlpha = 0.3;
            drawMountainLayer(0.02, 50, 30);
        }

        // 4. Special Sky Features
        this.drawSkyFeatures(ctx, w, h, scene, t);

        ctx.restore();
    }

    private drawSkyFeatures(ctx: CanvasRenderingContext2D, w: number, h: number, scene: SceneTheme, t: number) {
        if (scene.bgFeature === 'NONE') return;

        ctx.globalCompositeOperation = 'screen';

        if (scene.bgFeature === 'SKY_RIVER') {
            // --- COSMIC RIVER ---
            const color = scene.ambientColor; // Purple

            // Draw multiple sine waves to simulate a flowing river
            for(let i=0; i<5; i++) {
                const lineWidth = 30 + i * 10;
                const amplitude = 30 + i * 10;
                const phase = t * (0.2 + i * 0.05);
                const yBase = h * 0.3 + i * 20;

                ctx.strokeStyle = color;
                ctx.lineWidth = lineWidth;
                ctx.globalAlpha = 0.1 - (i * 0.01);
                ctx.beginPath();
                for(let x=0; x<=w; x+=10) {
                    const y = yBase + Math.sin(x * 0.005 + phase) * amplitude + Math.cos(x * 0.01 - t*0.5) * 20;
                    if (x===0) ctx.moveTo(x, y);
                    else ctx.lineTo(x, y);
                }
                ctx.stroke();
            }

            // Add particles in the river
            ctx.fillStyle = '#fff';
            ctx.globalAlpha = 0.6;
            for(let i=0; i<20; i++) {
                const prog = (t * 0.1 + i / 20) % 1;
                const x = prog * w;
                const y = h * 0.3 + 50 + Math.sin(x * 0.005 + t * 0.2) * 40;
                ctx.beginPath(); ctx.arc(x, y, Math.random()*2 + 1, 0, Math.PI*2); ctx.fill();
            }

        } else if (scene.bgFeature === 'AURORA') {
            // --- VERTICAL CURTAINS ---
            const colors = ['#34d399', '#22d3ee', '#818cf8']; // Green, Cyan, Indigo

            for(let i=0; i<3; i++) {
                const grad = ctx.createLinearGradient(0, 0, 0, h);
                grad.addColorStop(0, 'transparent');
                grad.addColorStop(0.2, colors[i]);
                grad.addColorStop(0.8, 'transparent');

                ctx.fillStyle = grad;
                ctx.globalAlpha = 0.15;

                const phase = t * 0.5 + i * 2;
                ctx.beginPath();
                ctx.moveTo(0, h);
                for(let x=0; x<=w; x+=20) {
                    const y = h * 0.4 + Math.sin(x * 0.01 + phase) * 100 * Math.sin(x*0.002);
                    ctx.lineTo(x, y);
                }
                ctx.lineTo(w, 0); // Top Right
                ctx.lineTo(0, 0); // Top Left
                ctx.fill();
            }

        } else if (scene.bgFeature === 'CANOPY') {
            // --- GOD RAYS ---
            ctx.globalCompositeOperation = 'overlay';
            const centerX = w * 0.8;
            const centerY = -100;

            const grad = ctx.createRadialGradient(centerX, centerY, 50, centerX, centerY, w);
            grad.addColorStop(0, '#fef08a'); // Yellow light
            grad.addColorStop(1, 'transparent');

            ctx.fillStyle = grad;
            ctx.globalAlpha = 0.2;

            // Draw Angular Rays
            for(let i=0; i<6; i++) {
                const angle = Math.PI / 2 + Math.sin(t * 0.2 + i) * 0.2 + (i * 0.3);
                const width = Math.PI / 16;

                ctx.beginPath();
                ctx.moveTo(centerX, centerY);
                ctx.lineTo(centerX + Math.cos(angle - width) * w * 1.5, centerY + Math.sin(angle - width) * w * 1.5);
                ctx.lineTo(centerX + Math.cos(angle + width) * w * 1.5, centerY + Math.sin(angle + width) * w * 1.5);
                ctx.fill();
            }
        } else if (scene.bgFeature === 'HEAT_WAVE') {
            // Rising heat distortion visual
            ctx.fillStyle = '#fca5a5';
            ctx.globalAlpha = 0.05;
            for(let i=0; i<10; i++) {
                const x = (i / 10) * w;
                const height = h * 0.5 + Math.sin(t * 2 + i) * 50;
                const width = w / 10;
                ctx.fillRect(x, h - height, width, height);
            }
        }
    }

    private drawAtmosphericFog(ctx: CanvasRenderingContext2D, mapW: number, mapH: number, scene: SceneTheme) {
        const t = this.globalTime;

        ctx.save();
        ctx.globalCompositeOperation = 'screen';

        const fogColor = scene.fogColor || '#fff';
        const fogSprite = AssetManager.getFogCloud(fogColor); // Use pre-rendered sprite
        const numClouds = 8;

        for (let i = 0; i < numClouds; i++) {
            // Moving clouds across the map
            const speed = 20;
            const x = ((t * speed + i * (mapW / numClouds)) % (mapW * 1.5)) - mapW * 0.25;
            const y = (Math.sin(i * 123 + t * 0.1) * 0.5 + 0.5) * mapH;
            const size = 300 + Math.sin(i) * 100;

            ctx.globalAlpha = 0.1 + Math.sin(t * 0.5 + i) * 0.05; // Pulse opacity
            ctx.drawImage(fogSprite, x - size/2, y - size/2, size, size * 0.6);
        }

        ctx.restore();
    }

    private drawDebugOverlay(ctx: CanvasRenderingContext2D, fps: number): void {
        ctx.fillStyle = 'rgba(255,255,255,0.5)'; 
        ctx.font = '10px monospace';
        ctx.fillText(`FPS: ${fps}`, 10, 20);
    }
}

import { Agent } from "../game";
import { SpriteManager } from "../sprites";
import { AssetManager } from "../assets";
import { AnimState, Role, Team } from "../../types";
import { RenderableItem } from "./grid";
import { HEX_SIZE } from "../../constants";
import { HexUtils, MapConfig } from "../utils";

// Visual Constants
const MAX_UNIT_SIZE_RATIO = 0.85; 
const UNIT_REFERENCE_HEIGHT = 100; 

export class UnitRenderSystem {

    public collectRenderables(
        agents: Agent[], 
        getTerrainHeight: (q: number, r: number) => number, 
        globalTime: number, 
        highlightAgent: Agent | null,
        mapConfig: MapConfig
    ): RenderableItem[] {
        const list: RenderableItem[] = [];

        agents.forEach(agent => {
            if (agent.hp <= 0 && agent.fullyDead) return;

            // --- HEIGHT CORRECTION (Interpolated) ---
            // Fix: Interpolate height between start and end of move to prevent "snapping"
            let currentHeight = getTerrainHeight(agent.q, agent.r);

            if (agent.isMoving && agent.path.length > 0) {
                // Determine start and end heights for the current move segment
                // agent.q, agent.r are technically the *start* of the current move segment in logic?
                // Wait, logic updates q,r at the end. So q,r is START. path[0] is END.
                const startH = getTerrainHeight(agent.q, agent.r);
                const endHex = agent.path[0];
                const endH = getTerrainHeight(endHex.q, endHex.r);

                // Interpolate
                currentHeight = HexUtils.lerp(startH, endH, agent.moveProgress);
            } else {
                // If static, use visual lookup to be safe against drift, or just q,r
                // Using visual lookup ensures if physics pushes them to another tile, they pop up (which is physically correct for knockback)
                const visualHex = HexUtils.fromPx(agent.px, agent.py, mapConfig);
                currentHeight = getTerrainHeight(visualHex.q, visualHex.r);
            }

            const visualY = agent.py - currentHeight;

            list.push({
                y: agent.py + 1, 
                z: 10,
                draw: (ctx) => this.drawAssembly(
                    ctx, 
                    agent, 
                    agent.px, 
                    visualY, 
                    globalTime, 
                    highlightAgent === agent,
                    false // Normal Mode
                )
            });
        });

        return list;
    }

    // Called by Renderer for Occlusion Pass
    public drawSilhouette(
        ctx: CanvasRenderingContext2D, 
        agent: Agent, 
        getTerrainHeight: (q: number, r: number) => number,
        globalTime: number,
        mapConfig: MapConfig
    ) {
        // Consistent height logic for silhouette
        let currentHeight = getTerrainHeight(agent.q, agent.r);
        if (agent.isMoving && agent.path.length > 0) {
            const startH = getTerrainHeight(agent.q, agent.r);
            const endHex = agent.path[0];
            const endH = getTerrainHeight(endHex.q, endHex.r);
            currentHeight = HexUtils.lerp(startH, endH, agent.moveProgress);
        } else {
            const visualHex = HexUtils.fromPx(agent.px, agent.py, mapConfig);
            currentHeight = getTerrainHeight(visualHex.q, visualHex.r);
        }

        const visualY = agent.py - currentHeight;

        this.drawAssembly(ctx, agent, agent.px, visualY, globalTime, false, true);
    }

    // =================================================================================
    // 🎨 HIERARCHICAL VECTOR ASSEMBLY RENDERER
    // =================================================================================

    private drawAssembly(
        ctx: CanvasRenderingContext2D, 
        agent: Agent, 
        drawX: number, 
        drawY: number, 
        globalTime: number, 
        isSelected: boolean,
        isSilhouette: boolean
    ) {
        // 1. Setup Constraint Space
        const maxDimension = HEX_SIZE * 2 * MAX_UNIT_SIZE_RATIO;

        // Distinct Scale Factors for Roles
        let roleScaleMod = 1.0;
        switch(agent.role) {
            case Role.TANK: roleScaleMod = 1.25; break; // Bulky
            case Role.WARRIOR: roleScaleMod = 1.1; break; // Standard strong
            case Role.RANGER: roleScaleMod = 0.9; break; // Agile/Slim
            case Role.MAGE: roleScaleMod = 0.9; break; // Small/Floating
            case Role.SUPPORT: roleScaleMod = 0.95; break;
        }

        const scaleFactor = (maxDimension / UNIT_REFERENCE_HEIGHT) * roleScaleMod;

        ctx.save();
        ctx.translate(drawX, drawY);
        ctx.scale(scaleFactor, scaleFactor);

        // 3. Apply Physics (Z-Jump / Blast)
        // We apply Physics Z translation to the whole container (Base + Body)
        const physX = agent.physics.x / scaleFactor;
        const physY = agent.physics.y / scaleFactor;
        const physZ = agent.physics.z / scaleFactor; 

        ctx.translate(physX, physY - physZ); 
        ctx.rotate(agent.physics.angle); // Apply Ragdoll Rotation

        // --- DRAW BASE (Ground Level) ---
        // The base should strictly align with the grid face (0,0 local)
        if (!isSilhouette && agent.hp > 0 && agent.visualStatus !== 'POLYMORPH') {
            const assets = SpriteManager.getUnitImages(agent.role, agent.team);
            ctx.save();
            // Center of base sprite ellipse is at (64, 79). 
            // We draw at (-64, -79) to align it with (0,0).
            ctx.drawImage(assets.base, -64, -79); 

            // Casting Floor Rune (Ground level)
            if (agent.castingSkillIdx !== -1) {
                const skill = agent.skills[agent.castingSkillIdx];
                if (skill) {
                    const circle = AssetManager.getMagicCircle(skill.color, skill.tag === 'ULT');
                    ctx.save(); 
                    ctx.scale(1, 0.5); 
                    ctx.rotate(globalTime * 2);
                    ctx.globalAlpha = 0.6;
                    ctx.drawImage(circle, -64, -64, 128, 128); 
                    ctx.restore();
                }
            }
            ctx.restore();
        }

        // --- PREPARE BODY TRANSFORM ---
        // Shift up to align body feet with ground (y=0)
        // Standard body drawing has feet around y=15. So we shift up by -15.
        const BODY_GROUNDING_OFFSET = -15; 

        let bodyFloat = BODY_GROUNDING_OFFSET; 

        // Add Breathing / Hovering
        if (agent.hp > 0) {
             if ((agent.role === Role.MAGE || agent.role === Role.SUPPORT) && !agent.isMoving && agent.visualStatus === 'NONE') {
                bodyFloat -= 5 + Math.sin(globalTime * 2) * 3; // Mages float higher
            }
        } else {
            bodyFloat = -5; // Dead units sink slightly into ground
        }

        ctx.translate(0, bodyFloat);

        // --- 2. Spawn Animation (Materialize) ---
        // Applies scale stretch and alpha fade if spawning
        let spawnAlpha = 1.0;
        let whiteOverlay = 0;

        if (agent.spawnTimer > 0) {
            const SPAWN_DURATION = 0.5; // From game.ts init
            const progress = 1 - (agent.spawnTimer / SPAWN_DURATION); // 0 -> 1
            const eased = 1 - Math.pow(1 - progress, 3); // Cubic Out

            spawnAlpha = eased;
            const spawnStretch = 2.0 - eased; // 2.0 -> 1.0
            whiteOverlay = 1 - eased; // 1 -> 0

            // Scale body vertically around its feet (now at 0,0 due to translate)
            ctx.scale(1, spawnStretch);
            ctx.globalAlpha *= spawnAlpha;
        }

        // Hit Flash / Death Filter
        if (agent.hp <= 0 && !isSilhouette) {
            ctx.filter = 'grayscale(100%) opacity(80%)'; 
        } else if (!isSilhouette && agent.hitFlashTimer > 0) {
            ctx.filter = 'brightness(200%)'; 
        } else if (whiteOverlay > 0) {
            ctx.filter = `brightness(${100 + whiteOverlay * 200}%)`;
        }

        ctx.scale(agent.facing > 0 ? 1 : -1, 1);

        // SILHOUETTE MODE SETUP
        if (isSilhouette) {
            ctx.globalCompositeOperation = 'source-over'; 
            ctx.globalAlpha = 0.8; 
        }

        // 4. Render Body (or Special Form)
        if (agent.visualStatus === 'POLYMORPH') {
            // Draw Sheep
            const sheep = SpriteManager.getSpecialModel('SHEEP');
            const bounce = Math.abs(Math.sin(globalTime * 5) * 5);
            ctx.drawImage(sheep, -32, -32 - bounce, 64, 64);
        } else {
            // Standard Unit Render
            if (agent.team === Team.BLUE) {
                this.drawImperialLegion(ctx, agent, globalTime, isSilhouette);
            } else {
                this.drawArcaneCovenant(ctx, agent, globalTime, isSilhouette);
            }

            // Casting VFX (Only if alive)
            if (!isSilhouette && agent.hp > 0 && agent.castingSkillIdx !== -1) {
                this.drawCastingVFX(ctx, agent, globalTime);
            }

            // Frozen Overlay
            if (agent.visualStatus === 'FROZEN') {
                const ice = SpriteManager.getSpecialModel('ICE');
                ctx.save();
                ctx.globalCompositeOperation = 'hard-light';
                // Ice block needs to cover body, roughly centered
                ctx.drawImage(ice, -48, -75, 96, 128);
                ctx.restore();
            }

            // Stasis Overlay
            if (agent.visualStatus === 'STASIS') {
                ctx.save();
                ctx.fillStyle = '#facc15';
                ctx.globalAlpha = 0.4;
                ctx.globalCompositeOperation = 'lighter';
                ctx.beginPath();
                ctx.ellipse(0, -15, 25, 50, 0, 0, Math.PI*2);
                ctx.fill();
                ctx.strokeStyle = '#fff';
                ctx.lineWidth = 2;
                ctx.stroke();
                ctx.restore();
            }
        }

        // 6. Selection Ring & Status (Only Normal Mode & Alive)
        if (!isSilhouette) {
            this.drawStatusIcons(ctx, agent, globalTime, drawX, drawY, scaleFactor);
            this.drawStatusEffects(ctx, agent, globalTime);

            if (isSelected && agent.hp > 0) {
                // Draw Selection Ring around Body center (approx -20)
                ctx.strokeStyle = '#fff';
                ctx.lineWidth = 2 / scaleFactor; 
                ctx.beginPath();
                ctx.ellipse(0, -20, 30, 15, 0, 0, Math.PI * 2);
                ctx.stroke();
            }
        }

        ctx.restore(); // End Assembly

        // 7. NEW: Spawn Role Indicator
        // Drawn AFTER restore so it is not affected by body stretch/fade/rotation
        if (agent.spawnTimer > 0 && !isSilhouette) {
            this.drawSpawnIndicator(ctx, agent, drawX, drawY, scaleFactor);
        }
    }

    private drawSpawnIndicator(ctx: CanvasRenderingContext2D, agent: Agent, x: number, y: number, scale: number) {
        const assets = SpriteManager.getUnitImages(agent.role, agent.team);
        const totalDuration = 0.5;
        const alpha = Math.max(0, agent.spawnTimer / totalDuration);
        const yOffset = -40 * scale; 

        ctx.save();
        ctx.translate(x, y + yOffset);
        const popScale = 1.0 + alpha * 0.2;
        ctx.scale(popScale, popScale);
        ctx.globalAlpha = alpha;

        ctx.fillStyle = 'rgba(15, 23, 42, 0.4)'; 
        ctx.strokeStyle = agent.team === Team.BLUE ? 'rgba(59, 130, 246, 0.8)' : 'rgba(239, 68, 68, 0.8)';
        ctx.lineWidth = 2;
        ctx.beginPath(); ctx.arc(0, 0, 18, 0, Math.PI*2); ctx.fill(); ctx.stroke();

        ctx.drawImage(assets.icon, -12, -12, 24, 24);

        ctx.font = 'bold 10px sans-serif';
        ctx.textAlign = 'center';
        ctx.fillStyle = '#fff';
        ctx.strokeStyle = 'rgba(0,0,0,0.8)';
        ctx.lineWidth = 2;
        ctx.strokeText(agent.role, 0, 28);
        ctx.fillText(agent.role, 0, 28);

        ctx.restore();
    }

    private drawStatusEffects(ctx: CanvasRenderingContext2D, agent: Agent, t: number) {
        if (agent.hp <= 0) return;

        ctx.save();
        // Undo facing flip so icons don't flip
        if (agent.facing < 0) ctx.scale(-1, 1);

        const HEAD_Y = -75; // Adjusted head position for icons

        // 1. STUN
        if (agent.stunTimer > 0 && !agent.banished && agent.visualStatus !== 'FROZEN') {
            const icon = AssetManager.getStatusIcon('STUN');
            const angle = t * 5;
            ctx.drawImage(icon, -20 + Math.cos(angle)*10, HEAD_Y + Math.sin(angle)*5, 24, 24);
            ctx.drawImage(icon, -10 + Math.cos(angle + 2)*10, HEAD_Y - 10 + Math.sin(angle + 2)*5, 16, 16);
        }

        // 2. SILENCE
        if (agent.silenceTimer > 0) {
            const icon = AssetManager.getStatusIcon('SILENCE');
            ctx.drawImage(icon, 15, HEAD_Y - 5 + Math.sin(t * 3) * 3, 24, 24);
        }

        // 3. BANISH
        if (agent.banished && agent.visualStatus === 'NONE') {
            const icon = AssetManager.getStatusIcon('BANISH');
            ctx.globalAlpha = 0.7;
            ctx.drawImage(icon, -12, HEAD_Y - 20 + Math.sin(t * 2) * 5, 24, 24);
        }

        // 4. DoT
        if (agent.dotTimer > 0) {
            const pulse = 1 + Math.sin(t * 10) * 0.2;
            const iconSize = 28 * pulse; 
            const icon = AssetManager.getStatusIcon('POISON'); 
            const glow = AssetManager.getGlowSprite('#ef4444');
            ctx.globalCompositeOperation = 'lighter';
            ctx.drawImage(glow, -35 - iconSize/2, HEAD_Y - iconSize/2, iconSize*2, iconSize*2);
            ctx.globalCompositeOperation = 'source-over';
            ctx.drawImage(icon, -35, HEAD_Y, iconSize, iconSize);

            ctx.globalAlpha = 0.8;
            for(let i=0; i<5; i++) {
                const cycle = (t * 2 + i * 0.7) % 1;
                const yOff = -cycle * 60; 
                const xOff = Math.sin(t * 5 + i) * 15;
                const size = (1 - cycle) * 7;
                ctx.fillStyle = i % 2 === 0 ? '#10b981' : '#a855f7';
                if (cycle < 1) {
                    ctx.beginPath(); ctx.arc(xOff, -20 + yOff, size, 0, Math.PI*2); ctx.fill();
                }
            }
        }

        // 5. HoT
        if (agent.hotTimer > 0) {
            const icon = AssetManager.getStatusIcon('REGEN');
            ctx.drawImage(icon, 25, HEAD_Y, 24, 24);
            ctx.globalAlpha = 0.8;
            ctx.fillStyle = '#4ade80';
            ctx.font = 'bold 14px sans-serif';
            for(let i=0; i<3; i++) {
                const cycle = (t * 1.5 + i * 0.4) % 1;
                const yOff = -cycle * 40;
                const xOff = Math.cos(t * 3 + i) * 15;
                if (cycle < 1) ctx.fillText('+', xOff, -20 + yOff);
            }
        }

        ctx.restore();
    }

    // --- VFX METHODS ---

    private drawCastingVFX(ctx: CanvasRenderingContext2D, agent: Agent, t: number) {
        const skill = agent.skills[agent.castingSkillIdx];
        if (!skill) return;

        const progress = 1 - (agent.castTimer / skill.cast);
        const color = skill.color;

        ctx.save();
        if (agent.facing < 0) ctx.scale(-1, 1);

        // 1. Rising Energy Lines
        ctx.globalCompositeOperation = 'lighter';
        ctx.strokeStyle = color;
        ctx.lineWidth = 3; 
        const lineCount = 5 + Math.floor(progress * 8); 
        for(let i=0; i<lineCount; i++) {
            const h = (t * 150 + i * 40) % 90; 
            const alpha = 1 - (h / 90);
            const xOff = Math.sin(t * 15 + i) * 20 * (1-progress); 
            ctx.globalAlpha = alpha;
            ctx.beginPath(); ctx.moveTo(xOff, 15 - h); ctx.lineTo(xOff, 15 - h - 20); ctx.stroke();
        }

        // 2. Converging Rings
        if (progress > 0.2) {
            const ringScale = (1 - progress) * 2.5; 
            ctx.globalAlpha = progress;
            ctx.lineWidth = 2;
            ctx.beginPath(); ctx.ellipse(0, -20, 30 * ringScale, 10 * ringScale, 0, 0, Math.PI*2); ctx.stroke();

            ctx.save(); ctx.translate(0, -20); ctx.rotate(t * 10);
            ctx.beginPath(); ctx.ellipse(0, 0, 20 * ringScale, 5 * ringScale, 0, 0, Math.PI*2); ctx.stroke();
            ctx.restore();
        }

        // 3. Hand Glow
        ctx.globalAlpha = 0.4 + (Math.sin(t * 20) * 0.2) + (progress * 0.6);
        ctx.fillStyle = color;
        ctx.beginPath(); ctx.arc(0, -20, 10 + progress * 15, 0, Math.PI*2); ctx.fill();

        // 4. Final Flash
        if (progress > 0.9) {
            ctx.globalAlpha = (progress - 0.9) * 10;
            ctx.fillStyle = '#fff';
            ctx.beginPath(); ctx.arc(0, -20, 30, 0, Math.PI*2); ctx.fill();
        }

        ctx.restore();
    }

    private drawStatusIcons(ctx: CanvasRenderingContext2D, agent: Agent, t: number, drawX: number, drawY: number, scaleFactor: number) {
         if (agent.hp > 0 && agent.castingSkillIdx !== -1) {
            const skill = agent.skills[agent.castingSkillIdx];
            if (skill && skill.visual) {
                const icon = AssetManager.getSkillIcon(skill.visual, skill.color);
                ctx.save();
                // Move Higher relative to Body top (approx -120 local)
                ctx.translate(0, -110);
                const pulse = 1 + Math.sin(t * 10) * 0.1;
                ctx.scale(pulse, pulse);

                const glow = AssetManager.getGlowSprite(skill.color);
                ctx.globalCompositeOperation = 'lighter';
                ctx.globalAlpha = 0.6;
                ctx.drawImage(glow, -32, -32, 64, 64);
                ctx.globalCompositeOperation = 'source-over';
                ctx.globalAlpha = 1.0;

                ctx.drawImage(icon, -12, -12, 24, 24);

                // Cast Bar
                ctx.fillStyle = '#000';
                ctx.fillRect(-14, 20, 28, 5); 
                ctx.fillStyle = skill.color;
                const pct = Math.max(0, 1 - (agent.castTimer / skill.cast));
                ctx.fillRect(-14, 20, 28 * pct, 5);
                ctx.restore();
            }
        }
    }

    // =================================================================================
    // STYLE A: THE IMPERIAL LEGION
    // =================================================================================
    private drawImperialLegion(ctx: CanvasRenderingContext2D, agent: Agent, t: number, isSilhouette: boolean) {
        const silhouetteColor = '#3b82f6'; 
        let grad: any = silhouetteColor;
        let accent = silhouetteColor;

        if (!isSilhouette) {
            grad = ctx.createLinearGradient(-20, -40, 20, 40);
            grad.addColorStop(0, '#eff6ff'); 
            grad.addColorStop(0.5, '#93c5fd'); 
            grad.addColorStop(1, '#2563eb');   
            accent = '#3b82f6'; 
        }

        let breathe = (agent.hp > 0) ? Math.sin(t * 3) * 1 : 0;
        let thrustX = 0;
        let armRot = 0;

        if (agent.animState === AnimState.ATTACK && agent.hp > 0) {
            const progress = this.getCastProgress(agent);
            if (progress < 0.3) {
                thrustX = -5 * (progress / 0.3);
                armRot = -0.5 * (progress / 0.3);
            } else if (progress < 0.5) {
                thrustX = 15;
                armRot = 1.0;
            } else {
                thrustX = 15 * (1 - (progress - 0.5)/0.5);
                armRot = 1.0 * (1 - (progress - 0.5)/0.5);
            }
        }

        ctx.save();
        ctx.translate(thrustX, breathe);

        // 1. Back Arm
        ctx.save();
        ctx.translate(10, -10);
        ctx.rotate(armRot);
        this.drawImperialWeapon(ctx, agent.role, grad, accent, isSilhouette);
        ctx.restore();

        // 2. Body Shape
        if (isSilhouette) {
            ctx.strokeStyle = silhouetteColor;
            ctx.lineWidth = 2;
            ctx.fillStyle = 'transparent'; 
        } else {
            ctx.fillStyle = grad;
            ctx.strokeStyle = '#1e3a8a'; 
            ctx.lineWidth = 1.5;
        }

        ctx.beginPath();
        if (agent.role === Role.TANK) {
            ctx.moveTo(-18, -30); ctx.lineTo(18, -30);  
            ctx.lineTo(12, 15); ctx.lineTo(-12, 15);   
        } else if (agent.role === Role.MAGE || agent.role === Role.SUPPORT) {
            ctx.moveTo(-10, -25); ctx.lineTo(10, -25);  
            ctx.lineTo(16, 25); ctx.lineTo(-16, 25);
        } else if (agent.role === Role.RANGER) {
            ctx.moveTo(-8, -25); ctx.lineTo(8, -25);  
            ctx.lineTo(6, 15); ctx.lineTo(-6, 15);
        } else {
            ctx.moveTo(-12, -25); ctx.lineTo(12, -25);  
            ctx.lineTo(8, 15); ctx.lineTo(-8, 15);   
        }
        ctx.closePath();

        if (isSilhouette) {
            ctx.stroke();
        } else {
            ctx.fill();
            ctx.fillStyle = '#172554';
            ctx.stroke();
            // Rivets
            if (agent.role === Role.TANK) {
                [[-12,-25], [12,-25], [-8, 10], [8, 10]].forEach(([rx, ry]) => {
                    ctx.beginPath(); ctx.arc(rx, ry, 1, 0, Math.PI*2); ctx.fill();
                });
            }
        }

        // 3. Head
        ctx.save();
        ctx.translate(0, (agent.role === Role.TANK ? -35 : -32) + breathe * 0.5);
        if (isSilhouette) {
            ctx.fillStyle = 'transparent';
            ctx.strokeStyle = silhouetteColor;
        } else {
            ctx.fillStyle = grad;
        }

        ctx.beginPath();
        if (agent.role === Role.MAGE || agent.role === Role.SUPPORT) {
            ctx.moveTo(-10, 5); ctx.lineTo(-8, -15); ctx.lineTo(8, -15); ctx.lineTo(10, 5);
        } else if (agent.role === Role.TANK) {
            ctx.rect(-10, -14, 20, 16);
        } else {
            ctx.rect(-8, -12, 16, 14);
        }

        if (isSilhouette) ctx.stroke();
        else {
            ctx.fill(); ctx.stroke();
            ctx.fillStyle = '#fef08a'; ctx.fillRect(-6, -8, 12, 2);
        }
        ctx.restore();

        // 4. Front Arm / Shield
        ctx.save();
        ctx.translate(-12, -8);
        if (agent.role === Role.TANK) {
            ctx.rotate(armRot * 0.2);
            ctx.translate(-5, 5);

            if (isSilhouette) {
                ctx.fillStyle = 'transparent';
                ctx.strokeStyle = silhouetteColor;
            } else {
                ctx.fillStyle = '#2563eb'; ctx.strokeStyle = '#fcd34d'; 
            }
            ctx.lineWidth = 2;

            ctx.beginPath();
            ctx.moveTo(-10, -20); ctx.lineTo(10, -20);
            ctx.lineTo(10, 10); ctx.lineTo(0, 25); ctx.lineTo(-10, 10);
            ctx.closePath();

            if (isSilhouette) ctx.stroke();
            else { ctx.fill(); ctx.stroke(); }

        } else if (agent.role === Role.RANGER) {
            ctx.rotate(armRot);
            if (isSilhouette) {
                ctx.strokeStyle = silhouetteColor;
                ctx.strokeRect(-2, -2, 4, 15);
            } else {
                ctx.fillStyle = '#334155'; ctx.fillRect(-2, -2, 4, 15);
            }
        } else {
            ctx.beginPath(); ctx.arc(0, 0, 6, 0, Math.PI*2); 
            if (isSilhouette) {
                ctx.strokeStyle = silhouetteColor; ctx.stroke();
            } else {
                ctx.fillStyle = grad; ctx.fill();
            }
        }
        ctx.restore();

        ctx.restore(); 
    }

    private drawImperialWeapon(ctx: CanvasRenderingContext2D, role: Role, grad: any, accent: string, isSilhouette: boolean) {
        if (isSilhouette) {
            ctx.strokeStyle = '#3b82f6';
            ctx.lineWidth = 2;
        }

        if (role === Role.WARRIOR) {
            ctx.beginPath();
            ctx.moveTo(-2, 0); ctx.lineTo(2, 0);
            ctx.lineTo(2, -40); ctx.lineTo(0, -45); ctx.lineTo(-2, -40);
            if (isSilhouette) ctx.stroke();
            else {
                ctx.fillStyle = '#e2e8f0'; ctx.fill(); ctx.stroke();
                ctx.fillStyle = '#f59e0b'; ctx.fillRect(-6, 0, 12, 3);
            }
        } else if (role === Role.RANGER) {
            ctx.rotate(-Math.PI/2);
            if (isSilhouette) ctx.strokeRect(0, -3, 30, 4);
            else {
                ctx.fillStyle = '#475569'; ctx.fillRect(0, -3, 30, 4);
                ctx.fillStyle = '#78350f'; ctx.fillRect(-10, -2, 10, 6);
            }
        } else if (role === Role.MAGE || role === Role.SUPPORT) {
            if (isSilhouette) ctx.strokeRect(-2, -40, 4, 50);
            else {
                ctx.fillStyle = '#475569'; ctx.fillRect(-2, -40, 4, 50);
                const glow = AssetManager.getGlowSprite(accent);
                ctx.save(); ctx.globalCompositeOperation = 'lighter';
                ctx.drawImage(glow, -16, -55, 32, 32); ctx.restore();
                ctx.fillStyle = accent; ctx.fillRect(-6, -45, 12, 12);
            }
        }
    }

    // =================================================================================
    // STYLE B: THE ARCANE COVENANT
    // =================================================================================
    private drawArcaneCovenant(ctx: CanvasRenderingContext2D, agent: Agent, t: number, isSilhouette: boolean) {
        const silhouetteColor = '#ef4444'; 
        let bodyColor = isSilhouette ? 'transparent' : '#78350f'; 
        let glowColor = isSilhouette ? silhouetteColor : '#ef4444'; 
        let secondary = isSilhouette ? silhouetteColor : '#1c1917'; 

        const floatY = (agent.hp > 0) ? Math.sin(t * 2) * 3 : 0;
        let jitterX = 0; let jitterY = 0; let energyGather = 0;

        if (agent.animState === AnimState.ATTACK && agent.hp > 0) {
            const progress = this.getCastProgress(agent);
            if (progress < 0.6) {
                energyGather = progress;
                jitterX = (Math.random() - 0.5) * 3 * progress;
                jitterY = (Math.random() - 0.5) * 3 * progress;
            } else {
                const recoil = (progress - 0.6) / 0.4;
                jitterX = -5 * recoil; 
            }
        }

        ctx.save();
        ctx.translate(jitterX, floatY + jitterY);

        if (isSilhouette) {
            ctx.strokeStyle = silhouetteColor;
            ctx.lineWidth = 2;
            ctx.fillStyle = 'transparent';
        } else {
            ctx.fillStyle = bodyColor;
        }

        ctx.beginPath();
        if (agent.role === Role.TANK) {
             ctx.ellipse(0, -10, 18, 28, 0, 0, Math.PI*2);
        } else if (agent.role === Role.MAGE || agent.role === Role.SUPPORT) {
             ctx.moveTo(-10, -30); ctx.lineTo(10, -30);
             ctx.lineTo(14, 15); ctx.lineTo(0, 20); ctx.lineTo(-14, 15);
        } else {
             ctx.ellipse(0, -10, 12, 25, 0, 0, Math.PI*2);
        }

        if (isSilhouette) ctx.stroke();
        else ctx.fill();

        if ((agent.role === Role.MAGE || agent.role === Role.SUPPORT) && agent.hp > 0) {
            const orbGlow = AssetManager.getGlowSprite(glowColor);
            for(let i=0; i<3; i++) {
                const angle = t * 2 + (i * Math.PI * 2 / 3);
                const ox = Math.cos(angle) * (agent.role === Role.MAGE ? 20 : 15) * (1 - energyGather * 0.8);
                const oy = Math.sin(angle) * 5;
                ctx.save(); ctx.translate(ox, oy - 20);
                if(!isSilhouette) { 
                    ctx.globalCompositeOperation = 'lighter'; ctx.globalAlpha = 0.6;
                    ctx.drawImage(orbGlow, -10, -15, 20, 20);
                    ctx.globalCompositeOperation = 'source-over'; ctx.globalAlpha = 1.0;
                    ctx.fillStyle = glowColor;
                    ctx.beginPath(); ctx.moveTo(0, -5); ctx.lineTo(3, 0); ctx.lineTo(0, 5); ctx.lineTo(-3, 0); ctx.fill();
                } else {
                    ctx.strokeStyle = glowColor;
                    ctx.beginPath(); ctx.moveTo(0, -5); ctx.lineTo(3, 0); ctx.lineTo(0, 5); ctx.lineTo(-3, 0); ctx.stroke();
                }
                ctx.restore();
            }
        }

        if (!isSilhouette) {
            ctx.fillStyle = secondary;
            ctx.beginPath(); ctx.ellipse(0, -10, 6, 15, 0, 0, Math.PI*2); ctx.fill();
            const coreGlow = AssetManager.getGlowSprite(glowColor);
            ctx.save(); ctx.globalCompositeOperation = 'lighter';
            ctx.globalAlpha = 0.5 + Math.sin(t*10)*0.2 + energyGather * 0.5;
            ctx.drawImage(coreGlow, -10, -25, 20, 20); ctx.restore();
            ctx.fillStyle = glowColor;
            ctx.beginPath(); ctx.arc(0, -15, 4, 0, Math.PI*2); ctx.fill();
        }

        ctx.save();
        const headBob = (agent.hp > 0) ? Math.sin(t*3.5)*2 : 0;
        ctx.translate(0, (agent.role === Role.TANK ? -45 : -40) + headBob); 

        if (isSilhouette) {
            ctx.fillStyle = 'transparent'; ctx.strokeStyle = silhouetteColor;
        } else {
            ctx.fillStyle = '#f5f5f4';
        }

        ctx.beginPath();
        if (agent.role === Role.TANK) {
            ctx.moveTo(-12, -10); ctx.lineTo(12, -10); ctx.lineTo(0, 12);
        } else {
            ctx.moveTo(-6, -8); ctx.lineTo(6, -8); ctx.lineTo(0, 8);
        }

        if (isSilhouette) ctx.stroke();
        else {
            ctx.fill();
            ctx.fillStyle = glowColor;
            ctx.fillRect(-3, -4, 2, 2); ctx.fillRect(1, -4, 2, 2);
        }
        ctx.restore();

        ctx.save();
        ctx.translate(15, -15);
        if (agent.role === Role.WARRIOR || agent.role === Role.TANK) {
            const bladeAngle = (agent.hp > 0) ? Math.sin(t) * 0.2 + (agent.animState === AnimState.ATTACK ? -1 : 0) : 0;
            ctx.rotate(bladeAngle);
            if(!isSilhouette) {
                const wepGlow = AssetManager.getGlowSprite(glowColor);
                ctx.save(); ctx.globalCompositeOperation = 'lighter'; ctx.globalAlpha = 0.4;
                ctx.drawImage(wepGlow, -10, -20, 30, 30); ctx.restore();
            } else {
                ctx.strokeStyle = silhouetteColor;
            }

            if (agent.role === Role.TANK) {
                ctx.lineWidth = 3;
                if (!isSilhouette) ctx.strokeStyle = glowColor;
                ctx.beginPath(); ctx.arc(0, 0, 20, Math.PI/2, 3*Math.PI/2); ctx.stroke();
            } else {
                ctx.beginPath();
                ctx.moveTo(0, 10); ctx.lineTo(5, -30); ctx.lineTo(-2, -25);
                if (isSilhouette) ctx.stroke(); else { ctx.fillStyle = glowColor; ctx.fill(); }
            }
        } else if (agent.role === Role.RANGER) {
            ctx.translate(5, 0);
            ctx.rotate(agent.animState === AnimState.ATTACK ? -0.5 : 0);
            if (isSilhouette) {
                ctx.strokeStyle = silhouetteColor;
                ctx.beginPath(); ctx.moveTo(-5, -5); ctx.lineTo(15, 0); ctx.lineTo(-5, 5); ctx.stroke();
            } else {
                ctx.fillStyle = secondary;
                ctx.beginPath(); ctx.moveTo(-5, -5); ctx.lineTo(15, 0); ctx.lineTo(-5, 5); ctx.fill();
                const wepGlow = AssetManager.getGlowSprite(glowColor);
                ctx.save(); ctx.globalCompositeOperation = 'lighter'; ctx.globalAlpha = 0.4;
                ctx.drawImage(wepGlow, 0, -10, 20, 20); ctx.restore();
                ctx.fillStyle = glowColor; ctx.beginPath(); ctx.arc(10, 0, 3, 0, Math.PI*2); ctx.fill();
            }
        }
        ctx.restore();

        ctx.restore(); 
    }

    private getCastProgress(agent: Agent): number {
        if (agent.castingSkillIdx === -1) return 0;
        const skill = agent.skills[agent.castingSkillIdx];
        if (!skill) return 0;
        const raw = agent.castTimer / skill.cast;
        return Math.max(0, Math.min(1, 1 - raw)); 
    }
}

import { GameEngine } from "../game";
import { SCENE_DB } from "../../data/scenes";
import { HexUtils } from "../utils";
import { BLOCK_HEIGHT, MAX_TERRAIN_TIER } from "../../constants";

export class MapSystem {
    public mapKeys: Set<string> = new Set();
    private validHashes: Set<number> = new Set();
    public obstacles: Set<string> = new Set();
    public obstaclesHash: Set<number> = new Set();

    // Terrain Height Logic (Moved from GridSystem)
    private heightCache: Map<string, number> = new Map();

    constructor() {}

    // QUANTIZED HEIGHT (Tier System)
    public getTerrainHeight(q: number, r: number): number {
        const key = `${q},${r}`;
        if (this.heightCache.has(key)) return this.heightCache.get(key)!;

        // Deterministic Noise
        const n = Math.sin(q * 12.9898 + r * 78.233) * 43758.5453;
        const noise = Math.abs(n - Math.floor(n));

        // Logic:
        // Stepped Tiers: 0, 1, 2, 3...
        // Low frequency noise for smooth hills
        const n2 = Math.sin(q * 0.5 + r * 0.3) * 0.5 + 0.5; // Smooth large waves

        // Use Deep/Chaotic Terrain logic permanently
        let tier = Math.floor(noise * MAX_TERRAIN_TIER * 0.8 + n2 * 3);

        // Clamp
        tier = Math.max(0, Math.min(MAX_TERRAIN_TIER, tier));

        const h = tier * BLOCK_HEIGHT;
        this.heightCache.set(key, h);
        return h;
    }

    public randomizeEnvironment(engine: GameEngine) {
        engine.mapConfig.w = Math.floor(8 + Math.random() * 7);
        engine.mapConfig.h = Math.floor(6 + Math.random() * 5);
        engine.currentScene = SCENE_DB[Math.floor(Math.random() * SCENE_DB.length)];
        this.rebuildMap(engine);
    }

    public rebuildMap(engine: GameEngine) {
        this.mapKeys.clear();
        this.validHashes.clear();
        this.obstacles.clear();
        this.obstaclesHash.clear();
        this.heightCache.clear();

        // 1. Generate Raw Grid
        for (let q = 0; q < engine.mapConfig.w; q++) {
            for (let r = 0; r < engine.mapConfig.h; r++) {
                const h = HexUtils.offsetToAxial(q, r, engine.mapConfig);
                this.mapKeys.add(HexUtils.key(h));
                this.validHashes.add(HexUtils.hash(h.q, h.r));
            }
        }

        // 2. Prune Disconnected Islands (Rule: No Disconnected Tiles)
        this.pruneDisconnected(engine);

        engine.mapVersion++;
    }

    private pruneDisconnected(engine: GameEngine) {
        if (this.validHashes.size === 0) return;

        // Find a center-ish tile as the seed
        const centerQ = Math.floor(engine.mapConfig.w / 2);
        const centerR = Math.floor(engine.mapConfig.h / 2);
        const centerHex = HexUtils.offsetToAxial(centerQ, centerR, engine.mapConfig);

        // Find closest valid tile to ideal center
        let seed = HexUtils.hash(centerHex.q, centerHex.r);
        if (!this.validHashes.has(seed)) {
            // Fallback: pick first valid
            seed = this.validHashes.values().next().value;
        }

        // BFS to find all reachable tiles
        const reachable = new Set<number>();
        const queue: number[] = [seed];
        reachable.add(seed);

        // Standard BFS
        let head = 0;
        while(head < queue.length) {
            const currentHash = queue[head++];
            const current = HexUtils.unhash(currentHash);
            // Height Aware? For checking island connectivity, we treat blocks as connected if they exist
            // Vertical movement is a pathfinding problem, not a map validity problem.
            const neighbors = HexUtils.neighbors(current);

            for (const n of neighbors) {
                const nHash = HexUtils.hash(n.q, n.r);
                if (this.validHashes.has(nHash) && !reachable.has(nHash)) {
                    reachable.add(nHash);
                    queue.push(nHash);
                }
            }
        }

        // Remove anything NOT in reachable set
        const toRemove: number[] = [];
        this.validHashes.forEach(h => {
            if (!reachable.has(h)) toRemove.push(h);
        });

        toRemove.forEach(h => {
            this.validHashes.delete(h);
            const hex = HexUtils.unhash(h);
            this.mapKeys.delete(HexUtils.key(hex));
        });
    }

    public toggleObstacle(q: number, r: number, engine: GameEngine) {
        if (!this.isValid(q, r)) return;

        const k = HexUtils.key({q, r});
        const h = HexUtils.hash(q, r);

        if (this.obstaclesHash.has(h)) {
            this.obstacles.delete(k);
            this.obstaclesHash.delete(h);
        } else {
            if (!engine.getAgentAt(q, r)) {
                this.obstacles.add(k);
                this.obstaclesHash.add(h);
            }
        }
    }

    public isValid(q: number, r: number) { 
        return this.validHashes.has(HexUtils.hash(q, r));
    }

    public isValidHash(h: number) {
        return this.validHashes.has(h);
    }

    public hasObstacle(q: number, r: number) {
        return this.obstaclesHash.has(HexUtils.hash(q, r));
    }

    public hasObstacleHash(h: number) {
        return this.obstaclesHash.has(h);
    }

    public isBlocked(q: number, r: number, engine: GameEngine, ignoreId: string | null = null) { 
        const h = HexUtils.hash(q, r);
        if (this.obstaclesHash.has(h)) return true;

        const occupant = engine.agentMap.get(h);
        if (occupant) {
            if (occupant.id === ignoreId) return false;
            if (occupant.hp <= 0 || occupant.banished) return false;
            return true;
        }

        // Check moving agents destination
        return engine.agents.some(a => {
            if (a.id === ignoreId) return false;
            if (!a.isMoving || a.path.length === 0) return false;
            const dest = a.path[0];
            return dest.q === q && dest.r === r;
        });
    }
}

import React, { useEffect, useRef, useState } from 'react';
import { GameEngine, Agent } from '../engine/game';
import { GameRenderer } from '../engine/renderer';
import { HexUtils } from '../engine/utils';
import { Team, ToolType, Hex, Skill, GameEvent } from '../types';
import { BLOCK_HEIGHT, HEX_SIZE } from '../constants'; 

interface GameCanvasProps {
    engine: GameEngine;
    tool: ToolType;
    hpInput: number;
    selectedAgent: Agent | null; 
    hoveredSkill: Skill | null;
    isShowcaseMode: boolean; 
    onSelect: (a: Agent | null) => void;
    onWin: (team: Team) => void;
    winner: Team | null;
    rematch: () => void;
    transitionPhase: 'IDLE' | 'IN' | 'OUT';
}

const GameCanvas: React.FC<GameCanvasProps> = ({ engine, tool, hpInput, selectedAgent, hoveredSkill, isShowcaseMode, onSelect, onWin, winner, rematch, transitionPhase }) => {
    const canvasRef = useRef<HTMLCanvasElement>(null);
    const wrapperRef = useRef<HTMLDivElement>(null);
    const camera = useRef({ x: 0, y: 0, zoom: 1.0 }); // Adjusted default zoom
    const fpsRef = useRef(60);

    // Instantiate Renderer
    const rendererRef = useRef(new GameRenderer());
    const transitionStartTime = useRef(0);

    // Bridge for Synchronous Redraw (Fixes black flash on resize)
    const drawCurrentFrameRef = useRef<() => void>(() => {});

    // Handle Transition Phase Timing
    useEffect(() => {
        transitionStartTime.current = performance.now();
    }, [transitionPhase]);

    // Interaction State
    const draggedAgentRef = useRef<Agent | null>(null);
    const dragStartHex = useRef<{q: number, r: number} | null>(null);
    const isDraggingUnit = useRef(false);

    const isPanning = useRef(false);
    const pointerDownStart = useRef<{x: number, y: number} | null>(null);
    const pendingAction = useRef<boolean>(false); 

    // Track hovered hex for visual feedback
    const hoveredHexRef = useRef<Hex | null>(null);

    // Track selected agent for the render loop
    const selectedAgentRef = useRef<Agent | null>(selectedAgent);
    useEffect(() => {
        selectedAgentRef.current = selectedAgent;
    }, [selectedAgent]);

    // --- Camera Control Logic ---
    const centerCamera = () => {
        if (!canvasRef.current || !wrapperRef.current) return;

        // Ensure dims are fresh
        canvasRef.current.width = wrapperRef.current.clientWidth;
        canvasRef.current.height = wrapperRef.current.clientHeight;

        const cw = engine.mapConfig.w;
        const ch = engine.mapConfig.h;

        // Calculate grid visual center
        // Grid Top-Left is roughly (0,0) in Axial
        // Center is (w/2, h/2)
        const centerHex = { q: Math.floor(cw / 2), r: Math.floor(ch / 2) };
        const p = HexUtils.toPx(centerHex.q, centerHex.r, engine.mapConfig);

        // Visual adjustments
        // 1. Terrain Height offset: Blocks go "up" (negative Y), so the visual center of the top face is higher than p.y
        // We estimate average height to be around 2 blocks
        const verticalOffset = -BLOCK_HEIGHT * 2; 

        // Center Point Formula: WorldPos - (ScreenSize / Zoom) / 2
        camera.current.x = p.x - (canvasRef.current.width / camera.current.zoom) / 2;
        camera.current.y = p.y + verticalOffset - (canvasRef.current.height / camera.current.zoom) / 2;
    };

    // Auto-Center Triggers
    useEffect(() => {
        // Trigger centering when:
        // 1. Transition IN starts (New map generated in Showcase)
        // 2. Showcase Mode is entered toggled on
        // 3. Map dimensions change (manual settings)
        if (isShowcaseMode || transitionPhase === 'IN') {
            // Wait for CSS transition (300ms) to finish before centering
            const t = setTimeout(centerCamera, 350);
            return () => clearTimeout(t);
        } else if (!isShowcaseMode && transitionPhase === 'IDLE') {
             // Also recenter when exiting showcase mode
             const t = setTimeout(centerCamera, 350);
             return () => clearTimeout(t);
        }
    }, [isShowcaseMode, transitionPhase, engine.mapConfig.w, engine.mapConfig.h]);

    // Resize Observer for Fluid Layout
    useEffect(() => {
        if (!wrapperRef.current || !canvasRef.current) return;

        const resizeObserver = new ResizeObserver(() => {
            if (wrapperRef.current && canvasRef.current) {
                // Immediately update canvas resolution to match container
                canvasRef.current.width = wrapperRef.current.clientWidth;
                canvasRef.current.height = wrapperRef.current.clientHeight;

                // If map is empty (initial load), center it
                if (engine.agents.length === 0) {
                    centerCamera();
                }

                // CRITICAL FIX: Synchronous Redraw
                // Immediately draw the frame to prevent the canvas from appearing blank/black 
                // between the resize (clear) and the next animation frame.
                drawCurrentFrameRef.current();
            }
        });

        resizeObserver.observe(wrapperRef.current);

        // Force initial center
        centerCamera();

        return () => resizeObserver.disconnect();
    }, [engine]);

    // Render Loop
    useEffect(() => {
        let frameId: number;
        let lastTime = 0;
        let acc = 0;
        const targetFPS = 60;
        const step = 1000 / targetFPS;
        let frameCount = 0;
        let lastFpsTime = 0;

        // Define draw function that can be called externally via ref
        const drawFrame = () => {
            const ctx = canvasRef.current?.getContext('2d');
            if (ctx) {
                const highlight = draggedAgentRef.current || selectedAgentRef.current || null;
                rendererRef.current.draw(ctx, engine, camera.current, highlight, fpsRef.current, hoveredHexRef.current, hoveredSkill); 
            }
        };

        // Assign to ref for ResizeObserver
        drawCurrentFrameRef.current = drawFrame;

        const loop = (t: number) => {
            if (!lastTime) lastTime = t;
            const dt = t - lastTime;
            lastTime = t;

            // Measure FPS
            frameCount++;
            if (t - lastFpsTime >= 1000) {
                fpsRef.current = frameCount;
                frameCount = 0;
                lastFpsTime = t;
            }

            // Logic Step
            if (engine.isRunning) {
                acc += dt;
                if (acc > 200) acc = 200;

                const frameEvents: GameEvent[] = [];

                while (acc >= step) {
                    const sdt = (step / 1000) * engine.timeScale;
                    engine.tick(sdt);
                    engine.battleTime += sdt;
                    acc -= step;

                    // Collect events from this tick to avoid dropping them
                    // or processing them multiple times in the render loop
                    frameEvents.push(...engine.events);
                }

                // Only process events if we actually ticked logic this frame
                if (frameEvents.length > 0) {
                    rendererRef.current.processEventsWithEngine(frameEvents, engine);
                }
            }

            // Visual Update
            rendererRef.current.update(dt / 1000, engine);

            // Handle Transition Animation Progress
            if (transitionPhase !== 'IDLE') {
                const elapsed = (performance.now() - transitionStartTime.current) / 1000;
                // Transition usually lasts 1.5s total logic in App, let's map 0-1 over 1.2s for visual
                const progress = Math.min(1.0, elapsed / 1.2);
                rendererRef.current.setTransition(progress, transitionPhase);
            } else {
                rendererRef.current.setTransition(0, 'IDLE');
            }

            drawFrame();
            frameId = requestAnimationFrame(loop);
        };

        engine.onWin = (team) => {
            onWin(team);
        };

        frameId = requestAnimationFrame(loop);
        return () => cancelAnimationFrame(frameId);
    }, [engine, onWin, hoveredSkill, transitionPhase]);

    // Input Handling
    useEffect(() => {
        const cvs = canvasRef.current;
        if (!cvs) return;

        const getHexFromEvent = (e: MouseEvent) => {
            const rect = cvs.getBoundingClientRect();
            const mouseX = e.clientX - rect.left;
            const mouseY = e.clientY - rect.top;

            // Use renderer's accurate 3D picking logic
            const hex = rendererRef.current.getHexAtScreenPoint(mouseX, mouseY, camera.current, engine);
            if (hex) return hex;

            // Picking fallback in 3D is tricky, we rely on the grid system's robustness
            return HexUtils.fromPx(
                mouseX / camera.current.zoom + camera.current.x,
                mouseY / camera.current.zoom + camera.current.y,
                engine.mapConfig
            );
        };

        const getWorldPosFromEvent = (e: MouseEvent) => {
            const rect = cvs.getBoundingClientRect();
            const mouseX = e.clientX - rect.left;
            const mouseY = e.clientY - rect.top;
            const wx = mouseX / camera.current.zoom + camera.current.x;

            // Get height at this position (approximate)
            const hex = rendererRef.current.getHexAtScreenPoint(mouseX, mouseY, camera.current, engine);
            let h = BLOCK_HEIGHT + 6;
            if (hex) h = rendererRef.current.getTerrainHeight(hex.q, hex.r);

            const wy = mouseY / camera.current.zoom + camera.current.y + h;
            return { x: wx, y: wy };
        };

        const handleMouseDown = (e: MouseEvent) => {
            pointerDownStart.current = { x: e.clientX, y: e.clientY };

            if (e.button === 2) {
                isPanning.current = true;
                pendingAction.current = false;
                return;
            }

            const h = getHexFromEvent(e);
            const agent = engine.getAgentAt(h.q, h.r);

            if (agent) {
                pendingAction.current = false;

                if (!engine.isRunning && tool === ToolType.DELETE) {
                    engine.removeAgent(h.q, h.r);
                    onSelect(null);
                    return;
                }

                onSelect(agent);

                if (!engine.isRunning) {
                    draggedAgentRef.current = agent;
                    dragStartHex.current = { q: agent.q, r: agent.r };
                    isDraggingUnit.current = true;
                }
                return;
            }

            pendingAction.current = true;
            isPanning.current = false;
        };

        const handleMouseMove = (e: MouseEvent) => {
            const h = getHexFromEvent(e);
            if (engine.isValid(h.q, h.r)) {
                hoveredHexRef.current = h;
            } else {
                hoveredHexRef.current = null;
            }

            if (isPanning.current) {
                camera.current.x -= e.movementX / camera.current.zoom;
                camera.current.y -= e.movementY / camera.current.zoom;
                return;
            }

            if (isDraggingUnit.current && draggedAgentRef.current) {
                const wPos = getWorldPosFromEvent(e);
                draggedAgentRef.current.px = wPos.x;
                draggedAgentRef.current.py = wPos.y;
                return;
            }

            if (pendingAction.current && pointerDownStart.current) {
                const dx = e.clientX - pointerDownStart.current.x;
                const dy = e.clientY - pointerDownStart.current.y;
                const dist = Math.sqrt(dx*dx + dy*dy);

                if (dist > 5) {
                    pendingAction.current = false;
                    isPanning.current = true;
                    camera.current.x -= e.movementX / camera.current.zoom;
                    camera.current.y -= e.movementY / camera.current.zoom;
                }
            }
        };

        const handleMouseUp = (e: MouseEvent) => {
            if (isPanning.current) {
                isPanning.current = false;
                pointerDownStart.current = null;
                return;
            }

            if (isDraggingUnit.current && draggedAgentRef.current) {
                const h = getHexFromEvent(e);
                const agent = draggedAgentRef.current;
                const isValidHex = engine.isValid(h.q, h.r);
                const isObstacle = engine.obstacles.has(HexUtils.key(h));
                const occupant = engine.getAgentAt(h.q, h.r);
                const isOccupiedByOther = occupant && occupant !== agent;

                if (isValidHex && !isObstacle && !isOccupiedByOther) {
                    agent.q = h.q;
                    agent.r = h.r;
                    const p = HexUtils.toPx(h.q, h.r, engine.mapConfig);
                    agent.px = p.x;
                    agent.py = p.y;
                } else {
                    if (dragStartHex.current) {
                        agent.q = dragStartHex.current.q;
                        agent.r = dragStartHex.current.r;
                        const p = HexUtils.toPx(agent.q, agent.r, engine.mapConfig);
                        agent.px = p.x;
                        agent.py = p.y;
                    }
                }

                draggedAgentRef.current = null;
                dragStartHex.current = null;
                isDraggingUnit.current = false;
                onSelect(agent);
                return;
            }

            if (pendingAction.current) {
                pendingAction.current = false;
                const h = getHexFromEvent(e);

                if (tool === ToolType.SELECT) {
                    onSelect(null);
                } else if (!engine.isRunning && winner === null) {
                    if (tool === ToolType.ADD_BLUE) engine.addAgent(Team.BLUE, h.q, h.r, hpInput);
                    else if (tool === ToolType.ADD_RED) engine.addAgent(Team.RED, h.q, h.r, hpInput);
                    else if (tool === ToolType.OBSTACLE) engine.toggleObstacle(h.q, h.r);
                    else if (tool === ToolType.DELETE) {
                        if (engine.obstacles.has(HexUtils.key(h))) {
                            engine.toggleObstacle(h.q, h.r);
                        }
                        onSelect(null);
                    }
                }
            }

            pointerDownStart.current = null;
        };

        const handleWheel = (e: WheelEvent) => {
            e.preventDefault();
            const delta = e.deltaY > 0 ? -0.1 : 0.1;
            camera.current.zoom = Math.max(0.5, Math.min(3.0, camera.current.zoom + delta));
        };

        const handleContextMenu = (e: MouseEvent) => e.preventDefault();

        cvs.addEventListener('mousedown', handleMouseDown);
        window.addEventListener('mousemove', handleMouseMove);
        window.addEventListener('mouseup', handleMouseUp);
        cvs.addEventListener('wheel', handleWheel, { passive: false });
        cvs.addEventListener('contextmenu', handleContextMenu);

        return () => {
            cvs.removeEventListener('mousedown', handleMouseDown);
            window.removeEventListener('mousemove', handleMouseMove);
            window.removeEventListener('mouseup', handleMouseUp);
            cvs.removeEventListener('wheel', handleWheel);
            cvs.removeEventListener('contextmenu', handleContextMenu);
        };
    }, [engine, tool, hpInput, onSelect, winner]);

    return (
        <div ref={wrapperRef} className="flex-1 overflow-hidden relative bg-slate-950 border-r border-slate-700">
            <canvas 
                ref={canvasRef} 
                className={`block shadow-inner ${tool === ToolType.SELECT ? 'cursor-default' : 'cursor-crosshair'}`}
                style={{ backgroundColor: engine.currentScene.background }} 
            />

            {/* STANDARD MODE VICTORY SCREEN */}
            {winner !== null && !isShowcaseMode && (
                <div className="absolute inset-0 flex items-center justify-center bg-black/70 z-50">
                    <div className="text-center p-8 bg-slate-900 rounded-lg border border-slate-700 shadow-2xl animate-bounce-in">
                        <h2 className={`text-4xl font-bold mb-4 font-serif tracking-widest ${winner === Team.BLUE ? 'text-blue-400' : 'text-red-400'}`}>
                            {winner === Team.BLUE ? 'VICTORY' : 'DEFEAT'}
                        </h2>
                        <button onClick={rematch} className="bg-slate-700 hover:bg-slate-600 text-white font-bold py-2 px-6 rounded border border-slate-500">REMATCH</button>
                    </div>
                </div>
            )}
        </div>
    );
};

export default GameCanvas;

import React, { useEffect, useRef, useState, useCallback } from 'react';
import { GameEngine, Agent } from './engine/game';
import GameCanvas from './components/GameCanvas';
import InspectorPanel from './components/InspectorPanel';
import { ToolType, Team, Skill } from './types';
import { HexUtils } from './engine/utils';

function App() {
  const engineRef = useRef(new GameEngine());

  // App States
  const [isShowcaseMode, setIsShowcaseMode] = useState(true); // Default to Showcase
  const [isPlaying, setIsPlaying] = useState(false);
  const [unitCount, setUnitCount] = useState(0);
  const [tool, setTool] = useState<ToolType>(ToolType.SELECT);
  const [selectedAgent, setSelectedAgent] = useState<Agent | null>(null);
  const [hoveredSkill, setHoveredSkill] = useState<Skill | null>(null);
  const [hpInput, setHpInput] = useState(600); 
  const [mapW, setMapW] = useState(12);
  const [mapH, setMapH] = useState(8);
  const [timeScale, setTimeScale] = useState(1.0);
  const [showMobileInspector, setShowMobileInspector] = useState(false);
  const [showMapSettings, setShowMapSettings] = useState(false);
  const [winner, setWinner] = useState<Team | null>(null);

  // UI Warnings
  const [showFactionWarning, setShowFactionWarning] = useState(false);

  // Transition Phase for Showcase Rebuild Effect
  const [transitionPhase, setTransitionPhase] = useState<'IDLE' | 'IN' | 'OUT'>('IDLE');

  // Layout Resizing State
  const [sidebarWidth, setSidebarWidth] = useState(450);
  const isResizing = useRef(false);

  // --- Showcase Logic Refactored ---

  // 1. Prepare Environment (Map & Scene only, No Units)
  const setupShowcaseMap = useCallback(() => {
      const engine = engineRef.current;
      engine.stop();
      setWinner(null);
      setSelectedAgent(null);

      // Randomize Map Dimensions & Scene
      engine.mapConfig.w = Math.floor(10 + Math.random() * 4);
      engine.mapConfig.h = Math.floor(8 + Math.random() * 4);
      engine.clear(false); // Clears units, randomizes scene, rebuilds map keys
  }, []);

  // 2. Spawn Units (Assumes map is ready)
  const spawnShowcaseUnits = useCallback(() => {
      const engine = engineRef.current;

      const validHexes = (Array.from(engine.mapKeys) as string[]).map(k => {
          const [q, r] = k.split(',').map(Number);
          return {q, r};
      });

      // Shuffle Hexes
      for (let i = validHexes.length - 1; i > 0; i--) {
          const j = Math.floor(Math.random() * (i + 1));
          [validHexes[i], validHexes[j]] = [validHexes[j], validHexes[i]];
      }

      let spawnIndex = 0;
      const spawn = (team: Team) => {
          if (spawnIndex < validHexes.length) {
              const h = validHexes[spawnIndex++];
              const hp = 500 + Math.floor(Math.random() * 400); 
              engine.addAgent(team, h.q, h.r, hp);
          }
      };

      for(let i=0; i<5; i++) spawn(Team.BLUE);
      for(let i=0; i<5; i++) spawn(Team.RED);

      engine.play();
      setIsPlaying(true);
  }, []);

  // Initial Load (Combines both)
  const startShowcaseMatch = useCallback(() => {
      setupShowcaseMap();
      spawnShowcaseUnits();
  }, [setupShowcaseMap, spawnShowcaseUnits]);

  // Initial Load Trigger
  useEffect(() => {
      startShowcaseMatch();
  }, [startShowcaseMatch]);

  const enterManualMode = () => {
      setIsShowcaseMode(false);
      engineRef.current.stop();
      setIsPlaying(false);
      setWinner(null);
      engineRef.current.clear(true); 
      engineRef.current.agents = [];
      setUnitCount(0);
  };

  // --- Existing Logic ---

  useEffect(() => {
    const interval = setInterval(() => {
        setUnitCount(engineRef.current.agents.length);
    }, 500); 
    return () => clearInterval(interval);
  }, []);

  useEffect(() => {
      engineRef.current.timeScale = timeScale;
  }, [timeScale]);

  const startResizing = useCallback(() => {
      isResizing.current = true;
      document.body.style.cursor = 'col-resize';
      document.body.style.userSelect = 'none';
  }, []);

  const stopResizing = useCallback(() => {
      isResizing.current = false;
      document.body.style.cursor = '';
      document.body.style.userSelect = '';
  }, []);

  const resize = useCallback((e: MouseEvent) => {
      if (isResizing.current) {
          const newWidth = window.innerWidth - e.clientX;
          if (newWidth > 300 && newWidth < window.innerWidth * 0.6) {
              setSidebarWidth(newWidth);
          }
      }
  }, []);

  useEffect(() => {
      window.addEventListener('mousemove', resize);
      window.addEventListener('mouseup', stopResizing);
      return () => {
          window.removeEventListener('mousemove', resize);
          window.removeEventListener('mouseup', stopResizing);
      };
  }, [resize, stopResizing]);

  const togglePlay = useCallback(() => {
    if (winner !== null) return;

    if (isPlaying) {
        engineRef.current.stop();
        setIsPlaying(false);
    } else {
        // Validation: Check if both teams have units
        const hasBlue = engineRef.current.agents.some(a => a.team === Team.BLUE);
        const hasRed = engineRef.current.agents.some(a => a.team === Team.RED);

        if (!hasBlue || !hasRed) {
            setShowFactionWarning(true);
            // Auto hide after 2 seconds
            setTimeout(() => setShowFactionWarning(false), 2500);
            return;
        }

        engineRef.current.play();
        setIsPlaying(true);
        setTool(ToolType.SELECT);
    }
  }, [isPlaying, winner]);

  const handleRestart = useCallback(() => {
    if (winner !== null) return;
    engineRef.current.restart();
    setIsPlaying(true);
    setTool(ToolType.SELECT);
  }, [winner]);

  const handleClear = useCallback(() => {
    engineRef.current.clear(); 
    setIsPlaying(false);
    setSelectedAgent(null);
    setWinner(null);
    setHoveredSkill(null);
  }, []);

  const handleSelectAgent = useCallback((a: Agent | null) => {
      if (isShowcaseMode) return; // Disable selection in showcase
      setSelectedAgent(a);
      if (!a) setHoveredSkill(null);
      if (a) setShowMobileInspector(true);
  }, [isShowcaseMode]);

  const updateMap = useCallback(() => {
      engineRef.current.mapConfig.w = mapW;
      engineRef.current.mapConfig.h = mapH;
      engineRef.current.clear(true);
      setSelectedAgent(null);
      setWinner(null);
      setShowMapSettings(false);
  }, [mapW, mapH]);

  const onWin = (team: Team) => {
    setWinner(team);

    if (isShowcaseMode) {
        // Auto-Restart sequence with Map Rebuild Effect
        setTimeout(() => {
            // 1. Trigger "Map Drop" animation (Exit Phase)
            setTransitionPhase('OUT');

            // Requirement 1: Clear units immediately when grid exits
            // We manually empty the arrays so the map falls empty
            engineRef.current.agents = [];
            engineRef.current.projectiles = [];

            // 2. Wait for drop animation (1.5s)
            setTimeout(() => {
                // 3. Prepare NEW Map (Hidden) & Start Rise (Enter Phase)
                setupShowcaseMap(); 
                setTransitionPhase('IN'); 

                // 4. Wait for rise animation to mostly finish (1.2s)
                setTimeout(() => {
                    setTransitionPhase('IDLE');

                    // Requirement 2: Spawn units AFTER grid is in
                    spawnShowcaseUnits(); 
                }, 1200);
            }, 1500);
        }, 2000);
    } else {
        setIsPlaying(false);
    }
  };

