                    </button>
                </div>
            </div>
        </div>

        {/* Resizer Handle: Hidden in Showcase */}
        {!isShowcaseMode && (
            <div 
                className="hidden md:flex w-2 bg-slate-950 hover:bg-blue-600 cursor-col-resize items-center justify-center shrink-0 transition-colors z-30"
                onMouseDown={startResizing}
