import { GameEngine, Agent } from "./game";
import { Hex, Team, GameEvent, Skill } from "../types";
import { GridSystem, RenderableItem } from "./systems/grid";
import { UnitRenderSystem } from "./systems/unit";
import { VFXSystem } from "./systems/vfx";
import { HUDSystem } from "./systems/hud";

export interface Camera {
    x: number;
    y: number;
    zoom: number;
}

export class GameRenderer {
    private grid: GridSystem;
    private unit: UnitRenderSystem;
    private vfx: VFXSystem;
    private hud: HUDSystem;

    private globalTime: number = 0;
    private transitionT: number = 0;
    private transitionPhase: 'IN' | 'OUT' | 'IDLE' = 'IDLE';
    private holoGlitchTimer: number = 0;

    // Flashes on grid tiles (e.g. from clicks or effects)
    private gridFlashes: { q: number; r: number; color: string; life: number }[] = [];

    constructor() {
        this.grid = new GridSystem();
        this.unit = new UnitRenderSystem();
        this.vfx = new VFXSystem();
        this.hud = new HUDSystem();
    }

    public update(dt: number, engine: GameEngine) {
        this.globalTime += dt;
        this.vfx.update(dt, this.globalTime, engine.currentScene.ambientType);
        this.hud.update(dt);

        if (this.holoGlitchTimer > 0) this.holoGlitchTimer -= dt;

        // Update grid flashes
        for (let i = this.gridFlashes.length - 1; i >= 0; i--) {
            this.gridFlashes[i].life -= dt * 2.0;
            if (this.gridFlashes[i].life <= 0) this.gridFlashes.splice(i, 1);
        }
    }

    public processEventsWithEngine(events: GameEvent[], engine: GameEngine) {
        events.forEach(e => {
            if (e.type === 'DAMAGE') {
                this.hud.addFloatingText(e.pos.x, e.pos.y - 60, e.value!.toString(), e.color || '#fff', 20, 'DAMAGE');
            } else if (e.type === 'HEAL') {
                this.hud.addFloatingText(e.pos.x, e.pos.y - 60, `+${e.value}`, e.color || '#fff', 20, 'HEAL');
            } else if (e.type === 'CC_APPLIED') {
                this.hud.addFloatingText(e.pos.x, e.pos.y - 80, e.text || 'CC', e.color || '#fff', 24, 'CC');
            } else if (e.type === 'CAST_START') {
                 // handled in animations usually, but could add shout
                 if (e.skill && e.skill.tag === 'ULT') {
                     this.hud.addFloatingText(e.pos.x, e.pos.y - 100, e.skill.name, e.skill.color, 32, 'SHOUT', true);
                     this.vfx.spawnDomainExpansion(e.pos.x, e.pos.y, e.skill.color, 1.0);
                 }
            } else if (e.type === 'PROJECTILE_HIT') {
                if (e.skill?.type === 'AOE') {
                    this.vfx.spawnShockwave(e.pos.x, e.pos.y, e.skill.color, 0.5);
                    this.vfx.addDecal(e.pos.x, e.pos.y, '#000');
                } else {
                    this.vfx.spawnExplosion(e.pos.x, e.pos.y, 30, 5, e.skill?.color || '#fff', 1.0, 0.5, 'SPARK');
                }
            } else if (e.type === 'DEATH') {
                if (e.sourceId) {
                    // Usually engine handles removal logic, but we have pos in event
                    this.vfx.spawnUnitShatter(e.pos.x, e.pos.y, e.team || Team.BLUE);
                }
            } else if (e.type === 'SPAWN') {
                this.vfx.spawnTeleport(e.pos.x, e.pos.y, e.color || '#fff');
            }
        });
    }

    public setTransition(t: number, phase: 'IN' | 'OUT' | 'IDLE') {
        this.transitionT = t;
        this.transitionPhase = phase;
    }

    public getHexAtScreenPoint(mx: number, my: number, camera: Camera, engine: GameEngine): Hex | null {
        return this.grid.getHexAtScreenPoint(mx, my, camera, engine);
    }

    public getTerrainHeight(q: number, r: number, engine: GameEngine): number {
        return this.grid.getTerrainHeight(q, r, engine);
    }

    public draw(
        ctx: CanvasRenderingContext2D, 
        engine: GameEngine, 
        camera: Camera, 
        highlightAgent: Agent | null, 
        fps: number,
        hoveredHex: Hex | null,
        hoveredSkill: Skill | null
    ) {
        ctx.save();

        // 1. Clear Background
        ctx.fillStyle = engine.currentScene.background;
        ctx.fillRect(0, 0, ctx.canvas.width, ctx.canvas.height);

        // 2. Camera Transform
        ctx.translate(ctx.canvas.width / 2, ctx.canvas.height / 2);
        ctx.scale(camera.zoom, camera.zoom);
        ctx.translate(-camera.x, -camera.y);

        // 3. Render Layers
        const renderList: RenderableItem[] = [];

        // Grid & Terrain
        renderList.push(...this.grid.collectRenderables(
            engine, 
            hoveredHex, 
            hoveredSkill, 
            highlightAgent, 
            this.gridFlashes,
            engine.projectiles,
            this.transitionT,
            this.transitionPhase,
            this.globalTime
        ));

        // Units
        renderList.push(...this.unit.collectRenderables(
            engine.agents, 
            (q, r) => this.grid.getTerrainHeight(q, r, engine), 
            this.globalTime, 
            highlightAgent,
            engine.mapConfig
        ));

        // VFX (Bottom/Ground) & Projectiles
        renderList.push(...this.vfx.collectRenderables(
            engine, 
            (q, r) => this.grid.getTerrainHeight(q, r, engine), 
            engine.mapConfig,
            this.transitionT,
            this.transitionPhase
        ));

        // Sort by Y then Z (Z-buffering painter's algorithm)
        renderList.sort((a, b) => {
            if (Math.abs(a.y - b.y) > 1) return a.y - b.y;
            return a.z - b.z;
        });

        // DRAW ALL SORTED ITEMS
        renderList.forEach(item => item.draw(ctx));

        // VFX (Top Layer Particles) - Drawn after sorting to overlay correctly
        this.vfx.drawTopLayerParticles(ctx, engine.currentScene, engine.mapConfig, this.transitionT, this.transitionPhase);

        // Silhouettes for occluded units
        const occludedUnits = this.grid.getOccludedAgents(engine);
        occludedUnits.forEach(u => {
             // Only draw if not highlighted (highlight is drawn normally)
             if (u !== highlightAgent) {
                 this.unit.drawSilhouette(
                     ctx, 
                     u, 
                     (q, r) => this.grid.getTerrainHeight(q, r, engine), 
                     this.globalTime, 
                     engine.mapConfig
                 );
             }
        });

        // HUD (World Space - HP Bars, Floating Text)
        this.hud.draw(ctx, engine.agents, (q, r) => this.grid.getTerrainHeight(q, r, engine), engine.mapConfig);

        ctx.restore();

        // 4. Screen Space HUD
        // Selected Unit Hologram
        if (highlightAgent) {
            this.drawHolographicHUD(ctx, highlightAgent, ctx.canvas.width, ctx.canvas.height, camera);
        }

        // FPS
        ctx.fillStyle = '#fff';
        ctx.font = '10px monospace';
        ctx.fillText(`FPS: ${fps}`, 10, 10);
    }

    // =========================================================================================
    // 📺 HOLOGRAPHIC TACTICAL HUD (Diegetic UI)
    // =========================================================================================

    private drawHolographicHUD(ctx: CanvasRenderingContext2D, agent: Agent, w: number, h: number, cam: Camera) {
        // Position: Top Right, floating
        const hudX = w - 280;
        const hudY = 80;
        const width = 240;
        const height = 160;

        ctx.save();

        // --- 1. Glitch Effect ---
        let gx = 0, gy = 0;
        if (this.holoGlitchTimer > 0) {
            gx = (Math.random() - 0.5) * 20;
            gy = (Math.random() - 0.5) * 10;
            if (Math.random() > 0.7) { ctx.restore(); return; } // Flicker off
        }

        // --- 2. Perspective Transform ---
        // Flattened to align with new 45-degree isometric camera (No Skew)
        ctx.transform(1, 0, 0, 1, hudX + gx, hudY + gy);

        // --- 3. Glass Background ---
        const bgGrad = ctx.createLinearGradient(0, 0, width, height);
        const baseColor = agent.team === Team.BLUE ? '#06b6d4' : '#f97316'; // Cyan vs Orange

        bgGrad.addColorStop(0, `${baseColor}40`); // 25% opacity
        bgGrad.addColorStop(1, `${baseColor}05`); // 2% opacity

        ctx.fillStyle = bgGrad;
        ctx.fillRect(0, 0, width, height);

        // Grid Lines
        ctx.strokeStyle = `${baseColor}30`;
        ctx.lineWidth = 1;
        ctx.beginPath();
        for(let i=0; i<=width; i+=20) { ctx.moveTo(i, 0); ctx.lineTo(i, height); }
        for(let i=0; i<=height; i+=20) { ctx.moveTo(0, i); ctx.lineTo(width, i); }
        ctx.stroke();

        // Border corners
        ctx.strokeStyle = baseColor;
        ctx.lineWidth = 2;
        const len = 15;
        ctx.beginPath();
        ctx.moveTo(0, len); ctx.lineTo(0, 0); ctx.lineTo(len, 0); // TL
        ctx.moveTo(width-len, 0); ctx.lineTo(width, 0); ctx.lineTo(width, len); // TR
        ctx.moveTo(width, height-len); ctx.lineTo(width, height); ctx.lineTo(width-len, height); // BR
        ctx.moveTo(len, height); ctx.lineTo(0, height); ctx.lineTo(0, height-len); // BL
        ctx.stroke();

        // --- 4. Content: Logic Visualization ---

        // Header
        ctx.fillStyle = baseColor;
        ctx.font = 'bold 12px monospace';
        ctx.fillText(`TARGET: ${agent.id}`, 10, 20);
        ctx.font = '10px monospace';
        ctx.fillStyle = '#fff';
        ctx.fillText(`STATUS: ${agent.btStatus.toUpperCase()}`, 10, 35);

        // Logic Graph
        // [SCAN] -> [DECISION] -> [ACTION]
        const nodes = [
            { x: 30, y: 80, label: 'SCAN', active: true }, // Always active
            { x: 100, y: 80, label: 'THINK', active: agent.btStatus !== '待機' },
            { x: 170, y: 80, label: 'ACT', active: agent.castingSkillIdx !== -1 || agent.isMoving }
        ];

        // Draw Connections
        ctx.strokeStyle = `${baseColor}60`;
        ctx.lineWidth = 2;
        ctx.beginPath();
        ctx.moveTo(nodes[0].x, nodes[0].y);
        ctx.lineTo(nodes[2].x, nodes[2].y);
        ctx.stroke();

        // Draw Active Flow (Pulse)
        const flowTime = (this.globalTime * 3) % 1; 
        const flowX = 30 + flowTime * 140;
        ctx.strokeStyle = '#fff';
        ctx.lineWidth = 2;
        ctx.beginPath();
        ctx.moveTo(flowX, 80);
        ctx.lineTo(flowX + 15, 80);
        ctx.stroke();

        // Draw Nodes
        nodes.forEach(n => {
            const isActive = n.active;

            // Outer Ring
            ctx.strokeStyle = isActive ? baseColor : `${baseColor}40`;
            ctx.fillStyle = `${baseColor}10`;
            ctx.beginPath(); ctx.arc(n.x, n.y, 10, 0, Math.PI*2); 
            ctx.fill(); ctx.stroke();

            // Inner Dot
            if (isActive) {
                ctx.fillStyle = '#fff';
                ctx.shadowColor = baseColor; ctx.shadowBlur = 10;
                ctx.beginPath(); ctx.arc(n.x, n.y, 4, 0, Math.PI*2); ctx.fill();
                ctx.shadowBlur = 0;
            }

            // Label
            ctx.fillStyle = isActive ? '#fff' : `${baseColor}60`;
            ctx.textAlign = 'center';
            ctx.fillText(n.label, n.x, n.y + 22);
        });

        // Special Alert: ULTIMATE
        if (agent.castingSkillIdx !== -1 && agent.skills[agent.castingSkillIdx]?.tag === 'ULT') {
            ctx.fillStyle = '#ef4444';
            ctx.globalAlpha = 0.5 + Math.sin(this.globalTime * 20) * 0.5;
            ctx.fillRect(0, 130, width, 20);
            ctx.fillStyle = '#fff';
            ctx.globalAlpha = 1.0;
            ctx.font = 'bold 12px monospace';
            ctx.textAlign = 'center';
            ctx.fillText('WARNING: ULTIMATE DETECTED', width/2, 144);
        } else if (agent.hp < agent.maxHp * 0.3) {
            ctx.fillStyle = '#ef4444';
            ctx.font = 'bold 10px monospace';
            ctx.fillText('CRITICAL CONDITION', width - 70, 20);
        }

        // --- 5. Tether Line to Unit ---
        ctx.beginPath();
        ctx.moveTo(10, height);
        ctx.lineTo(10, height + 20);
        ctx.strokeStyle = `${baseColor}40`;
        ctx.setLineDash([2, 4]);
        ctx.stroke();
        ctx.setLineDash([]);

        ctx.restore();
    }
}

