// engine/renderer.ts -> processEventsWithEngine

// ... (前略)

events.forEach(event => {
    // [優化] 優先嘗試透過 targetId 獲取精確座標
    let targetAgent = null;
    if (event.targetId) {
        targetAgent = engine.agents.find(a => a.id === event.targetId);
    }

    // 計算精確的基準點
    let baseX = event.pos.x;
    let baseY = event.pos.y;

    if (targetAgent) {
        // 如果有目標單位，直接鎖定它的「視覺頭頂」
        const h = this.grid.getTerrainHeight(targetAgent.q, targetAgent.r);
        // 注意：這裡直接使用 agent.py (已含旋轉) - 地形高度 - 單位身高(約50px)
        baseX = targetAgent.px;
        baseY = targetAgent.py - h - 50; 
    } else {
        // 地板技能 (AOE) 或是無目標事件，才使用反推
        const hex = HexUtils.fromPx(event.pos.x, event.pos.y, engine.mapConfig);
        const terrainHeight = this.grid.getTerrainHeight(hex.q, hex.r);
        baseY = event.pos.y - terrainHeight - 40;
    }

    // ... (後續文字顏色判斷邏輯保持不變) ...

    if (text) {
        // 傳入修正後的 baseX, baseY
        this.hud.addFloatingText(baseX + xOffset, baseY, text, color, size, type);
    }

    // ... (後續保持不變)
});

