private drawIsoBlock(
    ctx: CanvasRenderingContext2D, 
    x: number, y: number, 
    size: number, height: number, 
    theme: any, 
    flash: any, 
    isRange: boolean, rangeColor: string, 
    isHover: boolean, 
    dangerInfo: {color: string, progress: number} | undefined, 
    hasUnit: boolean,
    lightColor: string | null,
    lightIntensity: number,
    q: number = 0, r: number = 0, textureType: string = 'VOID',
    specialStatus: string | undefined,
    globalTime: number
) {
    // Use standard compressed hex factor defined in utils.ts
    const Y_SCALE = ISO_SCALE_Y; 
    const BASE_THICKNESS = 12; // Visual foundation thickness

    const corners: {x: number, y: number}[] = [];
    // Standard Pointy Top (PI/6) + 45 deg Rotation (PI/4) for Diamond Grid alignment
    const startAngle = Math.PI / 6 + Math.PI / 4; 

    for (let i = 0; i < 6; i++) {
        const angle = startAngle + i * Math.PI / 3;
        corners.push({ 
            x: x + size * Math.cos(angle), 
            y: y + size * Math.sin(angle) * Y_SCALE 
        });
    }

    // This is the TOP face Y level relative to ground (y)
    const topY = height; 

    const traceTopFace = () => {
        ctx.beginPath();
        ctx.moveTo(corners[0].x, corners[0].y - topY);
        for (let i = 1; i < 6; i++) {
            ctx.lineTo(corners[i].x, corners[i].y - topY);
        }
        ctx.closePath();
    };

    // --- 1. Draw Side Faces (The Stack) ---
    // Rotated 45deg: Front faces are 5, 0, 1 (Right-Down, Down, Left-Down)
    // Previous standard [0,1,2] causes gaps because face 2 is now Hidden and Face 5 is now Visible.
    const visibleIndices = [5, 0, 1];

    for (const i of visibleIndices) {
        const j = (i + 1) % 6;

        // Top vertices (Visual Top)
        const x1 = corners[i].x;
        const y1_top = corners[i].y - topY;
        const x2 = corners[j].x;
        const y2_top = corners[j].y - topY;

        // Bottom vertices (Visual Base/Foundation) -> Extended down by BASE_THICKNESS
        const y1_bottom = corners[i].y + BASE_THICKNESS;
        const y2_bottom = corners[j].y + BASE_THICKNESS;

        const grad = ctx.createLinearGradient(0, y - topY, 0, y + BASE_THICKNESS);
        // Alternate brightness for 3D effect
        // Faces 5 and 1 are side-ish, Face 0 is center-front.
        const baseColor = (i === 0) ? theme.sideDark : theme.sideLight;
        grad.addColorStop(0, baseColor);
        grad.addColorStop(1, '#020617'); // Darker at the very bottom foundation

        ctx.fillStyle = grad;
        ctx.beginPath();
        ctx.moveTo(x1, y1_bottom); // Bottom Left (Foundation)
        ctx.lineTo(x2, y2_bottom); // Bottom Right (Foundation)
        ctx.lineTo(x2, y2_top);    // Top Right
        ctx.lineTo(x1, y1_top);    // Top Left
        ctx.closePath();
        ctx.fill();

        // "Layer Lines" for Block Stack Effect (Tactics Ogre)
        if (height > BLOCK_HEIGHT) {
            ctx.strokeStyle = 'rgba(0,0,0,0.3)';
            ctx.lineWidth = 1;
            ctx.beginPath();
            for (let hStep = BLOCK_HEIGHT; hStep < height; hStep += BLOCK_HEIGHT) {
                ctx.moveTo(x1, corners[i].y - hStep);
                ctx.lineTo(x2, corners[j].y - hStep);
            }
            ctx.stroke();
        }

        // Outline Side
        ctx.strokeStyle = 'rgba(255,255,255,0.05)'; 
        ctx.lineWidth = 1; 
        ctx.stroke();
    }

    // --- 2. Draw Top Face (Base) ---
    traceTopFace();

    const topGrad = ctx.createRadialGradient(x, y - topY, 0, x, y - topY, size);
    topGrad.addColorStop(0, theme.top);
    topGrad.addColorStop(1, theme.detail); 
    ctx.fillStyle = topGrad;
    ctx.fill();

    // --- 2.5 Draw Terrain Texture (Detailing) ---
    this.drawTerrainDetail(ctx, x, y - topY, size, q, r, textureType, theme.detail);

    // --- 2.6 SPECIAL STATUS FLOOR EFFECT ---
    if (specialStatus) {
        traceTopFace(); 
        ctx.save();
        ctx.globalCompositeOperation = 'overlay';
        if (specialStatus === 'FROZEN') {
            ctx.fillStyle = '#bae6fd'; 
            ctx.globalAlpha = 0.6;
        } else if (specialStatus === 'POLYMORPH') {
            ctx.fillStyle = '#d8b4fe'; 
            ctx.globalAlpha = 0.5;
        } else if (specialStatus === 'STASIS') {
            ctx.fillStyle = '#fde047';
            ctx.globalAlpha = 0.5;
        }
        ctx.fill(); 
        ctx.restore();
    }

    // --- 2.7 AOE TELEGRAPH ---
    if (dangerInfo) {
        traceTopFace(); 
        ctx.save();
        // 1. Tile Coloring
        const opacity = 0.1 + dangerInfo.progress * 0.6;
        ctx.fillStyle = dangerInfo.color;
        ctx.globalAlpha = opacity;
        ctx.globalCompositeOperation = 'source-over'; 
        ctx.fill(); 

        // 2. Glowing Border
        ctx.strokeStyle = dangerInfo.color;
        ctx.lineWidth = 1 + dangerInfo.progress * 2;
        ctx.globalAlpha = 0.8;
        ctx.stroke();

        // 3. Particles
        if (dangerInfo.progress > 0.2) {
            const particleCount = 3 + Math.floor(dangerInfo.progress * 5);
            ctx.fillStyle = dangerInfo.color;
            ctx.globalCompositeOperation = 'lighter'; 

            for(let i=0; i<particleCount; i++) {
                const seed = (Math.abs(q * 100 + r * 10) + i * 123.45);
                const speed = 20 + (seed % 20);
                const t = (globalTime * speed * 0.05 + seed) % 1; 
                const pAlpha = 1 - t;

                const pX = x + Math.sin(t * 10 + seed) * (size * 0.5);
                const pY = (y - topY) - (t * 40); 

                ctx.globalAlpha = pAlpha * opacity; 
                const pSize = 1 + (seed % 2);

                ctx.beginPath();
                ctx.arc(pX, pY, pSize, 0, Math.PI*2);
                ctx.fill();
            }
        }
        ctx.restore();
    }

    // --- 3. Dynamic Lighting ---
    if (lightColor && lightIntensity > 0) {
        traceTopFace(); 
        ctx.save();
        ctx.globalCompositeOperation = 'lighter'; 
        ctx.globalAlpha = lightIntensity * 0.8; 
        ctx.fillStyle = lightColor;
        ctx.fill();
        ctx.restore();
    }

    // --- 4. Interactive Overlays ---
    if (flash || isRange || isHover || hasUnit) {
        ctx.save();
        traceTopFace(); 

        if (isRange) { 
            ctx.fillStyle = rangeColor;
            ctx.globalAlpha = 0.2; 
            ctx.fill();
            ctx.strokeStyle = rangeColor; 
            ctx.lineWidth = 2; 
            ctx.globalAlpha = 0.8; 
            ctx.stroke();
        }

        if (isHover) { 
            ctx.fillStyle = 'rgba(255,255,255,0.15)'; 
            ctx.globalAlpha = 1.0;
            ctx.fill(); 
            ctx.strokeStyle = '#fff'; 
            ctx.lineWidth = 3; 
            ctx.stroke(); 
        }

        if (flash) {
            ctx.globalCompositeOperation = 'lighter';
            ctx.fillStyle = flash.color;
            ctx.globalAlpha = 0.6;
            ctx.fill();
            ctx.strokeStyle = '#fff';
            ctx.lineWidth = 2;
            ctx.stroke();
        }

        if (hasUnit && !isHover && !dangerInfo) {
            ctx.strokeStyle = 'rgba(255,255,255,0.3)';
            ctx.lineWidth = 1;
            ctx.stroke();
        }

        ctx.restore();
    }
}

// =========================================================================================
// 📺 HOLOGRAPHIC TACTICAL HUD (Diegetic UI)
// =========================================================================================

private drawHolographicHUD(ctx: CanvasRenderingContext2D, agent: Agent, w: number, h: number, cam: Camera) {
    // Position: Top Right, floating
    const hudX = w - 280;
    const hudY = 80;
    const width = 240;
    const height = 160;

    ctx.save();

    // --- 1. Glitch Effect ---
    let gx = 0, gy = 0;
    if (this.holoGlitchTimer > 0) {
        gx = (Math.random() - 0.5) * 20;
        gy = (Math.random() - 0.5) * 10;
        if (Math.random() > 0.7) return; // Flicker off
    }

    // --- 2. Perspective Transform ---
    // Flattened to align with new 45-degree isometric camera (No Skew)
    ctx.transform(1, 0, 0, 1, hudX + gx, hudY + gy);

    // --- 3. Glass Background ---
    const bgGrad = ctx.createLinearGradient(0, 0, width, height);
    const baseColor = agent.team === Team.BLUE ? '#06b6d4' : '#f97316'; // Cyan vs Orange

    bgGrad.addColorStop(0, `${baseColor}40`); // 25% opacity
    bgGrad.addColorStop(1, `${baseColor}05`); // 2% opacity

    ctx.fillStyle = bgGrad;
    ctx.fillRect(0, 0, width, height);

    // Grid Lines
    ctx.strokeStyle = `${baseColor}30`;
    ctx.lineWidth = 1;
    ctx.beginPath();
    for(let i=0; i<=width; i+=20) { ctx.moveTo(i, 0); ctx.lineTo(i, height); }
    for(let i=0; i<=height; i+=20) { ctx.moveTo(0, i); ctx.lineTo(width, i); }
    ctx.stroke();

    // Border corners
    ctx.strokeStyle = baseColor;
    ctx.lineWidth = 2;
    const len = 15;
    ctx.beginPath();
    ctx.moveTo(0, len); ctx.lineTo(0, 0); ctx.lineTo(len, 0); // TL
    ctx.moveTo(width-len, 0); ctx.lineTo(width, 0); ctx.lineTo(width, len); // TR
    ctx.moveTo(width, height-len); ctx.lineTo(width, height); ctx.lineTo(width-len, height); // BR
    ctx.moveTo(len, height); ctx.lineTo(0, height); ctx.lineTo(0, height-len); // BL
    ctx.stroke();

    // --- 4. Content: Logic Visualization ---

    // Header
    ctx.fillStyle = baseColor;
    ctx.font = 'bold 12px monospace';
    ctx.fillText(`TARGET: ${agent.id}`, 10, 20);
    ctx.font = '10px monospace';
    ctx.fillStyle = '#fff';
    ctx.fillText(`STATUS: ${agent.btStatus.toUpperCase()}`, 10, 35);

    // Logic Graph
    // [SCAN] -> [DECISION] -> [ACTION]
    const nodes = [
        { x: 30, y: 80, label: 'SCAN', active: true }, // Always active
        { x: 100, y: 80, label: 'THINK', active: agent.btStatus !== '待機' },
        { x: 170, y: 80, label: 'ACT', active: agent.castingSkillIdx !== -1 || agent.isMoving }
    ];

    // Draw Connections
    ctx.strokeStyle = `${baseColor}60`;
    ctx.lineWidth = 2;
    ctx.beginPath();
    ctx.moveTo(nodes[0].x, nodes[0].y);
    ctx.lineTo(nodes[2].x, nodes[2].y);
    ctx.stroke();

    // Draw Active Flow (Pulse)
    const flowTime = (this.globalTime * 3) % 1; 
    const flowX = 30 + flowTime * 140;
    ctx.strokeStyle = '#fff';
    ctx.lineWidth = 2;
    ctx.beginPath();
    ctx.moveTo(flowX, 80);
    ctx.lineTo(flowX + 15, 80);
    ctx.stroke();

    // Draw Nodes
    nodes.forEach(n => {
        const isActive = n.active;

        // Outer Ring
        ctx.strokeStyle = isActive ? baseColor : `${baseColor}40`;
        ctx.fillStyle = `${baseColor}10`;
        ctx.beginPath(); ctx.arc(n.x, n.y, 10, 0, Math.PI*2); 
        ctx.fill(); ctx.stroke();

        // Inner Dot
        if (isActive) {
            ctx.fillStyle = '#fff';
            ctx.shadowColor = baseColor; ctx.shadowBlur = 10;
            ctx.beginPath(); ctx.arc(n.x, n.y, 4, 0, Math.PI*2); ctx.fill();
            ctx.shadowBlur = 0;
        }

        // Label
        ctx.fillStyle = isActive ? '#fff' : `${baseColor}60`;
        ctx.textAlign = 'center';
        ctx.fillText(n.label, n.x, n.y + 22);
    });

    // Special Alert: ULTIMATE
    if (agent.castingSkillIdx !== -1 && agent.skills[agent.castingSkillIdx]?.tag === 'ULT') {
        ctx.fillStyle = '#ef4444';
        ctx.globalAlpha = 0.5 + Math.sin(this.globalTime * 20) * 0.5;
        ctx.fillRect(0, 130, width, 20);
        ctx.fillStyle = '#fff';
        ctx.globalAlpha = 1.0;
        ctx.font = 'bold 12px monospace';
        ctx.textAlign = 'center';
        ctx.fillText('WARNING: ULTIMATE DETECTED', width/2, 144);
    } else if (agent.hp < agent.maxHp * 0.3) {
        ctx.fillStyle = '#ef4444';
        ctx.font = 'bold 10px monospace';
        ctx.fillText('CRITICAL CONDITION', width - 70, 20);
    }

    // --- 5. Tether Line to Unit ---
    ctx.beginPath();
    ctx.moveTo(10, height);
    ctx.lineTo(10, height + 20);
    ctx.strokeStyle = `${baseColor}40`;
    ctx.setLineDash([2, 4]);
    ctx.stroke();
    ctx.setLineDash([]);

    ctx.restore();
}

