            ctx.lineWidth = 1 + dangerInfo.progress * 2;
            ctx.globalAlpha = 0.8;
            ctx.stroke();

            // 3. Particles
            if (dangerInfo.progress > 0.2) {
                const particleCount = 3 + Math.floor(dangerInfo.progress * 5);
                ctx.fillStyle = dangerInfo.color;
                ctx.globalCompositeOperation = 'lighter'; 

                for(let i=0; i<particleCount; i++) {
                    const seed = (Math.abs(q * 100 + r * 10) + i * 123.45);
                    const speed = 20 + (seed % 20);
                    const t = (globalTime * speed * 0.05 + seed) % 1; 
                    const pAlpha = 1 - t;

                    const pX = x + Math.sin(t * 10 + seed) * (size * 0.5);
                    const pY = (y - topY) - (t * 40); 

                    ctx.globalAlpha = pAlpha * opacity; 
                    const pSize = 1 + (seed % 2);

                    ctx.beginPath();
                    ctx.arc(pX, pY, pSize, 0, Math.PI*2);
                    ctx.fill();
                }
            }
            ctx.restore();
        }

        // --- 3. Dynamic Lighting ---
        if (lightColor && lightIntensity > 0) {
            traceTopFace(); 
            ctx.save();
            ctx.globalCompositeOperation = 'lighter'; 
            ctx.globalAlpha = lightIntensity * 0.8; 
            ctx.fillStyle = lightColor;
            ctx.fill();
            ctx.restore();
        }

        // --- 4. Interactive Overlays ---
        if (flash || isRange || isHover || hasUnit) {
            ctx.save();
            traceTopFace(); 

            if (isRange) { 
                ctx.fillStyle = rangeColor;
                ctx.globalAlpha = 0.2; 
                ctx.fill();
                ctx.strokeStyle = rangeColor; 
                ctx.lineWidth = 2; 
                ctx.globalAlpha = 0.8; 
                ctx.stroke();
            }

            if (isHover) { 
                ctx.fillStyle = 'rgba(255,255,255,0.15)'; 
                ctx.globalAlpha = 1.0;
                ctx.fill(); 
                ctx.strokeStyle = '#fff'; 
                ctx.lineWidth = 3; 
                ctx.stroke(); 
            }

            if (flash) {
                ctx.globalCompositeOperation = 'lighter';
                ctx.fillStyle = flash.color;
                ctx.globalAlpha = 0.6;
                ctx.fill();
                ctx.strokeStyle = '#fff';
                ctx.lineWidth = 2;
                ctx.stroke();
            }

            if (hasUnit && !isHover && !dangerInfo) {
                ctx.strokeStyle = 'rgba(255,255,255,0.3)';
                ctx.lineWidth = 1;
                ctx.stroke();
            }

            ctx.restore();
        }
    }
}

import { GameEngine, Agent } from "./game";
import { HexUtils } from "./utils";
import { Camera, Team, Skill, Hex, GameEvent } from "../types";
import { TERRAIN_THEMES, HEX_SIZE } from "../constants";
import { GridRenderSystem, RenderableItem } from "./systems/grid";
import { UnitRenderSystem } from "./systems/unit";
import { VFXSystem } from "./systems/vfx";
import { HUDSystem } from "./systems/hud";

export class GameRenderer {
    public gridSystem = new GridRenderSystem();
    public unitSystem = new UnitRenderSystem();
    public vfxSystem = new VFXSystem();
    public hudSystem = new HUDSystem();

    private globalTime = 0;
    private holoGlitchTimer = 0;
    private transitionT = 0;
    private transitionPhase: 'IDLE' | 'IN' | 'OUT' = 'IDLE';

    public update(dt: number, engine: GameEngine) {
        this.globalTime += dt;
        this.holoGlitchTimer -= dt;
        if (this.holoGlitchTimer <= 0 && Math.random() < 0.01) this.holoGlitchTimer = 0.2;

        // Update VFX
        this.vfxSystem.update(dt, this.globalTime, engine.currentScene.ambientType);

        // Update HUD (floating text physics)
        this.hudSystem.update(dt);
    }

    public processEventsWithEngine(events: GameEvent[], engine: GameEngine) {
        events.forEach(e => {
            if (e.type === 'DAMAGE' || e.type === 'HEAL') {
                this.hudSystem.addFloatingText(e.pos.x, e.pos.y, e.value! > 0 ? `+${e.value}` : `${e.value}`, e.color || '#fff', 20, e.type);
            }
            if (e.type === 'PROJECTILE_HIT') {
                this.vfxSystem.spawnExplosion(e.pos.x, e.pos.y, 10, 5, e.skill?.color || '#fff', 1, 0.5, 'SPARK');
            }
            if (e.type === 'DEATH') {
                 this.vfxSystem.spawnUnitShatter(e.pos.x, e.pos.y, e.team || Team.BLUE);
            }
             if (e.type === 'CC_APPLIED') {
                this.hudSystem.addFloatingText(e.pos.x, e.pos.y, e.text || '', e.color || '#fff', 18, 'CC');
            }
            if (e.type === 'SPAWN') {
                 // Spawning logic visual handled by unit system spawnTimer
            }
            if (e.type === 'PROJECTILE_SPAWN') {
                 // handled by projectile update
            }
        });
    }

    public setTransition(t: number, phase: 'IDLE' | 'IN' | 'OUT') {
        this.transitionT = t;
        this.transitionPhase = phase;
    }

    public getHexAtScreenPoint(x: number, y: number, cam: Camera, engine: GameEngine): Hex | null {
        // Raycasting against terrain height map
        // Iterate through valid hexes, sort by depth (back to front), check if point is in iso block
        // Simplified approach: Iterate visible map keys, project top face, check collision

        const worldX = (x - (window.innerWidth || 1000) / 2) / cam.zoom + (window.innerWidth || 1000) / 2 + cam.x; 
        // Note: The above math is approximate to GameCanvas transform, but since we don't have exact canvas dims here easily,
        // we might rely on GameCanvas passing relative mouse coordinates if we want precision.
        // However, GameCanvas already passes (mouseX, mouseY) which are relative to canvas.
        // We need to apply inverse camera transform.

        // Let's assume input x,y are client coordinates relative to canvas
        // Canvas Center: (cw/2, ch/2)
        // Transform: translate(cw/2, ch/2) -> scale(zoom) -> translate(-cw/2-cam.x, -ch/2-cam.y)
        // Inverse: translate(cw/2+cam.x, ch/2+cam.y) -> scale(1/zoom) -> translate(-cw/2, -ch/2)

        // This logic is best handled by standard hex picking if flat, but with height it's tricky.
        // For now, we return null to use fallback 2D picking in GameCanvas, which is usually "good enough" for flat maps,
        // but imperfect for tall maps. To fix fully would require ray-aabb intersection.
        return null; 
    }

    public getTerrainHeight(q: number, r: number, engine: GameEngine): number {
        return engine.map.getTerrainHeight(q, r);
    }

    public draw(ctx: CanvasRenderingContext2D, engine: GameEngine, cam: Camera, highlight: Agent | null, fps: number, hoveredHex: Hex | null, hoveredSkill: Skill | null) {
        const w = ctx.canvas.width;
        const h = ctx.canvas.height;

        ctx.clearRect(0, 0, w, h);
        ctx.fillStyle = engine.currentScene.background;
        ctx.fillRect(0, 0, w, h);

        ctx.save();
        ctx.translate(w/2, h/2); // Center camera
        ctx.scale(cam.zoom, cam.zoom);
        ctx.translate(-w/2 - cam.x, -h/2 - cam.y);

        const renderQueue: RenderableItem[] = [];

        // 1. Grid Tiles
        engine.mapKeys.forEach(key => {
            const [q, r] = key.split(',').map(Number);
            const px = HexUtils.toPx(q, r, engine.mapConfig);
            const terrainHeight = engine.map.getTerrainHeight(q, r);
            const theme = TERRAIN_THEMES[engine.currentScene.textureType];

            const isHover = hoveredHex && hoveredHex.q === q && hoveredHex.r === r;

            // Skill Range Highlight
            let isRange = false;
            let rangeColor = '';
            if (highlight && highlight.hp > 0 && highlight.skillIds) {
                // If checking range...
            }
            // Simple hovered skill range visualization
            if (hoveredSkill && highlight) {
                const dist = HexUtils.dist({q, r}, highlight);
                // We need effective range, but that requires engine.movement which is circular or accessible via engine
                // For viz purposes, just basic dist is okay or access engine.movement
                const effRange = engine.movement.getEffectiveRange(highlight, q, r, hoveredSkill.range, engine);
                if (dist <= effRange) {
                    isRange = true;
                    rangeColor = hoveredSkill.color;
                }
            }

            renderQueue.push({
                y: px.y + 10, // Base sort y
                z: 0,
                draw: (c) => this.gridSystem.drawIsoBlock(
                    c, px.x, px.y, HEX_SIZE, terrainHeight, theme, 
                    null, isRange, rangeColor, !!isHover, undefined, !!engine.getAgentAt(q, r), 
                    null, 0, q, r, engine.currentScene.textureType, undefined, this.globalTime
                )
            });
        });

        // 2. Units
        renderQueue.push(...this.unitSystem.collectRenderables(engine.agents, (q,r)=>engine.map.getTerrainHeight(q,r), this.globalTime, highlight, engine.mapConfig));

        // 3. VFX
        renderQueue.push(...this.vfxSystem.collectRenderables(engine, (q,r)=>engine.map.getTerrainHeight(q,r), engine.mapConfig, this.transitionT, this.transitionPhase));

        // Sort Painter's Algorithm
        renderQueue.sort((a, b) => {
            if (Math.abs(a.y - b.y) > 1) return a.y - b.y;
            return a.z - b.z;
        });

        // Execute Draw
        renderQueue.forEach(item => item.draw(ctx));

        // Top Layer Particles
        this.vfxSystem.drawTopLayerParticles(ctx, engine.currentScene, engine.mapConfig, this.transitionT, this.transitionPhase);

        // HUD (World Space)
        this.hudSystem.draw(ctx, engine.agents, (q,r)=>engine.map.getTerrainHeight(q,r), engine.mapConfig);

        ctx.restore();

        // Screen Space HUD
        if (highlight) {
            this.drawHolographicHUD(ctx, highlight, w, h, cam);
        }
    }

    // =========================================================================================
    // 📺 HOLOGRAPHIC TACTICAL HUD (Diegetic UI)
    // =========================================================================================

    private drawHolographicHUD(ctx: CanvasRenderingContext2D, agent: Agent, w: number, h: number, cam: Camera) {
        // Position: Top Right, floating
        const hudX = w - 280;
        const hudY = 80;
        const width = 240;
        const height = 160;

        ctx.save();

        // --- 1. Glitch Effect ---
        let gx = 0, gy = 0;
        if (this.holoGlitchTimer > 0) {
            gx = (Math.random() - 0.5) * 20;
            gy = (Math.random() - 0.5) * 10;
            if (Math.random() > 0.7) { ctx.restore(); return; } // Flicker off
        }

        // --- 2. Perspective Transform ---
        // Flattened to align with new 45-degree isometric camera (No Skew)
        ctx.transform(1, 0, 0, 1, hudX + gx, hudY + gy);

        // --- 3. Glass Background ---
        const bgGrad = ctx.createLinearGradient(0, 0, width, height);
        const baseColor = agent.team === Team.BLUE ? '#06b6d4' : '#f97316'; // Cyan vs Orange

        bgGrad.addColorStop(0, `${baseColor}40`); // 25% opacity
        bgGrad.addColorStop(1, `${baseColor}05`); // 2% opacity

        ctx.fillStyle = bgGrad;
        ctx.fillRect(0, 0, width, height);

        // Grid Lines
        ctx.strokeStyle = `${baseColor}30`;
        ctx.lineWidth = 1;
        ctx.beginPath();
        for(let i=0; i<=width; i+=20) { ctx.moveTo(i, 0); ctx.lineTo(i, height); }
        for(let i=0; i<=height; i+=20) { ctx.moveTo(0, i); ctx.lineTo(width, i); }
        ctx.stroke();

        // Border corners
        ctx.strokeStyle = baseColor;
        ctx.lineWidth = 2;
        const len = 15;
        ctx.beginPath();
        ctx.moveTo(0, len); ctx.lineTo(0, 0); ctx.lineTo(len, 0); // TL
        ctx.moveTo(width-len, 0); ctx.lineTo(width, 0); ctx.lineTo(width, len); // TR
        ctx.moveTo(width, height-len); ctx.lineTo(width, height); ctx.lineTo(width-len, height); // BR
        ctx.moveTo(len, height); ctx.lineTo(0, height); ctx.lineTo(0, height-len); // BL
        ctx.stroke();

        // --- 4. Content: Logic Visualization ---

        // Header
        ctx.fillStyle = baseColor;
        ctx.font = 'bold 12px monospace';
        ctx.fillText(`TARGET: ${agent.id}`, 10, 20);
        ctx.font = '10px monospace';
        ctx.fillStyle = '#fff';
        ctx.fillText(`STATUS: ${agent.btStatus.toUpperCase()}`, 10, 35);

        // Logic Graph
        // [SCAN] -> [DECISION] -> [ACTION]
        const nodes = [
            { x: 30, y: 80, label: 'SCAN', active: true }, // Always active
            { x: 100, y: 80, label: 'THINK', active: agent.btStatus !== '待機' },
            { x: 170, y: 80, label: 'ACT', active: agent.castingSkillIdx !== -1 || agent.isMoving }
        ];

        // Draw Connections
        ctx.strokeStyle = `${baseColor}60`;
        ctx.lineWidth = 2;
        ctx.beginPath();
        ctx.moveTo(nodes[0].x, nodes[0].y);
        ctx.lineTo(nodes[2].x, nodes[2].y);
        ctx.stroke();

        // Draw Active Flow (Pulse)
        const flowTime = (this.globalTime * 3) % 1; 
        const flowX = 30 + flowTime * 140;
        ctx.strokeStyle = '#fff';
        ctx.lineWidth = 2;
        ctx.beginPath();
        ctx.moveTo(flowX, 80);
        ctx.lineTo(flowX + 15, 80);
        ctx.stroke();

        // Draw Nodes
        nodes.forEach(n => {
            const isActive = n.active;

            // Outer Ring
            ctx.strokeStyle = isActive ? baseColor : `${baseColor}40`;
            ctx.fillStyle = `${baseColor}10`;
            ctx.beginPath(); ctx.arc(n.x, n.y, 10, 0, Math.PI*2); 
            ctx.fill(); ctx.stroke();

            // Inner Dot
            if (isActive) {
                ctx.fillStyle = '#fff';
                ctx.shadowColor = baseColor; ctx.shadowBlur = 10;
                ctx.beginPath(); ctx.arc(n.x, n.y, 4, 0, Math.PI*2); ctx.fill();
                ctx.shadowBlur = 0;
            }

            // Label
            ctx.fillStyle = isActive ? '#fff' : `${baseColor}60`;
            ctx.textAlign = 'center';
            ctx.fillText(n.label, n.x, n.y + 22);
        });

        // Special Alert: ULTIMATE
        if (agent.castingSkillIdx !== -1 && agent.skills[agent.castingSkillIdx]?.tag === 'ULT') {
            ctx.fillStyle = '#ef4444';
            ctx.globalAlpha = 0.5 + Math.sin(this.globalTime * 20) * 0.5;
            ctx.fillRect(0, 130, width, 20);
            ctx.fillStyle = '#fff';
            ctx.globalAlpha = 1.0;
            ctx.font = 'bold 12px monospace';
            ctx.textAlign = 'center';
            ctx.fillText('WARNING: ULTIMATE DETECTED', width/2, 144);
        } else if (agent.hp < agent.maxHp * 0.3) {
            ctx.fillStyle = '#ef4444';
            ctx.font = 'bold 10px monospace';
            ctx.fillText('CRITICAL CONDITION', width - 70, 20);
        }

        // --- 5. Tether Line to Unit ---
        ctx.beginPath();
        ctx.moveTo(10, height);
        ctx.lineTo(10, height + 20);
        ctx.strokeStyle = `${baseColor}40`;
        ctx.setLineDash([2, 4]);
        ctx.stroke();
        ctx.setLineDash([]);

        ctx.restore();
    }
}
